INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c0e93b5c-45a9-4720-bf84-2e36fb07baf8', 'Interaksi manusia dan komputer: teori dan praktek / P. Insap Santosa', NULL, 2006, '2006-01-01', 'Paulus Insap Santosa', NULL, 'JOURNAL', NULL, 'http://library.um.ac.id/free-contents/index.php/buku/detail/interaksi-manusia-dan-komputer-teori-dan-praktek-p-insap-santosa-33633.html', NULL, 2, 'OPENALEX', '{"openalex": "https://openalex.org/W1014975495"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('8be60491-8750-465f-b0b9-d2876813e345', 'Understanding Students'' Online Forum Usage', NULL, 2005, '2005-05-14', 'Paulus Insap Santosa; Gee Kin Yeo; Julian Lin', 'National University of Singapore', 'JOURNAL', NULL, 'http://scholarbank.nus.edu.sg/handle/10635/42804', 'Proc. Int. Conf. on Computers in Education 2005: "Towards Sustainable and Scalable Educational Innovations Informed by the Learning Sciences"- Sharing Research Results and Exemplary Innovations, ICCE', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W143869790"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f209a436-33e7-4b38-8d00-f09dada9708b', 'Design of Intelligent Tutoring System for Mastery Learning', NULL, 2013, '2013-08-14', 'Dwijoko Purbohadi; Lukito Edi Nugroho; Paulus Insap Santosa; Amitya Kumara', 'Advanced Science Letters', 'JOURNAL', '10.1166/asl.2014.5313', 'https://doi.org/10.1166/asl.2014.5313', 'Intelligent Tutoring System (ITS) is an interactive e-learning tool to help students learn independently. Currently, the implementation ITS is still in laboratory scale, means ITS has not been used in large scale using internet technology. One of
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e4af5766-608d-408b-a42d-766917f12115', 'Providing information sources domain for information seeking agent from organizing knowledge', NULL, 2014, '2014-11-01', 'Istiadi Istiadi; Lukito Edi Nugroho; Paulus Insap Santosa', NULL, 'JOURNAL', '10.1109/icitacee.2014.7065758', 'https://doi.org/10.1109/icitacee.2014.7065758', 'This paper proposes a tracking mechanism to obtain the information sources that are stored on the personal knowledge organization which will be used to direct the search of information on the Internet by a software agent. Semantic representation of the organizer is viewed as a map of the information sources that are classified hierarchically based on the scopes of knowledge domains from the standpoint of the agent. The tracking mechanism by query will look for the information sources in the knowledge domains based on the same scope of a defined knowledge domain. This tracking will produce a list of information sources that will be followed to get the domain location as internet access preferences', 2, 'OPENALEX', '{"doi": "10.1109/icitacee.2014.7065758", "openalex": "https://openalex.org/W2084363421"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('82340d7b-0443-4767-90f6-e2e00a80c9a8', 'Principal Component Analysis Combined with Second Order Statistical Feature Method for Malaria Parasites Classification', NULL, 2014, '2014-05-10', 'Iis Hamsir Ayub Wahab; Adhi Susanto; Paulus Insap Santosa; Maesadji Tjokronegoro', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/101150/', 'The main challenge in detecting malaria parasites is how to identify the subset of relevant features. The objective of this study was to identify a subset of features that are most predictive of malaria parasites using second-order statistical features and principal component analysis methods. Relevant features will provide the successful implementation of the overall detection modeling, which will reduce the computational and analytical efforts. The results showed that the combination of the principal components of the feature value the correlation to the ASM, and the contrast to the correlation can separate classes of malaria parasites.', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W2265486074"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('458d7e4f-18d1-4362-88b9-b80cabc9e328', 'REVIEW LAYOUT KEYBOARD YANG OPTIMAL UNTUK PENGETIKAN DALAM BAHASA INDONESIA', NULL, 2016, '2016-02-22', 'M Rizki Fadhilah; Paulus Insap Santosa; Sri Suning Kusumawardani', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/1225/1165', 'Keyboard adalah suatu perangkat masukan yangdigunakan pada komputer. Layout keyboard yangdigunakan pada komputer di Indonesia menggunakanlayout QWERTY. Awalnya layout ini digunakan padamesin ketik. Penerapan layout QWERTY pada keyboardkonvensional saat ini tidak efisien untuk pengetikan,terutama untuk pengetikan cepat. Muncul penelitianseperti Layout Dvorak, yaitu layout yang lebih optimaldari QWERTY, namun Dvorak lebih optimal untukBahasa Inggris. Berdasarkan frekuensi kemunculankarakter, Bahasa Inggris berbeda dengan BahasaIndonesia.Tujuan dari penelitian ini adalah untuk menganalisisbeberapa layout yang ada untuk kasus pengetikan dalamBahasa Indonesia. Perbandingan akan dilihat dari segikeoptimalan home row, analisis beban tangan, analisisbeban jari, serta analisis dengan Keyboard LayoutAnalyzer.Berdasarkan hasil pengujian didapatkan layout yangterbaik menurut berdasarkan beban home row adalahCarPalx, berdasarkan beban tangan adalah Capewell,berdasarkan beban jari adalah Workman danberdasarkan KLA adalah Colemak.', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W2414363695"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2f397a49-a958-4f53-9dab-389a66f3c25b', 'EVALUASI KINERJA MAHASISWA BERDASARKAN TEKNOLOGI SMARTPHONE MENGGUNAKAN METODE MODIFIED TASK-TECHNOLOGY FIT', NULL, 2015, '2015-02-06', 'Mohammad Fauzan Bahadjai; Wing Wahyu Winarno; Paulus Insap Santosa', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/695/666', 'Di masa perkembangan teknologi informasi dan komunikasi melaju dengan pesat, smartphone muncul dengan bentuk, kemampuan dan daya tarik yang luar biasa serta menawarkan layanan yang bervariasi, baik untuk pelaku bisnis maupun masyarakat biasa. Tidak hanya itu, kepopuleran smartphone akhirnya menggeser teknologi pendahulunya, notebook dan PDA. Teknologi ini sudah tidak asing lagi di kalangan mahasiswa. Namun, apakah pemanfaatan teknologi ini sudah sesuai dengan aktifitas dan tugas mereka sebagai mahasiswa secara optimal masih belum menemukan titik terang. VARK Learning Styles merupakan suatu konsep yang memahami karakteristik gaya belajar mahasiswa yang terdiri dari Visual (penglihatan), Aural (pendengaran), Read/write (Baca/tulis) dan Kinesthetic (Praktek secara langsung). Setiap mahasiswa memiliki gaya belajar sendiri dalam memahami materi yang didapatkan. Oleh karena itu, penelitian ini akan menguji keselarasan karakteristik tugas, teknologi dan individu dan pengaruhnya terhadap pemanfaatan dan kinerja mahasiswa. Dengan menggunakan metode Task- Technology Fit yang dimodifikasi dengan menambahkan karakteristik individu berdasarkan konsep VARK Learning Styles. Penelitian ini diharapkan menjawab hipotesis yang ada dan membuktikan berdasarkan data bahwa karakteristik gaya belajar seseorang akan selaras dengan penggunaan teknologi dalam menyelesaikan tugas hingga berpengaruh positif terhadap peningkatkan kinerja.', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W2462841295"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('12ba3aaa-24ea-4d33-b513-ef2f419bdb25', 'Aplikasi DS80C400 sebagai Network Bridge dalam Jaringan PLC berbasis AVR AT90S8535', NULL, 2006, '2006-01-01', 'Selo Sulistyo; Eka Firmansyah', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/32291/', 'Dalam industri yang menggunakan PLC, monitoring dan pengontrolan secara jarak jauh menjadi salah satu alternatif untuk efisiensi dalam manufakturing. Ini dapat dilakukan dengan menghubungkan PLC dengan LAN. Akan tetapi tidak semua PLC mempunyai interface ke jaringan sehinga diperlukan komputer untuk mewujudkannya. Dikembangkan network bridge berbasis DS90C400 untuk menghubungkan PLC berbasis AVR 90S8535.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W133430100"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d2c74619-48d7-4476-8580-82a89c1564d3', 'IDENTIFIKASI CRITICAL SUCCESS FACTORS LAYANAN E-LEARNING BERBASIS KERANGKA KERJA E-LEARNING MATURITY MODEL (STUDI KASUS: PROGRAM ICT EQEP DI DIY)', NULL, 2015, '2015-02-06', 'Wihardianto Setia Nugroho; Paulus Insap Santosa; Hanung Adi Nugroho', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/681/653', 'Pesatnya perkembangan implementasi layanan elearning di Indonesia belum diimbangi oleh adanya suatu standar penyelenggaraan layanan e-learning yang resmi, baik dari pemerintah maupun dari institusi berwenang lainnya. Kealpaan ini mengakibatkan para penyelenggara layanan e-learning, terutama sekolah pada jenjang pendidikan dasar dan menengah, mengalami kesulitan dalam mengidentifikasi faktorfaktor krusial yang harus diperhatikan dan dilaksanakan agar layanan e-learning memiliki mutu yang baik dan mampu berkembang secara berkelanjutan. Penelitian ini bertujuan mengidentifikasi faktor-faktor kritis atau Critical Success Factors (CSF) yang berpengaruh dalam mencapai dan meningkatkan kapabilitas institusi penyelenggara layanan e-learning. Kerangka kerja ELearning Maturity Model (EMM) digunakan sebagai basis penyusunan model penelitian. 5 area proses dan 35 proses dalam EMM, ditambah dengan 1 variabel endogen dan 3 indikatornya dari hasil studi pustaka, direpresentasikan sebagai variabel eksogen, variabel endogen dan indikator dalam model penelitian yg dikembangkan. Data penelitian diperoleh dengan mengambil sampel dari 110 sekolah sasaran program ICT EQEP tahap pertama di DIY. Structural Equation Modeling berbasis varian atau yang dikenal sebagai Partial Least Square adalah metode statistik yang digunakan untuk menganalisis data dan model penelitian. Sebagai hasil penelitian, 5 area proses dari EMM bersama dengan 27 indikatornya terbukti signifikan pengaruhnya terhadap variabel endogen dan dapat disimpulkan sebagai CSF penyelenggaraan layanan e-learning', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W2466167457"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('fc8a4a5d-eab7-4a5e-9d60-84336c7d8bd8', 'Interoperability model for eGoverment service based on adaptive ontology', NULL, 2015, '2015-11-01', 'I Wayan Ordiyasa; Lukito Edi Nugroho; Paulus Insap Santosa; Ridi Ferdiana; Wahyudi Kumorotomo', NULL, 'JOURNAL', '10.1109/icodse.2015.7436986', 'https://doi.org/10.1109/icodse.2015.7436986', 'Nowadays, implementation of interoperability in eGoverment services become more important and larger,. As of reference, interoperability is connection of different systems, information and schema of working, in among different administrations which running together and could be applied around the world. Interoperability is implemented in eGoverment with various form that distinctive each other. Interoperability is very important in supporting eGoverment for achieving a good service. eGoverment applied interoperability schema to give a lot of service for the citizen and to achieve a one-stop government in a country. In addition, eGoverment services based interoperability is a part requirement for designing and implementing various eGovernment applications for certain goal. Today, Interoperability composed of heterogenity and dynamic data sources in a transaction. Therefore, in this paper we propose a novel approach to solve interoperability in eGoverment services with heterogeneous data source by using adaptive ontology schema.', 2, 'OPENALEX', '{"doi": "10.1109/icodse.2015.7436986", "openalex": "https://openalex.org/W2540027779"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a49e1bb2-3006-4893-8198-cdfb2419f9d6', 'Comparison expert and novice scan behavior for using e-learning', NULL, 2017, '2017-06-19', 'Felisia Novita Sari; Paulus Insap Santosa; Sunu Wibirama', 'Proceedings of SPIE, the International Society for Optical Engineering/Proceedings of SPIE', 'JOURNAL', '10.1117/12.2280731', 'https://doi.org/10.1117/12.2280731', 'E-Learning is an important media that an educational institution must have. Successful information design for e-learning depends on its user’s characteristics. This study explores differences between novice and expert users’ eye movement data. This differences between expert and novice users were compared and identified based on gaze features. Each participant must do three main tasks of e-learning. This paper gives the result that there are differences between gaze features of experts and novices.', 2, 'OPENALEX', '{"doi": "10.1117/12.2280731", "openalex": "https://openalex.org/W2625016684"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('82bdb273-177b-4b87-beee-5be923e2e706', 'Study on the influencing factors of the flexibility of university IT management in education 4.0', NULL, 2021, '2021-01-01', 'Shaymaa E. Sorour; Paulus Insap Santosa; Wasilah Wasilah; Lukito Edi Nugroho', 'International Journal of Innovation and Learning', 'JOURNAL', '10.1504/ijil.2021.10037402', 'https://doi.org/10.1504/ijil.2021.10037402', 'Education systems at all levels should embrace new technologies to comply with Industry 4.0 developments. Universities need to adapt to these new changes. However, studies that discuss the flexibility in service-based organisations are limited. The study of IT flexibility currently focuses on manufacturing organisations in aspects of IT infrastructure. IT infrastructure flexibility is only a part of IT resources that is managed in IT management. The contribution of this study is to produce variables that significantly influence the flexibility of IT management in the university. T tests obtained six variables with a significant direct effect; they are data integration, modularity of an application, value drivers, human resource competence, human resource development and knowledge sharing. R square test shows that these variables also simultaneously influence the flexibility of IT management universities with a fairly high influence of 76%.', 2, 'OPENALEX', '{"doi": "10.1504/ijil.2021.10037402", "openalex": "https://openalex.org/W3159125136"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6d07939f-5108-4fc9-835d-008cfcd7ef95', 'Confirmation of Personality Types Using Visual Evoked Potential with User Interface Design Stimulus', NULL, 2021, '2021-11-01', 'Ilham Perdana; Paulus Insap Santosa; Noor Akhmad Setiawan; Supra Wimbarti', 'Journal of Computer Science', 'JOURNAL', '10.3844/jcssp.2021.1138.1146', 'https://doi.org/10.3844/jcssp.2021.1138.1146', 'After obtaining the consistency of Visual Evoked Potential (VEP) by using a stimulus with data-entry user interface design. This study tries to confirm whether an individual''s VEP will be classified according to personality type, which results from the proceeds of conventional personality tests usually carried out by the organization that is the place of this research. The results of this study will be an attempt to complement the needs of particular organizations for the elicitation stage to show user personas by using personality types as something to consider in software development in organizations. The recording of 20 participants whose personality types were known from the results of personality tests at the organization was completed. Each individual has a unique VEP. to confirm personality types and it is necessary to prove the similarity of VEP between individuals of the same type. 93.75% of VEP is classified according to personality type. Therefore it is necessary to consider that personality type can be used as user persona for user classification at the stage of user needs. To identify personality types at the personality test stage, it is still necessary to add more participants involved to get more convincing results.', 2, 'OPENALEX', '{"doi": "10.3844/jcssp.2021.1138.1146", "openalex": "https://openalex.org/W4200473024"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('01a5b0f8-bf9f-4ffd-b56f-6d5cfdd2d3c3', 'Analisis Search Engine Optimization (SEO) Pada Layanan Sistem Informasi Ketenagakerjaan', NULL, 2021, '2021-12-31', 'Arif Budi Setiawan; Paulus Insap Santosa', 'Jurnal Ketenagakerjaan', 'JOURNAL', '10.47198/naker.v16i2.104', 'https://doi.org/10.47198/naker.v16i2.104', 'Sistem Informasi Ketenagakerjaan (Sisnaker) merupakan penerapan e-government di Kementerian Ketenagakerjaan yang ditujukan agar masyarakat dapat dengan mudah mengakses informasi dan layanan ketenagakerjaan. Untuk mencari informasi biasanya masyarakat menggunakan mesin pencari. Sisnaker harus berada dihalaman depan halaman mesin pencari agar mudah ditemukan masyarakat. Penelitian ini melakukan analisis penerapan search engine optimization (SEO) pada sisnaker dengan alat otomatis seperti Google Analytics, Moz Pro dan Ubersuggest. Metode yang digunakan adalah metode deskriptif dengan mendeskripsikan hasil yang didapat dari alat analisis otomatis SEO. Hasilnya didapatkan penerapan SEO sisnaker sudah baik namun terdapat beberapa hal yang harus diperbaiki.', 2, 'OPENALEX', '{"doi": "10.47198/naker.v16i2.104", "openalex": "https://openalex.org/W4285311266"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5a807ae1-6ba5-469b-8093-da2b8fe70993', 'Student-centered Factors on Online Learning: A Systematic Literature Review', NULL, 2022, '2022-07-20', 'I Putu Eka Juliantara; Paulus Insap Santosa; Sri Suning Kusumawardani', NULL, 'JOURNAL', '10.1109/isitia56226.2022.9855282', 'https://doi.org/10.1109/isitia56226.2022.9855282', 'Along with its growth, one of the research areas to perfect online learning is student-centered factors that affect how online learning is going from the student’s perspective. However, online learning still faces similar problems from the student perspective even until the COVID-19 pandemic. This fact confirms researchers still need to do more studies, or educators still need to learn more. So, this study aimed to help researchers and educators by providing the latest and relevant student-centered factors. This study reviewed 21 latest and relevant studies to achieve the objective. As a result, 12 types were discovered, with at least three factors in each factor type. Also, the impact of each factor on each other was given. Then, some factors were prioritized to solve the problems mentioned before. It’ll be easier to improve the prioritized factors by taking steps back and improving the independent variables first. Hopefully, researchers can see a gap in those factors and start a study to solve it. Also, educators can learn at once and adjust some relevant factors to facilitate online learning as expected, especially during the COVID-19 pandemic.', 2, 'OPENALEX', '{"doi": "10.1109/isitia56226.2022.9855282", "openalex": "https://openalex.org/W4292388558"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f452bcb0-fd6e-438d-bf36-e8d4aeebb037', 'Mapping of Instructional Design of MOOC’s Elements', NULL, 2022, '2022-09-13', 'El Vionna Laellyn Nurul Fatich; Paulus Insap Santosa; Ridi Ferdiana', 'JATISI (Jurnal Teknik Informatika dan Sistem Informasi)', 'JOURNAL', '10.35957/jatisi.v9i3.2195', 'https://doi.org/10.35957/jatisi.v9i3.2195', 'MOOC (Massive Open Online Course) is an innovation in the field of online learning that has been popular since 2012. MOOC users during the COVID-19 pandemic increased dramatically, but the dropout rate for MOOC was also high. One of the things that causes the high dropout rate is the MOOC design. To get a good MOOC design, it is necessary to design an instructional design. Instructional design is a guide in designing instruction or learning stages to facilitate effective learning so that learning objectives can be achieved. Many examples of instructional design have been introduced in previous studies, one of which is "The 7Cs Learning Design Framework". In this research, a mapping of elements that are found in MOOC will be carried out into the category of MOOC features that are closely related because of the similarity of functions and properties with "The 7Cs Learning Design Framework". It is hoped that after this mapping has been carried out, system developers and MOOC instructors can focus more on a good MOOC design so as to maintain MOOC user retention and satisfaction.', 2, 'OPENALEX', '{"doi": "10.35957/jatisi.v9i3.2195", "openalex": "https://openalex.org/W4296103084"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('315c6c6c-614a-487d-b2b3-fd85ebd2ca01', 'PURWARUPA SISTEM PERINGATAN DINI AWAN PANAS GUNUNGAPI BERBASIS SISTEM INFORMASI GEOGRAFIS(Kasus Gunung Merapi di Perbatasan Jawa Tengah dan Daerah Istimewa Yogyakarta)', NULL, 2012, '2012-01-01', 'Muhammad Nur Budiyanto; Paulus Insap Santosa; Sujoko Sumaryono', NULL, 'JOURNAL', '10.22146/jnteti.v1i1.5', 'http://ejnteti.jteti.ugm.ac.id/index.php/JNTETI/article/view/5', 'Purwarupa Sistem Peringatan Dini Awan Panas Gunungapi Berbasis Sistem Informasi Geografis (Kasus Gunung Merapi di Perbatasan Jawa Tengah dan Daerah Istimewa Yogyakarta) M. Nur Budiyanto1, P. Insap Santosa2, Sujoko Sumaryono3 Salah satu bahaya primer yang ditimbulkan oleh aktivitas valkanis gunung Merapi adalah awan panas (piroclastic flow) yang bergerak dengan cepat dan terdiri dari gas panas, abu vulkanik dan bebatuan. Aliran ini dapat bergerak dengan cepat menuruni lereng gunung dengan suhu yang sangat tinggi. Kondisi alam gunung Merapi menyebabkan kesulitan dalam pemantauan awan panas secara visual, sedangkan penggunaan peralatan seismik membutuhkan tenaga ahli untuk menganalisis data. Hal ini mengakibatkan petugas kesulitan untuk memberikan peringatan dini kepada masyarakat secara cepat dan tepat. Sehingga perlu dilakukan kajian untuk merancang sistem peringatan dini awan panas yang dapat memberikan kemudahan petugas untuk melakukan pemantauan awan panas dan dapat memberikan peringatan bahaya. Penelitian ini merancang sistem peringatan dini awan panas berbasis sistem informasi geografis dengan memanfaatkan sensor suhu sebagai alat deteksi awan panas, sistem ini diharapkan dapat memberikan kemudahan pemantauan dan dapat memberikan peringatan dini kepada penduduk disekitar gunung Merapi sehingga dapat meminimalkan korban jiwa akibat awan panas. Penelitian dilaksanakan dengan metode survai lapangan, pengamatan dan wawancara sedangkan perancangan perangkat lunak menggunakan metodologi waterfall atau model sekuensial linier yang terdiri dari analisa, desain, implementasi serta pengujian. Untuk pengujian digunakan sensor suhu infra merah menggunakan mikrokontroller ATMega8535. Hasil yang diperoleh dari penelitian ini adalah purwarupa sistem peringatan dini awan panas gunungapi berbasis sistem informasi geografis dengan memanfaatkan sensor suhu sebagai alat deteksi awan panas. Sensor suhu yang digunakan dalam pengujian sistem adalah sensor suhu infra merah dengan menggunakan mikrokontroler sebagai pengubah sinyal analog ke digital. Sistem ini memiliki fasilitas untuk mengatur peletakan sensor, membaca suhu pada masing-masing sensor, dan memberikan peringatan bahaya sesuai dengan batasan yang sudah ditentukan.', 2, 'OPENALEX', '{"doi": "10.22146/jnteti.v1i1.5", "openalex": "https://openalex.org/W74928835"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('02b5e477-21fa-4bbe-a2cc-8c19c54db06c', 'Augmented Reality Application for Book Promotion', NULL, 2013, '2013-01-24', 'Aan Erlansari; Paulus Insap Santosa; Ridi Ferdiana', NULL, 'JOURNAL', NULL, NULL, 'With the proliferation of smartphone amongst the world population with ever increasing sets of advanced feature such as camera, high resolution and processor speed, Augmented reality (AR) has the opportunity to emerge from laboratories into product advertising. In this paper we discuss, implementation of AR to be use in book advertisement or book promotion to be viewed via mobile phone equipped with high resolution cameras. The prototyping of AR is using vuforia SDK library which allow the system to be deployed through eclipse or unity3D tools. The purpose of this research is to develop promotion media with AR technology application under android platform.', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W76972431"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e200d85d-d41b-4cb8-968a-f8228ecc50ed', 'An agent model of domain based information seeking on personal knowledge organizer', NULL, 2014, '2014-11-01', 'Istiadi Istiadi; Lukito Edi Nugroho; Paulus Insap Santosa', NULL, 'JOURNAL', '10.1109/icitsi.2014.7048274', 'https://doi.org/10.1109/icitsi.2014.7048274', 'This paper proposes a design of information-seeking agent to support complement the resources on personal knowledge organizer through accessing the internet. The Information seeking approach is based on users experience in the Internet accessing which is tend to repeat the search on the same location domain. Information sources (URLs) as users access experience stored in the knowledge representation in organizer as part of the data property. The representation viewed as map of information sources from the standpoint of the agent. The information sources will be extracted to obtain the domain location (URL base) as a preference for directing search to the related information. The searching results should be selected to obtain recommended content that will be mapped to organizer. Functionality actors such as knowledge representation interface, browser agent, and similarity analyzer identified to satisfy the capability of agent in automatic content retrieval.', 1, 'OPENALEX', '{"doi": "10.1109/icitsi.2014.7048274", "openalex": "https://openalex.org/W1608014026"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('ced78d8a-c544-44e2-a6af-989831ab0bb3', 'Perancangan Sistem Informasi Posyandu Online', NULL, 2014, '2014-12-01', 'Yudi Wahyu Wibowo; Paulus Insap Santosa; Eko Nugroho', NULL, 'JOURNAL', NULL, 'https://publikasiilmiah.ums.ac.id/bitstream/11617/5456/1/18.Yudi%20Wahyu%20Wibowo.pdf', NULL, 1, 'OPENALEX', '{"openalex": "https://openalex.org/W1817589110"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d2bc543b-484f-420d-add9-c5337c5e10b5', 'Leveraging Knowledge from Different Communities Using Ontologies', NULL, 2013, '2013-01-01', 'Herlina Jayadianti; Carlos Sousa Pinto; Lukito Edi Nugroho; Paulus Insap Santosa; Wahyu Widayat', 'Advances in intelligent systems and computing', 'BOOK_CHAPTER', '10.1007/978-3-642-36981-0_7', 'https://doi.org/10.1007/978-3-642-36981-0_7', NULL, 1, 'OPENALEX', '{"doi": "10.1007/978-3-642-36981-0_7", "openalex": "https://openalex.org/W190519710"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6d373c39-f655-49f5-b481-bc2a7c66e3c3', 'Semantic interrelation in distributed system through green computing ontology', NULL, 2013, '2013-10-01', 'Herlina Jayadianti; Lukito Edi Nugroho; Paulus Insap Santosa; Carlos Alberta Baptista Sousa Pinto; Wahyu Widayat', NULL, 'JOURNAL', '10.1109/iciteed.2013.6676241', 'https://doi.org/10.1109/iciteed.2013.6676241', 'Green computing refers to the system that provides minimal impact on the environment. When we are talking about green computing we discuss about how much energy is used by the system, such as energy used by the system, time used for the search process, and how effective the system is. Related to that issue, trough this paper we want to proposes a new effort to achieve Green Computing in heterogeneous data in distributed system. The technology chosen to deal with them is Ontology. We try to generate a common ontology including a common set of terms, based on the several ontologies available, in order to make possible to share the common terminology (set of terms) that it implements, between different communities. If a very large amount of distributed data is not managed and distributed properly, user will need more time to do a search process. The longer the search is done, the more energy is used.', 1, 'OPENALEX', '{"doi": "10.1109/iciteed.2013.6676241", "openalex": "https://openalex.org/W2079185761"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b7fb5abf-29c0-4ab1-af93-da66a59b03f4', 'Isolated Sign Language Characters Recognition', NULL, 2013, '2013-09-01', 'Paulus Insap Santosa', 'TELKOMNIKA (Telecommunication Computing Electronics and Control)', 'JOURNAL', '10.12928/telkomnika.v11i3.1142', 'https://doi.org/10.12928/telkomnika.v11i3.1142', 'People with normal senses use spoken language to communicate with others. This method cannot be used by those with hearing and speech impaired. These two groups of people will have difficulty when they try to communicate to each other using their own language. Sign language is not easy to learn, as there are various sign languages, and not many tutors are available. This study focuses on the character recognition based on manual alphabet. In general, the characters are divided into letters and numbers. Letters were divided into several groups according to their gestures. Characters recognition was done by comparing the photograph of a character with a gesture dictionary that has been previously developed. The gesture dictionary was created using the normalized Euclidian distance. Character recognition was performed by using the nearest neighbor method and sum of absolute error. Overall, the level of accuracy of the proposed method was 96.36%.', 1, 'OPENALEX', '{"doi": "10.12928/telkomnika.v11i3.1142", "openalex": "https://openalex.org/W2129365849"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4beb3ca4-f7b5-4163-84a7-0272733662e8', 'A HEURISTIC TEST TO UNDERSTAND USER MENTAL MODEL OF A FLIGHT SCHEDULE SEARCH FORM', NULL, 2012, '2012-07-31', 'Paulus Insap Santosa; Rianto Rianto', 'DOAJ (DOAJ: Directory of Open Access Journals)', 'JOURNAL', '10.21107/kursor.v6i4.1071', 'https://doaj.org/article/0860050f1cea459caeee17819e1b3e8b', 'Situs web yang bagus adalah situs yang sederhana dan berguna bagi penggunanya. Antarmuka merupakan salah satu aspek penting yang menentukan keberhasilan suatu situs web. Makalah ini ini melaporkan hasil sebuah studi untuk mengevaluasi ransangan situs tiket online. Secara khusus, studi ini berfokus pada kombinasi warna dan kebiasaan pengguna. Test kebergunaan dilakukan dengan membandingkan situs web Garasitiket (Form1) aktif dengan rancangan alternatifnya (Form2). Form 1 dan Form2 dirancang secara berbeda dalam hal cara memilih jadwal penerbangan. Metode riset yang digunakan dalam studi ini adalah uji heuristik. Responden, berjumlah 99 orang, berasal dari anggota Garasitiket. Uji sampel-berpasangan (paired-sample test) digunakan untuk menentukan apakah Form1 berbeda dengan Form2. Hasil penelitian menunjukkan bahwa kebiasaan responden mempengaruhi pilihan antarmuka yang digunakan. Ada kecenderungan dari anggota Garasitiket untuk tidak tertarik pada kombinasi warna. Mereka lebih fokus pada hasil pencarian dan kesederhanaan rancangan situs. Analisis statistis menunjukkan bahwa ada perbedaan signifikan antara Form1 dan Form2. Lebih lanjut, responden lebih memilih Form1 dibandingkan dengan Form2. Kata kunci: Model Mental, Kebergunaan, Jadwal Penerbangan, Uji Heuristik. Abstract A great web site should be simple and usable to its users. Interface design is one important aspect that determine the success of certain website. This paper reports the result of a study to evaluate the design of an online ticket website. In particular, the study focuses on color combination, and usesâ€™s habit. Usability test was done by comparing the published Garasitiket Website (Form1) and its alternative (Form2). Form 1 and Form2 were designed differently in term of the way respondents determined their flight schedule. Research method used for this study was heuristic test. Respondents, 99 people, were from members of Garasitiket. Paired-sample test was used to determine whether Form1 differs from Form2. The results indicated that membersâ€™ habit influences user interface selection. There was a tendency of Garasitiket members to not interested in color combinations. Rather, they were more focus on the search results and Web design simplicity. Statistical analyses indicated that there was significant difference between Form1 and Form2. Furthermore, Form1 was more preferable.', 1, 'OPENALEX', '{"doi": "10.21107/kursor.v6i4.1071", "openalex": "https://openalex.org/W2186616146"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c4b7cc1b-ee87-4ff5-ae81-0c2ba14a35c2', 'Model Evaluasi E-Leadership pada Implementasi Program E-Development', NULL, 2015, '2015-01-01', 'Sudarmin; Paulus Insap Santosa; Wing Wahyu Winarno', NULL, 'JOURNAL', NULL, 'http://is.its.ac.id/pubs/oajis/index.php/home/detail/1586/Model-Evaluasi-E-Leadership-pada-Implementasi-Program-E-Development', NULL, 1, 'OPENALEX', '{"openalex": "https://openalex.org/W2209719221"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('bf6df92e-e57a-42dc-be88-bbd6c165fa35', 'Querying ontology through HTTP protocol to bridge interoperability and platform difference', NULL, 2015, '2015-10-01', 'Sri Suning Kusumawardani; Robertus Sonny Prakoso; Paulus Insap Santosa', NULL, 'JOURNAL', '10.1109/iciteed.2015.7408927', 'https://doi.org/10.1109/iciteed.2015.7408927', 'Ontology is one of semantic web implementation and knowledge representation that can be implemented and consumed by any kind of application. Therefore, it will face the interoperability issue, as there are lots of application platform nowadays, and developers can''t restrict usage of ontology only in the application with same platform. As ontology is part of semantic web, the most suitable method to solve the interoperability issue is using web environment. One of solution that can be used is serving ontology through HTTP protocol and accessing the ontology by S PARQL. This paper explain one alternative of S PARQL implementation over HTTP protocol by using SPARQL endpoint to store and serve the ontology.', 1, 'OPENALEX', '{"doi": "10.1109/iciteed.2015.7408927", "openalex": "https://openalex.org/W2292024681"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('de10d669-dba6-4704-9258-4812f3ad7222', 'DOMAIN BASED WEB RETRIEVAL DRIVEN BY SEMANTIC REPRESENTATION OF PERSONAL KNOWLEDGE ORGANIZER', NULL, 2016, '2016-05-25', 'Istiadi Istiadi; Lukito Edi Nugroho; Paulus Insap Santosa', 'Jurnal Teknologi', 'JOURNAL', '10.11113/jt.v78.8766', 'https://doi.org/10.11113/jt.v78.8766', 'One important aspect in self-directed learning is to find learning resources, which can be referenced from the Internet. In the process of finding the resources, users have experience in accessing certain sites for specific information. But, when they want to refer back to related information, usersare supposed to recall the domain of sites and to determine the proportion of priority on a number of sites. The experience of accessing the Internet is mapped into semantic representation of Knowledge Organization (KO) like a memory thatit can be exploited to support in gaining new resources in the same domain of knowledge. This study aims to develop a web retrieval application to assist users based on their experience. The application will identify the domains of the sites that were previously accessed by tracing the representation. The domains are used as references to direct the search. Searching the web resources is undertaken by the composition of domain based search and search without domain limitation. The composition ofboth searchescan be determined by the users according to their expectations. The domain based search composition is determined by the resourcecontributions within the scope of a knowledge domain. The test results show that the system is able to identify the domain’s location and the proportions as preferences for searching. The performance of the system in searching shows thatthe query returnsof relevant documents are dominant.', 1, 'OPENALEX', '{"doi": "10.11113/jt.v78.8766", "openalex": "https://openalex.org/W2409780715"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d41804b4-1ed5-487a-87dc-fb842fd832bc', 'LOW TEMPERATURE SPERM SELECTION METHOD TO SUPPORT BOVINE BREEDING INDUSTRY', NULL, 2016, '2016-05-26', 'Tatag Lindu Bhakti; Adhi Susanto; Paulus Insap Santosa; Diah Tri Widayati', 'Jurnal Teknologi', 'JOURNAL', '10.11113/jt.v78.8814', 'https://doi.org/10.11113/jt.v78.8814', 'This research proposed novel bovine sperm selection method based on sperm motility parameter to support bovine breeding industry. Sperm selection method consists of three main processes. First, decrease and holdbovine semen temperature at 4oC to reduce average sperm motility.Second, determine targeted sperm location which has highest motility within objective’s field of view after general motility observed decreasedinto 5% from initial value.Third, track targeted sperm and maintain holding temperature continuously until targeted sperm immotile and ready to be aspirated. Testing result showstemperature controller prototype can decrease bovine semen temperature safely without generate any intracellular ice. Micro actuator prototype can provide high motion performance exceed bovine sperm average velocity so it fully supporting motion detection software to perform real time bovine sperm tracking. Autofocus mechanism was succeedingincrease motion detection sensitivity using 4X, 10X and 40X objectives lens. All prototype devices developed in this research provide safely selection process to achieve high quality bovine sperm.', 1, 'OPENALEX', '{"doi": "10.11113/jt.v78.8814", "openalex": "https://openalex.org/W2411175717"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('547cccf2-3d6a-4d44-a3fe-bee988bd03dd', 'DESAIN MULTIMEDIA SISTEM BLENDED E-LEARNING PADA PELAJARAN FISIKA', NULL, 2015, '2015-02-06', 'Hera Susanti; Paulus Insap Santosa; Rudy Hartanto', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/899/862', 'Siswa terkadang mengalami kesulitan memahami pelajaran fisika. Pembelajaran fisika dapat dimodelkan dengan metode lain agar dapat dengan mudah diterima dan dikembangkan oleh siswa. Salah satunya dengan cara pembelajaran online atau e-Learning yang dikombinasikan dengan pembelajaran konvensional. Untuk mengembangkan pemodelan pembelajaran online-nya, digunakan media pembelajaran berbasis multimedia. Metode yang digunakan adalah research and development. Hasil yang diharapkan adalah desain media pembelajaran berbasis multimedia yang dapat meningkatkan nilai e-Learning sehingga dapat membantu dalam proses kegiatan belajar mengajar (KBM) bagi guru dan siswa yang masih mengalami kesulitan dalam memahami konsep-konsep pelajaran fisika. E-Learning yang dihasilkan dapat dipergunakan sebagai media pembelajaran di dalam maupun di luar kelas.', 1, 'OPENALEX', '{"openalex": "https://openalex.org/W2482873015"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('8817306f-b92c-4e05-a99f-08cd79e2c4c4', 'RISK ANALYSIS OF DATABASE PRIVELEGE IMPLEMENTATION IN SQL INJECTION CASE', NULL, 2016, '2016-05-19', 'Prajna Deshanta Ibnugraha; Lukito Edi Nugroho; Widyawan Widyawan; Paulus Insap Santosa', 'Jurnal Teknologi', 'JOURNAL', '10.11113/jt.v78.8724', 'https://doi.org/10.11113/jt.v78.8724', 'Software is important thing that needed by enterprises to support business. When developers build software, security must be concerned as important element. In bad condition, security incidents can make financial loss to organizaion so it need mitigation actions to minimize risk. Security testing and risk analysis become base process to choose good mitigation method. Implementation of database privilege become one of mitigation methods that can be used in SQL injection attack case. Based on DREAD analysis, it can decrease risk of SQL injection attack from high to medium ranking.', 1, 'OPENALEX', '{"doi": "10.11113/jt.v78.8724", "openalex": "https://openalex.org/W2492692656"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3d4a7372-b934-4aa5-9143-b42cff644f5b', 'ANALISIS LOYALITAS PADA LAYANAN E-GOV: STUDI KASUS PELAYANAN STATISTIK TERPADU (PST) DI BPS', NULL, 2016, '2016-09-05', 'Arif Widyadarma; Paulus Insap Santosa; Hanung Adi Nugroho', NULL, 'JOURNAL', NULL, 'http://journal.bakrie.ac.id/index.php/INDOCOMPAC/article/view/1603', 'Perkembangan teknologi informasi semakin pesat. Teknologi informasi merupakan bagian terpenting untuk menjalankan kegiatan ( bussiness ), baik ekonomi, industri dan budaya, dan jika digunakan dengan baik dan benar akan menghasilkan keuntungan. Dalam menghadapi era Masyarakat Ekonomi ASEAN (MEA), kondisi pasar yang dinamis, tidak hanya kepuasan konsumen yang perlu diperhatikan, melainkan mempertahankan loyalitas konsumen juga merupakan hal yang penting. Pelayanan publik yang dilakukan pemerintah juga perlu memperhatikan loyalitas konsumen untuk meningkatkan kepercayaan terhadap sistem informasi pemerintah. Sistem informasi dapat menjadi suatu sistem yang useless bilamana sistem informasi tersebut tidak dikelola dengan baik dan benar sehingga dalam hal ini pemerintah wajib membangun sistem informasinya dengan sangat baik dari sisi kualitas sistem, informasi dan layanan.  Sistem informasi yang terintegrasi dengan sangat baik tidaklah cukup, karena sistem informasi tersebut haruslah mudah digunakan dan bermanfaat bagi kebutuhan pengguna. Badan Pusat Statistik (BPS) sebagai lembaga penyedia data memiliki Pelayanan Statistik Terpadu (PST), sistem informasi yang sedang terus dikembangkan bagi pengguna data. Penggunaan sistem informasi di lingkup pemerintah memiliki karakteristik yang berbeda dengan lingkup bisnis. Untuk menentukan model analisis yang tepat dan sesuai dengan karakteristik lembaga pemerintah, maka perlu dilakukan penelitian terkait model analisis loyalitas pada sistem Pelayanan Statistik Terpadu BPS. Penelitian ini mengusulkan model integrasi dari model kesuksesan sistem informasi DeLone dan McLean dan model penerimaan TAM terkait pengaruh yang ditimbulkan terhadap kepercayaan dan loyalitas pengguna sistem informasi tersebut. Penelitian ini menggunakan metode penelitian deskriptif kuantitatif dengan melakukan survei melalui kuesioner yang disebarkan kepada sampel dari populasi. Populasi dalam penelitian ini adalah pengunjung Perpustakan BPS DI Yogyakarta dengan sampel pengunjung yang datang pada 1 periode penelitian. Penelitian ini akan menggunakan skala linkert enam point yang memiliki kehandalan yang tinggi dan untuk menghindari atau mengurangi resiko penyimpangan pada pengambilan data di lapangan. Data lapangan yang diperoleh, akan dianalisis menggunakan Structural Equation Modeling Partial Least Square (SEM-PLS). Tujuan penelitian ini untuk mengetahui pengaruh model kesuksesan sistem informasi DeLone dan McLean dan model penerimaan TAM terhadap kepercayaan dan loyalitas pengguna PST. Kata kunci: model penerimaan TAM, model kesuksesan SI DeLone dan McLean, trust, e-loyalty, Badan Pusat Statistik Increasingly rapid development of information technology. Information technology is an important part of running events (business), both the economy, industry and the culture, and if used properly will produce a profit. In the era of the ASEAN Economic Community (MEA), dynamic market conditions, not only customer satisfaction need to be considered, but also maintain customer loyalty is important. Public services the government needs to do consumer loyalty to increase confidence in the system of government information. The information system can be a system that is useless if the information system is not managed properly so that in this case the government is obliged to build its information system with excellent in terms of quality systems, information and services. The information system that integrates very well is not enough, because the information system must be easy to use and useful for the needs of the user. The Badan Pusat Statistik (BPS) as an institution has a data provider Pelayanan Statistik Terpadu (PST), the information system is designed for the user data. The use of information systems in the scope of government has different characteristics with the business scope. To determine the analysis model is appropriate and in accordance with the characteristics of a government agency, it is necessary to do research related to the analysis model of loyalty to the system of PST. This study presents a model of integration of information systems success DeLone and McLean Model and Technology Acceptance Model (TAM) related effect that the trust and loyalty of the information system users. This research uses descriptive quantitative research methods to conduct a survey through a questionnaire circulated to a sample of the population. The population in this study is the BPS DI Yogyakarta Library visitors with samples of visitors coming in the first period of the study. This study will use a six-point scale linkert which has high reliability and to avoid or reduce the risk of irregularities in data collection in the field. Field data obtained will be analyzed using Structural Equation Modeling Partial Least Square (PLS-SEM). Through this research, is expected to determine the effect of information systems success model DeLone and McLean and TAM to the trust and loyalty of users from PST. Keywords : model penerimaan TAM, model kesuksesan SI DeLone dan McLean, trust, e-loyalty, Badan Pusat Statistik', 1, 'OPENALEX', '{"openalex": "https://openalex.org/W2513480100"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('68be4ea6-4380-45d0-ad0c-e0e24e8fe946', 'A Model of Personalized Context Aware E-learning Based on Psychological Experience', NULL, 2018, '2018-02-05', 'Dadang Syarif Sihabudin Sahid; Lukito Edi Nugroho; Paulus Insap Santosa', 'Journal of Telecommunication Electronic and Computer Engineering (JTEC)', 'JOURNAL', NULL, 'http://journal.utem.edu.my/index.php/jtec/article/view/3645', 'The use of context-aware approach in e-learning system has brought a new passion for users as an alternative to learning. It can provide personalized and adaptive learning patterns that can tailor to the needs, the circumstances and the behavior of users. Along with the continued development pervasive and ubiquitous computing, there are several studies related to this model. However, the existing models developed still focus on a wide variety of contexts, such as explicit contexts and context related to the physical environment of learning. Additionally, the developments of the current models by involving psychological condition of the learner taken into account are still limited. In fact, this condition can influence the learning engagement of learners. This research proposed a model of context aware e-learning that personalizing e-learning according to psychological state of the learners. The psychological experience is based on the theory of flow consisting of anxiety, boredom, and optimal condition measured naturally when users are interacting with e-learning. Furthermore, it becomes one of the strengths of this research. Psychological experiences are measured after the learner interacting with the e-learning. The data are obtained from learner behavior saved in the server log.', 1, 'OPENALEX', '{"openalex": "https://openalex.org/W2795951986"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f52f7515-032b-4065-a3b5-cb0015f7ed48', 'Adaptive Ontology based on Cross Phrase Identification in e-Government', NULL, 2018, '2018-02-19', 'I Wayan Ordiyasa; Lukito Edi Nugroho; Paulus Insap Santosa; Wahyudi Kumorotomo', 'Journal of Telecommunication Electronic and Computer Engineering (JTEC)', 'JOURNAL', NULL, 'http://journal.utem.edu.my/index.php/jtec/article/view/3882', 'Currently, the implementation of interoperability in e-Government services becomes very crucial. It is the connection of different systems and different schema of applications managed by different administrations. The system is very important in supporting e-Government for achieving good services. Therefore, it has to ensure good quality of services. Discrepancies in data and system structure have caused problems to interlink between systems. In this paper, we propose a method for cross-phrase identification of semantic relation based on word similarity measurement and morposemantic relations for e-Government services. It will solve the interoperability of e-Government services using heterogeneity data to make adaptive ontology.', 1, 'OPENALEX', '{"openalex": "https://openalex.org/W2802402433"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6f0dff3a-2413-4a37-90cb-503b3894d81d', 'Selecting elicitation technique on requirements elicitation process: A case study on education application for children', NULL, 2018, '2018-12-04', 'Mira Kania Sabariah; Paulus Insap Santosa; Ridi Ferdiana', 'IOP Conference Series Materials Science and Engineering', 'JOURNAL', '10.1088/1757-899x/434/1/012056', 'https://doi.org/10.1088/1757-899x/434/1/012056', 'Children''s educational applications are designed to help children in the learning process; thus, direct child involvement in elicitation process helps to achieve learning objectives. Failure in the requirements elicitation stage may lead to undefined user requirements for the application affecting the quality and usability of the developed software. Failure in requirements elicitation occurs because the user is not directly involved in the application. It is also caused by the lack of the elicitation team''s knowledge in selecting elicitation techniques that match the characteristics of users, where children have different characteristics with adults and parents. Communication in exploring the needs of users is closely related to elicitation techniques selection. Selection of elicitation techniques that are inconsistent with children''s characteristics can lead to failure in exploring the children''s needs for children educational application. The results of questionnaires and interview with the application developers show that the prototype and interview techniques are the techniques most suitable in the elicitation process involving children as respondents because these methods are suitable for the child characteristics and the short elicitation time required in the application development.', 1, 'OPENALEX', '{"doi": "10.1088/1757-899x/434/1/012056", "openalex": "https://openalex.org/W2903025991"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('02fc39f1-72af-4e3d-bba5-3ae6b60fcb78', 'ANALISIS RESPON AFEKTIF TERHADAP USER INTERFACE B2C MCOMMERCE BERDASARKAN JENIS KELAMIN DAN LATAR BELAKANG STUDI MENGGUNAKAN KANSEI ENGINEERING', NULL, 2018, '2018-02-10', 'Afriq Yasin Ramadhan; Paulus Insap Santosa; Ridi Ferdiana', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/view/2091', 'Pengembangan aplikasi B2C m-commerce tidak bisa terlepas dari keterlibatan pengguna yang diikutsertakan ke dalam proses perancangan dan pembuatan aplikasi. Sejauh ini, desain antarmuka aplikasi mobile kurang mempertimbangkan perspektif konsumen ke dalam proses perancangan. Perancangan m-commerce tidak hanya memikirkan kemudahan, kenyamanan, dan kelebihan dari fitur canggihnya. Isu penting lainnya adalah bagaimana secara psikologis membuat seseorang dari kelompok sosial tertentu terbujuk untuk menggunakannya. Sehingga, penelitian ini menggunakan kansei engineering Type I (KEPack) untuk mengetahui hubungan respon afektif terhadap aplikasi B2C mcommerce berdasarkan jenis kelamin dan latar belakang studi. Dari hasil penelitian ini, dapat disimpulkan bahwa perbedaan jenis kelamin dan latar belakang studi pada subjek yang berpartisipasi dalam instrumen penelitian mempengaruhi hasil struktur kansei yang menjadi faktor penentu dalam desain afektif m-commerce. Kata kunci: affective evaluation, kansei engineering, mcommerce, user interface', 1, 'OPENALEX', '{"openalex": "https://openalex.org/W2908845995"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('37ca536f-b8ca-4892-a403-34490377b67e', 'Ontology-Based Social Media Talks Topic Classification (Twitter Case)', NULL, 2019, '2019-09-13', 'Fransisca Julia Kusuma Deviyanti; Sri Suning Kusumawardani; Paulus Insap Santosa', 'IJITEE (International Journal of Information Technology and Electrical Engineering)', 'JOURNAL', '10.22146/ijitee.46534', 'https://doi.org/10.22146/ijitee.46534', 'In the era of digital communication, the use of Twitter as a customer service has been widely encountered. Companies have started to develop strategies around effective use of Twitter, one of which was to identify problems that customers frequently complain about. Twitter, with its straightforward tweet characteristics, will certainly contain sentences with very specific and easily recognizable keywords. These characteristics can be used as a basis for classifying tweets into certain topics. With a help of ontology, classification with keywords can be done automatically. The purpose of this paper is to design an ontology used as a basis for classifying tweets into certain topics related to the 4G telecommunications network in Indonesia and to evaluate performance of proposed classifier model.', 1, 'OPENALEX', '{"doi": "10.22146/ijitee.46534", "openalex": "https://openalex.org/W2974306719"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('310524e9-38f2-468e-ac75-f0ba2e847476', 'Readiness Indicators of Human Resources Aspects for MOOC Implementation', NULL, 2019, '2019-07-01', 'Ertanto Yohan Khrysdianto; Sri Suning Kusumawardani; Paulus Insap Santosa', '2019 International Conference on Information and Communications Technology (ICOIACT)', 'JOURNAL', '10.1109/icoiact46704.2019.8938477', 'https://doi.org/10.1109/icoiact46704.2019.8938477', 'At present, the development of internet technology in Indonesia is very rapidly. The internet has been used in various fields, one of which is e-Learning in education. The application and implementation of e-Learning by each university are different. Today, a new e-learning model is being developed, namely MOOC. Generally, a new system requires readiness in its implementation so as not to fail. Based on previous research, the readiness of human resources has the lowest score, even though the readiness of human resources is one of the important factors in the implementation of e-Learning. The aim of this paper is the result of a preliminary study which outlines indicators of MOOC implementation readiness on human resources aspects. Classification, adoption, literature review, analysis development, and modification methods are carried out through papers published in international and national journals related to e-Learning readiness, human resources readiness and MOOC. The results of this study are components to measure the readiness of human resources, namely, motivation, knowledge, experience, and skills. These indicators can be adopted into the university environment to measure the readiness of MOOC implementation of human resources aspects.', 1, 'OPENALEX', '{"doi": "10.1109/icoiact46704.2019.8938477", "openalex": "https://openalex.org/W2997912530"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9243e70f-2b5c-47f2-b602-f31472319e0f', 'The Crowdsourcing Method to Normalize “Bahasa Alay”, a Case of Indonesian Corpus', NULL, 2020, '2020-11-03', 'Rianto Rianto; Achmad Benny Mutiara; Eri Prasetyo Wibowo; Paulus Insap Santosa', '2020 Fifth International Conference on Informatics and Computing (ICIC)', 'JOURNAL', '10.1109/icic50835.2020.9288534', 'https://doi.org/10.1109/icic50835.2020.9288534', 'In verbal communication, people use sentences that can be classified into two categories, namely formal and non- formal. The former meets the grammatical standard as prescribed by linguistic rules of the language, while the latter deviates it. In daily communication, however, non-formal sentences are more intensively used because they are more practical and easier to understand. With this deviation, nonformal sentences cause problems in linguistic computation because most linguistic computations use formal languages that already have standard rules. This research aims to develop an Indonesian closed corpus related to airline ticket reservations. The data used to develop the corpus are taken from conversations between customer service staff and consumers in airline ticket reservations. This is a preliminary study to propose and develop a chatbot in airline ticket reservations. The result of this study is the Indonesian closed corpus related to airline ticket reservations to determine the right response for consumers.', 1, 'OPENALEX', '{"doi": "10.1109/icic50835.2020.9288534", "openalex": "https://openalex.org/W3114948931"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('530b7a47-0068-4f73-b41d-867665151ef2', 'Confirmation of Personality Types Using Visual Evoked Potential with User Interface Design Stimulus – A Research Plan', NULL, 2021, '2021-09-25', 'Ilham Perdana; Paulus Insap Santosa; Noor Akhmad Setiawan; Supra Wimbarti', 'Turkish Online Journal of Qualitative Inquiry', 'JOURNAL', NULL, 'https://www.tojqi.net/index.php/journal/article/view/6428', 'Identification of personality types is one of the activities commonly carried out by organizations to select human resources (HR). The personality type is adjusted to the job description that must be done by the selected individual. Maximum individual performance is the reason why personality tests are needed by organizations. The personality test method commonly used is to get a response in the form of a written answer from a questionnaire. Another method is proposed which takes into account individual facial expressions. Both methods use an iterative process to achieve consistency in individual responses. The repetition process is carried out with a limited frequency and the implementation takes a long time. This limited frequency has the potential to cause errors in inferring personality types. Inconsistent responses from individuals identified with personality types make the reliability level of personality tests less than optimal. Reliability that is not optimal can have a negative impact on decision-making in the selection of selected human resources. Based on these problems, this study proposes the use of electroencephalography (EEG) to confirm individual personality types. The EEG used is a stimulated wave because the individual sees a visual form known as Visual Evoked Potential (VEP). Visual stimulus is the user interface design of a job support application. The stimulus is generated with a lot of frequency so that it can be relied on in knowing the consistent response. It is hoped that the recorded VEP pattern will reach a very good permanent level. An excellent permanent VEP rate can be determined by comparing between recording sessions. The permanent level of the VEP becomes the actual individual VEP. VEP comparisons between individuals will be compared for the classification process. The resulting classification is expected to show that individual VEP corresponds to each individual''s personality type from the results of personality tests carried out by conventional methods.', 1, 'OPENALEX', '{"openalex": "https://openalex.org/W3202187569"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('ba41e56c-fa61-411c-a7b7-0d24e7d3b0f7', 'Observing Cognitive Load During Online Learning with Various Task Complexities: An Eye Tracking Approach', NULL, 2022, '2022-10-19', 'Paulus Insap Santosa; Suatmi Murnani; Prabaria Vesca Yulianandra; Sunu Wibirama', 'International Journal of Innovation and Learning', 'JOURNAL', '10.1504/ijil.2023.10051446', 'https://doi.org/10.1504/ijil.2023.10051446', NULL, 1, 'OPENALEX', '{"doi": "10.1504/ijil.2023.10051446", "openalex": "https://openalex.org/W4306855702"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('36ceacce-a979-4d5c-87cf-6ff69487860f', 'The Effects of Surprising Events on Promoting Social Change in Unwinnable Persuasive Games', NULL, 2023, '2023-04-03', 'Reza Giga Isnanda; Paulus Insap Santosa; Rudy Hartanto', 'International Journal of Serious Games', 'JOURNAL', '10.17083/ijsg.v10i1.530', 'http://dx.doi.org/10.17083/ijsg.v10i1.530', 'Surprising events can be beneficial for unwinnable persuasive games, especially since they can evoke players to reflect on their failure to win the game. Despite its presence in some titles, the usage of surprising events still lacks empirical support. This study aims to gain insight into it by comparing the effects of revealing the game’s context from the beginning to delaying it until the game ends. In addition, we also examine the interaction effects with playing duration since it is possible that longer playtime will lead to smaller effects for a game with surprising events, whereas longer playtime will result in greater effects for a game without surprising events. To do so, we conducted a 2 x 2 factorial between-subject experiment with an additional no-treatment control group. The results suggest that delaying the revelation to create a surprising event can promote the same level of donation from players, regardless of their playing time. On the other hand, longer playtime is important if players know the context from the beginning. Additional results about the effect of playing duration on donation and willingness to help were also discussed in this paper.', 1, 'OPENALEX', '{"doi": "10.17083/ijsg.v10i1.530", "openalex": "https://openalex.org/W4362580788"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('fbdfe0b5-e339-41ec-910b-d611ec490117', 'Faktor-Faktor Determinan Pemanfaatan E-Government oleh Masyarakat di Kota Probolinggo', NULL, 2023, '2023-06-26', 'Andre Firmansyah; Paulus Insap Santosa; Puguh Prasetya Utomo', 'Journal of Governance and Social Policy', 'JOURNAL', '10.24815/gaspol.v4i1.31425', 'https://doi.org/10.24815/gaspol.v4i1.31425', 'E-government implementation can facilitate public participation in terms of information disclosure, public services, as well as complaints and aspirations in formulating policies to achieve good governance. So it is necessary to analyze the determinant factors of e-government usage by citizens in th etechnical and social aspects. This research was conducted in the Probolinggo City, Indonesia as one of the cities that has implemented e-government system in public administration. This study uses evaluation models that integrates information system factors from the DeLone McLean model, social capital factors, and digital literacy factors. Data was collected through distributing questionnaires to respondents who have participated electronically with a sample of 210 people. This study uses quantitative methods with analytical techniques using Structural Equation Modeling - Partial Least Square (SEM-PLS). The results of this study indicate the influence of information system factors, social capital factors and digital literacy factors on use of e-government. As well as measuring the effect of citizen satisfaction and perceived usefullness on the continuance intention to use and recommend it. These results can be a new insight in implementing citizen-centered e-government to realize good governance', 1, 'OPENALEX', '{"doi": "10.24815/gaspol.v4i1.31425", "openalex": "https://openalex.org/W4383198703"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('30bb1e08-676b-42a8-a04c-baa6507721fc', 'Systematic Literature Review: Automated Text Summarization for Indonesian Language', NULL, 2023, '2023-08-31', 'Rizka Irianty Naharuddin; Paulus Insap Santosa; Teguh Bharata Adji', NULL, 'JOURNAL', '10.1109/icitacee58587.2023.10277395', 'http://dx.doi.org/10.1109/icitacee58587.2023.10277395', 'Text and document summarization machines is becoming more and more indispensable following the increase in the amount of digital information available both online and offline. Text summarization machines are needed to obtain shorter text without losing the essence of the document. This paper provides an overview of recent research on automatic text summarization for Indonesian documents. This review presents various text summarization techniques, datasets, categorization, challenges, and evaluation methods that can be used as a baseline in the development of an appropriate method and evaluation measure. This study is conducted with Systematic Literature Review (SLR) to get a more systematic and structured results with a measurable approach. The results of this paper can be used as a tool to help identifying opportunities to contribute within text summarization field.', 1, 'OPENALEX', '{"doi": "10.1109/icitacee58587.2023.10277395", "openalex": "https://openalex.org/W4387712998"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e9ac021f-bb7b-4f76-8610-18598adf830e', 'Handling Data Imbalance Using Text Augmentation For Classifying Public Complaints', NULL, 2023, '2023-10-04', 'Muhammad Rizqi Indrahimawan; Paulus Insap Santosa; Teguh Bharata Adji', NULL, 'JOURNAL', '10.1109/ic3ina60834.2023.10285813', 'http://dx.doi.org/10.1109/ic3ina60834.2023.10285813', 'As a public service provider, the local government is obliged to provide services for every citizen, including complaint services as a public response to the services provided. Through the E-Lapor Jogja Istimewa service of Diskominfo DIY, the public can submit complaints or problems that occur online. The classification of complaints is an integral part of accelerating the government’s response to resolving problems. Automatic classification is expected to reduce errors in the selection of complaint categories. One of the problems in classification is data imbalance which causes low classification performance. Therefore, oversampling methods are used to balance the data and improve classification performance. This research uses text augmentation-based oversampling with the Synonym Replacement technique. With the SVM method, the results show that Synonym Replacement can improve classification performance with an accuracy value of 0.84 and an f1-score of 0. S2. This result is better than the SMOTE method which produces an accuracy value of 0.77 and an f1-score of 0.70.', 1, 'OPENALEX', '{"doi": "10.1109/ic3ina60834.2023.10285813", "openalex": "https://openalex.org/W4387735147"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d4e708a8-7b57-4bb5-8dd6-aa625c0e5389', 'Optimizing Sisnaker Training Services: A Holistic Approach with SEO, Web Analytics, and SUS', NULL, 2023, '2023-11-29', 'Arif Budi Setiawan; Paulus Insap Santosa; Ridi Ferdiana', NULL, 'JOURNAL', '10.1109/icitisee58992.2023.10404497', 'http://dx.doi.org/10.1109/icitisee58992.2023.10404497', 'The proposed research aims to optimize Sisnaker Training Services by integrating Search Engine Optimization (SEO), Web Analytics and System Usability Scale (SUS) evaluation methods. The methodology used in this research involves three web evaluation methods, namely SEO, Web Analytics, and SUS. To evaluate SEO and Web Analytics, this research uses Semrush and Ubersuggest as analysis tools. Meanwhile, to evaluate usability, this research uses SUS. The data collection process includes collecting data related to content, structure and metadata, identifying web usage patterns, user behavior and factors that influence the quality of the Sisnaker training service website. The SUS questionnaire was distributed to selected respondents via WhatsApp broadcast, and the collected data was processed using Python to determine the mean, median, standard deviation, margin of error and confidence interval. The integration of the results of these three web evaluation methods provides comprehensive recommendations on how to optimize Sisnaker training services effectively and efficiently. The results of the analysis show that the average usability score for the Sisnaker training service is 64.19, which shows that the system is quite good in terms of usability. However, several areas requiring improvement were identified, such as website navigation and content layout. By using these materials and methods, this research provides a more comprehensive understanding of how to optimize Sisnaker training services, as well as more appropriate recommendations for improving the quality of these services. The proposed approach offers novelty in integrating these three aspects of evaluation, potentially having a significant impact on this field. Additionally, the results of this research can help organizations achieve their marketing goals while ensuring their online presence remains strong and competitive.', 1, 'OPENALEX', '{"doi": "10.1109/icitisee58992.2023.10404497", "openalex": "https://openalex.org/W4391409478"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f8c4bfeb-3364-463b-a20e-6cc1518bd577', 'Interface design features and evaluation of batik 4.0 mobile application', NULL, 2024, '2024-02-16', 'Nova Suparmanto; Anna Maria Sri Asih; Andi Sudiarso; Paulus Insap Santosa', 'Indonesian Journal of Electrical Engineering and Computer Science', 'JOURNAL', '10.11591/ijeecs.v33.i3.pp1604-1619', 'https://doi.org/10.11591/ijeecs.v33.i3.pp1604-1619', 'The use of information and communication technology could increase the quantity and quality of small medium enterprises (SME) production, including batik industry. This study focuses on the development of batik 4.0, a custom batik mobile-based interface that makes it easier for customer which can be used to quickly produce high-quality digital batik designs. The findings of this study simplify the ordering process for potential clients who want to acquire custom batik designs. Ease of transactions, namely down payments (DP) where users can make advance payments, so that users are relieved in terms of payment transactions. In designing mobile devices, applications, and user interfaces (UI), it is important to consider the user experience (UX). This paper focuses on UX design rooted in the user-centered design (UCD) approach, placing emphasis on understanding user requirements and prioritizing empathy for users. This ensures the recognition of user needs and the creation of a high-fidelity prototype. Then it was validated by the UI experts to identify problems and user difficulties in interacting with the UI. The experts responded positively towards the application and suggest for prototype improvement. Lastly, UX testing; based on the user experience questionnaire (UEQ)-S benchmark results, the batik 4.0 mobile is included in the “Excellent” category.', 1, 'OPENALEX', '{"doi": "10.11591/ijeecs.v33.i3.pp1604-1619", "openalex": "https://openalex.org/W4391906951"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b07a5577-a6da-4bf8-aeab-4adaf3467560', 'SOLVING DIFFERENT LANGUAGES PROBLEM (PORTUGUESE, ENGLISH and BAHASA INDONESIA) IN DIGITAL LIBRARY WITH ONTOLOGY', NULL, 2013, '2013-05-15', 'Herlina Jayadianti; Carlos Sousa Pinto; Lukito Edi Nugroho; Paulus Insap Santosa; Wahyu Widayat', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/36092/', 'In this paper we will present in how digital library work
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f05f2170-69d3-4d52-ad22-519f3cfe9ea5', 'Student''s Attitude toward Webcast Lecture: An Online Survey Result.', NULL, 2004, '2004-01-01', 'Paulus Insap Santosa', 'Information Integration and Web-based Applications & Services', 'JOURNAL', '10.1016/0922-4106(94)90037-x', 'https://dblp.uni-trier.de/db/conf/iiwas/iiwas2004.html#Santosa04', 'We investigated the effects of the platelet activating factor (PAF) receptor antagonists, SM-12502 ((+)-cis-3,5-dimethyl-2-(pyridyl)- thiazolidin-4-one hydrochloride), WEB-2086 (3-(4-(2-chlorphenyl)-9-methyl-6H-thieno(3,2-f)-(1,2,4)triazolo(4, 3- a)(1,4)diazepin-2-yl)-1-(4-morpholinyl)-1-propanone) and RP-48740 (3-(3-pyridyl)-1H,3H-pyrrolo[1,2-c]thiazole-7-carboxamide) on the PAF-mediated activation of rat neutrophils. These antagonists inhibited PAF-induced degranulation and chemotaxis in neutrophils at a dose that correlated well with PAF-induced platelet aggregation based on the statistical analyses. N-formyl-L-methionyl-L-leucyl-L- phenylalanin (fMLP)-induced cellular responses were also inhibited by the PAF receptor antagonists, but their inhibitory potencies did not correlate with those for PAF-induced platelet aggregation. In addition, the doses required for inhibition were higher than those required against PAF-induced responses (i.e. IC50 ratio of WEB-2086, SM-12502 and RP-48740 in fMLP-induced/PAF-induced degranulation was 40.0, 2.8 and 5.6, respectively). PAF receptor antagonists inhibited inositol 1,4,5-triphosphate production and the release of Ca2+ from the intracellular store site after stimulation with PAF. In the fMLP-induced responses, PAF receptor antagonists did not inhibit IP3 production and Ca2+ release, but did inhibit transmembrane Ca2+ influx. These results suggest the presence of distinct PAF receptor subtype, to which exogenously added PAF binds, while endogenously produced PAF binds to the other. Intracellular PAF, which was produced by fMLP-stimulation, may play an important role in the late phase of signal transduction, and may participate in the transmembrane Ca2+ influx.', 1, 'OPENALEX', '{"doi": "10.1016/0922-4106(94)90037-x", "openalex": "https://openalex.org/W7895770"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('66fcce75-39db-4080-8247-d8ff91b292c1', 'Leaf Classification Using Shape, Color, and Texture Features', NULL, 2013, '2013-11-20', 'Abdul Kadir; Lukito Edi Nugroho; Adhi Susanto; Paulus Insap Santosa', 'arXiv (Cornell University)', 'PREPRINT', '10.48550/arxiv.1401.4447', 'http://arxiv.org/abs/1401.4447', 'Several methods to identify plants have been proposed by several researchers. Commonly, the methods did not capture color information, because color was not recognized as an important aspect to the identification. In this research, shape and vein, color, and texture features were incorporated to classify a leaf. In this case, a neural network called Probabilistic Neural network (PNN) was used as a classifier. The experimental result shows that the method for classification gives average accuracy of 93.75% when it was tested on Flavia dataset, that contains 32 kinds of plant leaves. It means that the method gives better performance compared to the original work.', 211, 'OPENALEX', '{"doi": "10.48550/arxiv.1401.4447", "openalex": "https://openalex.org/W1530280161"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('7205d3c8-be30-4a29-8c7d-6a3e4c645c9a', 'Experiments of Distance Measurements in a Foliage Plant Retrieval System', NULL, 2013, '2013-11-20', 'Abdul Kadir; Lukito Edi Nugroho; Adhi Susanto; Paulus Insap Santosa', 'arXiv (Cornell University)', 'PREPRINT', '10.48550/arxiv.1401.3584', 'http://arxiv.org/abs/1401.3584', 'One of important components in an image retrieval system is selecting a distance measure to compute rank between two objects. In this paper, several distance measures were researched to implement a foliage plant retrieval system. Sixty kinds of foliage plants with various leaf color and shape were used to test the performance of 7 different kinds of distance measures: city block distance, Euclidean distance, Canberra distance, Bray-Curtis distance, x2 statistics, Jensen Shannon divergence and Kullback Leibler divergence. The results show that city block and Euclidean distance measures gave the best performance among the others.', 12, 'OPENALEX', '{"doi": "10.48550/arxiv.1401.3584", "openalex": "https://openalex.org/W1563946824"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('97029289-5ef6-45f0-98c8-1f0e36485030', 'Improving the Accuracy of Text Classification using Stemming Method, A Case of Informal Indonesian Conversation', NULL, 2020, '2020-08-17', 'Rianto Rianto; Achmad Benny Mutiara; Eri Prasetyo Wibowo; Paulus Insap Santosa', 'Research Square', 'PREPRINT', '10.21203/rs.3.rs-41431/v1', 'https://doi.org/10.21203/rs.3.rs-41431/v1', 'Abstract As social beings, humans always interact with one another using either verbal or non-verbal language. Language is an arbitrary sound-symbol system, which is used by members of a community to cooperate, interact, and identify themselves. Indonesian language is classified into two categories, namely formal and non-formal. The former meets the grammatical standard as prescribed by linguistic rules of the language, while the latter tends to deviate it. In daily communication, however, non-formal language is more intensively used because they are more practical and easier to understand. With this tendency, non-formal language causes problems in linguistic computation because most linguistic computations use formal standard languages that already have standardized rules. This research aims to develop a dynamic Indonesian closed corpus related to airline ticket reservation, namely "Incorbiz". The "Incorbiz" will be used as stemming tool for formal and non-formal Indonesian. Text processing, text normalization, and auto-update data were proposed in this research. This research also compared two stemming techniques i.e. "Sastrawi" and "Incorbiz" to process the 30-sample dataset. The algorithm used to process the classification is Support Vector Machine (SVM). The data used to develop the "Incorbiz" were taken from conversations between customer service staff and consumers in airline ticket reservations. The result showed that "Incorbiz" had higher accuracy than "Sastrawi" on 0.89 and 0.67, respectively.', 3, 'OPENALEX', '{"doi": "10.21203/rs.3.rs-41431/v1", "openalex": "https://openalex.org/W4212798443"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('369bf194-ea65-468c-82ef-795281c59070', 'Improving the Accuracy of Text Classification using Stemming Method, A Case of Non-formal Indonesian Conversation', NULL, 2020, '2020-11-17', 'Rianto Rianto; Achmad Benny Mutiara; Eri Prasetyo Wibowo; Paulus Insap Santosa', 'Research Square', 'PREPRINT', '10.21203/rs.3.rs-41431/v2', 'https://doi.org/10.21203/rs.3.rs-41431/v2', 'Abstract Stemming has long been used in data pre-processing in information retrieval, which aims to make affix words into root words. However, there are not many stemming methods for non-formal Indonesian text processing. The existing stemming method has high accuracy for formal Indonesian, but low for non-formal Indonesian. Thus, the stemming method which has high accuracy for non-formal Indonesian classifier model is still an open-ended challenge. This study introduces a new stemming method to solve problems in the non-formal Indonesian text data pre-processing. Furthermore, this study aims to provide comprehensive research on improving the accuracy of text classifier models by strengthening on stemming method. Using the Support Vector Machine algorithm, a text classifier model is developed, and its accuracy is checked. The experimental evaluation was done by testing 550 datasets in Indonesian using two different stemming methods. The results show that using the proposed stemming method, the text classifier model has higher accuracy than the existing methods with a score of 0.85 and 0.73, respectively. In the future, the proposed stemming method can be used to develop the Indonesian text classifier model which can be used for various purposes including text clustering, summarization, detecting hate speech, and other text processing applications.', 3, 'OPENALEX', '{"doi": "10.21203/rs.3.rs-41431/v2", "openalex": "https://openalex.org/W4254541043"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b6d90d6e-9b28-40f0-b296-fbb95a47545e', 'Improving the Accuracy of Text Classification using Stemming Method, A Case of Non-Formal Indonesian Conversation', NULL, 2021, '2021-01-11', 'Rianto Rianto; Achmad Benny Mutiara; Eri Prasetyo Wibowo; Paulus Insap Santosa', 'Research Square', 'PREPRINT', '10.21203/rs.3.rs-41431/v3', 'https://doi.org/10.21203/rs.3.rs-41431/v3', 'Abstract Background: Stemming has long been used in data pre-processing to retrieve information by tracking affixed words back into their root. In an Indonesian setting, existing stemming methods have been observed, and the existing stemming methods are proven to result in high accuracy level. However, there are not many stemming methods for non-formal Indonesian text processing. This study introduces a new stemming method to solve problems in the non-formal Indonesian text data pre-processing. Furthermore, this study aims to improve the accuracy of text classifier models by strengthening stemming method. Using the Support Vector Machine algorithm, a text classifier model is developed, and its accuracy is checked. The experimental evaluation was done by testing 550 datasets in Indonesian using two different stemming methods. Findings: The results show that using the proposed stemming method, the text classifier model has higher accuracy than the existing methods with a score of 0.85 and 0.73, respectively. These results indicate that the proposed stemming methods produces a classifier model with a small error rate, so it will be more accurate to predict a class of objects. Conclusion: The existing Indonesian stemming methods are still oriented towards Indonesian formal sentences, therefore the method has limitations to be used in Indonesian non-formal sentences. This phenomenon underlies the suggestion of developing a corpus by normalizing Indonesian non-formal into formal to be used as a better stemming method. The impact of using the corpus as a stemming method is that it can improve the accuracy of the classifier model. In the future, the proposed corpus and stemming methods can be used for various purposes including text clustering, summarizing, detecting hate speech, and other text processing applications in Indonesian.', 2, 'OPENALEX', '{"doi": "10.21203/rs.3.rs-41431/v3", "openalex": "https://openalex.org/W4233783780"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d68987a6-495d-47b4-b29f-125d234c572d', 'The Effect of Information Seeking Behavior on an Online Purchase Intention.', NULL, 2003, '2003-01-01', 'Paulus Insap Santosa', NULL, 'JOURNAL', NULL, 'http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.109.734', 'This paper reports a research in progress to study the effect of information seeking behavior on an online purchase intention. There are several strategies people use to find information in the Internet, whether information of interest is known or unknown. Furthermore, before conducting a search, people may have plans on how they will gather information or simply browsing the Web without having any plan at all. During an information seeking period, people may perceived more information than they first intended to have. These perceived information might, in turn, influence their willingness to buy things online. Perceived information considered on this study are secure payment system, product quality, after-sales support, and company trustworthiness. It combines Theory of Planned Behavior and Technology Acceptance Model. Survey will be conducted to test the hypotheses stated on this study.', 1, 'OPENALEX', '{"openalex": "https://openalex.org/W173028550"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('de392d13-1b3a-4cc2-bb16-ee7d749ebaa0', 'Grafika komputer dan antarmuka grafis : teknik penyusunan program aplikasi berbasis grafis yang profesional / P. Insap Santosa', NULL, 1996, '1996-01-01', 'Paulus Insap Santosa', NULL, 'JOURNAL', NULL, 'http://library.um.ac.id/free-contents/downloadpdf.php/buku/grafika-komputer-dan-antarmuka-grafis-teknik-penyusunan-program-aplikasi-berbasis-grafis-yang-profesional-p-insap-santosa-19885.pdf', NULL, 1, 'OPENALEX', '{"openalex": "https://openalex.org/W2345277905"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5b9f09d6-fa36-4a1e-8751-2944c40556db', 'Bagaimana mendayagunakan sepasang komputer', NULL, 1995, '1995-01-01', 'P. Chacha; Paulus Insap Santosa; Satoko Yasumoto; Morio Matsuzaki; Kensuke Okada; Yasuhiro Yamaguchi; Hoshiko Yoshida', NULL, 'JOURNAL', NULL, 'https://lib.pdii.lipi.go.id/index.php?p=show_detail&id=2153&keywords=', NULL, 1, 'OPENALEX', '{"openalex": "https://openalex.org/W3201411128"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f0351fc8-94e5-455a-96b4-9196966df7b5', 'Penggunaan metode hamming untuk pengendalian galat satu digit dalam sandi biner.', NULL, 1986, '1986-01-01', 'Ismadi Isran; Paulus Insap Santosa', 'Media Teknik', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal//detail.php?dataId=2372', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1007109175"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f0c71df6-b8f8-40db-bb18-394af30de74f', 'Struktur data menggunakan turbo pascal 6.0 / P. Insap Santosa', NULL, 1992, '1992-01-01', 'Paulus Insap Santosa', NULL, 'JOURNAL', NULL, 'http://library.um.ac.id/free-contents/download/pub/download-print2.php/19195.pdf', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1512484099"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('8de74300-2a16-4390-8be3-7a8053c82ab6', 'Prototipe Sistem Informasi Perpustakaan Pusat dan Daerah', NULL, 2015, '2015-07-31', 'Vieka Aprilya Intanny; Paulus Insap Santosa; Abdul Kadir', 'Jurnal Buana Informatika', 'JOURNAL', '10.24002/jbi.v6i3.437', 'https://doi.org/10.24002/jbi.v6i3.437', 'Abstract. Library has one of important resources to obtain information for research needs. The quality of a library information system needs to improve promptly because the information is needed quickly and accurately. In order to present library catalogue data that can be integrated with all central and local libraries, the library information system of Research and Development of the Human Resources Agency of the Ministry of Communication and Information Technology (Balitbang SDM Kominfo) needs to be well developed. The aim of this research is to design a prototype of library information system in order to present library data from central and local libraries accurately. Simulation tests are performed in eight research centers in the Ministry of Communication and Information Technology. The test is performed to analyze the perception of the users about the effectiveness of the system. The results show that the central library and information systems have good quality. Keywords: central library, local library, prototype, information systemÂ Abstrak. Perpustakaan merupakan sarana untuk mendapatkan literasi informasi melalui hasil penelitian yang telah dilakukan. Peningkatan kualitas layanan sistem informasi perpustakaan yang tersaji dengan cepat, akurat dan aktual mutlak diperlukan. Untuk itu dipandang perlu suatu perbaikan sistem perpustakaan Balitbang SDM Kominfo agar dapat menyajikan data perpustakaan yang dapat terintegrasi antara perpustakaan pusat dan perpustakaan daerah. Penelitian ini bertujuan untuk merancang prototipe suatu sistem informasi perpustakaan pusat dan daerah agar data perpustakaan pusat dan daerah dapat tersaji dengan cepat dan akurat. Pengujian dilakukan dengan simulasi sistem di delapan balai Kominfo. Pengujian ini bertujuan untuk menganalisis persepsi administrator pusat dan administrator daerah mengenai efektivitas sistem. Hasil pengujian menunjukkan bahwa sistem informasi perpustakaan pusat dan daerah memiliki kualitas yang baik. Kata Kunci: perpustakaan daerah, perpustakaan pusat, prototipe, sistem informasi', 0, 'OPENALEX', '{"doi": "10.24002/jbi.v6i3.437", "openalex": "https://openalex.org/W1541161212"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('033ff6d4-e2a2-46be-914b-c5cbf0544757', 'APLIKASI "KANTIN KEJUJURAN" BERBASIS SMART CARD', NULL, 2013, '2013-08-05', 'Diana Aristiawan Setyo Wibowo; Paulus Insap Santosa', 'Proceedings of KNASTIK', 'JOURNAL', NULL, 'https://ti.ukdw.ac.id/ojs/index.php/proceedings/article/view/199', 'Aplikasi “Kantin Kejujuran” berbasis smart card merupakan aplikasi berbasis desktop yang dibuat dengan menggunakan Borland Delphi, Basis data MySQL dan teknologi smart card. Dalam aplikasi ini, smart card digunakan sebagai kartu pembayaran. Pengguna perlu mendepositkan uangnya agar dapat melakukan transaksi pembelian. Smart card menyimpan informasi pengguna yang digunakan untuk proses autentikasi serta menyimpan informasi saldo. Aplikasi yang dikembangkan masih sebatas prototype dan belum dihubungkan ke sistem pembayaran yang ada. Aplikasi “Kantin Kejujuran” berbasis smart card ini diharapkan dapat memberikan kemudahan dan kenyamanan pembeli dalam melakukan proses pembelian serta memberikan keamanan pada proses autentikasi.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1609761293"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('61dd1b7c-45ef-48c5-a020-e52ecc7cd0c1', 'Pengelolaan Tempat Parkir Berbasis Radio Frequency Identification dan WonderwareIn Touch', NULL, 2010, '2010-01-01', 'Fransiscus Aditya Utama Wijaya; Paulus Insap Santosa; Rudy Hartanto', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12021', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W161960452"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('86cabd9b-8d82-4889-b132-117aab464191', 'PENGELOLAAN EMAIL PADA PENGEMBANGAN PERANGKAT LUNAK BERSAMA', NULL, 2013, '2013-08-05', 'Giovanni Yoko Kristianto; Paulus Insap Santosa', 'Proceedings of KNASTIK', 'JOURNAL', NULL, 'https://ti.ukdw.ac.id/ojs/index.php/proceedings/article/view/183', 'Komunikasi yang terstruktur sangat diperlukan oleh sebuah tim pengembang perangkat lunak. Berlangsungnyakomunikasi, khususnya yang menggunakan email, yang terstruktur membuat kelompok pengembang perangkat lunak dapatmengelola proyek yang diikutinya dengan lebih baik. Untuk mengelola komunikasi antar anggota tim pengembang, makadikembangkan sebuah aplikasi manajemen komunikasi email. Aplikasi ini merupakan aplikasi dengan arsitektur tiga tier.Ketiga tier ini terdiri atas presentation tier yang dikembangkan menggunakan VSTO, logic tier yang dikembangkanmenggunakan teknologi WCF, dan data tier yang dikembangkan menggunakan ADO.NET. Aplikasi manajemen komunikasiemail dirancang untuk dapat mendukung beberapa kegiatan, yaitu pembuatan proyek baru, penyetujuan dan penolakantawaran proyek, penambahan dan pengurangan partisipan, pengiriman laporan dan umpan balik, dan pengamatan detailproyek. Pengujian dilakukan pada tiga buah komputer pada sebuah jaringan lokal. Masing-masing komputer tersebutmemiliki peran sebagai komputer klien, server web, dan server basis data. Hasil pengujian menunjukkan bahwa semua fiturdari aplikasi manajemen komunikasi email telah berjalan dengan baik.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1680686974"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c39d6f43-9478-4a6c-b07b-59ee26b600a5', 'Improved Tracking Capabilities With Collaboration Multimarker Augmented Reality', NULL, 2014, '2014-12-04', 'Fendi Aji Purnomo; Paulus Insap Santosa; Rudy Hartanto', NULL, 'JOURNAL', NULL, 'http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.1019.5802', 'Abstract — The most common problem in Augmented Reality (AR) is the inability of detecting marker in different angle to show the expected virtual object. This study has been conducted to improve the ability reading / tracking in order to overcome the inability of AR in marker tracking for different angle. The method is to find the angle of the tracking error with rotation. Based on found angle of each corner and then registering the target image to the same virtual object. The marker is a 3D real object (marker-less) which captured into movie to produce 3D objects with the same condition. The conversion of the target image into multi marker using Vuforia. Testing is conducted with angle tracking variation to the emergence of the virtual object. The result of this study stated that the reading ability can be done by the application of AR which is virtual object appear for tracking variations for angle between 0 and 360.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1703813216"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b3ac08bc-4c2e-4e9d-8b46-645873018306', 'Model Sistem Akuisisi Data Multiplatform Menggunakan Aplikasi Antarmuka Pengguna Berbasis Bahasa Pemrograman Processing', NULL, 2013, '2013-10-24', 'Arief Hendra Saptadi; Paulus Insap Santosa; Bambang Sutopo', NULL, 'JOURNAL', NULL, 'http://siskom.undip.ac.id/citacee/index.php/citacee/2013/paper/view/80', 'Sistem akuisisi data terdiri dari komputer, perangkat akuisisi data dan rangkaian sensor. Data yang diperoleh dari perangkat akuisisi data untuk selanjutnya ditampilkan dan disimpan pada komputer melalui suatu aplikasi antarmuka pengguna (user interface application). Pengembangan aplikasi tersebut pada umumnya dilakukan melalui perangkat proprietary, yang memunculkan isu ketergantungan pada vendor, implementasi yang terbatas pada platform tertentu dan biaya lisensi. Penelitian ini bertujuan untuk mengembangkan sebuah model sistem akuisisi data multi platform, bebas-lisensi, menggunakan aplikasi antarmuka pengguna, berbasis bahasa pemrograman Processing. Sistem terdiri dari mikropengendali ATMEL ATmega328P, sensor DHT11 (untuk pengukuran suhu dan kelembaban) dan aplikasi Processing. Dari hasil pengujian yang dilakukan pada platform Linux (Ubuntu 12.04) dan Windows (Windows 7), aplikasi antarmuka pengguna telah dapat menerima data dari perangkat akuisisi data via komunikasi serial, memvisualisasikan data dan melakukan penyimpanan dalam bentuk arsip teks berformat CSV (Comma-Separated Values).', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1761442946"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('99dc7976-e7b1-4e4a-8ea9-88cf07c44d80', 'First Observations from Reflective Learning on a Knowledge Repository', NULL, 2005, '2005-05-14', 'Gee Kin Yeo; Paulus Insap Santosa; J. B. Foo; Pei-Chin Low', 'National University of Singapore', 'JOURNAL', NULL, 'http://scholarbank.nus.edu.sg/handle/10635/42803', 'Proc. Int. Conf. on Computers in Education 2005: "Towards Sustainable and Scalable Educational Innovations Informed by the Learning Sciences"- Sharing Research Results and Exemplary Innovations, ICCE', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1839356869"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('42370651-39f2-43bf-933b-ec27b7bffdd2', 'MELIBATKAN SISWA DALAM KONTEN PEMBELAJARAN FISIKA BERBASIS WEB FISIKA DI SMU: PERSPEKTIF SOCIAL LEARNING THEORY (SLT) DAN TASK TECHNOLOGY FIT (TTF)', NULL, 2015, '2015-01-01', 'Hera Susanti; Paulus Insap Santosa; Rudy Hartanto', 'Prosiding SNST Fakultas Teknik', 'JOURNAL', NULL, 'https://publikasiilmiah.unwahas.ac.id/index.php/PROSIDING_SNST_FT/article/download/1162/1268', 'Fiska merupakan pelajaran yang dianggap sulit oleh sebagian siswa SMA. Pembelajaran fisika berbasis web merupakan salah satu media pembelajaran untuk menunjang pembelajaran bagi siswa agar materi belajar dapat diperoleh siswa kapan saja dan dimana saja. Namun untuk menarik perhatian/atensi siswa dan mengingat materi yang telah dipelajari memerlukan proses yang rumit. Dengan membiarkan siswa terlibat dalam konten pembelajaran fisika berbasis web, maka siswa akan dapat memahami tentang apa yang mereka inginkan dalam konten pembelajaran fisika berbasis web sehingga materi yang telah dipelajari dapat diendapkan dalam memori (retensi), sehingga diharapkan mampu meningkatkan performa belajar siswa. Metodelogi yang diusulkan menyarankan berbagai kemungkinan baru untuk kerjasama yang kreatif dalam lingkungan pembelajaran fisika berbasis web untuk pendidikan yang lebih baik . Social Learning Theory (SLT) digunakan untuk mengevaluasi kecukupan pengembangan konten pembelajaran fisika berbasis web pada kebutuhan kognitif siswa. Proses pembelajaran berdasarkan SLT yang terdiri dari atensi dan retensi memiliki pengaruh terhadap konstrak Task Technology Fit (TTF), yaitu utilisasi pembelajaran fisika berbasis web, dan utilisasi memiliki pengaruh yang positif terhadap performa siswa. Hasil penelitian metode campuran ini akan berguna dalam menilai efek web based learning fisika pada kognitif siswa dan hasil afektif dalam pengaturan pendidikan. Kata kunc i: melibatkan siswa , teori pembelajaran sosial, kesesuaian tugas-teknologi, pembelajaran fisika berbasis web', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1894803996"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e990df88-5f75-4c38-968c-debe9d714845', 'PURWARUPA APLIKASI PENDAFTARAN KTP BERGERAK', NULL, 2013, '2013-08-07', 'Fathahillah Fathahillah; Paulus Insap Santosa; Rudy Hartanto', 'Proceedings of KNASTIK', 'JOURNAL', NULL, 'https://ti.ukdw.ac.id/ojs/index.php/proceedings/article/view/255', 'SIAK (Sistem Informasi Administrasi Kependudukan) telah diimplementasikan di Kolaka selama beberapa tahun. Namun, dalam pemanfaatannya masih belum maksimal. Tujuan dari penelitian ini adalah untuk merancang prototipe aplikasi mobile government yang akan memungkinkan warga negara untuk mengajukan permohonan KTP baru atau perpanjang jarak jauh dengan menggunakan telepon seluler. Desain prototipe ini menggunakan teori UML dan pengujian sistem dilakukan dengan metode memasukkan segala kemungkinan sebagai input sistem. Prototipe diimplementasikan dengan menggunakan PHP dan MySQL . Karena sistem ini diimplementasikan dengan menggunakan WAP , untuk menjalankan aplikasi ini ponsel yang digunakan harus mendukung minimal WAP 1.2.1 dan resolusi layar minimal 320 x 240 piksel. Pelayanan dengan menggunakan prototipe aplikasi mobile government versi WAP ini mampu memberikan kemudahan bagi masyarakat untuk mendapatkan proses pelayanan KTP. Dari manapun mereka berada dan kapan pun waktunya, masyarakat dapat langsung mendapatkan pelayanan tanpa harus datang langsung ke kantor kelurahan atau kecamatan.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1952288635"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b9936c3c-76dd-4375-9a1c-bef7fc5b9e6e', 'Adding synonyms to concepts in ontology to solve the problem of semantic heterogeneity', NULL, 2015, '2015-07-31', 'Herlina Jayadianti; Lukito Edi Nugroho; Paulus Insap Santosa; Wahyu Widayat', 'International Journal of Advances in Intelligent Informatics', 'JOURNAL', '10.26555/ijain.v1i2.19', 'https://doi.org/10.26555/ijain.v1i2.19', 'Nowadays many department (community) are thinking how to get more knowledges and metadata by linking more systems from other community. There are great challenges to make all systems organizing knowledge and sharing metadata – to make it easy searched, indexed and used in different context. In this paper we will focus on metadata in specific domain - ‘Poverty’2. Regardless of the various definitions of poverty, in this paper we will focus on managing metadata in “Poverty” with many different terms therein. Ontology Mapping is the process of relating similar concepts or relations from different sources through some equivalence relation. Mapping allows finding correspondences between the concepts of two ontologies. If two concepts correspond, then they mean the same thing or closely related things. Currently, the mapping process is regarded as a promise to solve the problem between ontologies since it attempts to find correspondences between semantically related entities that belong to different ontologies. It takes as input two ontologies, each consisting of a set of components (classes, instances, properties, rules and axioms). Based on the presented reasons, we believe that ontologies with common terms and common concepts are very important in a metadata sharing process.', 0, 'OPENALEX', '{"doi": "10.26555/ijain.v1i2.19", "openalex": "https://openalex.org/W2138317201"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d22665d2-035d-408d-8e14-b56b24a72948', 'Ontologi Sistem Penilaian E-Learning Berbasis Kompetensi', NULL, 2011, '2011-01-02', 'Desi Windisari; Sri Suning Kusumawardani; Paulus Insap Santosa', 'Indonesian Journal of Biotechnology (Universitas Gadjah Mada)', 'JOURNAL', NULL, 'http://jurnal.ugm.ac.id/mft/article/view/2042', 'Automation grading on e-Learning assessment helps educators in assessing the results of the exam. In a previous research, automation grading vaue jus in the form of numbers, not performed a review the achievement of competency standards. In this research we developed assessment system ontology design fo e-learning base competence. This propose ontology design models the relation between matter and competence then made the rule for the calculation of achievement students against each competency and make recommendations to the student passing the exam. From the test results with the protege show that ontology design can grade the assessment and give recommendations to the student passing the exam, in accordance with the rules made. Keywords : Ontology, assessment e-Learning, Automation grading.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2159646561"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3f9a8f4a-b297-470b-8982-bd53f74bff85', 'Dasar-dasar Pemrograman Pascal - Teori dan Pemrograman Terapan', NULL, 1997, '1997-01-01', 'Paulus Insap Santosa', NULL, 'JOURNAL', NULL, 'https://lib.pdii.lipi.go.id/index.php?p=show_detail&id=456339&keywords=', 'Buku ini membicarakan tentang bahasa pemrograman Pascal dari tingkat paling dasar sampai menengah, dengan contoh-contoh programnya disajikan menggunakan Turbo Pascal. Pembahasan dimulai dari tipe-tipe data yang ada dalam Pascal sampai dengan perubahan tentang file dengan berbagai macam variasi. Dengan adanya contoh-contoh program dari yang paling sederhana meningkat ke persoalan yang lebih rumit, penulis berharap agar pemahaman terhadap Pascal bisa lebih mudah. Program dalam buku ini dapat dikembangkan sesuai kebutuhan.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2215898767"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('660f2d4c-faa6-4bbd-900c-de3a636cad7d', 'PEMANFAATAN DUBLIN CORE METADATA TERM DALAM PENGEMBANGAN PERPUSTAKAAN DIGITAL BERBASIS SEMANTIK', NULL, 2014, '2014-01-01', 'Herlina Jayadianti; Juwairiah Juwairiah; Lukito Edi Nugroho; Paulus Insap Santosa; Wahyu Widayat', 'Seminar Nasional Informatika (SEMNASIF)', 'JOURNAL', NULL, 'http://jurnal.upnyk.ac.id/index.php/semnasif/article/download/1033/987', 'Pemanfaatan metadata yang disediakan secara online, sebagai contoh metadata dalam dublin core, memiliki pengaruh yang sangat besar dalam pertukaran informasi digital saat ini. Galeri, Perpustakaan, Arsip, Museum saat ini mulai membuka data dalam menyamakan penemuan standar yang lebih baik bagi sumber daya elektronik dimasa depan.Temu kembali informasi bersejarah menjadi tujuan yang paling utama. Dublin Core adalah satu set metadata yang terdiri dari 15 set elemen telah dibangun untuk mendukung temu kembali informasi perpustakaan dengan lebih mudah. Dublin core term telah terstandarmelalui sebuah konsensus internasonal danpenggunaannya lebih sederhana dibanding MARC dalam pengelolaan data di perpustakaan. Oleh karenanya perpustaaan dan museum saat ini mulai menggunakan kosakata standar dari Dublin Core – hal ini dilakukan untuk mendukung wacana perpustakaan dengan akses yang terbuka. Tujuan dari penulisan ini adalah untuk mengimplementasikan 15 term dalam Dublin Coredalam studi kasus perpustakaan serta mengujinya melalui uji validator RDF.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2224683334"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('bb2263dd-2c54-4e38-ade5-f4a10b6129fc', 'RANCANG BANGUN MODEL PERANGKAT AKUISISI DATA PORTABEL BERBASIS MIKROPENGENDALI ATMEGA8L', NULL, 2013, '2013-01-19', 'Arief Hendra Saptadi; Paulus Insap Santosa; Bambang Sutopo', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/577/553', 'Pengambilan data digital dari sebuah proses pengukuran membutuhkan suatu perangkat akuisisi data. Pencatat data (data logger) berbasis mikropengendali merupakan pilihan populer untuk aplikasi sederhana. Meski demikian perangkat tersebut pada umumnya tidak dapat diprogram ulang, memiliki arsitektur yang tertutup dan cenderung hanya berjalan pada sistem operasi tertentu sehingga menyulitkan pengembangannya maupun pengintegrasiannya ke sistem yang sudah ada. Penelitian ini bertujuan untuk merancang dan membangun suatu model perangkat akuisisi data berbasis mikropengendali ATmega8L. Berdasarkan hasil pengujian diketahui bahwa galat pengukuran suhu dan kelembaban ruangan, masingmasing adalah sebesar 7% ( 2C) dan (10%). Galat, khususnya untuk kelembaban (maksimal 5%) masih cukup tinggi. Perekaman data ke dalam EEPROM telah berhasil dilakukan tanpa kesalahan, baik untuk nilai maupun alamat memori. Komunikasi serial (USART) antara perangkat dengan PC, di Windows maupun Ubuntu telah dapat berjalan dengan baik. Bila menggunakan baterai, perangkat dapat beroperasi hingga 4 jam 40 menit. Perangkat juga telah dapat diprogram ulang melalui konektor ISP (In-System Programming). Diharapkan pada pengembangan selanjutnya dimensi fisik alat bisa diperkecil melalui optimasi tata letak komponen pada rangkaian atau penggunaan komponen surface mount, konsumsi daya diminimalkan menggunakan fasilitas Sleep pada mikropengendali dan akurasi pengukuran ditingkatkan dengan mengatur kembali pemasangan sensor.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2227657771"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('26edec97-559d-4aed-8d24-c05f4b4ef18d', 'IMPLEMENTASI ALGORITMA BEST PATH PLANNING UNTUK PENCARIAN RUTE TRANS JOGJA', NULL, 2014, '2014-01-01', 'Anik Budiati; Paulus Insap Santosa; W Wing Wahyu', 'Seminar Nasional Informatika (SEMNASIF)', 'JOURNAL', NULL, 'http://jurnal.upnyk.ac.id/index.php/semnasif/article/download/991/862', 'Untuk membantu mengatasi kemacetan di Yogyakarta, Pemda DIY menyediakan bus TransJogja sebagai sarana transportasi publik. Akan tetapi, masih banyak masyarakat yang memilih menggunakan kendaraan pribadi untuk bepergian. Salah satu hal yang menyebabkan masyarakat malas menggunakan transportasi publik adalah ketika mereka harus pergi ke suatu tempat, tetapi mereka tidak tahu bus jalur berapa yang harus dinaiki untuk sampai ke lokasi tersebut. Penelitian ini bertujuan membuat suatu aplikasi untuk merencanakan rute perjalanan dari suatu halte asal ke halte tujuan. Algoritma yang digunakan untuk penentuan rute adalah algoritma Best Path Planning. Pada algoritma ini, rute terpilih adalah rute dengan jumlah transfer paling sedikit dan jarak tempuh terpendek. Penelitian dimulai dari proses mengumpulkan data, melakukan perancangan aplikasi, kemudian mengimplementasikan rancangan tersebut menjadi sebuah aplikasi. Dari hasil uji coba, sistem berhasil menemukan rute terpendek dengan jumlah transfer seminimal mungkin.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2228111515"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b2c14803-1c14-4fa4-8821-daf3669f41ab', 'Adding Synonyms To A Concept In An Ontology', NULL, 2014, '2014-08-20', 'Herlina Jayadianti; Lukito Edi Nugroho; Paulus Insap Santosa; Wahyu Widayat; Carlos Alberta Baptista Sousa Pinto', 'International Conference on Electrical Engineering', 'JOURNAL', '10.11591/eecsi.1.363', 'https://journal.portalgaruda.org/index.php/EECSI/article/view/363', 'The purpose of this paper is to provide research based understanding of adding sinonyms to a concept in an ontology. We hypothesize that managing synonyms with a good taxonomy and a good integration process are good approaches to organize and share knowledge. This paper can give a discourse to a group of people in different societies that want to share data using different concepts in the same domain. We will generate a common set of terms based on the terms of several different storage devices, used by different societies, in order to make data retrieval independent of the different perceptions and terminologies used by those societies. We use ontologies to represent the particular knowledge of each society and integration techniques to find relations between terms used in those ontologies.', 0, 'OPENALEX', '{"doi": "10.11591/eecsi.1.363", "openalex": "https://openalex.org/W2290167618"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6b201050-b967-43cf-ad51-2594be793524', 'Computational Cost of Learning Vector Quantization Algorithm for Malaria Parasite Classification in Realtime Test', NULL, 2016, '2016-01-17', 'Iis Hamsir Ayub Wahab; Adhi Susanto; Paulus Insap Santosa; Maesadji Tjokronegoro', 'International journal of imaging and robotics', 'JOURNAL', NULL, 'http://ceser.in/ceserp/index.php/iji/article/view/4027', 'Analysis and interpretation of malaria parasite images were performed in which one of them was to obtain the parasite image patterns, thus it could be conducted classification process towards image based on its pattern. The parasite image pattern is different between one and another, this depends on parasite type. Differentiating between one image and another needs a feature for each pattern. This study, therefore, aimed to analyze and evaluate algorithms of learning vector quantization neural network for malaria parasite pattern recognition test in real time. The result of this study showed that the LVQ network classification method could recognize 92% object,. Algorithm time complexity for LVQ is O(n).', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2293744731"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('fb4a9385-adb1-4460-ace1-62c9ea0fda16', 'Interaksi manusia dan komputer / P. Insap Santosa; Editor FL Sigit Suyantoro', NULL, 2011, '2011-01-01', 'Paulus Insap Santosa', NULL, 'JOURNAL', NULL, 'http://library.um.ac.id/free-contents/downloadpdf.php/buku/interaksi-manusia-dan-komputer-p-insap-santosa-editor-fl-sigit-suyantoro-43083.pdf', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2300678368"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('bfb211a7-0ed4-460d-a494-3cb5bd35a17d', 'A declarative query language based on speech act theory for web systems', NULL, 2015, '2015-11-01', 'D. P. Bambang Purnomosidi; Lukito Edi Nugroho; Paulus Insap Santosa; Widyawan Widyawan', NULL, 'JOURNAL', '10.1109/icodse.2015.7436962', 'https://doi.org/10.1109/icodse.2015.7436962', 'The World Wide Wide provides an enormous resources to be utilized by human. There are many possibilities of their existence, from unstructured data (can only be processed by human), semi structured data (structured data inside unstructured data), and fully structured data. In this context, many web scraper software exist to fetch and extract those data from the Web. However, until now, those tools are meant to just help human to fetch web pages / resources. Therefore, while useful for human, they do not significantly contribute to automation. To enhance level of automation, we must combine pragmatic capabilities into client / web scraper (as service consumer) and server / web application (as service provider). In this paper we propose a declarative query language for service consumer and service provider interaction. To enable pragmatic capabilities, we use illocutionary act from speech act theory as interaction patterns. The declarative query language reside on the service consumer''s side while service provider provides resources to parse requests from service consumer and act accordingly. A prototype implementation of the declarative query language is presented.', 0, 'OPENALEX', '{"doi": "10.1109/icodse.2015.7436962", "openalex": "https://openalex.org/W2303709123"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f70e1ae7-a0e2-45cb-90e7-977263a47e5e', 'MANAGEMENT SUPPORT FOR SUCCESSFUL E-LEARNING IMPLEMENTATION', NULL, 2016, '2016-03-01', 'Paulus Insap Santosa; Wihardianto Setia Nugroho', 'INTED proceedings', 'JOURNAL', '10.21125/inted.2016.1764', 'https://doi.org/10.21125/inted.2016.1764', 'Appears in: INTED2016 Proceedings Publication year: 2016Pages: 3265-3273ISBN: 978-84-608-5617-7ISSN: 2340-1079doi: 10.21125/inted.2016.1764Conference name: 10th International Technology, Education and Development ConferenceDates: 7-9 March, 2016Location: Valencia, Spain', 0, 'OPENALEX', '{"doi": "10.21125/inted.2016.1764", "openalex": "https://openalex.org/W2328564999"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('750d174e-a247-42b8-9d60-bf93a0717db8', 'Context-Aware Mobile Learning Model for Traveler', NULL, 2015, '2015-10-01', 'Dadang Syarif Sihabudin Sahid; Lukito Edi Nugroho; Ridi Ferdiana; Paulus Insap Santosa', 'Advanced Science Letters', 'JOURNAL', '10.1166/asl.2015.6441', 'https://doi.org/10.1166/asl.2015.6441', NULL, 0, 'OPENALEX', '{"doi": "10.1166/asl.2015.6441", "openalex": "https://openalex.org/W2331304805"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2fe165d5-7c28-4e77-9bad-3be462d75aed', 'PEMODELAN KONTEKS DAN CONTEXT AWARENESS AVATAR DI DUNIA VIRTUAL', NULL, 2014, '2014-03-01', 'Muhammad Dedi Iskandar; Lukito Edi Nugroho; Paulus Insap Santosa', NULL, 'JOURNAL', NULL, NULL, 'Konteks avatar perlu dimodelkan secara utuh sehingga dapat digunakan dalam beragam skenario dunia virtual yang dinamis. Tool pemodelan yang digunakan harus dapat meminimalisir ambiguitas penafsiran pada pengembangan sistem selanjutnya, sehingga digunakanlah Mocha, suatu tool spesifikasi berbasis Ambient Calculus dan UNITY. Mocha dikembangkan sehingga dapat mengekspresikan situasi dimana dua atau lebih konteks terjadi secara konkuren. Situasi konteks konkuren memiliki bentuk situasi konteks yang unik pada dunia virtual dan tidak dapat dimodelkan oleh notasi konteks primitif.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2406402966"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('84784d33-3e73-4018-b180-4214842909c8', 'IMPLEMENTASI PERCEPTUAL USER INTERFACE PADA VIRTUAL MUSIC INSTRUMENT', NULL, 2016, '2016-02-22', 'Rouli Munthe; Paulus Insap Santosa; Ridi Ferdiana', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/view/1272', 'Dewasa ini, perkembangan teknologi semakin berkembang, tampilan antar muka menjadi tidak mudah didukung dengan kebutuhan pengguna. Oleh karena itu dibutuhkan perluasan area penggunaan, pekerjaan, dan pilihan yang dapat membuat antar muka menjadi lebih alami, intuitif dan tidak menganggu. Perceptual User Interface (PUI) menjadi salah satu fokus dari antar muka komputer yang membuat interaksi manusia dan komputer menjadi lebih nyata. PUI berusaha mengambil keuntungan kemampuan antara manusia dengan kemampuan persepsi mesin atau sistem. Pengembangannya dapat dilakukan dengan berbagai cara melalui teknologi seperti speech, vision, natural language, haptik, penalaran, serta lingkungan virtual musik, dengan memahami ekspetasi, batasan dan kemampuan persepsi dan semantik alami dari interaksi manusia. Oleh karena itu, makalah ini akan menunjukkan beberapa implementasi dari perceptual user interface pada virtual music instrument pada penelitian-penelitian sebelumnya sehingga dapat digunakan sebagai tambahan pengetahuan dan gagasan baru dalam mengembangkan strategi antar muka pengguna bagi penelitian-penelitian selanjutnya.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2427149435"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3f0c73a1-1281-442a-acaa-926b3ea08d3e', 'MODEL KONSEPTUAL PENGARUH INOVASI TERHADAP PENERIMAAN PENGGUNA PADA SISTEM INFORMASI PENGELOLAAN KEUANGAN DAERAH (SIPKD) DI PEMERINTAH KOTA BANJARMASIN', NULL, 2015, '2015-02-06', 'Satria Yudha Lesmana; Wing Wahyu Winarno; Paulus Insap Santosa', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/770/737', 'Pemerintah Kota Banjarmasin telah melakukan beberapa inovasi pada Sistem Informasi Pengelolaan Keuangan Daerah (SIPKD) sejak tahun 2013. Namun adanya inovasi-inovasi yang dilakukan ternyata menimbulkan beberapa permasalahan dan tidak menjamin dapat diterima seluruhnya oleh pengguna. Adanya permasalahan terhadap penerimaan pengguna ternyata berpengaruh akan keberlanjutan penggunaan SIPKD di Pemerintah Kota Banjarmasin, sehingga sekarang ada usulan agar SIPKD diganti dengan sistem yang lain TAM (Technology Acceptance Model) adalah sebuah teori dalam sistem informasi yang menjelaskan bagaimana pengguna mau menerima dan menggunakan teknologi sedangkan teori difusi inovasi banyak digunakan dalam penelitian untuk menyelidiki faktorfaktor yang mempengaruhi adopsi atau penerimaan terhadap suatu inovasi dalam sebuah lingkungan. Pada penelitian ini dilakukan kombinasi antara TAM dengan teori difusi inovasi untuk mengetahui pengaruh dari inovasi terhadap penerimaan pengguna pada Sistem Informasi Pengelolaan Keuangan Daerah di Kota Banjarmasin. Dari hasil kombinasi tersebut didapatkan sebuah model konseptual yang akan diterapkan dalam penelitian selanjutnya. Kata kunci: SIPKD, inovasi, TAM, teori difusi inovasi.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2463103415"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('37cedd28-e684-4e78-bce0-3018f613d957', 'PLATFORM E-LEARNING TEKNIK AUDIT BERBANTUAN KOMPUTER (TABK) BERBASIS OPEN EDX', NULL, 2014, '2014-02-08', 'Hafizhuddin Amin; Paulus Insap Santosa; Ahmad Ashari', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/492/470', 'Meskipun Computer-assisted audit tools and technique (CAATT) atau teknik audit berbantuan komputer (TABK) memungkinkan tugas pemeriksaan menjadi lebih efektif dan efisien, penerimaan dan penguasaannya ternyata masih cukup rendah. salah satu penyebabnya adalah karena TABK dipersepsikan sulit dikuasai. solusinya a.l. dengan mendesain program pelatihan yang baik. Makalah ini membahas pengembangan platform e- learning materi TABK pada Badan Pemeriksa Keuangan (BPK) RI. Tujuannya agar pemeriksa BPK yang tersebar di seluruh provinsi di Indonesia dapat berlatih dan menguasai materi TABK secara mandiri, terutama menjelang implementasi penuh program strategis e- Audit. E-learning ini mengacu pada desain model kuliah online platform open source Open edX. Berdasarkan pengujian terbatas yang dilakukan pada pengguna pemeriksa BPK RI, implementasi fitur yang dikembangkan dipersepsikan cukup efektif membantu pembelajaran materi TABK.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2465955741"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b92da04f-4331-4476-bfd5-e393e1825529', 'Semi Automatic Detector of Plasmodium Falciparum on Microscope Image Based', NULL, 2013, '2013-11-19', 'Iis Hamsir Ayub Wahab; Adhi Susanto; Paulus Insap Santosa; Maesadji Tjokronegoro', NULL, 'JOURNAL', NULL, 'http://repository.ugm.ac.id/101164/', 'The inspection standard for diagnosis of active malaria
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2a2d8804-bd9c-4dde-916a-5267ff6561d1', 'Helping Users, Mentally', NULL, 2006, '2006-01-01', 'Paulus Insap Santosa', 'IGI Global eBooks', 'BOOK_CHAPTER', '10.4018/978-1-59140-763-8.ch008', 'https://doi.org/10.4018/978-1-59140-763-8.ch008', 'The World Wide Web offers a vast collection of information. As the result, information seeking and related activities have become increasingly common. However, several drawbacks of the current systems often cause some user frustrations. One source of frustration is the way information is presented on the Web. It appears that virtually anyone could become an information source and Web site owner. As such, it is difficult, if not impossible, to have a standardized structure on how information should be structured and presented on the Web. This chapter presents a comprehensive literature review on information seeking emphasizing aspects of human cognition. It starts by pointing out some problems the information seekers may encounter when searching the Web. It proceeds with a navigation metaphor to compare the real-word navigation into hypertext navigation.', 0, 'OPENALEX', '{"doi": "10.4018/978-1-59140-763-8.ch008", "openalex": "https://openalex.org/W2492800229"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e8e7cab2-f1a8-4d08-b69e-1ade0db9a2e1', 'A Meta-Review of the Smartphone as the Measurement Device', NULL, 2020, '2020-06-01', 'Bimo Sunarfri Hantono; Lukito Edi Nugroho; Paulus Insap Santosa; R Musaddiq', 'Journal of Physics Conference Series', 'JOURNAL', '10.1088/1742-6596/1566/1/012099', 'https://doi.org/10.1088/1742-6596/1566/1/012099', 'Abstract With the development of increasingly affordable smartphone technology that is owned by almost everyone, making some activities can be done only by using this device. Smartphone computing capability that is quite powerful, accompanied by various sensors embedded in it, allows the smartphone to be used as a measurement device in various fields of research. This article tries to review the use of smartphones as a measure of one’s mentality by conducting a meta-review of several review articles that have been done before. This article tries to look at research trends that measure a person’s mental state by using sensors found on smartphones and also to help researchers decide on topics to explore.', 0, 'OPENALEX', '{"doi": "10.1088/1742-6596/1566/1/012099", "openalex": "https://openalex.org/W3040078704"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c025fed1-6cde-4253-b20e-2acafe67f81b', 'Tinjauan Dasar Desain User Experience dalam Media Pembelajaran Bagi Anak Berkebutuhan Khusus', NULL, 2015, '2015-01-01', 'Tri Sagirani; Lukito Edi Nugroho; Paulus Insap Santosa; Amitya Kumara', 'SIR - STIKOM Institutional Repository', 'BOOK_CHAPTER', NULL, NULL, 'Perkembangan Teknologi Informasi dan Komunikasi (TIK) kini telah menjadi bagian penting dalam segala aspek kehidupan sebagai alat bantu dalam mempermudah penyelesaian sebuah aktifitas yang dilakukan manusia, tanpa terkecuali juga dalam aspek pendidikan bagi anak berkebutuhan khusus yang mengalami gangguan kognitif. TIK mampu memfasilitasi akuisisi dan penyerapan pengetahuan juga memberikan kesempatan yang luar biasa dalam peningkatan sistem pendidikan pada sekolah luar biasa. Anak berkebutuhan khusus (ABK) mendapatkan dukungan dalam proses belajar dengan berbantuan TIK. Proses belajar dengan memperhatikan kebutuhan khusus yang ABK miliki menjadikan pembelajaran lebih efisien dan efektif. TIK membantu seorang ABK dalam proses membaca, menulis, mendengar serta melihat. Namun demikian pemanfaatan TIK dalam pembelajaran bagi ABK harus memperhatikan beberapa hal berikut ini, dalam penggunaan teks untuk belajar membaca, media pembelajaran selalu diikuti dengan audio dan visualisasi berupa gambar, animasi ataupun video untuk mempermudah proses penyerapan informasi. Pemanfataan kata atau kalimat ditampilkan dalam bentuk yang paling sederhana dan digunakan secara berulang, dan ditulis dengan jenis teks yang simple, mudah dibaca dan ukuran yang lebih besar dari yang biasa digunakan untuk anak normal. Penelitian ini akan menyampaikan konsep-konsep sederhana yang perlu diperhatikan bagi guru ataupun pengembang media pembelajaran dengan harapan produk yang mereka hasilkan dalam bentuk media pembelajaran memiliki perhatian terhadap konten, penyajian, fungsionalitas dan interaksi ABK dengan media pembelajaran. Dengan memperhatikan beberapa hal dasar ini diharapkan dapat meningkatkan pengalaman ABK dalam proses akuisisi dan penyerapan pengetahuan sebagai bekal hidup mandiri ketika mereka dewasa.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2504139037"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('56fb1080-d951-44b7-8734-8b43e97f8967', 'Toward SCORM generating based on semantic representation of knowledge organizer', NULL, 2016, '2016-10-01', 'Istiadi Istiadi; Lukito Edi Nugroho; Paulus Insap Santosa', NULL, 'JOURNAL', '10.1109/iciteed.2016.7863275', 'https://doi.org/10.1109/iciteed.2016.7863275', 'Knowledge organizer is a medium to organize the objects of knowledge. The organizer that use semantic representations provide an advantage, because it can be understood by the computing machinery. The organized objects as resources to increase knowledge should be able shared through such as Learning Management System (LMS) which generally use a SCORM (Shareable Content Object Reference Model) as standard. The differences of standards representation should be resolved automatically by the system that uses a semantic platform. This paper aim to presents the possibility of lesson learning generation in the form of SCORM based on resources that have been organized using semantic technology. An essence of the lesson learning is to present a structured of learning objects. The main part of the knowledge organizer is knowledge representation that in this case using language of web ontology (OWL). To identify the main elements of SCORM lesson learning, this representation allows queried by SPARQL to find location and file name of the objects and their relationships to construct the structure of the lesson learning. Furthermore, the query results will be used for formation of the SCORM elements.', 0, 'OPENALEX', '{"doi": "10.1109/iciteed.2016.7863275", "openalex": "https://openalex.org/W2592783055"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d7925cbb-26af-4d8d-bd76-f2f7cfc50fb5', 'Pengembangan Aplikasi "Event Management Desktop" Berbasis Adobe Integrated Runtime (AIR)', NULL, 2010, '2010-01-01', 'Ageng Sajiwo; Paulus Insap Santosa; Bimo Sunarfrihantono', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12554', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2600924299"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9c38dea4-a3be-46b1-a7ce-3ea62d382ba2', 'Algoritma Sinkronisasi Data pada Teknologi Basisdata MySQL dan Microsoft Access melalui Pemanfaatan Simple ''Query Language Untuk Integrasi Data', NULL, 2010, '2010-01-01', 'Sigit Tri Wibowol; Paulus Insap Santosa; Ridi Ferdiana', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12558', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2601807990"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('8d50cd25-813a-425b-9c6e-354f957fa098', 'Sistem Evaluasi Belajar Tanpa Kertas di Sekolah Menengah Atas Menggunakan AJAX', NULL, 2010, '2010-01-01', 'Shita Nur Martiasningrumt; Paulus Insap Santosa; Sri Suning Kusumawardani', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/download.php?dataId=12557', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2602293779"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0cf9804a-01ef-4dd6-8259-248e3443355f', 'Pengalaman Pengguna Laman Toko Daring', NULL, 2017, '2017-05-20', 'Yas Ahmad Adha; Wing Wahyu Winarno; Paulus Insap Santosa', NULL, 'JOURNAL', NULL, NULL, 'Toko daring berkembang begitu cepat khususnya di Indonesia, tidak sedikit laman toko daring yang bermunculan dengan mengembangkan konten yang diharapkan dapat memikat pengguna pada laman toko daring. Perkembangan konten pada toko daring menjadikan sulitnya untuk diukur kualitas terhadap pengguna, mengembangkan suatu sistem tidak hanya dilihat dari sistem saja, tetapi juga dilihat dari pengguna sistem yang dikembangkan. Penelitian ini mengunakan metrik PULSE dan metrik HEART yang telah dimodifikasi dengan variabel WEBQUAL serta variabel perceived benefit untuk mengukur kualitas dari pengalaman pengguna. Metode ini diuji coba pada laman toko daring data diambil mengunakan kuesioner yang disesuaikan, total ada 65 responden. 9 hipotesis diuji dengan menggunakan perangkat lunak SmartPLS 3 versi student. 6 hipotesis dapat diterima, sedangkan 3 hipotesis lainnya ditolak, mengarah kepada engagement atau keterkaitan pengguna.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2741278142"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('72546cf9-ec31-4053-aa1b-3f0909ce9d5c', 'Dasar dasar Pemrograman Pascal', NULL, 2010, '2010-07-01', 'Paulus Insap Santosa', NULL, 'JOURNAL', NULL, 'https://openlibrary.telkomuniversity.ac.id/home/catalog/id/23269/slug/dasar-dasar-pemrograman-pascal.html', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2751377512"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('291c2675-1e98-4585-b3b2-f6ccaa2b9610', 'Perbedaan Beban Kognitif pada Penggunaan Kata Sandi Berbasis Pola Garis dan Angka', NULL, 2018, '2018-03-05', 'Paulus Insap Santosa', 'Jurnal Nasional Teknik Elektro dan Teknologi Informasi (JNTETI)', 'JOURNAL', '10.22146/jnteti.v7i1.399', 'http://doi.org/10.22146/jnteti.v7i1.399', 'Most applications require users to enter a password in order to use those applications. One type of the passwords used on smartphones is based on certain line pattern. The pattern of lines that make up the password is essentially an image similar to a sequence of numbers arranged in a particular order. Just when users need to memorize a series of numbers, "memorizing" the line pattern also gives cognitive load to certain level. This study observed the cognitive load experienced by users when they were using line pattern-based password as compared to numeric-based password. The research method employed in this study was a scenario-based experiment followed by a survey to self-report the cognitive load experienced by the user after they run the scenario. Cognitive load experienced by users were reported by users themselves. The subjects of the study were 67 undergraduate and master students. They were voluntarily participated in this research. The result obtained from this study indicated that the cognitive load experienced by users when they used the pattern of the line based password was smaller than the number-based password.', 0, 'OPENALEX', '{"doi": "10.22146/jnteti.v7i1.399", "openalex": "https://openalex.org/W2790559783"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('30beb5c9-e96f-42a0-a04e-e8036d6972b4', 'Pengalaman Pengguna Laman Pelayanan Publik', NULL, 2017, '2017-01-01', 'Yasril Adha; Wing Wahyu Winarno; Paulus Insap Santosa', NULL, 'JOURNAL', NULL, NULL, 'Penyelenggara pelayanan publik mengembangkan sistem layanan publik untuk melayani pengguna (masyarakat) secara efisien, efektif. Perkembangan konten-konten pada sistem daring menjadikan semakin sulit diukur oleh instansi untuk melihat kualitas pengalaman pengguna. Mengem-bangkan suatu sistem tidak hanya melihat dari sistem daring tersebut tetapi juga dilihat dari pengalaman pengguna. Dengan mengunakan metrik PULSE dan HEART, yang akan dikem¬bangkan dengan metode variabel kualitas interaksi layanan dan perceived benefit. Metrik PULSE dan HEART diguna¬¬kan untuk meneliti pengalaman pengguna terhadap suatu produk. Pengu¬naan metode ini akan diterapkan terhadap sistem layanan publik pemerintah pada bidang pendidikan sistem daring pendaftaran penyetaraan ijazah lulusan perguruan tinggi luar negeri pada Kementerian Riset, Teknologi dan pendidikan tinggi. Metode penelitian menggunakan kuesioner dengan responden pengguna pelayanan penyetaraan ijazah lulusan perguruan tinggi luar negeri, total 90 responden. Enam hipotesis diuji coba dengan menggunakan SmartPLS 3 dan semua hipotesis dapat diterima.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2893210472"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e77ce598-acc0-40ba-941f-dfa37084acb6', 'An Interactive Book With Augmented Reality For Learning The Cirebon Mask Dance', NULL, 2018, '2018-08-27', 'Dinan Yulianto; Rudy Hartanto; Paulus Insap Santosa', 'JURNAL INFOTEL', 'JOURNAL', '10.20895/infotel.v11i3.374', 'http://ejournal.st3telkom.ac.id/index.php/infotel/article/download/374/226', 'Today, augmented reality has an important role in human activity, especially in the field of education. The increasing capabilities of mobile devices also contribute to augmented reality to reduce real world distance with the virtual world. This paper will discuss the design and testing of iBook as media of learning the Cirebon mask dance art. IBook is a form of optimisation of traditional books based on augmented reality. The iBook designs will interact with virtual objects through direct touch on the application interface (pinch and swipe). The technical testing of iBook is a test of marker less reading ability and audio response time test. The markerless detection test resulted in minimum response time less than 1 second, minimum distance of 64 cm and a maximum distance of 3 cm, a minimum angle of 23° and a maximum angle of 90°. Tracking test obtained a minimum distance of 3 cm and a maximum distance of 71 cm, a minimum angle of 90° and a maximum angle of 16°. Any markerless detection and tracking can be done in unobstructured condition of no more than 50%. The testing of audio content obtained activation response time less than 1 second with original duration equal to active duration.', 0, 'OPENALEX', '{"doi": "10.20895/infotel.v11i3.374", "openalex": "https://openalex.org/W2900281621"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('7e3eb518-fcad-419a-8293-b5082fe67cdf', 'Pemanfaatan Gamifikasi pada Massive Open Online Course (MOOC)', NULL, 2019, '2019-02-21', 'Wirawan Arief Nugroho; Paulus Insap Santosa; Silmi Fauziati', 'Seminar Nasional Teknologi Komputer & Sains (SAINTEKS)', 'JOURNAL', NULL, 'https://prosiding.seminar-id.com/index.php/sainteks/article/view/125', 'Sejak dimulainya era Revolusi Industri 4.0 Gamifikasi dan Massive Open Online Course (MOOC) merupakan fenomena baru dalam pembelajaran terbuka dan dikenal sebagai strategi yang baik untuk meningkatkan kualitas pendidikan. Namun demikian, MOOC memiliki dua kelemahan utama: pertama, kurangnya pemahaman untuk mengetahui sasaran pribadi; dan kedua, tingkat penyelesaian yang rendah dibandingkan dengan jumlah pendaftaran ke MOOCs. Untuk dapat mengatasi dua kelemahan tersebut peneliti akan mengusulkan pemanfaatan Gamifikasi. Dalam tulisan ini akan diuraikan berbagai penelitian yang berkaitan dengan Gamifikasi dan MOOC. Metodologi penelitian ini menggunakan pendekatan kualitatif dengan menekankan pada analisis data. Hasilnya diketahui bahwa MOOC tidak memerlukan tingkat penyelesaian penuh seperti kursus tradisional yang biasanya dianggap sebagai keberhasilan. Kata Kunci : Gamifikasi, MOOC dan Tingkat Penyelesaian', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2964554187"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f6549731-f18f-4567-bc2a-47eda8256acd', 'Estimating Cognitive Performance Changes Based on Psychophysiological Sensor in the Smartphone: A Proposed Model', NULL, 2019, '2019-10-01', 'Bimo Sunarfri Hantono; Lukito Edi Nugroho; Paulus Insap Santosa', NULL, 'JOURNAL', '10.1109/iciteed.2019.8929946', 'https://doi.org/10.1109/iciteed.2019.8929946', 'In the last few years, the approach to introducing cognitive performance automatically gained significant scientific interest. Likewise, cognitive performance observation research using the method of collecting the results of objective measurements that occur in everyday life. Today almost everyone has a smartphone, and they have become partners in living their daily lives. The smartphone has been equipped with various kinds of sensors to facilitate its use and for its full features. The existence of sensors on a smartphone is also the potential to be used to obtain information and the user''s situation for a long time and does not disturb the user. Therefore, research using smartphone sensing provides research opportunities in the field of psychology, especially for observing the cognitive performance of users. This study aimed to investigate the possibility of using smartphones as a medium to detect cognitive performance in general outside laboratory conditions.', 0, 'OPENALEX', '{"doi": "10.1109/iciteed.2019.8929946", "openalex": "https://openalex.org/W2996683952"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0cc4927b-51c3-4dea-849d-39eeeff27e88', 'A Conceptual Framework of Adaptive Mobile POI Recommendations', NULL, 2019, '2019-07-01', 'Emanuel Ristian Handoyo; Selo Sulistyo; Paulus Insap Santosa; Bimo Sunarfri Hantono', '2019 International Conference on Information and Communications Technology (ICOIACT)', 'JOURNAL', '10.1109/icoiact46704.2019.8938542', 'https://doi.org/10.1109/icoiact46704.2019.8938542', 'Many mobile applications that recommend attractive and customized POIs are often not adaptive enough for users who are actively traveling. Although almost all mobile applications and one concept of the mobile recommendation system have been able to adapt to users, in fact, the findings prove that this is only a small effort that mostly focuses on capturing user behavior during tourism activities. Instead, the Adaptive Mobile Recommendation System (AMRS) is proposed by carrying out all possible configurations that can improve adaptability in mobile applications. Furthermore, the AMRS was built as a new concept based on the Adaptive Tourist Recommendation System (ATRS) concept that was proposed in the past. AMRS takes advantage of the travel cycle and the concept of experiential learning as an unlimited effort of adaptivity that can be applied in a real way using the structure of the recommendation system.', 0, 'OPENALEX', '{"doi": "10.1109/icoiact46704.2019.8938542", "openalex": "https://openalex.org/W2996899609"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('204c78d2-0340-4f30-880d-498d0ddf85ab', 'Implementation of VARK Learning Styles in the MOOC User Interface Design', NULL, 2019, '2019-01-01', 'Nungky Amalia Imran; Paulus Insap Santosa; Sri Suning Kusumawardani', NULL, 'JOURNAL', '10.5220/0009867502200223', 'https://doi.org/10.5220/0009867502200223', NULL, 0, 'OPENALEX', '{"doi": "10.5220/0009867502200223", "openalex": "https://openalex.org/W3038707355"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f022ffa2-2751-495a-94fd-525d97d1ed62', 'Identifying Smartphone Based Features for Automatic Learning Style Identification Approaches Using Correlation Tests', NULL, 2019, '2019-07-01', 'Maximillian Sheldy Ferdinand Erwianda; Paulus Insap Santosa; Sri Suning Kusumawardani; Bimo Sunarfri Hantono; Meizar Raka Rimadana', '2019 5th International Conference on Science and Technology (ICST)', 'JOURNAL', '10.1109/icst47872.2019.9166165', 'https://doi.org/10.1109/icst47872.2019.9166165', 'Learning style identification is attracting considerable interest due to its potential to solve problems in human learning activities and has been widely utilized in learning management systems. Despite this interest, no one has studied learning style identification in an informal learning environment. Moreover, informal learning even plays the biggest role in human lifelong education. This study thus proposes smartphones as a new plausible observation environment, for their uses match the characteristics of informal learning. However, it is not yet known which smartphone parameters are reliable to be used as features in learning style identification models. Therefore, this study aims to find reliable features from smartphones by conducting the Spearman''s rank correlation tests between several potential smartphone parameters and the Visual, Aural, Read/Write, Kinesthetic (VARK) learning style scores. The parameters were collected using a dedicated application and tested in two scenarios. We treated the applications individually without clustering in the first scenario, while we clustered the applications by their functions in the second one. The result revealed that there were eight potential features in total. This study has opened more possibilities to improve the development of the learning style identification system.', 0, 'OPENALEX', '{"doi": "10.1109/icst47872.2019.9166165", "openalex": "https://openalex.org/W3049208569"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0c32f947-50f8-47de-ad0d-870c6895f657', 'Bukti Korespondensi Artikel Evaluasi Buku Interaktif Berbasis Augmented Reality Menggunakan System Usability Scale dan User Experience Questionnaire pada Jurnal Resti', NULL, 2020, '2020-06-20', 'Dinan Yulianto; Rudy Hartanto; Paulus Insap Santosa', 'Selamat Datang di Repository UAD (Universitas Ahmad Dahlan)', 'OTHER', NULL, NULL, NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W3090758338"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
