INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0aa5bcc7-3f0e-4b38-9f77-2e32925add4a', 'Pemanfaatan program Matlab for Windows dalamsimulasi komunikasi dengan modulasi GMSK.', NULL, 1999, '1999-01-01', 'Agustinus Tedja; Wahyu Dewanto', 'Media Teknik', 'JOURNAL', '10.1038/s41556-024-01563-z', 'http://i-lib.ugm.ac.id/jurnal/download.php?dataId=3427', NULL, 0, 'OPENALEX', '{"doi": "10.1038/s41556-024-01563-z", "openalex": "https://openalex.org/W39528703"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0461a145-02d9-4bdb-aafa-89bdea43b245', 'Multi-distance fluctuation based dispersion fractal for epileptic seizure detection in EEG signal', NULL, 2021, '2021-07-07', 'Inung Wijayanto; Rudy Hartanto; Hanung Adi Nugroho', 'Biomedical Signal Processing and Control', 'JOURNAL', '10.1016/j.bspc.2021.102938', 'https://doi.org/10.1016/j.bspc.2021.102938', NULL, 17, 'OPENALEX', '{"doi": "10.1016/j.bspc.2021.102938", "openalex": "https://openalex.org/W3180581806"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('ac856c58-63d9-4a65-b666-3e8fe22b6efb', 'Two-Dimensional Direction-of-Arrival Estimation for More Sources Than Sensors', NULL, 2022, '2022-12-08', 'Hasbi N. P. Wisudawan; Amalia Rizqy Ramadhani; Nicholaus Valentino Dwicahyo; Dyonisius Dony Ariananda; Risanuri Hidayat; Wahyu Dewanto', NULL, 'JOURNAL', '10.1109/isriti56927.2022.10053025', 'http://dx.doi.org/10.1109/isriti56927.2022.10053025', 'This paper concerns the problem of two-dimensional (2-D) angle (azimuth and elevation) estimation for uncorrelated far-field sources using the proposed sparse rectangular array of antennas, which is constructed by applying the spatial compression on the uniform rectangular array based on the 2-D sparse ruler concept. The correlation matrix of the sources is estimated and applied as an input for the power spectrum / pseudospec-trum estimation algorithm, i.e., classical beamforming, minimum variance distortionless response (MVDR), and multiple signal classification (MUSIC). The simulation study shows that the estimation algorithms are able to spot the direction-of-arrival (DoA) of the sources, which consists of the azimuth and elevation angles, and where the number of sensors is less than the number of sources. Apart from that, the 2-D DoA estimation process using the MUSIC-based method shows better performance from the perspective of the root mean square error, even in a very low sisnal-te-noise ratio value at the receiver.', 0, 'OPENALEX', '{"doi": "10.1109/isriti56927.2022.10053025", "openalex": "https://openalex.org/W4323520589"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2f391566-3ea8-4431-9fd1-a5dd8899f367', 'Evaluasi Platform Perangkat Keras Sistem Tertanam untuk Unit Kontrol Parkir Otomatis', NULL, 2023, '2023-11-28', 'Wahyu Dewanto; Agung Fathurrahman; Agus Bejo', 'Jurnal Nasional Teknik Elektro dan Teknologi Informasi (JNTETI)', 'JOURNAL', '10.22146/jnteti.v12i4.6277', 'http://dx.doi.org/10.22146/jnteti.v12i4.6277', 'Sistem parkir otomatis merupakan salah satu teknologi manajemen parkir yang saat ini banyak digunakan di berbagai instansi. Sistem parkir otomatis merupakan sistem parkir yang bekerja dengan menempatkan sebuah mesin portal parkir. Mesin portal parkir tersebut kemudian secara otomatis dapat membuka dan menutup portal serta merekam nomor kendaraan saat masuk dan keluar dengan menggunakan sebuah kunci akses berupa smart card. Salah satu kendala dalam penerapan sistem parkir otomatis adalah terjadinya kemacetan apabila kondisi lalu lintas sedang tinggi. Hal tersebut terjadi karena unit kontrol pada sistem parkir otomatis memerlukan waktu yang relatif lama saat melakukan proses pengambilan dan penyimpanan citra dari kamera. Dalam penelitian ini, dilakukan pengujian pada beberapa platform sistem tertanam yang nantinya digunakan sebagai unit kontrol pada sistem parkir otomatis, yaitu Raspberry Pi 3B, Raspberry Pi 4B, dan Orange Pi Zero Plus. Tujuan pengujian tersebut adalah untuk mencari platform unit kontrol terbaik dengan beberapa kriteria, yaitu memiliki waktu respons tercepat saat mengambil citra, memiliki waktu respons tercepat saat menyimpan citra, dan memiliki konsumsi daya yang rendah. Dari pengujian yang dilakukan, didapatkan hasil bahwa platform Raspberry Pi 4B memiliki waktu respons tercepat untuk mengambil dan menyimpan citra dengan waktu rata-rata sebesar 1.827,9 ms, sedangkan konsumsi daya terendah dicapai oleh platform Orange Pi Zero Plus dengan nilai sebesar 1,9 W. Dari hasil pengujian yang telah dilakukan, Raspberry Pi 4B direkomendasikan sebagai unit kontrol pada sistem parkir otomatis apabila sistem parkir otomatis memerlukan perangkat dengan kinerja tinggi. Sementara itu, jika sistem parkir otomatis memerlukan perangkat yang hemat daya, Orange Pi Zero Plus direkomendasikan sebagai unit kontrol pada sistem parkir otomatis.', 0, 'OPENALEX', '{"doi": "10.22146/jnteti.v12i4.6277", "openalex": "https://openalex.org/W4389322773"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('bca6c652-d306-42f9-9ebf-111945b36919', 'Blockchain and IOT for the sustainable agriculture census system development', NULL, 2023, '2023-12-22', 'Wahyu Dewanto; Muhammad Hafidh Firmansyah; Hariyono Rakhmad; Seok‐Joo Koh', 'World Journal of Advanced Research and Reviews', 'JOURNAL', '10.30574/wjarr.2023.20.3.2537', 'http://dx.doi.org/10.30574/wjarr.2023.20.3.2537', 'The integration of Blockchain and the Internet of Things (IoT) technologies has revolutionized various sectors, including agriculture, by enhancing transparency, security, and efficiency. This abstract provides an overview of a groundbreaking project aimed at developing Blockchain and IoT technologies for agriculture. The conventional agriculture census process is often plagued by inefficiencies, data inaccuracies, and vulnerability to fraud. to fraud often plague the conventional agriculture census process. To address these challenges, this project leverages Blockchain''s immutable ledger capabilities to ensure the integrity of agricultural data collected during the census. Furthermore, IoT devices, such as sensors and drones, are deployed to automate data collection and monitor various aspects of agricultural operations, promoting sustainability and resource optimization. Through the combination of Blockchain and IoT, the SACS provides several advantages. It offers secure, tamper-proof storage of agricultural data, ensuring its accuracy and reliability. Smart contracts on the Blockchain facilitate automated and transparent transactions, streamlining interactions among stakeholders in the agriculture ecosystem. Moreover, the real-time data collected by IoT devices enable farmers and policymakers to make data-driven decisions that improve crop yields, resource utilization, and environmental sustainability.', 0, 'OPENALEX', '{"doi": "10.30574/wjarr.2023.20.3.2537", "openalex": "https://openalex.org/W4390110798"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9591329a-9183-480e-be26-8fb1d6726b90', 'Implementasi Dompet Digital Polije Berbasis IoT dan Blockchain', NULL, 2023, '2023-12-22', 'Muhammad Hafidh Firmansyah; Wahyu Dewanto; Hariyono Rakhmad', 'JURNAL PENGABDIAN MASYARAKAT AKADEMISI', 'JOURNAL', '10.59024/jpma.v2i1.504', 'https://doi.org/10.59024/jpma.v2i1.504', 'urrently, the implementation of IoT devices has been widely utilized by various parties in supporting the increasingly complex aspects of human life. IoT devices have become a favorite among hardware and software developers due to their ease of use and flexibility in adapting to the evolving systems of today. One of the uses of IoT is in the realm of digital economics, where digital economy represents a new way of prioritizing technology and ease in the buying and selling transaction process between sellers and buyers. In the past, payment processes for goods or services used to involve paper money and coins, but nowadays, payments are made using digital media. However, the current digital payment methods still rely on centralized storage technology. Therefore, if the data held at the center is damaged or compromised, it can disrupt the flow of financial transactions, and user data privacy becomes a subsequent concern.', 0, 'OPENALEX', '{"doi": "10.59024/jpma.v2i1.504", "openalex": "https://openalex.org/W4390957192"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('ee4c68ad-8f4e-4592-8648-91a167d3f962', 'Implementasi Modbus TCP dalam Pengiriman Data Deteksi Objek ke PLC Schneider M221', NULL, 2024, '2024-06-24', 'Enas Dhuhri Kusuma; T. Aziz; Wahyu Dewanto', 'Journal of Applied Electrical Engineering', 'JOURNAL', '10.30871/jaee.v8i1.7334', 'http://dx.doi.org/10.30871/jaee.v8i1.7334', 'Visi komputer telah diaplikasikan dalam berbagai sektor termasuk sektor industri. Aplikasi teknologi ini dapat menciptakan sistem manufaktur cerdas. Meskipun demikian, kurangnya alat praktikum yang memadai di perguruan tinggi dapat menyebabkan celah pengetahuan antara industri dan perguruan tinggi sebagai pencetak insinyur. Untuk menutup kekurangan tersebut, sebuah alat peraga deteksi objek di atas konveyor peraga berbasis Raspberry Pi 4 telah didesain di Laboratorium Schneider Electric Universitas Gadjah Mada. Meskipun demikian, alat peraga ini masih berdiri sendiri sehingga perlu dihubungkan ke sistem yang lebih besar seperti di industri. Penelitian ini dilakukan untuk menjalin komunikasi antara Raspberry Pi 4 dengan PLC Schneider M221 sehingga dapat terjadi pengiriman data deteksi objek. Komunikasi ini diimplementasikan dengan protokol Modbus TCP. Dari pengujian, data deteksi berhasil ditransfer secara akurat ke memori dan mengubah kondisi relay output PLC M221 sehingga dapat menjadi dasar pengendalian lebih lanjut. Pengiriman data memiliki latensi sebesar 0,007249 detik dan 0,009185 detik untuk data dalam bit dan word.', 0, 'OPENALEX', '{"doi": "10.30871/jaee.v8i1.7334", "openalex": "https://openalex.org/W4401623439"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('74881384-e922-4437-84de-9d984beb84d9', 'OPTIMALISASI BUFFER ZONE SEBAGAI PENGAMAN PERMUKIMAN DI SEKITAR DEPO TANGKI BAHAN BAKAR MINYAK PT. PERTAMINA PLUMPANG, JAKARTA', NULL, 2024, '2024-12-10', 'Udi Susilo; I Nyoman Teguh Prasidha; Wahyu Dewanto', 'JURNAL PENELITIAN DAN KARYA ILMIAH LEMBAGA PENELITIAN UNIVERSITAS TRISAKTI', 'JOURNAL', '10.25105/pdk.v9i2.21437', 'https://doi.org/10.25105/pdk.v9i2.21437', 'The fuel storage tanks in Plumpang, North Jakarta, owned by PT. Pertamina Tbk. initially had a land area of ​​153 hectares, with the use of 71 hectares as an operational area and the rest as a buffer zone. However, the buffer zone changed its function to a residential area as a place of residence and economic activities for the community which became increasingly dense accompanied by issues of land ownership status. The Plumpang fuel storage tanks fire incident that occurred several times which caused loss of life and property, is a reminder of the importance of a buffer zone that serves as a separating space between areas at risk of flammable material disasters and residential areas. This paper is the result of research on the analysis of the optimization of land requirements for the Plumpang fuel storage tanks buffer zone, by applying quantitative descriptive methods and spatial mapping of the area using Arcgis software, with reference to fuel depot safety standards. It requires the acquisition of 5.2 hectares of land as a buffer zone area in the form of a safe distance from the safety fence wall, construction of a ditch that functions as an accident pool, and re-arrangement of settlements directly adjacent to the buffer zone.', 0, 'OPENALEX', '{"doi": "10.25105/pdk.v9i2.21437", "openalex": "https://openalex.org/W4405174934"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4a17bda1-7f40-49e1-bb7d-a2cf092e45cf', 'Node-RED dan Robotik pada Sistem Penyiraman Otomatis berbasis IoT', NULL, 2024, '2024-11-29', 'Wahyu Dewanto; Aji Seto Arifianto; Hariyono Rakhmad; Hermawan Arief Putranto; Muhammad Hafidh Firmansyah', 'JTIM Jurnal Teknologi Informasi dan Multimedia', 'JOURNAL', '10.35746/jtim.v6i3.609', 'https://doi.org/10.35746/jtim.v6i3.609', 'The Internet of Things (IoT) technology offers great potential in the agricultural sector, especially in the automation of plant irrigation systems. Many farmers face challenges with water use efficiency and real-time land condition monitoring. Manual irrigation systems often lead to water wastage. Currently, many centralized irrigation systems use a one-by-one watering approach, requiring multiple sensors to monitor each plant''s condition, making them less efficient. To address this issue, this research developed an automated irrigation system controlled by Node-RED and robotic technology. The system is designed to require only one sensor to monitor the entire agricultural area, while still efficiently distributing water to many plants. Node-RED manages data from soil moisture and environmental temperature sensors, then activates the watering robot to distribute water according to the plants'' needs. The system was tested by comparing manual and automatic methods using polybags. The soil moisture sensor sends data to Node-RED, which activates the watering robot when soil moisture falls below a set threshold. Test results show that the automated system can save up to 20% of water usage compared to manual methods, while keeping soil moisture within the optimal range. This system also enables real-time monitoring and control, providing a more efficient, timely, and resource-saving solution.', 0, 'OPENALEX', '{"doi": "10.35746/jtim.v6i3.609", "openalex": "https://openalex.org/W4405779607"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4f79def2-a4a3-4e75-a266-05e845fe3080', 'Perubahan Kurikulum dan Strategi Implementasi di Sekolah Arsitektur di Indonesia', NULL, 2024, '2024-12-20', 'Wahyu Dewanto; L. Edhi Prasetya; Lioni Fakhirah Salsabila; Nabila Auryn', 'Latar', 'JOURNAL', '10.69749/jl.v2i2.1217', 'https://doi.org/10.69749/jl.v2i2.1217', 'Peran arsitek profesional di Indonesia dan kebutuhan akan perubahan dalam pendidikan arsitektur telah menarik perhatian publik, pemerintah, arsitek, dan akademisi. Dalam menanggapi ini, diperlukan reformasi kebijakan pendidikan dan kurikulum yang lebih memahami proses pengajaran, persyaratan kurikulum, dan harapan profesional lulusan arsitektur. Rekrutmen, pelatihan, dan retensi dosen yang efektif menjadi krusial dalam mencapai kualitas pendidikan yang optimal. Kolaborasi antardosen dalam sekolah, berbagi pengalaman, dan komitmen terhadap peningkatan kualitas sekolah dan lulusan adalah penting. Dosen sebagai agen utama pembelajaran harus responsif terhadap perubahan kebijakan, kurikulum yang diperbarui, serta kebutuhan teknologi dan strategi pembelajaran yang relevan. Meski demikian, tantangan waktu dan tekanan eksternal sering kali menghambat upaya inovasi dalam pengajaran. Makalah ini mengusulkan strategi implementasi untuk meningkatkan kurikulum di sekolah arsitektur Indonesia, mengatasi hambatan dan meningkatkan efektivitas pengajaran dan pembelajaran. Kata Kunci: kurikulum, sekolah arsitektur, Indonesia', 0, 'OPENALEX', '{"doi": "10.69749/jl.v2i2.1217", "openalex": "https://openalex.org/W4406255367"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9239fcf6-cc84-4d40-a4ae-92fccd25ef8e', 'Pencegahan Perundungan Anak Dengan Memanfaatkan Teknologi Digital Studi Kasus UPTD SPF SDN Nangkaan Bondowoso', NULL, 2024, '2024-12-25', 'Wahyu Dewanto; Aji Seto Arifianto; Hariyono Rakhmad; Muhammad Hafidh Firmansyah; Kasiyati Kasiyati', 'Sejagat', 'JOURNAL', '10.25047/sejagat.v1i3.5374', 'https://doi.org/10.25047/sejagat.v1i3.5374', 'Bullying among students is increasingly prevalent, driven by various factors, including environmental influences and the impact of globalization. This issue poses significant challenges for teachers, who are often expected to monitor all students throughout the school day despite limited resources and time. The aim of this study is to explore effective strategies for preventing bullying in schools by integrating technological and creative approaches. The research employs a mixed-methods approach, combining quantitative analysis of bullying incidents with qualitative data from interviews and observations. The study focuses on the implementation of CCTV technology to enhance student behavior monitoring and prevent bullying incidents. Additionally, it investigates the use of arts-based activities as a means to help students channel excess energy into positive, creative outlets, thus reducing the likelihood of engaging in bullying behavior. The findings suggest that the combination of technological supervision and arts-based interventions significantly reduces the incidence of bullying in schools. The conclusion emphasizes the effectiveness of a holistic approach that incorporates both advanced monitoring tools and emotional support activities, highlighting the potential for these strategies to create a safer and more supportive school environment where students can thrive both emotionally and socially.', 0, 'OPENALEX', '{"doi": "10.25047/sejagat.v1i3.5374", "openalex": "https://openalex.org/W4412048510"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d5608854-e90b-4b99-a56f-5c63a49543f8', 'Perbandingan Unjuk Kerja Detektor PIN dan Detektor APD pada Transmisi Serat Optik', NULL, 2010, '2010-01-01', 'Muhammad Reza Sarkasiht; Wahyu Dewanto; Eny Sukani Rahayu', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12043', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W78009502"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b0d2e8e4-26f1-4412-bc7f-c9b2348ac23b', 'The Relevance of Jamal Al-Banna''s Islamic Legal Thoughts with Religious Moderation in Indonesia', NULL, 2023, '2023-05-23', 'Sakban Lubis; Rustam Ependi; Tumiran Tumiran; Muhammad Yunan Harahap; Abdul Hakim', 'Al-ISTINBATH Jurnal Hukum Islam', 'JOURNAL', '10.29240/jhi.v8i1.6649', 'https://doi.org/10.29240/jhi.v8i1.6649', 'This research aims to find out the relevance of Jamal Al-Banna''s Islamic Legal Thought with Religious Moderation in Indonesia. This research is a doctrinal Islamic legal research using historical approach method (content analysis). The primary data source of this research is Jamal al-Banna''s own work, namely Nahwa Fiqh Jadîd and the book Religious Moderation written by the Balitbang Team of the Indonesian Ministry of Religion. This research is also supported by secondary sources in the form of works related to the topic of study. The result of this research is that the Relevance of Jamal Al-Banna''s Islamic Legal Thought with Religious Moderation in Indonesia. textually there are 2 (two), namely: justice and tolerance. As for substantially there are also 2 (two), namely: the value of the principle of "convenience" is the same as tawassuṭ and compassion is the same as the principle of equality (musawah/egalitarian).', 14, 'OPENALEX', '{"doi": "10.29240/jhi.v8i1.6649", "openalex": "https://openalex.org/W4381569404"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('fbcae1e7-4127-40b0-887c-74f1d10adc77', 'Power System Planning Assessment for Optimizing Renewable Energy Integration in the Maluku Electricity System', NULL, 2022, '2022-07-10', 'Tumiran Tumiran; Lesnanto Multa Putranto; Roni Irnawan; Sarjiya Sarjiya; Candra Febri Nugraha; Adi Priyanto; Ira Savitri', 'Sustainability', 'JOURNAL', '10.3390/su14148436', 'https://doi.org/10.3390/su14148436', 'The planning of electrical power systems in remote island areas poses a few challenges, such as requiring many load centers, various energy sources, and certain geographical conditions, which leads to inefficiencies in energy production. For this reason, it is necessary to plan an electrical transmission system to efficiently transfer the power between load centers. Previous research has found that the completion of the most economical power system will be achieved in 2050 on the condition that the Ambon, Seram, Haruku, and Saparua (Ambon-SHS) systems are interconnected in 2025. Providing complementary support, this paper conducts a power system analysis to assess the proposed interconnection system in Maluku Island, which has several islands, small load centers, and local renewable energy resources. The power system analysis was performed using DIgSILENT PowerFactory and was carried out every 5 years of the system planning period until 2050. The results show that the design of the obtained transmission system meets the standard security criteria, which include thermal loading and voltage, being under both normal and N-1 contingency conditions, a short-circuit current, voltage stability, frequency stability, and transient stability. Finally, this paper demonstrates that the proposed plan is economically and technically feasible.', 5, 'OPENALEX', '{"doi": "10.3390/su14148436", "openalex": "https://openalex.org/W4285006427"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9d7daf73-aa1d-4b26-81ae-f36d317e8dde', 'The Damage of ZnO Arrester Block Due To Multiple Impulse Currents', NULL, 2011, '2011-04-01', 'Tarcicius Haryono; K.T. Sirait; Tumiran Tumiran; Hamzah Berahim', 'TELKOMNIKA (Telecommunication Computing Electronics and Control)', 'JOURNAL', '10.12928/telkomnika.v9i1.685', 'https://doi.org/10.12928/telkomnika.v9i1.685', 'A lightning arrester installed in an electrical power system is designed to protect some electrical equipment against damage due to lightning impulse strike. However, if there is a multiple impulse current striking a lightning arrester, it may damage the lightning arrester itself and then, as a result, it cannot provide lightning protection to the electrical equipment anymore. In this research, three peak values of lightning impulse current,which were 600, 1300, and 2500A, each of which had 5 repetitive impulse current, was applied to a 5000A (1p.u.) ZnO block of a 24kV nominal voltage lightning arrester having seven ZnO block units. The results of research showed that by applying impulse current of the order of 600(0.12), 1300(0.26), dan 2500(0.5) A(p.u.), making the ZnO block damage as much as 26.58, 50, and 100% concecutively. In addition, the damage of the ZnO block appeared as permanen low value of residual voltage as low as more than 5% of the new ZnO block residual voltage. If the ZnO block is still being used in a lightning arrester in electrical power system, it may result in the opening of a circuit breaker and possibly making electrical power outages from a number of electrical power customers.', 19, 'OPENALEX', '{"doi": "10.12928/telkomnika.v9i1.685", "openalex": "https://openalex.org/W1603078166"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d6451d46-f4a1-4355-b68b-eb936a5b190d', 'Application Values of Character Education in the Modern Pesantren System and Culture (Study at Pondok Pesantren Modern Ar-Raudlatul Hasanah Medan)', NULL, 2021, '2021-12-04', 'Manshuruddin Manshuruddin; Tumiran Tumiran; Muhammad Yunan', 'International Journal of Multicultural and Multireligious Understanding', 'JOURNAL', '10.18415/ijmmu.v8i12.3241', 'https://doi.org/10.18415/ijmmu.v8i12.3241', 'Pondok pesantren today can be said to be the most ideal and potential educational institution in fostering a character that is loaded with education values both religious values and the noble values of the nation. The importance of this research is to find different strategies or patterns that can be used as a reference for the development of character education models for formal schools. This research uses qualitative methods that are descriptive with a research site, namely Modern Pesantren Ar-Raudhatul Hasanah Medan. The results showed that character education in Ar-Raudlatul Hasanah Medan boarding school was carried out systemically-integratively. All center activities from waking up in the morning to going back to sleep at night accumulate in pesantren systems and cultures based on the values of Panca Jiwa, Motto, and Philosophy of Pesantren. The strategy of implementing character education is through integration into kmi curriculum learning activities, the formation of pesantren culture/ culture, and extracurricular activities. The methods carried out are direction, transparency, assignment, training, habituation, discipline, appreciation and punishment.', 7, 'OPENALEX', '{"doi": "10.18415/ijmmu.v8i12.3241", "openalex": "https://openalex.org/W4200028752"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('dd23da75-b157-40e9-92c0-7fe711c8f07a', 'Development of Enterprise Security Framework in SKK Migas Based on Integration of ISO 27000 and SABSA Model', NULL, 2018, '2018-07-01', 'Warsun Najib; Sujoko Sumaryono; Lukito Edi Nugroho; Guntur Dharma Putra', NULL, 'JOURNAL', '10.1109/iciteed.2018.8534747', 'https://doi.org/10.1109/iciteed.2018.8534747', 'This paper presents the development of Enterprise Security Framework (ESF) for an Indonesian government institution called SKK Migas (Special Task Force for Upstream Oil and Gas Business Activities). The framework developed based on two security standard namely ISO 27000 and SABSA. The development is started by evaluating available information security standard and best practice used in enterprise scale. The next step is analyzing existing security policy and implementation regarding the Information Security Management System (ISMS) in SKK Migas and then perform gap analysis. The main step is the synthesis of security framework which intended to improve information security management in SKK Migas. The resulted security framework covers 14 security domains which will be used to control information security management within the institution.', 4, 'OPENALEX', '{"doi": "10.1109/iciteed.2018.8534747", "openalex": "https://openalex.org/W2900601089"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b1c95715-92d1-4cbb-9d98-34ad551b1fb0', 'Implementation of Pedagogic Competency of Islamic Religious Education Teachers to Improve the Quality of Students'' Learning at Sman 7 Binjai', NULL, 2025, '2025-05-16', 'Rubi Yohana Khalistiasari; Tumiran Tumiran', 'JIM Jurnal Ilmiah Mahasiswa Pendidikan Sejarah', 'JOURNAL', '10.24815/jimps.v10i2.34422', 'https://doi.org/10.24815/jimps.v10i2.34422', 'The pedagogical competence possessed by teachers will make education the first step towards teacher success in educating students in school. This study aims to analyze the implementation of pedagogical competence that will be implemented by Islamic religious education teachers with the hope of being able to increase teacher competence by producing quality students with high, effective and efficient learning abilities. The research method used in this writing is a qualitative method with observation, interview and documentation data collection techniques. In this study, the informants were the principal / vice principal, Islamic Religious Education teachers and students at SMAN 7 Binjai. The results of this study are 1). Islamic Religious Education teachers at SMAN 7 Binjai carry out pedagogical competence quite well with efforts to improve the quality of student learning supported by the school by providing facilities for the development of effective, innovative and creative learning and teaching activities. 2). The teacher''s pedagogical competence is implemented in accordance with the learning plan that has been prepared by the Islamic Religious Education teacher. 3). Students are very receptive to learning to be creative and improve their enthusiasm and quality of learning very well.', 5, 'OPENALEX', '{"doi": "10.24815/jimps.v10i2.34422", "openalex": "https://openalex.org/W4410573934"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('7f287c7e-5444-45d2-bb88-ec9c61dce2b5', 'Electrical Tracking Formation on Silane Epoxy Resin under Various Contaminants', NULL, 2013, '2013-03-01', 'Abdul Syakur; Hamzah Berahim; Tumiran Tumiran; Rochmadi Rochmadi', 'TELKOMNIKA (Telecommunication Computing Electronics and Control)', 'JOURNAL', '10.12928/telkomnika.v11i1.878', 'https://doi.org/10.12928/telkomnika.v11i1.878', 'Contamination at the surface of the insulator becomes a serious problem. Especially for the tropical area, humidity and rainfall play an important role in wetness by the water at the insulator surface, which result in the presence of contaminant and leakage current flowing at the surface. This leakage current will generate heat which occurs at the surface of an insulator. This ultimately leads to flashover. This paper presents the influence of contaminants to leakage current and formation of electrical tracking at the surface of epoxy resin compound wit silicon rubber. The test was based on IPT method with NH4Cl as contaminants. The industrial and coastal contaminants are used to explain the effect of contaminant at surface tracking process. The flow rate of contaminant was 0.3 ml/min. The 3.5 kV AC high voltage 50 Hz was applied to the top electrodes. It is found that industrial contamination resulting in the smallest surface leakage current is 327.6 mA. Also it is found that coastal contaminant showed the severest damage at surface of test sample. Therefore, special treatment of the sample is needed under these conditions so that the material performance can be improved, especially against the electrical tracking.', 11, 'OPENALEX', '{"doi": "10.12928/telkomnika.v11i1.878", "openalex": "https://openalex.org/W2012923940"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1b31be94-4a2e-49f4-8d2c-5166a9e59338', 'Power Oscillation Damping Control using Robust Coordinated Smart Devices', NULL, 2011, '2011-04-01', 'Tumiran Tumiran; Cuk Supriyadi Ali Nandar; Sarjiya Sarjiya', 'TELKOMNIKA (Telecommunication Computing Electronics and Control)', 'JOURNAL', '10.12928/telkomnika.v9i1.646', 'https://doi.org/10.12928/telkomnika.v9i1.646', 'The lack of damping of the electromechanical oscillation modes usually causes severe problems of low frequency oscillations in interconnected power systems. In the extreme operating conditions, PSS may fail to damp power oscillation. This paper pr esents a robust coordinated design of power system stabilizer (PSS) and thyristor controlled series capacitor (TCSC) to damp power oscillation in an interconnected power system. The inverse additive perturbation is applied to represent unstructured uncertainties in the power system such as variations of system parameters, system generating and loading conditions . In addition, genetic algorithm is employed to search a robust tuning to the controller parameters of both PSS and TCSC simultaneously. Simulation studie s have been done in a single machine infinite bus system to confirm that the performance and robustness of the proposed controller are superior to th at of the conventional controller.', 7, 'OPENALEX', '{"doi": "10.12928/telkomnika.v9i1.646", "openalex": "https://openalex.org/W875397722"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('ea562dbb-142f-460f-b393-73981218f844', 'Audiosonic Acoustic Detection of Air Corona Discharge based on Fast Fourier Transform', NULL, 2019, '2019-10-01', 'Mochammad Wahyudi; Tumiran Tumiran; I Made Yulistya Negara; Noor Akhmad Setiawan; Bambang Sugiyantoro', '2019 2nd International Conference on High Voltage Engineering and Power Systems (ICHVEPS)', 'JOURNAL', '10.1109/ichveps47643.2019.9011029', 'https://doi.org/10.1109/ichveps47643.2019.9011029', 'In this paper, acoustic emission in audiosonic range of air corona discharge was detected by using fast Fourier transform (FFT). A microphone was employed to record the acoustic signal of corona that was generated by using a needle-plane electrode with air gap. A high frequency current transformer (HFCT) sensor was used to acquire the partial discharge (PD) current pulses. Furthermore, the PD current pulses were correlated to the recorded acoustic signal. The given ac voltage stress was increased until the light spot appeared on the tip of the needle. The results showed that the acoustic emission of corona could easily be detected by using FFT. Based on the frequency spectrum of acoustic signal, the presence of corona was seen on the high frequency, whereas the noise was found on the low frequency. The high frequency amplitudes created a unique pattern like hilly shapes. Hence, the high pass filter that was applied to the acoustic signal was effective to separate the acoustic signal of corona from the noise. The higher voltage stress, the more visible PD current pulse and the greater high frequency amplitude of acoustic frequency spectrum. However, the occurrence of corona was firstly known by its PD current pulse rather than its acoustic signal.', 5, 'OPENALEX', '{"doi": "10.1109/ichveps47643.2019.9011029", "openalex": "https://openalex.org/W3009967946"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b2b7d5d7-2420-4f4a-bca4-40f90839ed41', 'Aplikasi Mesin Pencari Informasi Buku Berbasis WAP', NULL, 2010, '2010-01-01', 'Puthut punggawasesa; Sujoko Sumaryono; Soedjatmiko Soedjatmiko', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/download.php?dataId=12027', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W135854256"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('089a7881-717a-4ff4-b025-b75675222d4d', 'IMPLEMENTASI PEMBARUAN ALAMAT IP PADA DOMAIN NAME SYSTEMDINAMIS MENGGUNAKAN PYTHON', NULL, 2010, '2010-01-01', 'Yuda Nugrahadi; Sujoko Sumaryono; Addin Suwastomo', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12025', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W146917166"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('fb50cf2a-9bbe-4067-b29b-40c39b147e5e', 'Integration Of Moral Education On Implementation of The 2013 Curricuum In Madrasah Aliyah Swasta Miftahussalam Medan', NULL, 2023, '2023-02-05', 'Dina Raniati; Tumiran Tumiran', 'Educan Jurnal Pendidikan Islam', 'JOURNAL', '10.21111/educan.v7i1.9088', 'https://doi.org/10.21111/educan.v7i1.9088', 'Kurikulum merupakan hal yang penting dalam setiap satuan pendidikan. Sebagaimana dalam judul “Integrasi Pendidikan Akhlak Dalam Penerapan Kurikulum 2013 di Madrasah Aliyah Swasta Miftahussalam Medan”. Penelitian ini bertujuan agar kita dapat mengetahui kesesuaian kurikulum 2013 yang berbasis karakter ini dalam proses menyatukan pendidikan akhlak yang ada disekolah tersebut. Selanjutnya dalam pembahasan ini, peneliti menggunakan metode pendekatan kualitatif deskriptif, diantaranya melalui observasi langsung kesekolah, melakukan wawancara kepada narasumber dan melalui dokumentasi sebagai data pendukung yang dapat digunakan oleh peneliti. Dalam hal yang menjadi pembahasan peneliti, bahwa integrasi merupakan hal yang menghubungkan, mengkaitkan, menyatukan suatu hal dengan objek tertentu. Dengan demikian integrasi pendidikan akhlak dalam menerapkan kurikulum 2013 merupakan hal yang harus ada dan lazim dalam dunia pendidikan. Karena pada dasarnya setiap pembelajaran tentu saja sangat berkaitan dengan pendidikan akhlak. Adapun mata pelajaran yang diterapkan pada madrasah ini berjumlah 21 yang akan menjadi ilmu untuk siswa/siswi MAS Miftahussalam Medan tersebut. Pendidikan memiliki tujuan untuk menjadikan insan yang memiliki kepribadian yang baik. Sasaran yang dituju adalah Madrasah Aliyah, dimana seperti yang kita ketahui bahwa madrasah memiliki kekhususan yang kurikulumnya terdapat pelajaran-pelajaran tentang keIslaman. Maka demikian kurikulum 2013 sudah diterapkan dengan baik disekolah ini. Sebagaimana dalam tujuan pendidikan pada Madrasah Aliyah adalah meningkatkan kecerdasan, pengetahuan yang luas, kepribadian yang baik, memiliki akhlakul karimah yang mulia, serta keterampilan untuk hidup mandiri dan mengikuti pendidikan lebih lanjut.', 3, 'OPENALEX', '{"doi": "10.21111/educan.v7i1.9088", "openalex": "https://openalex.org/W4321378592"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b1b0c8bf-846a-4300-b5cf-18524899a5c6', 'Implementasi Manajemen Pendidikan Berbasis Digitalisasi (Studi Kasus di Mas Tarbiyah Islamiyah Kec. Hamparan Perak Kabupaten Deli Serdang)', NULL, 2024, '2024-11-16', 'Tumiran Tumiran; Bahtiar Siregar; Nanda Rahayu Agustia; Faiza Azhari', 'JIM Jurnal Ilmiah Mahasiswa Pendidikan Sejarah', 'JOURNAL', '10.24815/jimps.v9i4.32899', 'https://doi.org/10.24815/jimps.v9i4.32899', 'Tulisan ini bertujuan untuk menganalisis implementasi manajemen pendidikan berbasis digital di MAS Tarbiyah Islamiyah, Kecamatan Hamparan Perak, Kabupaten Deli Serdang. Digitalisasi di sini mencakup penerapan teknologi informasi dan komunikasi (TIK) dalam aspek administrasi, pengelolaan data, dan pembelajaran di kelas. Metode yang digunakan adalah studi kasus dengan pendekatan kualitatif, melibatkan wawancara mendalam, observasi, dan dokumentasi sebagai teknik pengumpulan data. Subjek penelitian meliputi kepala sekolah, guru, siswa, dan staf administrasi. Hasil penelitian menunjukkan bahwa implementasi manajemen pendidikan berbasis digital di sekolah ini berhasil meningkatkan efisiensi administrasi, seperti pengolahan data siswa dan keuangan yang lebih cepat dan akurat berkat TIK. Digitalisasi dalam pembelajaran juga meningkatkan partisipasi siswa dan akses ke materi, sementara guru merasa terbantu dalam penyusunan rencana pelajaran dan evaluasi hasil belajar yang lebih terstruktur. Tantangan seperti keterbatasan infrastruktur teknologi, ketidakmerataan akses internet, dan perangkat keras yang terbatas masih menghambat optimalisasi digitalisasi. Kompetensi digital pendidik dan tenaga kependidikan juga perlu ditingkatkan untuk mendukung penerapan digitalisasi yang lebih optimal. Studi ini merekomendasikan peningkatan infrastruktur, pelatihan digital, serta kebijakan sekolah yang mendukung digitalisasi sebagai upaya menjadikan MAS Tarbiyah Islamiyah sebagai model manajemen pendidikan berbasis digital bagi sekolah-sekolah lain.', 3, 'OPENALEX', '{"doi": "10.24815/jimps.v9i4.32899", "openalex": "https://openalex.org/W4407000345"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3912df05-4fa4-4a58-affe-0bf5a1396cd2', 'Accelerated Aging Effect on Epoxy-polysiloxane-Rice Husk Ash Polymeric Insulator Material', NULL, 2012, '2012-12-01', 'Tumiran Tumiran; Arif Jaya; Hamzah Berahim; Rochmadi Rochmadi', 'TELKOMNIKA (Telecommunication Computing Electronics and Control)', 'JOURNAL', '10.12928/telkomnika.v10i4.853', 'https://doi.org/10.12928/telkomnika.v10i4.853', 'The performances of outdoor polymeric insulators are influenced by environmental conditions. The use of polymeric materials in a particular composition can be produced insulators that are resistant to environmental influences. This paper presents the effect of artificial tropical climate on the hydrophobicity, equivalent salt deposit density (ESDD), surface leakage current, flashover voltage, and surface degradation on epoxy-polysiloxane polymeric insulator materials with rice husk ash (RHA). Test samples are made at room temperature vulcanized (RTV) of various composition of epoxy-polysiloxane with rice husk ash as filler. The aging was carried out in test chamber at temperature from 50oC to 62oC, relative humidity of 60% to 80%, and ultraviolet (UV) radiation 21.28 w/cm2 in daylight conditions for 96 hours. The experiment results showed that the flashover voltage fluctuates from 34.13 kV up to 40.92 kV and tends to decrease on each variation of material composition. The surface leakage current fluctuates and tends to increase. Test samples with higher filler content result greater hydrophobicity, smaller equivalent salt deposit density, and smaller critical leakage current, which caused the increase of the flashover voltage. Insulator material (RTVEP3) showed the best performance in tropical climate environment. Artificial tropical aging for short duration gives less effect to the surface degradation of epoxy-polysiloxane insulator material.', 7, 'OPENALEX', '{"doi": "10.12928/telkomnika.v10i4.853", "openalex": "https://openalex.org/W852221551"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('04b551df-319e-453b-beb5-a46e4b8403ec', 'Long-Term Electricity Demand Forecast Using Multivariate Regression and End-Use Method: A Study Case of Maluku-Papua Electricity System', NULL, 2021, '2021-09-29', 'Tumiran Tumiran; Sarjiya Sarjiya; Lesnanto Multa Putranto; Edwin Nugraha Putra; Rizki Firmansyah Setya Budi; Candra Febri Nugraha', NULL, 'JOURNAL', '10.1109/ict-pep53949.2021.9601144', 'https://doi.org/10.1109/ict-pep53949.2021.9601144', 'One of the most important stages in electric power system planning is load forecasting. An accurate demand forecast model is required to create the most optimal plan. Long-term demand forecasts are developed in this study using regression and end-use models. Simulation is carried out to determine the load demand of the Maluku-Papua system through 2050. The variables that have the greatest influence on demand forecasting, according to data analysis, are gross regional domestic product (GRDP), population, electrification ratio, and electricity price. The electricity demand in Maluku-Papua is expected to rise by 5.7% in the business as usual (BaU) scenario and 6.7% in the High scenario. The peak load is expected to increase by 5.6% in the BaU scenario and 6.5% in the High scenario. Furthermore, the results of the demand forecast can be used to determine policies and the planning of the electric power system.', 6, 'OPENALEX', '{"doi": "10.1109/ict-pep53949.2021.9601144", "openalex": "https://openalex.org/W3215543413"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('044a4d0e-a4bb-45b9-83c6-5fc1056dc70a', 'Pengelolaan Murid Unggul Berbasis Manajemen Kelas Pendidikan Anak Usia Dini (PAUD)', NULL, 2018, '2018-09-08', 'Tumiran Tumiran', NULL, 'JOURNAL', NULL, 'http://jurnal.dharmawangsa.ac.id/index.php/almufida/article/download/94/89', NULL, 5, 'OPENALEX', '{"openalex": "https://openalex.org/W2972528481"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('544b84e7-a57a-4cf2-b6cd-68901229d8bc', 'Implementasi Komputer Cluster Untuk Melakukan DNA Sequencing Dengan Menggunakan OpenMPI dan mpiBLAST Ivan Aditya Pratikno1, Sujoko Sumaryono2,Widyawan2', NULL, 2010, '2010-01-01', 'Ivan Aditya Pratikno; Sujoko Sumaryono; Widyawan Widyawan', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12553', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2598445850"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('8660d4b6-de87-430b-8ea5-f6618bfea47a', 'PEMBANGKITAN SENGKALAN LAMBA BERBASIS LISP DENGAN PENDEKATAN METODE JOSEPH', NULL, 2010, '2010-01-01', 'Jati Yunita Dwi Kornia Putri; Surjono Surjono; Sujoko Sumaryono', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12555', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2598573012"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1e89725e-f903-4f95-b768-f8e5a6e289ce', 'MENINGKATKAN PRESTASI BELAJAR MELALUI MODEL PEMBELAJARAN CREATIVE PROBLEM SOLVING ( DALAM KAJIAN AQIDAH AKHLAK)', NULL, 2020, '2020-12-27', 'Tumiran Tumiran', 'Jurnal Ilmiah Al-Hadi', 'JOURNAL', '10.54248/alhadi.v6i1.1084', 'https://doi.org/10.54248/alhadi.v6i1.1084', 'Model Creative Problem Solving adalah suatu model pembelajaran yang melakukan pemusatan pada pembelajaran dan keterampilan pemecahan masalah, yang diikuti dengan penguatan ketrampilan. Model pembelajaran Creative Problem Solving siswa dapat berdiskusi kelompok, kerjasama, mandiri, memberikan ide-ide pemikiran tentang suatu konsep serta dapat mengaplikasikan melalui pembelajaran akidah akhlak yang dimana mereka lebih sopan santun, menjaga kebersihan, memberi salam, serta bertanggung jawab atas apa yang mereka lakukan baik itu di dalam kelas mau pun diluar kelas. Peningkatan prestasi belajar siswa berdampak lebih baik karena guru membuat system belajar siswa berkelompok kecil 4-5 orang perkelompok, dan guru menjelaskan prosedur solusi kreatif kepada peserta didik permasalahn, ilustrasi, problematis, dan tugas, pengumpulan data dan verifikasi mengenai suatu peristiwa dan siswa mencari informasi dan menjawab pertanyaan, peserta didik diberikan kesempatan untuk memberikan pendapat (brain storming), baik berdasarkan pengalaman dan pengetahuan peserta didik, membaca referensi, maupun mencari data/informasi dari lapangan.', 3, 'OPENALEX', '{"doi": "10.54248/alhadi.v6i1.1084", "openalex": "https://openalex.org/W3115166066"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9fcf95b9-ac9a-4d0c-9285-8aca5036a819', 'Implementasi Manajemen Kelas Religius Berbasis Digitalisasi Di MAN 3 Langkat', NULL, 2024, '2024-11-30', 'Hakimah Ihsyan; Tumiran Tumiran', 'JIM Jurnal Ilmiah Mahasiswa Pendidikan Sejarah', 'JOURNAL', '10.24815/jimps.v9i4.33756', 'https://doi.org/10.24815/jimps.v9i4.33756', 'Tulisan ini bertujuan untuk menganalisis implementasi manajemen religius berbasis digitalisasi di MAN 3 Langkat dengan melihat aspek-aspek yang telah berjalan dengan baik serta mengidentifikasi berbagai tantangan yang dihadapi. Metode penelitian yang digunakan adalah metode penelitian kualitatif deskriptif dengan teknik pengumpulan data yang dilakukan adalah observasi, wawancara dan dokumentasi. Hasil penelitian antara lain: (1) Perencanaan pembelajaran yang terstruktur: Penyusunan rencana pelaksanaan pembelajaran (RPP) dan persiapan materi atau bahan ajar metode, serta perangkat-perangkat digital yang dibutuhkan. (2) Pengorganisasian kelas yang kondusif: Pengaturan tempat duduk yang bervariasi dan dikelompokkan berdasarkan jenis kelamin sehingga menghindari kedekatan dengan lawan jenis. Ruangan kelas bernuansa hijau dengan pencahayaan yang cukup, hiasan dinding dengan kaligrafi Islami dan slogan-slogan positif, serta jadwal piket untuk membersikan kelas setiap hari. (3) Penerapan nilai-nilai religius: Kebiasaan guru dan peserta didik, seperti bersalaman, berdoa, membaca surah Al-Qur’an, berpakaian yang sopan dan menutup aurat, mendidik dan memotivasi peserta didik, menjaga akhlak serta komunikasi yang baik. (4) Penggunaan digital dalam pembelajaran: Memanfaatkan infocus, laptop, dan smartphone. Platform digital seperti e-book, geogebra, youtobe, quizizz, google forms, serta google drive dan e-learning dalam proses pembelajaran.', 2, 'OPENALEX', '{"doi": "10.24815/jimps.v9i4.33756", "openalex": "https://openalex.org/W4407000195"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('654ca69a-67d2-4e1a-9def-bfd0d82eb564', 'The Role of Parents In Internalizing Islamic Religious Values and Instilling Noble Character (Akhlaq Al-Karimah) in Children in Minority Areas of Lau Gumba Village, Brastagi District, Karo Regency', NULL, 2024, '2024-11-25', 'Hadi Saputra Panggabean; Tumiran Tumiran; Rita Nofianti; Hardakwah Umat', 'JIM Jurnal Ilmiah Mahasiswa Pendidikan Sejarah', 'JOURNAL', '10.24815/jimps.v9i4.33016', 'https://doi.org/10.24815/jimps.v9i4.33016', 'The inculcation of Islamic religious values, particularly concerning noble character (Akhlaq al-Karimah), in children is essential. This effort requires the involvement of various elements, not solely relying on formal educational institutions. It becomes more effective when families and communities are actively engaged. The family environment, often referred to as the first and foremost setting for a child''s education, plays a critical role. In fostering values of goodness and virtue, parents are encouraged to communicate closely with their children. Parents should ideally serve as role models in all aspects of life for their children. Beyond their role as leaders, parents are primary educators within the household. Ideally, parents should guide, educate, train, teach, and exemplify behaviors that shape their children''s character and support their learning activities. In the specific context of Lau Gumba Village, where Muslims are a minority, children are particularly vulnerable to the influences of non-Muslim peers. Additionally, the community''s socio-economic conditions and the educational background of parents contribute to varied parenting styles. Some families provide significant attention to their children, while others tend to neglect the importance of family education, placing full responsibility on schools. Consequently, many children exhibit weak religious values. In this village, some children neglect their five daily prayers, fail to fast during Ramadan, consume alcoholic beverages (tuak), smoke, and adopt negative behaviors influenced by their environment''s traditions', 2, 'OPENALEX', '{"doi": "10.24815/jimps.v9i4.33016", "openalex": "https://openalex.org/W4407000294"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('672d69f9-a3a7-4a15-b959-7a00f5ccf1ed', 'PENGUATAN MASALAH KEPEMIMPINAN TRANSFORMASIONAL KEPALA SEKOLAH DAN PENGELOLAAN BERWAWASAN LINGKUNGAN HIDUP ISLAMI DI SD NEGERI 106153 KLAMBIR LIMA KEBUN HAMPARAN PERAK', NULL, 2022, '2022-08-01', 'Tumiran Tumiran; Rustam Efendi; Bahtiar Siregar', 'Warta Dharmawangsa', 'JOURNAL', '10.46576/wdw.v16i3.2236', 'https://doi.org/10.46576/wdw.v16i3.2236', 'RINGKASAN- Penelitian ini menggunakan jenis penelitian kualitatif deskriptif. Dengan sumber data: (1) Data primer: kepala sekolah, guru/wali kelas dan perwakilan peserta didik. (2) Data sekunder, bahan kepustakaan, penelitian relevan, dan dokumen-dokumen terkait. Prosedur pengumpulan: observasi, wawancara, dokumentasi, dan catatan lapangan. Teknik analisis data: mereduksi data, display data/penyajian data, dan verifikasi/penarikan kesimpulan. Dari hasil penelitian: (1) Penguatan masalah kepemimpinan transformasional kepala sekolah SD Negeri 106153 Klambir Lima Kebun.Kepemimpinan transformasional yang dilaksanakan kepala sekolah: charisma didalamnya indikator memberikan visi dan rasa atas misi, menanamkan kebanggaan, meraih penghormatan dan kepercayaan kepada seluruh guru, dan pegawai. Pola dan cara melaksanakan: stimulasi intlektual, pertimbangan individual dengan memberikan perhatian dan melayani pribadi, melatih dan menasihati guru, senantiasa memberikan dorongan, motivasi, dan mengubah sikap bekerja membangun nilai-nilai yang tinggi, memberikan keyakinan, menciptakan budaya sekolah,dan iklim organisasi sekolah, menjalin komitmen bekerja sistem tim, meningkatkan kepuasan kerja, dan menghilangkan stres para guru dan pegawai, kepercayaan terhadap orang tua, inovasi iptek dan imtaq, serta mampu menghadapi situasi yang rumit; (2) Pengelolaan berwawasan lingkungan hidup Islami SD 106153 Klambir Lima. Program kerja berwawasan lingkungan hidup Islami dituangkan pada kurikulum dengan mengintegrasikan dalam proses pembelajaran dari seluruh mata pelajaran. Tumpuan pelaksanaan: ruang kelas, ruangan kepala sekolah, dan guru, kamar mandi/WC, halaman sekolah dan tempat bermain baik didepan, samping, maupun dibelakang tertata rapi dengan tanaman menghijau, rindang, subur, asri, Pengelolaan sampah, limbah cair sudah sangat baik, pembuangan air kotor dan sampah tersedia dengan baik. Penataan lingkungan didepan kantor ada taman, sela-sela ruang kelas ada tatanan bunga-bungaan, dan dihalam terbuka bebas ada tanaman buah-buhan dan apotik hidup, mushola tempat praktek sholat, bina mental, pengajian, belajar membaca Al-Quraan. Perpustakaan, dan laboratorium komputer yang tertata rapih dan bersih;(3).Faktor penghambat dan pendukung dalam pengelolaan berwawasan lingkungan hidup Islami SD Negeri106153 Klambir Lima Kebun.Kata Kunci: Kepemimpinan Transformasional, Kepala Sekolah, Berwawasan, Lingkungan Hidup Islami.', 1, 'OPENALEX', '{"doi": "10.46576/wdw.v16i3.2236", "openalex": "https://openalex.org/W4312456833"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('bc15c33d-d189-4cb9-86e6-ee2ed9fc8469', 'KEBERADAAN HUKUM ISLAM DAN SISTEM HUKUM DI INDONESIA', NULL, 2023, '2023-05-10', 'Tumiran Tumiran', 'Jurnal Pendidikan Guru', 'JOURNAL', '10.47783/jurpendigu.v4i2.501', 'https://doi.org/10.47783/jurpendigu.v4i2.501', 'Untuk kesempurnaan amanat dan hukum yang sebaik-baiknya dan seadil-adilnya, diperintahkan untuk taat kepada Allah dan taat kepada Rasul-Nya serta pemerintah. Ada tiga katagori hukum yang berlaku dalam pergaulan masyarakt Islam; 1. Syari’at yaitu keetentuan Allah yang berkaitan dengan perbuatan subyek hukum, berupa melakukan suatu perbuatan, memilih atau menentukan sesuatu sebagai syarat, sebab atau penghalang. Syari’at bersifat tetap, tidak berubah dan seharusnya tidak terdapat perbedaan pendapat, 2. Fiqh adalah pemahaman tentang hukum-hukum syara yang bersfat perbuatan yang dipahami dari dalil- dalilnya yang rinci. Fiqh adalah hasil kemampuan intelektualitas (Ijtihad) ulama terhadap dalil-dalil hukum yang terdapat pada Al-Quran dan Hadis, yang selalu berkembang dan selalu terdapat perbedaan pendapat, 3. Siyasah syari’ah adalah kewenangan pemerintah untuk melakukan kebijakan yang dikehendaki oleh kemaslahantan, melalui aturan yang tidak bertentangan dangan agama, meskipun tidak adil ada dalil tertentu. Siyasah syari’ah lebih terbuka dalam menerima perkem-bangan dan perbedaan pendapat. Perbedaan kondisi dan zaman berpengaruh besar terhadap siyasah syari’ah.', 1, 'OPENALEX', '{"doi": "10.47783/jurpendigu.v4i2.501", "openalex": "https://openalex.org/W4382520448"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('66740c60-b7ea-42cd-9753-6251bf219edb', 'APLIKASI SMS (Short Messages Service) GATEWAY UNTUK PENJADW ALAN ANTRIAN PASIEN', NULL, 2010, '2010-01-01', 'Manumpak Aguswan; Sujoko Sumaryono; Markus Nurtiantara', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12561', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2756877751"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('21abf6d7-0380-4b2f-b325-1846209c8806', 'Kebijakan Pertamina dalam Perdagangan Minyak Indonesia (1969–2015)', NULL, 2019, '2019-09-15', 'Sukusen Soemarinda; Yeremias T. Keban; Muhadjir Darwin; Tumiran Tumiran', 'Populasi', 'JOURNAL', '10.22146/jp.44151', 'https://doi.org/10.22146/jp.44151', 'Pertamina has a long history of oil trading and was influenced by the actors seizing for the power. The first oil shipments was held in 1958, while this research only discussesPertamina oil trading from 1969 to 2015 through a special subsidiary which was established to carry out the trading for almost fifty years since it was still named as Perta Group (1969) until Petral (2015). The purpose of this research is to know how Pertamina oil trading policy was specified and implemented over a period of time and parties affecting the process so rent- seeking and corruption happened throughout the history of Pertamina oil trading. The method of research a descriptive qualitative method of case study. The data was collected from various documents and interview of perpetrators related. Based on the research carried out, Pertamina oil trading from Perta Group (1969) until Petral (2015) could be classified into three periods, i.e. Perta Group period (1969-1978), POML period (1978-1998), and Petral (1998-2015). The first and second period occurred under the authority of the New Order government, while the third period under the reformation periodThe first period was characterized by the domination of military interests and the second period influenced by the interests of inner circle and family business related to the ruler of the New Order and the third period was dominated by the influence of powerfull person/company.', 1, 'OPENALEX', '{"doi": "10.22146/jp.44151", "openalex": "https://openalex.org/W2922144860"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d0b9b0dc-8d89-4f31-96a0-8ad8e6f2f6a5', 'Aktor dan Konfigurasi Subsistem dalam Perubahan Kebijakan Pengolahan Sampah Menjadi Listrik di Provinsi DKI Jakarta', NULL, 2019, '2019-09-15', 'Sri Utami Gayatri; Muhammad Baiquni; Muhadjir Darwin; Tumiran Tumiran', 'Populasi', 'JOURNAL', '10.22146/jp.44149', 'https://doi.org/10.22146/jp.44149', 'Population growth in DKI Jakarta Province continues to increase. The consequence of population increase is indeed in the volume of waste which also continues to increase and at the same time the need for energy is increasing. Since 2011 DKI Provincial Government has implemented waste to energy (WTE) in Bantargebang TPST, but it was not as the main processing unit. Since 2011, DKI Provincial Government has also compiled a plan (2012-2032 Waste Management System Master Plan) to make WTE as a central processing unit by making an Intermediate Treatment Facility (ITF) at four points in DKI Jakarta Province. It was only in 2018, one ITF in Sunter began to be built. To unravel the problem of the slow implementation of RISPS, researcher tried to map the existing network of actors and to explore the extent to which the configuration of the subsystem accepted new ideas and actors in the context of accelerating WTE development. The results of this study indicated that the policy change process runs gradually paradigmatically oriented to policy goals in an open subsystem.', 1, 'OPENALEX', '{"doi": "10.22146/jp.44149", "openalex": "https://openalex.org/W2931448922"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9528f14e-b19a-45c5-ab3e-efce69c7d3ab', 'TEKNIK IDENTIFIKASI POLYCHAETA DI DELTA MAHAKAM, KALIMANTAN TIMUR', NULL, 2019, '2019-01-16', 'Dewi Apriyanti; Tumiran Tumiran', 'BULETIN TEKNIK LITKAYASA Sumber Daya dan Penangkapan', 'JOURNAL', '10.15578/btl.16.1.2018.49-53', 'http://ejournal-balitbang.kkp.go.id/index.php/btl/article/download/7454/6034', 'Secara geografis Delta Mahakam terletak pada 117o 26’ – 1170 63’ BT dan 0o 33’ – 0o 92’ LS. Secara administratif kawasan delta Mahakam berada dalam wilayah kabupaten Kutai Kartanegara, tepatnya berada di Kecamatan Anggana, Muara Jawa dan Sanga-Sanga. Kawasan ekosistem di Delta Mahakam memiliki vegetasi mangrove yang telah rusak akibat alih fungsi lahan menjadi tambak dan kegiatan tambang batubara. Selain itu, kerusakan hutan mangrove di Delta Mahakam juga diakibatkan oleh jalur kapal pengangkut batubara dan limbah rumah tangga. Pengelolaan wilayah yang kurang baik telah menyebabkan perubahan kondisi lingkungan di wilayah tersebut yang berakibat pada kerusakan ekosistem di dalamnya, termasuk polychaeta. Polychaeta adalah jenis cacing Annelida yang umumya hidup di laut, sebagian juga ditemukan di sungai, danau dan sebagian hidup di daratan. Seluruh permukaan tubuh Polychaeta terdapat rambut-rambut kaku atau setae yang dilapisi kutikula sehingga licin dan kaku. Tubuhnya berwarna menarik, seperti ungu kemerah – merahan. Setiap segmen tubuh polychaeta dilengkapi dengan sepasang alat gerak atau alat berenang yang disebut parapodia, pada cacing yang bergerak aktif (Errantia), tetapi pada cacing yang relative lambat bergerak (Sedentaria) tidak memiliki parapodia. Parapodia berperan sebagai alat pernapasan. Ukuran polychaeta sebagian besar berukuran 5 – 10 cm, tetapi ada yang kurang dari 1 mm (misalnya Diurodrilus), ada juga yang mencapai 3 mm (Namalycastis rhodochorde).', 1, 'OPENALEX', '{"doi": "10.15578/btl.16.1.2018.49-53", "openalex": "https://openalex.org/W2942765160"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('af35715a-d811-4207-af55-475dae8f16ff', 'Regional Clustering for Developing Electricity Systems in Archipelagic Area: A Case Study of Maluku and Papua Islands', NULL, 2021, '2021-09-29', 'Tumiran Tumiran; Rachmawan Budiarto; Sarjiya Sarjiya; Lesnanto Multa Putranto; D Y N Naimah; Abdan Hanifan Dharmasakya; Adi Priyanto', NULL, 'JOURNAL', '10.1109/ict-pep53949.2021.9601113', 'https://doi.org/10.1109/ict-pep53949.2021.9601113', 'Maluku and Papua islands have complex geographical conditions, thousands of small islands, uneven population densities, and lower income distribution compared to other part of Indonesia. Therefore, the development of electricity system cannot be performed by assuming that every area has the same growth characteristics. In this study, clustering is performed to group the areas with the same characteristics. Hence, the development of electricity system can be based on this clustering. This study used k-means clustering algorithm to perform the clustering method. In this study there are six clusters created based on the data such as, population, average growth of population, Gross Regional Domestic Product (GRDP), and average growth of GRDP. These six clusters can be used as a reference for the development of electricity system in Maluku and Papua Islands.', 1, 'OPENALEX', '{"doi": "10.1109/ict-pep53949.2021.9601113", "openalex": "https://openalex.org/W3215480876"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('93ab2ed6-2125-4dea-8c59-ec4732304d41', 'Perbandingan Unjuk-Kerja Protokol Transport Pada Jaringan MPLS dan non MPLS : Studi Kasus Jaringan di Jurusan Teknik Elektro Politeknik Negeri Bandung', NULL, 2009, '2009-08-04', 'Malayusfi Malayusfi; Risanuri Hidayat; Sujoko Sumaryono', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/37626/', 'Makalah ini merupakan hasil analisis unjukkerja
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('eea19c8a-f97e-4332-98b8-11561745deb7', 'Character Education Strategy Through Systemic-Integrative Model in Modern Pesantren Ar-Raudlatul Hasanah Medan', NULL, 2021, '2021-11-30', 'Manshuruddin Manshuruddin; Tumiran Tumiran; Muhammad Yunan; Hamdan Hamdan', 'International Journal of Social Science Research and Review', 'JOURNAL', '10.47814/ijssrr.v4i4.116', 'https://doi.org/10.47814/ijssrr.v4i4.116', 'This research aims to find out the character values developed in Ar-Raudlatul Hasanah pesantren and its implementation strategy. This research method uses qualitative methods with descriptive types of analytical. The results showed that the implementation of character education in Ar-Raudlatul Hasanah boarding school refers to a systemic-integrative model. All components of education in the formation of santri''s character have a strong relationship with each other that is built systematically and integrated. All santri activities from waking up in the morning to going back to sleep at night accumulated in the pesantren system and culture based on the values of Panca Jiwa consisting of sincerity, simplicity, independence, Ukhuwah Islamiyah, Freedom. In addition, pesantren also developed the motto that is virtuous, able-bodied, knowledgeable, free-thinking, and charitable. These character-building values are applied and developed systemically-integratively through learning activities in the KMI curriculum, the formation of pesantren culture/ culture, and through co-curricular and extracurricular activities. Methods used in the application of character education values are direction, transparency, assignment, training, habituation, discipline, appreciation, and punishment. Therefore, it can be said that Pesantren Ar-Raudlatul Hasanah is a modern system pesantren that applies character education systematically and is integrated into the overall totality of education starting from the learning process, pesantren management, and daily activities.', 1, 'OPENALEX', '{"doi": "10.47814/ijssrr.v4i4.116", "openalex": "https://openalex.org/W3217458781"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('cab04cc8-7484-467d-811b-36cf58fc2e78', 'Monitoring and Troubleshooting of Subsea MPFM by KPIs and Virtual Metering Application in Offshore Environment', NULL, 2022, '2022-10-31', 'Fabrizio Ursini; Antonio Torsello; Simone Fiorita; Abimbola Akinmade; Giuseppe Ciriello; Emanuele Vignati; Tumiran Tumiran', NULL, 'JOURNAL', '10.2118/211139-ms', 'https://doi.org/10.2118/211139-ms', 'Abstract This paper presents the application of real time monitoring techniques on production allocation in a complex scenario, focusing on definition of dedicated KPIs to identify possible issues in flowmeters installed at well level. The analysis includes a comparison with a dedicated Virtual Meter system. Real time production allocation is monitored by means of a dedicated KPI dashboard, detecting any possible drift in Multiphase Flowmeter (MPFM) measurement processes. The ratio between reference measurements and MPFM readings is calculated for assessing allocation quality. Furthermore, an independent virtual flowmeter (VM) technique was developed to estimate well production rates and compare them with the MPFM flow rates. The VM relies on analytical models (Vertical Lift Performance) to correlate real time pressure losses in the tubing with flow rates. KPIs monitoring and VM are developed in a digital environment available to the engineers operating the field to provide a quick problem detection and a promptly response. During the initial production phase, a good match between subsea and topside total MPFM readings and daily production figures resulted in a robust production back allocation. This trend was confirmed by the dashboard of allocation KPIs being within the acceptable thresholds. The Virtual Metering system was calibrated against MPFM rates during this initial production phase. After one year of production, KPIs showed a drift between the total subsea and topside MPFM readings, while a good match was achieved by virtual metering, topside MPFM and daily fiscal production. A well by well comparison between VM and MPFM installed at wellhead allowed to identify reliable MFPM and pinpoint the ones requiring retuning. In the meantime, during the troubleshooting process and actions implementation to restore the MPFM functionalities, the virtual metering estimations were used in the production back allocation process. A combined application of the Virtual Meter and the KPIs monitoring enabled us to improve the quality of back allocation relying on the best type of well production estimation available at each phase of production. The methodology described in this paper entered the daily routines followed by engineers operating the field. This paper shows the benefits of the digital platform for asset monitoring, as well as the technology that allowed to set up a cooperative environment. Sharing real-time data and model based estimation for a multi-disciplinary team, from Reservoir to Operations, facilitated working together to achieve faster trouble shooting and optimize production performance.', 1, 'OPENALEX', '{"doi": "10.2118/211139-ms", "openalex": "https://openalex.org/W4307665148"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3a8c7d97-1077-4f63-8694-7d54d0509eb4', 'PENINGKATAN KINERJA GURU DALAM PEGEMBANGAN KUALITAS PESERTA DIDIK MELALUI BUDAYA ORGANISASI SEKOLAH (Perspektif Dalam Kajian Nilai-nilai Religius)', NULL, 2018, '2018-11-22', 'Tumiran Tumiran', 'Jurnal Ilmiah Al-Hadi', 'JOURNAL', '10.54248/alhadi.v3i2.358', 'http://dx.doi.org/10.54248/alhadi.v3i2.358', 'Peningkatan Kinerja Guru dalam Pengembangan Kualitas Peserta Didik Melalui Budaya Organisasi Sekolah sangat penting dalam kajian nilai- nilai relegius. Karena variabel-variabel tersebut saling berkaitan dan berkontribusi sangat kuat dimana peningkatan kinerja guru yang memiliki nilai-nilai religius menunjang kualitas individu guru berdampak dalam peningkatan kualitas peserta didik secara langsung pada setiap proses pembelajaran baik pada rana afektif, kognitif, maupun psikomotorik. Pengembangan kualitas peserta didik dibarengi dengan kekuatan nilai-nilai relegius yang terbangun secara konfrehensif memiliki kualitas individunya yang didorong oleh kekuatan keprofesionalisme guru pada saat melaksanakan proses pembelajaran. Budaya organisasi sekolah lebih dominan membentuk sebuah karakteristik kepribadian peserta didik dengan nilai-nilai religius yang terkait dengan seluruh warga sekolah melandasi perilaku, tradisi, kebiasaan keseharian, dan simbol-simbol, serta nilai-nilai keyakinan, asumsi, pemahaman yang dijadikan pedoman untuk pemecahan masalah baik internal maupun eksternal.', 1, 'OPENALEX', '{"doi": "10.54248/alhadi.v3i2.358", "openalex": "https://openalex.org/W4402629460"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e1b9778b-a1ed-48c7-b5dc-0313cbbf4d1b', 'Pengujian Karakteristik Limbah Pasir PLTP Dieng Sebagai Bahan Pengisi Isolator Resin Epoksi Silane', NULL, 2013, '2013-02-27', 'Abdul Syakur; Tumiran Tumiran; Hamzah Berahim; Rochmadi Rochmadi', 'Jurnal Natural (Faculty of Mathematics and Natural Science, Syiah Kuala University)', 'JOURNAL', NULL, 'http://jurnal.unsyiah.ac.id/JRE/article/view/154', 'Epoxy resin has been developed as an insulator material on the distribution and transmission line. In its development, the basic composition of DGEBA epoxy resin with MPDA as hardener is hydrophilic. Silane is added to improve the surface properties of materials to be more hydrophobic. To reduce the volume of epoxy resin as base material, silica sand from PLTP Dieng is added as filler. This paper presents the results of research on the effect of adding the composition of silica materials from PLTP Dieng upon silane epoxy resin sample to the value of the dielectric loss factor, contact angle and leakage current. Samples were prepared with a sample size 120mm x 50mm x 5mm. Material is composed of DGEBA, MPDA, silanes and silica with a various composition. Sample codes were 10%, 20%, 30%, 40% and 50%. Contact angle and leakage current were carried out according with IEC 587:1984 standards. Measurement of the dielectric loss factor (Tan ) was carried out at the Laboratory of High Voltage Engineering, PT. PLN (Persero) Electricity R&D, Duren Tiga Jakarta, using a measuring instrument series M4100 Insulation Analyzer Instrument. The electrodes used in these measurements have diameter of 2.5 cm and 5 cm. The results showed that the composition of silica materials PLTP Dieng upon silane epoxy resin samples affect the value of dielectric loss factor. Based on the results of the measurement, it is concluded that the higher composition of silica materials, the higher value of dielectric loss factor are. Based on these results, it is suggested that the use of silica as a filler must consider the effect on the value of dielectric loss factor. When the dielectric loss factor is high, then the losses in the dielectric material is also high.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2133985294"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('90bfcf50-73ae-4590-b3ad-561b75ee8062', 'PENGARUH PENAMBAHAN KARET SILIKON TERHADAP SUDUT KONTAK HIDROPOBIK DAN KARAKTERISTIK ARUS BOCOR PERMUKAAN PADA BAHAN RESIN EPOKSI', NULL, 2010, '2010-12-01', 'Abdul Syakur; Ika Novia; Sarjiya Sarjiya; Tumiran Tumiran; Hamzah Berahim', 'DOAJ (DOAJ: Directory of Open Access Journals)', 'JOURNAL', NULL, 'https://doaj.org/article/9092a9fb0012462cb9d08adcc3796b16', 'Currently, polymer materials such as epoxy resin have been used as an insulator in the distribution and<br />transmission line. Some advantages of using this epoxy resin material having the dielectric properties are better than<br />porcelain and glass insulators. On the other side, epoxy resins are also disadvantage the surface is hygroscopic. For<br />the repair was done by adding the surface properties of silicone rubber material<br />This paper describes the effect of adding silicone rubber against contact angle of hidrophobicity and surface<br />leakage current characteristics of epoxy resin materials ( Di-Glycidyl Ether of Bisphenol A (DGEBA) and<br />Methaphenylene-Diamine (MPDA). The study was conducted in the laboratory using the electrode method IEC<br />587:1984 with NH4Cl contaminants. The voltage applied to the epoxy resin sample at 3.5 kV and 50 Hz frequency<br />The experimental results showed that the addition of silicon rubber in epoxy resin makes the surface material<br />contact angle increases. The higher percentage of silicone rubber, the greater the contact angle and the longer time<br />required for the occurrence of surface discharge.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2178588797"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2e091a63-2940-436b-b6cd-f0bc5b1a99bf', 'Perbaikan Tegangan Pada Penyulang SMU 5 Dengan Pemasangan Kapasitor Shunt', NULL, 2010, '2010-01-01', 'Wilson Pamintu; Bambang Sugiyantoro; Harnoko', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', '10.1016/s0140-6736(96)90934-4', 'http://i-lib.ugm.ac.id/jurnal/download.php?dataId=12002', NULL, 0, 'OPENALEX', '{"doi": "10.1016/s0140-6736(96)90934-4", "openalex": "https://openalex.org/W8622500"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1f7f6fed-dc03-45f0-8ab1-bc265abca995', 'Rancangan Mekanisme Pelepasan Beban Otomatis Pada Kabel Laut 4.16 KV di Lapangan Yakin Selat Makassar PT. Chevron Indonesia Company', NULL, 2010, '2010-01-01', 'Yoga Ernanto Prabowo; Tri Haryono; Bambang Sugiyantoro', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12006', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W92846064"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('61ce83b2-5559-4972-963f-79ff13d9a77b', 'Aplikasi Desktop Perhitungan Biaya Pembuatan Gerobak Alumunium CV. Mitra Alumunium', NULL, 2015, '2015-09-09', 'M. Sofjan; Tumiran Tumiran', 'JURNAL SISFOTEK GLOBAL', 'JOURNAL', '10.38101/sisfotek.v5i2.86', 'http://journal.stmikglobal.ac.id/index.php/sisfotek/article/download/86/88', 'Saat ini sering kita temui para pedagang terutama pedagang makanan yang menggunakan gerobak aluminium dengan berbagai model dan ukuran. Banyaknya minat penggunaan gerobak aluinium sekarang ini menjadikan perusahaan yang membuat gerobak aluminium menjadi peluang untuk terus berkebang dan mendapat banyak pesanan pembuatan gerobak dari para pengusaha franchise tersebut dan CV Mitra Aluminium adalah salah satu perusahaan yang membuat gerobak aluminium. Pesatnya perkembangan usaha pembuatan gerobak ini ternyata tidak dibarengi dengan pengelolaan dan perhitungan biaya pembuatan gerobak tersebut. Perusahaan masih menggunakan sistem yang manual dengan menggunakan buku besar dan menggunakan Microsoft Office (Word dan Exel). Berbagai permasalahan akibat penggunaan sistem yang manual ini mengakibatkan perusahaan sulit mengetahui harga bahan baku yang akan digunakan, sulit menghitung biaya pembuatannya, sulit menetapkan harga jual, sulit mengelola data-data dan transaksi dengan cepat dan sulit untuk menyimpan dan menggunakan kembali data yang diperlukan. Metode penelitian tentang perhitungan biaya pembuatan gerobak aluminium ini pertama-tama dilakukan dengan metode pengumpulan data yaitu dengan cara wawancara, observasi dan studi pustaka. Tahap kedua adalah metode perancangan sistem dengan menggunakan UML Diagram (Use Case Diagram, Activity Diagram, Sequence Diagram, Class Diagram), perancangan basis data dan kemudian perancangan menu antarmuka. Tahap ketiga yaitu implementasi dan pengujian unit dengan menggunakan Visual Basic 6.0. Tahap  keempat metode testing dengan Black Box Test. Dari penelitian yang dilakukan dihasilkan Aplikasi Perhitungan Biaya Pembuatan Gerobak Aluminium Berbasis Desktop. Aplikasi ini memiliki menu master data, menu transaksi dan menu laporan yang dapat digunakan dalam mengelola bisnis bagi CV. Mitra Aluminium.', 0, 'OPENALEX', '{"doi": "10.38101/sisfotek.v5i2.86", "openalex": "https://openalex.org/W2496478975"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c6c45e32-7974-4983-8f66-7943b7f4f0f1', 'PENGUKURAN MORFOMETRIK IKAN BAUNG MUNTI (Bagrichthys macracanthus) DI SUNGAIMUSI', NULL, 2016, '2016-11-21', 'Yanu Prasetiyo Pamungkas; Tumiran Tumiran', 'BULETIN TEKNIK LITKAYASA Sumber Daya dan Penangkapan', 'JOURNAL', '10.15578/btl.10.1.2012.31-34', 'https://doi.org/10.15578/btl.10.1.2012.31-34', 'Ikan baung munti adalah salah satu famili dari Bagridae. Mempunyai ciri sungut rahang bawah bagian luar maupun dalam lurus. Berwarna hitam dengan garis putih sepanjang gurat sisi. Sirip lemak panjang dan tidak terikat oleh badan bagian belakang (Kottelat et al., 1993).Dari ikan contoh yang diperoleh diSungai Musi telah ditemukan tiga jenis ikan baungmunti yaitu jenis Bagroides melapterus, Bagrichthys macracanthus, dan Bagrichthys micranodus.Setiap ikan mempunyai ukuran yang berbeda beda, tergantung pada umur, jenis kelamin, dan keadaan lingkungan hidupnya. Faktor-faktor lingkungan dapat mempengaruhi kehidupan ikan antara lainmakanan, pH, suhu, dan salinitas, dengan demikian, walaupun dua ekor ikan mempunyai umur yang sama namun ukuran mutlak di antara keduanya dapat saling berbeda.Ukuran ikan adalah jarak antara suatu bagian tubuh dengan bagian tubuh yang lainnya. Pada tulisan ini akan diinformasikan tentang hasil dari pengukuran morfometrik pada ikan baungmunti jenis Bagrichthysmacracanthus yang hidup di Sungai Musi bagian hilir. Pengukuran morfometrik merupakan', 0, 'OPENALEX', '{"doi": "10.15578/btl.10.1.2012.31-34", "openalex": "https://openalex.org/W2552722327"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5416062a-b469-46b5-9225-e9afd5bfd2d5', 'PENERAPAN METODE KOOPERATIF TIPE NUMBER HEADSTOGETHER UNTUK MENINGKATKAN HASIL BELAJAR PADA MATERI PENJUMLAHAN DAN PENGURANGAN BILANGAN DESIMAL SISWA KELAS IV SD NEGERI 003 KUNDUR', NULL, 2018, '2018-07-30', 'Tumiran Tumiran', 'JURNAL PAJAR (Pendidikan dan Pengajaran)', 'JOURNAL', '10.33578/pjr.v2i4.5706', 'https://doi.org/10.33578/pjr.v2i4.5706', 'The design of this research is classroom action research. The purpose of the study is to increase the low scoreobtained by the students which is under the KKM. Before conducting the research, pre-cycle test was held with theresult is the total of the score in one class 1177 with average score 58.85 and not complete 65.00% and complete35.00%, while the lowest one is 52 and the highest is 75. The treatment in the first cycle increased to the total ofscore 1337 which is average 66.85 and 25.00% not complete and 75.00% complete with the lowest score 50 and thehighest 83. Furthermore for cycle II the total of values increased to 1528, the average score of 76.65 and thestudents passed 100 %. Subjects in this study were the fourth grade of SD Negeri 003Kundur. Subject matter of theteaching material Mathematics is summation and decimal number reduction, semester II with basic competency ingrade IV SD Negeri 003Kundur. The method used in this research is the method Numbered Heads Together. Theresearch cycle is carried out twice (cycle I and cycle II). Each cycle, teacher and student observations and learningoutcomes was held. So the use of inquery method can improve the motivation and learning outcomes the fourthgrade students of SD Negeri 003Kundur.', 0, 'OPENALEX', '{"doi": "10.33578/pjr.v2i4.5706", "openalex": "https://openalex.org/W2921805212"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4241204a-2a38-432c-a624-243b533016f5', 'Fault Location Algorithm for HVDC Transmission Based on Synchronized Fault Time', NULL, 2019, '2019-09-24', 'Kristianto Adi Widiatmoko; F. Danang Wijaya; Tumiran Tumiran', 'IJITEE (International Journal of Information Technology and Electrical Engineering)', 'JOURNAL', '10.22146/ijitee.44926', 'https://doi.org/10.22146/ijitee.44926', 'To determine the fault location of the dc line fault in an HVDC transmission system, a new algorithm based on the traveling wave method and learning based method is proposed in this paper. The relationship between the traveling wave time of arrival differences with fault location is presented. The differences in traveling wave time of arrival measured at both ends of transmission line combined with associated fault locations form a fault pattern which is used to perform a simple calculation in order to determine the disturbance location. The fault current for different fault locations is simulated using the electromagnetic transient simulation software EMTDC/PSCAD. Performance of the proposed fault location algorithm is investigated using various fault location and resistance. The impact of data sampling rate also being investigated here. The simulation result shows that the proposed algorithm can reduce the sampling frequency and the number of train feature with the same accuracy.', 0, 'OPENALEX', '{"doi": "10.22146/ijitee.44926", "openalex": "https://openalex.org/W2980184352"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('02e2b96e-7f41-4e6d-aee9-7279588de8c9', 'Pengaruh Perubahan Kelembaban Udara terhadap Kegagalan Tegangan pada Berbagai Jenis Permukaan Elektroda', NULL, 1988, '1988-08-20', 'Tumiran Tumiran', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/275945/', 'Kegagalan tegangan antara dua elektroda yang
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5f245c1a-12f4-4d2b-9c81-bf6c93948b42', 'BERBASIS KECERDASAN LINGUISTIK DALAM PENGUATAN PEMBELAJARAN PENDIDIKAN AGAMA ISLAM DI MTS SWASTA DESA KELAMBIR V', NULL, 2022, '2022-08-01', 'Bahtiar Siregar; Tumiran Tumiran; Ismaraidha Ismaraidha; Dewi Indah Noviana Pratiwi', 'Warta Dharmawangsa', 'JOURNAL', '10.46576/wdw.v16i3.2228', 'https://doi.org/10.46576/wdw.v16i3.2228', 'RINGKASAN - Kemampuan untuk memahami sesuatu dan kemampuan untuk mengungkapkan pikiran seseorang. Semakin cerdas seseorang, semakin mudah bagi mereka untuk memahami suatu masalah dan semakin cepat mereka dapat menyelesaikannya. Penelitian ini bertujuan untuk menilai penerapan model kecerdasan linguistik pada siswa MTs Swasta Desa Kelambir V. Penelitian ini merupakan penelitian kualitatif dengan menggunakan metode observasi, wawancara, dan dokumentasi. Pengumpulan data ini digunakan untuk analisis data. Dari tahap observasi hingga penyusunan RPP, pelaksanaan pembelajaran, dan tahap penilaian, semuanya didasarkan pada kecerdasan linguistik, dengan hasil yang cukup menggembirakan dan menghasilkan umpan balik yang lebih banyak daripada yang biasanya diberikan oleh guru mata pelajaran Pendidikan Agama Islam. di sekolah, guna lebih meningkatkan kecerdasan linguistik siswa di kelas. Dengan kata lain, pendekatan pembelajaran berbasis kecerdasan linguistik ini dapat diterapkan pada mata kuliah lain. Padahal, efek dari pertumbuhan ini dapat meningkatkan kecerdasan bahasa siswa pendidikan agama.KataKunci: Kecerdasan Linguistik, Pengembangan Pembelajaran Agama Islam', 0, 'OPENALEX', '{"doi": "10.46576/wdw.v16i3.2228", "openalex": "https://openalex.org/W4312230471"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('834b246c-8cb7-44f0-af38-a4f57ca3241c', 'Tinjauan Pembelajaran Fiqih Mawaris Madrasah Aliyah Tarbiah Islamiyah Kecamatan Hamparan Perak Kabupaten Deli Serdang', NULL, 2024, '2024-03-05', 'Sakban Lubis; Tumiran Tumiran; Muhammad Yunan Harahap; Sinta Rahayu', 'Jurnal Keislaman', 'JOURNAL', '10.54298/jk.v7i1.4071', 'https://doi.org/10.54298/jk.v7i1.4071', 'Harta waris merupakan masalah yang rawan sering menimbulkan perselisihan dan pertengkaran anta sesama keluarga, dalam beberapa budaya, anak laki-laki sering kali dianggap memiliki hak yang lebih besar atas harta warisan daripada anak perempuan. Penelitian ini bertujuan untuk mengevaluasi proses pembelajaran fiqih mawaris di madrasah tersebut, serta untuk menilai efektivitas metode yang digunakan dalam proses pembelajaran tersebut. Metode penelitian yang digunakan adalah metode deskriptif kualitatif dengan teknik pengumpulan data melalui observasi, wawancara, dan studi dokumentasi. Hasil penelitian menunjukkan bahwa proses pembelajaran fiqih mawaris di Madrasah Aliyah Swasta Tarbiah Islamiyah mengalami beberapa kendala, antara lain kurangnya pemahaman konsep, kurangnya penggunaan metode pembelajaran yang bervariasi, serta kurangnya sumber belajar yang memadai. Berdasarkan hasil analisis, disarankan untuk meningkatkan pemahaman konsep melalui pendekatan yang lebih praktis, mengimplementasikan metode pembelajaran yang inovatif, dan menyediakan sumber belajar yang lebih lengkap dan aktual. Diharapkan penelitian ini dapat memberikan kontribusi positif bagi pengembangan pembelajaran fiqih mawaris di madrasah tersebut.', 0, 'OPENALEX', '{"doi": "10.54298/jk.v7i1.4071", "openalex": "https://openalex.org/W4399338909"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d40af084-64ad-4792-a26b-be116a9169f1', 'Tinjauan Pembelajaran Fiqih Mawaris Madrasah Aliyah Tarbiah Islamiyah Kecamatan Hamparan Perak Kabupaten Deli Serdang', NULL, 2024, '2024-03-01', 'Sakban Lubis; Tumiran Tumiran; Muhammad Yunan Harahap; Sinta Rahayu', 'Jurnal Keislaman', 'JOURNAL', '10.54298/jk.v7i1.259', 'http://dx.doi.org/10.54298/jk.v7i1.259', 'Inheritance is a sensitive issue that often leads to disputes and conflicts within families. In some cultures, sons are often considered to have greater rights to inheritance than daughters. This research aims to evaluate the process of teaching inheritance fiqh (Islamic jurisprudence) in the madrasah, as well as to assess the effectiveness of the methods employed in the teaching process. The research methodology employed is qualitative descriptive method, utilizing data collection techniques such as observation, interviews, and documentary studies. The research findings indicate that the process of teaching inheritance fiqh at Madrasah Aliyah Swasta Tarbiah Islamiyah faces several challenges, including a lack of conceptual understanding, The research findings also highlight insufficient utilization of diverse teaching methods, as well as inadequate learning resources. Based on the analysis, it is recommended to enhance conceptual understanding through a more practical approach, implement innovative teaching methods, and provide comprehensive and up-to-date learning resources. It is hoped that this research will contribute positively to the development of inheritance fiqh teaching in the madrasah.', 0, 'OPENALEX', '{"doi": "10.54298/jk.v7i1.259", "openalex": "https://openalex.org/W4402316325"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('64e47aab-da48-4672-b481-9851046a48de', 'Implementation of Legal Protection for Children as Victims of Domestic Violence in Lau Gumba Village', NULL, 2024, '2024-12-31', 'Arif Sahlepi; Tumiran Tumiran; Charles Rangkuti; Syafira Ardani', 'Pena Justisia Media Komunikasi dan Kajian Hukum', 'JOURNAL', '10.31941/pj.v23i3.4481', 'https://doi.org/10.31941/pj.v23i3.4481', 'This research aims to determine the implementation of legal protection for children as victims of domestic violence in Lau Gumba Village and to determine the obstacles faced in providing protection for children as victims of domestic violence. This research was conducted at the Berastagi District Police and the Berastagi District Prosecutor''s Office using technical observation or direct observation and interviews, namely by communicating directly through interviews with several Berastagi District Police legal officers and other informants as well as distributing questionnaires to prosecutors at the Berastagi District Prosecutor''s Office. In relation to the legal protection of children which has been stipulated in Law Number 23 of 2002 jo Unbdang - Law Number 35 of 2014 and Law Number 13 of 2006 concerning the protection of witnesses and victims which is the basis of the 1945 Constitution of the Republic of Indonesia as a rule that guarantees legal protection towards children who are victims of domestic violence. The author will provide an overview of the forms of legal protection for children who are victims of domestic violence in Lu Gumba Village which are not optimal from the perspective of Law Number 23 of 2002. The obstacles faced in providing legal protection for children as victims of violence in the household, namely: traditional constraints, psychological constraints of children and the constraints of ignorance of the children themselves and society. As well as several obstacles faced by law enforcement officers', 0, 'OPENALEX', '{"doi": "10.31941/pj.v23i3.4481", "openalex": "https://openalex.org/W4406031906"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f5edeec4-de0e-4c4d-a563-6afce6c960cb', 'Rancang Bangun Identity and Access Management IoT Berbasis KSI dan Permissioned Blockchain', NULL, 2018, '2018-11-22', 'Guntur Dharma Putra; Sujoko Sumaryono; Widyawan Widyawan', 'Jurnal Nasional Teknik Elektro dan Teknologi Informasi (JNTETI)', 'JOURNAL', '10.22146/jnteti.v7i4.455', 'http://doi.org/10.22146/jnteti.v7i4.455', 'Blockchain menawarkan berbagai dobrakan di bidang teknologi, mulai dari bidang keuangan hingga kesehatan. Beberapa usulan juga menerapkan blockchain pada teknologi IoT untuk meningkatkan unjuk kerja dan scalability. Namun, tipikal penerapan teknologi IoT dalam skala masif masih memiliki beberapa kendala, terlebih dalam hal manajemen akses dan identitas peranti yang terkoneksi. Makalah ini mengusulkan kombinasi dari permissioned blockchain dan teknologi Keyless Signature Infrastructure (KSI) sebagai metode untuk mengatur hak akses dan identitas peranti IoT. KSI dikenal mampu untuk memberikan layanan tanda tangan digital tanpa tergantung pada kunci privat maupun publik dengan menggunakan teknik pohon hash. Dengan karakteristik dari blockchain yang terdistribusi, teknologi KSI dapat dipadukan secara lebih efisien. Hasil yang diperoleh memberikan manajemen akses dan identitas dengan scalability yang tinggi.', 12, 'OPENALEX', '{"doi": "10.22146/jnteti.v7i4.455", "openalex": "https://openalex.org/W2907888078"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('7df37ae9-d413-4b53-89a9-586e55d0e3a1', 'Optimalisasi Kompetensi Guru Melalui Workshop Inovasi Pembelajaran Berbasis Digitalisasi Di Mas Tarbiyah Islamiyah Kecamatan Hamparan Perak Kabupaten Deli Serdang', NULL, 2024, '2024-11-16', 'Tumiran Tumiran; Bahtiar Siregar; Nanda Rahayu Agustia; Faiza Azhari', 'Journal of Human and Education (JAHE)', 'JOURNAL', '10.31004/jh.v4i6.1790', 'https://doi.org/10.31004/jh.v4i6.1790', 'Kegiatan pengabdian ini bertujuan untuk meningkatkan kompetensi guru di MAS Tarbiyah Islamiyah, Kecamatan Hamparan Perak, Kabupaten Deli Serdang, melalui pelaksanaan workshop inovasi pembelajaran berbasis digitalisasi. Sejalan dengan perkembangan teknologi, sektor pendidikan diharapkan dapat beradaptasi dan memanfaatkan teknologi digital dalam proses belajar mengajar. Namun, banyak guru yang mengalami kendala dalam mengimplementasikan teknologi tersebut secara efektif di kelas. Kegiatan ini menggunakan metode penelitian kualitatif dengan pendekatan studi kasus, di mana data dikumpulkan melalui observasi, wawancara mendalam, dan analisis dokumen terkait pelaksanaan workshop. Hasil dari workshop menunjukkan bahwa terdapat peningkatan signifikan pada kompetensi guru dalam mengintegrasikan teknologi digital ke dalam strategi pembelajaran yang interaktif dan efisien. Selain itu, workshop ini berhasil memperkuat pemahaman guru tentang pentingnya teknologi digital sebagai sarana mendukung proses pembelajaran yang lebih efektif. Kesimpulannya, workshop inovasi pembelajaran berbasis digitalisasi merupakan strategi yang efektif dalam meningkatkan kompetensi guru, yang pada gilirannya berpotensi meningkatkan kualitas pendidikan di MAS Tarbiyah Islamiyah. Optimalisasi kompetensi ini diharapkan dapat mendukung adaptasi pendidikan terhadap perkembangan teknologi serta mempersiapkan siswa untuk menghadapi tantangan masa depan..', 0, 'OPENALEX', '{"doi": "10.31004/jh.v4i6.1790", "openalex": "https://openalex.org/W4408706495"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1919ee92-0749-4453-ab25-0c3ecdf2581f', 'TRANSFORMASI NILAI PENDIDIKAN ISLAM PADA ERA MODERN: TELAAH TERHADAP PEMIKIRAN MUHAMMAD ALI PASHA', NULL, 2025, '2025-08-07', 'Mansur Ali Hanafi Siregar; Tumiran Tumiran', 'PROSIDING FAKULTAS AGAMA ISLAM UNIVERSITAS DHARMAWANGSA', 'JOURNAL', '10.46576/pfai.v5i0.578', 'https://doi.org/10.46576/pfai.v5i0.578', 'Penelitian ini bertujuan untuk mengkaji transformasi nilai-nilai pendidikan Islam pada era modern melalui telaah terhadap pemikiran dan kebijakan pendidikan Muhammad Ali Pasha di Mesir pada awal abad ke-19. Sebagai salah satu tokoh sentral dalam proses modernisasi dunia Islam, Muhammad Ali Pasha dianggap telah membawa perubahan besar dalam sistem pendidikan, baik dari segi struktur kelembagaan, kurikulum, maupun orientasi nilai. Penelitian ini menggunakan pendekatan kualitatif dengan metode studi pustaka, yang berfokus pada analisis historis dan filosofis terhadap dokumen, karya ilmiah, serta referensi terkait yang relevan. Hasil penelitian menunjukkan bahwa reformasi pendidikan yang dilakukan Muhammad Ali Pasha merupakan upaya strategis untuk memperkuat kapasitas negara dalam bidang militer, administrasi, dan teknologi melalui sistem pendidikan yang modern. Namun, transformasi ini juga menimbulkan dampak terhadap nilai-nilai pendidikan Islam, terutama terjadinya pergeseran dari pendidikan berbasis spiritualitas dan akhlak ke arah pendidikan yang pragmatis, teknokratik, dan sekuler. Terjadi pula dikotomi antara ilmu agama dan ilmu umum yang masih memengaruhi sistem pendidikan di negara-negara Muslim hingga saat ini. Penelitian ini menyimpulkan bahwa pemikiran Muhammad Ali Pasha tetap relevan untuk dikaji sebagai pijakan dalam merancang sistem pendidikan Islam yang integratif. Pendidikan Islam masa kini memerlukan model yang mampu menggabungkan nilai-nilai keislaman dengan kemajuan ilmu pengetahuan modern tanpa kehilangan identitas spiritual dan moralnya.', 0, 'OPENALEX', '{"doi": "10.46576/pfai.v5i0.578", "openalex": "https://openalex.org/W4413130815"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('ceb40216-6fab-4c49-b758-e05437a1dfc9', 'TANTANGAN ORANG TUA DALAM MEMBIMBING KEBIASAAN IBADAH ANAK DI ERA KETERGANTUNGAN GADGET DI KLAMBIR LIMA GG. GEMBIRA: PERSFEKTIF PEMBELAJARAN PAI', NULL, 2025, '2025-09-15', 'Dewi Agustin; Tumiran Tumiran', 'PROSIDING FAKULTAS AGAMA ISLAM UNIVERSITAS DHARMAWANGSA', 'JOURNAL', '10.46576/pfai.v5i0.601', 'https://doi.org/10.46576/pfai.v5i0.601', 'Penelitian ini bertujuan untuk menganalisis tantangan orang tua dalam membimbing kebiasaan ibadah anak di era ketergantungan gadget, khususnya di Klambir Lima Gg. Gembira. Perkembangan teknologi digital yang pesat telah membawa perubahan signifikan terhadap pola hidup anak, termasuk dalam aspek spiritualitas. Anak-anak cenderung lebih terdistraksi oleh hiburan digital dibandingkan aktivitas ibadah, sehingga kualitas dan konsistensi pelaksanaan ibadah mengalami penurunan. Penelitian ini menggunakan pendekatan kualitatif deskriptif dengan metode fenomenologi. Subjek penelitian terdiri dari 10 orang tua dan 10 anak yang dipilih melalui teknik purposive sampling. Data dikumpulkan melalui wawancara, observasi, dan dokumentasi. Hasil penelitian menunjukkan bahwa ketergantungan gadget menimbulkan berbagai tantangan, antara lain distraksi anak saat ibadah, resistensi psikologis, lemahnya pengawasan orang tua, serta pengaruh lingkungan sosial dan teman sebaya yang memperkuat kebiasaan digital. Dampaknya, ibadah sering dilakukan secara terburu-buru, ditunda, atau bahkan terabaikan. Penelitian ini menyimpulkan bahwa peran orang tua sangat krusial sebagai teladan, pengawas, dan pendamping spiritual. Sinergi antara keluarga, sekolah, dan masyarakat diperlukan agar nilai-nilai Pendidikan Agama Islam dapat diterapkan secara konsisten, sehingga anak mampu menempatkan ibadah sebagai prioritas meski berada di tengah derasnya arus digitalisasi.', 0, 'OPENALEX', '{"doi": "10.46576/pfai.v5i0.601", "openalex": "https://openalex.org/W4414251766"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1fe815f1-e313-4d2b-a9f0-c1672d11c0f4', 'Improving Teacher Competence Through Digital-Based Learning Innovation Workshop at MAS Tarbiyah Islamiyah Hamparan Perak, Deli Serdang Regency', NULL, 2025, '2025-09-30', 'Tumiran Tumiran; Bahtiar Siregar; Nanda Rahayu Agustia; Faiza Azhari', 'Unram Journal of Community Service', 'JOURNAL', '10.29303/ujcs.v6i3.1176', 'https://doi.org/10.29303/ujcs.v6i3.1176', 'This community service aims to improve teacher competence in integrating digital technology in the learning process at MAS Tarbiyah Islamiyah Hamparan Perak, Deli Serdang Regency. Activities are carried out through a workshop method that focuses on digital-based learning innovations, including the use of digital platforms, interactive media, and effective modern learning strategies. The activity participants consisted of MAS Tarbiyah Islamiyah teachers who have been facing various obstacles in implementing digital learning optimally. The results of the service showed that the workshop succeeded in increasing teachers'' understanding and skills in applying various digital tools and platforms in learning. In addition, the teachers also showed high enthusiasm and motivation to continue developing learning innovations. This activity is expected to improve the quality of learning and support the creation of a more interactive and enjoyable learning environment for students.', 0, 'OPENALEX', '{"doi": "10.29303/ujcs.v6i3.1176", "openalex": "https://openalex.org/W4414764416"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c39d4f99-ab12-4055-bf41-688e52571b7f', 'Developing augmented reality-based learning media and users’ intention to use it for teaching accounting ethics', NULL, 2021, '2021-04-15', 'Said Hirzi Hadi; Adhistya Erna Permanasari; Rudy Hartanto; Intan Sulistyaningrum Sakkinah; Mahfud Sholihin; Ratna Candra Sari; Roszaini Haniffa', 'Education and Information Technologies', 'JOURNAL', '10.1007/s10639-021-10531-1', 'https://doi.org/10.1007/s10639-021-10531-1', NULL, 45, 'OPENALEX', '{"doi": "10.1007/s10639-021-10531-1", "openalex": "https://openalex.org/W3153022969"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6e44fbca-0f35-4603-92eb-95399f086ca0', 'Internalisasi Nilai- Nilai Pendidikan Islam melalui Inovasi Digitalisasi Pembelajaran PAI di SD SWASTA PAB 5 Klumpang', NULL, 2025, '2025-10-03', 'Dewi Agustin; Tumiran Tumiran', 'Riwayat Educational Journal of History and Humanities', 'JOURNAL', '10.24815/jr.v8i4.49060', 'https://doi.org/10.24815/jr.v8i4.49060', 'Penelitian ini mengkaji strategi internalisasi nilai-nilai Pendidikan Islam melalui inovasi digitalisasi pembelajaran Pendidikan Agama Islam (PAI) di SD SWASTA PAB 5 Klumpang. Latar belakang penelitian berangkat dari tantangan era digital yang menuntut metode pembelajaran lebih kreatif agar mampu menanamkan nilai keislaman tidak hanya pada aspek kognitif, tetapi juga afektif dan psikomotorik. Metode penelitian menggunakan pendekatan kualitatif dengan studi deskriptif naratif melalui observasi, wawancara, dan dokumentasi. Hasil penelitian menunjukkan bahwa strategi internalisasi nilai dilakukan melalui pemanfaatan aplikasi Islami (misalnya aplikasi Think Qur’an), multimedia Islami (seperti video animasi kisah nabi), serta kolaborasi intensif antara guru dan orang tua dalam membimbing siswa. Penerapan inovasi digital terbukti meningkatkan semangat siswa dalam ibadah, menumbuhkan literasi digital Islami, serta membentuk karakter yang disiplin dan religius. Kesimpulannya, digitalisasi pembelajaran PAI menjadi solusi strategis untuk mengintegrasikan kebutuhan generasi digital dengan misi pendidikan Islam, sekaligus memperkuat sinergi sekolah dan keluarga dalam membentuk pribadi muslim yang berakhlak mulia.', 0, 'OPENALEX', '{"doi": "10.24815/jr.v8i4.49060", "openalex": "https://openalex.org/W4415123020"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('56f2d3c7-516d-403c-9e79-be202abb5c95', 'Multimedia-Based Islamic Education Learning Patterns at SMK Muhammadiyah 8 Medan', NULL, 2025, '2025-10-11', 'Nanda Rizky; Hadi Saputra Panggabean; Tumiran Tumiran', 'Riwayat Educational Journal of History and Humanities', 'JOURNAL', '10.24815/jr.v8i4.49653', 'https://doi.org/10.24815/jr.v8i4.49653', 'Along with the rapid development of information technology, the use of multimedia in the learning process is expected to improve the effectiveness and interactivity of delivering Islamic Religious Education (PAI) materials. This study aims to analyze the learning patterns of multimedia-based Islamic Religious Education at SMK Muhammadiyah 8 Medan. The research employed a qualitative approach with a case study design, involving teachers and students as the research subjects. Data were collected through in-depth interviews, direct observation, and relevant documentation, and were analyzed using descriptive analysis techniques to provide a detailed description of multimedia application in PAI learning. The findings indicate that the use of multimedia in PAI learning not only enhances students'' understanding of the material but also creates a more engaging and interactive learning atmosphere, in line with the needs of the digital generation. Furthermore, the role of the teacher as a facilitator becomes increasingly crucial in guiding students so that multimedia utilization remains oriented toward achieving learning objectives. This study implies that the integration of multimedia technology can serve as an effective strategy to improve the quality of PAI learning in vocational high schools', 0, 'OPENALEX', '{"doi": "10.24815/jr.v8i4.49653", "openalex": "https://openalex.org/W4415123259"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a111f7f6-718f-437f-8d8c-d1b105934612', 'Performance and Techno Economic Analysis of The Cirata Floating Photovoltaic Power Plant: A Comparison with Ground Mounted Systems', NULL, 2025, '2025-09-03', 'Zainur Oktafian Prabandaru; Tumiran Tumiran; Avrin Nur Widiastuti', NULL, 'JOURNAL', '10.1109/ict-pep67281.2025.11232151', 'https://doi.org/10.1109/ict-pep67281.2025.11232151', 'The global push toward net zero emissions have intensified the transition from fossil-based to renewable energy systems, with solar power playing a vital role. PT. PLN (Persero) as national electricity company of Indonesia has responded by developing the Cirata Floating Photovoltaic (FPV) power plant, the first and largest FPV facility in the country, leveraging the nation’s abundant solar potential and minimizing land use conflicts. This study evaluates the first-year performance of the Cirata FPV (December 2023–November 2024) by analyzing key performance indicators including energy yield, performance ratio (PR), and techno economic factors. The plant generated approximately 280 GWh, achieving 95 percent of its projected energy target, with a PR of 79 percent, representing 93 percent of the design target. The floating configuration provides a natural cooling effect that reduces module temperatures by 2 to 5 degrees Celsius compared to ground mounted systems, leading to a performance gain of up to 17 percent. From an economic perspective, significant cost savings were realized using floating structures instead of conventional land acquisition, resulting in estimated savings of 50.3 percent. Additionally, the plant contributed to an annual reduction of approximately 243,670 tons of carbon dioxide equivalent emissions compared to coal fired generation. These findings demonstrate the viability and benefits of FPV systems in tropical regions and support their broader adoption to accelerate Indonesia’s renewable energy transition.', 0, 'OPENALEX', '{"doi": "10.1109/ict-pep67281.2025.11232151", "openalex": "https://openalex.org/W4416183085"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a1abb87a-784c-4ddc-9127-c8573dedf841', 'Impact of Through Fault Current on Insulating Oil Characteristics and Dissolved Gas Content in Power Transformers', NULL, 2025, '2025-09-03', 'Anindita Singgih Pambudi; Tumiran Tumiran; Lesnanto Multa Putranto', NULL, 'JOURNAL', '10.1109/ict-pep67281.2025.11232235', 'https://doi.org/10.1109/ict-pep67281.2025.11232235', 'Faults in the 20 kV distribution network on the low-voltage side of power transformers still frequently occur, allowing Through Fault Currents (TFC) to flow through the transformer windings. This results in the transformer being subjected to significant electrical stress in the form of high current surges. The resulting temperature rise within the windings and transformer core can alter the condition of the insulating oil and potentially trigger the generation of dissolved gases (DGA). By comparing the percentage of TFC with the changes observed in the transformer oil, the impact of the TFC on the condition of the insulating oil can be determined. This serves as a predictive approach to transformer condition monitoring, enabling better analysis, evaluation, and maintenance strategies. The study will investigate and use data from power transformers that have a history of disturbances in the 20 kV distribution network. The cumulative and average percentages of TFC were calculated during the periods between the oil testing intervals. These percentages were analyzed using statistical methods to evaluate changes in the condition of the insulating oil before and after exposure to TFC events. Support Vector Regression (SVR) was used and compared with Multivariate Linear Regression (MLR). The SVR method demonstrated a better ability to capture the relationship between the percentages of TFC and the changes in oil condition, achieving smaller error values. The results indicate that TFC leads to an increase in the concentration of nearly all DGA components and changes in oil characteristics, accompanied by an overall decline in oil quality.', 0, 'OPENALEX', '{"doi": "10.1109/ict-pep67281.2025.11232235", "openalex": "https://openalex.org/W4416183096"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0713df01-16db-48d7-b7e1-9e00a849b907', 'Generation Expansion Planning Considering BESS for Optimizing the Full Potential of Solar Power Plant: A Case Study of Flores Power System', NULL, 2025, '2025-09-03', 'Aginta Ramadhanu Adjani; Eka Firmansyah; Lesnanto Multa Putranto; Tumiran Tumiran; Ahmad Adhiim Muthahhari; Mary Anne Alvin; Ira Savitri; Wa Ode Astuty H', NULL, 'JOURNAL', '10.1109/ict-pep67281.2025.11232393', 'https://doi.org/10.1109/ict-pep67281.2025.11232393', 'Nowadays, climate change has become one of the main global concerns and can be mitigated through the development of renewable energy, especially in regions with abundant potential, such as Flores. Moreover, the existence of advanced grid-connected batteries also supports the development of renewable energy to cope with intermittency issues. Therefore, generation expansion planning (GEP) for the Flores Power System was conducted to maximize its high solar potential through the integration of battery energy storage systems (BESS). In response to Indonesia’s Net Zero Emission target for 2060 and its de-dieselization program, two scenarios were optimized over 2025–2032 period: a Base Scenario and a De-dieselization Scenario which retires diesel units in 2027. The results show how both scenarios prioritize renewable deployment, with the Base Scenario adding 122 MW of PVPP, 5 MW of PV BESS, and 15 MW of biomass. Meanwhile, the De-dieselization Scenario adds 59 MW of PV, 15 MW of PV BESS, and 50 MW of gas engine power plants to satisfy reliability constraints. The de-dieselization scenario has an LCOE of 17.79 ¢/kWh, which is lower than the base scenario’s 18.82 ¢/kWh. In terms of CO<inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emission, de-dieselization Scenario achieves an average annual CO<inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> reduction of 103 kt. This demonstrates both the technical and economic feasibility of emission reduction programs by the development of renewable energy and low emission power plants.', 0, 'OPENALEX', '{"doi": "10.1109/ict-pep67281.2025.11232393", "openalex": "https://openalex.org/W4416183130"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5c622366-65e3-4fa1-9ea0-9f7dd6680b27', 'Transformasi Budaya Madrasah dan Karakter Islami Melalui Kepemimpinan Transformasional di Era Digital: Studi Kasus MAS Islamiayah Sunggala Medan', NULL, 2025, '2025-12-09', 'Tumiran Tumiran; Manshuruddin Manshuruddin; Bahtiar Siregar; Dinda Mayani Pramudita', 'Islamic Education', 'JOURNAL', '10.57251/ie.v5i2.1895', 'https://doi.org/10.57251/ie.v5i2.1895', 'Madrasahs in the digital era face the dual challenge of preserving Islamic values while responding to rapid technological development. This study aims to examine the cultural transformation of the madrasah and the formation of Islamic character through transformational leadership at Madrasah Aliyah Swasta Islamiyah Sunggala Medan. Using a descriptive qualitative method with a case study design, data were collected through interviews, observations, and documentation involving principals, teachers, and students. Triangulation techniques were applied to ensure data validity. The findings reveal that transformational leadership effectively fosters an innovative and technology-adaptive madrasah culture by articulating a shared vision, empowering educators and learners, and encouraging collaborative practices. These cultural shifts contribute to the strengthening of students’ Islamic character, particularly in aspects of discipline and honesty. Nevertheless, challenges such as limited infrastructure and resistance to change remain significant barriers. This study highlights the essential role of transformational leadership in guiding madrasah transformation in the digital era.', 0, 'OPENALEX', '{"doi": "10.57251/ie.v5i2.1895", "openalex": "https://openalex.org/W4417414603"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e4f60826-013d-4efc-99dc-2130f90144ce', 'Analysis of Visible-Light Image and Flashover Voltage on the Cap-and-Pin Insulator With Fan-Shaped Pollution Distribution', NULL, 2026, '2026-01-01', 'Mochammad Wahyudi; Tumiran Tumiran; Noor Akhmad Setiawan', 'IEEE Access', 'JOURNAL', '10.1109/access.2026.3683618', 'https://doi.org/10.1109/access.2026.3683618', 'Previous models have examined the relationship between insulator pollution level and flashover voltage, as well as between pollution levels and image-based features. This study investigated the potential correlation between visible-light images and flashover voltage. Porcelain cap-and-pin insulators were contaminated using a modified fan-shaped pollution distribution technique with a low-volume medium-pressure spray gun. Four pollution levels were produced by varying the ash–salt concentration (0.02–0.12 g/mL) and the number of spray gun trigger actuation (2-12). After ultrasonic humidification at 90% relative humidity for 90 min, the AC flashover tests were repeated at each pollution level until ten flashover voltages were obtained. Insulator images were captured under controlled conditions, including illumination (6,000 lm, 6,500 K), exposure parameters (ISO 500, f/16, 1/10 s), imaging geometry (1.3 m distance, 11.5° downward tilt, maximum optical zoom), and in-camera sRGB color space. Image processing involved selecting the fan-shaped area, cropping, background removal, conversion to RGB and HSV stacks, and histogram computation. Pearson’s correlation analysis showed that the histogram peak displacement between the dry and wet conditions of the pollutant layer was the most representative image feature with respect to flashover voltage. The RGB histogram peak displacement exhibited a higher correlation level than HSV, with the red component showing the greatest correlation coefficient (0.82). Furthermore, multivariable linear regression based on RGB histogram peak displacement yielded a coefficient of determination of 0.915. These results indicate that visible-light images can serve as non-contact predictors of the insulator pollution level and flashover voltage.', 0, 'OPENALEX', '{"doi": "10.1109/access.2026.3683618", "openalex": "https://openalex.org/W7155193873"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0bba1748-1934-40a7-ba77-fe6df8592454', 'AI-Driven Islamic Classroom Management in the Digital Era: The Roles of Neuro-Pedagogy, Spiritual Intelligence, and Innovative Teaching Performance', NULL, 2026, '2026-05-12', 'Tumiran Tumiran; Bahtiar Siregar; Sakban Lubis; M. Yunan Harahap; Mhd. Habibu Rahman', 'Qubahan Academic Journal', 'JOURNAL', '10.48161/qaj.v6n2a2072', 'https://doi.org/10.48161/qaj.v6n2a2072', 'The rapid advancement of digital technologies and artificial intelligence (AI) is reshaping educational systems worldwide, including Islamic education institutions that seek to preserve spiritual and ethical values while embracing pedagogical innovation. This study investigates the influence of digital technology integration, Islamic neuro-pedagogy, classroom environment, and teachers’ spiritual intelligence on Islamic classroom management and innovative teaching performance in madrasahs in Medan City, Indonesia. A quantitative research design was employed using structured questionnaires distributed to 120 teachers, and the collected data were analyzed through path analysis to examine direct and mediating relationships among variables. The findings reveal that Islamic neuro-pedagogy exerts the strongest positive effect on innovative teaching performance (β = 0.268), followed by digital technology integration (β = 0.253). Although classroom environment and spiritual intelligence demonstrate comparatively smaller direct effects, both significantly contribute to effective pedagogical practices and classroom interaction. Furthermore, Islamic classroom management plays a significant mediating role, strengthening the relationship between technological, cognitive, and spiritual dimensions and teachers’ innovative performance. The study proposes a holistic framework for AI-supported Islamic education that integrates neuroscience-informed pedagogy, digital learning technologies, and spiritual intelligence within value-based classroom management practices. These findings contribute theoretically to contemporary Islamic educational research and provide practical implications for educators, curriculum designers, and policymakers seeking to foster innovative, ethical, and spiritually grounded learning environments in the digital era.', 0, 'OPENALEX', '{"doi": "10.48161/qaj.v6n2a2072", "openalex": "https://openalex.org/W7160945352"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('10b69a9b-131e-4fc6-9baa-d4e152c530fe', 'Denoising Speech for MFCC Feature Extraction Using Wavelet Transformation in Speech Recognition System', NULL, 2018, '2018-07-01', 'Risanuri Hidayat; Agus Bejo; Sujoko Sumaryono; Anggun Winursito', NULL, 'JOURNAL', '10.1109/iciteed.2018.8534807', 'https://doi.org/10.1109/iciteed.2018.8534807', 'Mel frequency cepstral coefficient (MFCC) is a popular feature extraction method for a speech recognition system. However, this method is susceptible to noise even though it generates a high accuracy. The conventional MFCC method has a degraded performance when the input signal has noises. This paper presents the implementation of denoising wavelet on speech input of MFCC feature extraction method. The addition of denoising process using wavelet transformation was expected to improve the MFCC performance on noisy signals. The study used 120 speech data, with 30 data were used as the reference, and the other 90 were used as the testing data. The testing data were mixed with white Gaussian noise and then tested to the speech recognition system that already had the reference data. Parameters used in the wavelet denoising process were soft thresholding with the Minimaxi thresholding rule. Eleven wavelet methods on decomposition level 10 were tested on the denoising process. The classification process used K-nearest neighbor (KNN) method. The Fejer-Korovkin 6 wavelet was the best denoising speech signal method that achieved the highest accuracy on input signals with SNR of 5-15dB. Meanwhile, the Daubechies 5 method had a high accuracy on input signal with SNR of 3 dB. All of the tested denoising methods using wavelet transformation were able to improve the accuracy of the speech recognition system on input signals with SNR of 0-10 dB compared to the system without denoising method.', 57, 'OPENALEX', '{"doi": "10.1109/iciteed.2018.8534807", "openalex": "https://openalex.org/W2900953099"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('50fe8188-4393-41b6-9755-b456955fd7a8', 'Assessing building vulnerability to earthquake and tsunami hazard using remotely sensed data', NULL, 2012, '2012-11-23', 'Matthias Mück; Hannes Taubenböck; Joachim Post; Stephanie Wegscheider; Günter Strunz; Sujoko Sumaryono; F A Ismail', 'Natural Hazards', 'JOURNAL', '10.1007/s11069-012-0481-1', 'https://doi.org/10.1007/s11069-012-0481-1', NULL, 49, 'OPENALEX', '{"doi": "10.1007/s11069-012-0481-1", "openalex": "https://openalex.org/W2003855843"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('41660390-a1a4-418a-9d17-2b7218eba72f', 'Unjukkerja Standar ZigBee pada WPAN dengan Topologi Mesh', NULL, 2012, '2012-08-01', 'Eka Wahyudi; Risanuri Hidayat; Sujoko Sumaryono', NULL, 'JOURNAL', '10.22146/jnteti.v1i2.17', 'http://ejnteti.jteti.ugm.ac.id/index.php/JNTETI/article/view/17', 'ZigBee standard can be used in wireless sensor
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('079475f2-a84d-4711-b485-dba57bf87c3a', 'Comparison of vowel feature extraction on time and frequency domain', NULL, 2017, '2017-10-01', 'Risanuri Hidayat; D. Yulian; Agus Bejo; Sujoko Sumaryono', NULL, 'JOURNAL', '10.1109/iciteed.2017.8250477', 'https://doi.org/10.1109/iciteed.2017.8250477', 'Vowel recognition is the most important part of the speech recognition process. Most spoken speeches must contain vowels to be sounded. It needs a method that can separate a vowel with another. The methods of the feature extraction on time domain, frequency, cepstrum, and fourier are several basic methods that can be used. This paper compares features of the strengths of the feature of zero crossing rate, energy, spectral centroid, spectral spread, spectral entropy, harmonic ratio, fundamental frequency, cepstrum, and fourier to separate and recognize vowels of a, i, u, e, and o in Indonesian dialect/language. The results show that the spectral spread feature that is one of the features in the frequency domain has the most accurate ability to recognize vowels tested compared to other features.', 2, 'OPENALEX', '{"doi": "10.1109/iciteed.2017.8250477", "openalex": "https://openalex.org/W2782835988"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('266fe164-4f45-4b3b-ab69-dab3069f2216', 'Pengembangan Virtual Appliance Server Dengan Metode Virtualisasi', NULL, 2012, '2012-05-01', 'Novan Ardianto; Widyawan Widyawan; Sujoko Sumaryono', NULL, 'JOURNAL', '10.22146/jnteti.v1i1.4', 'http://ejnteti.jteti.ugm.ac.id/index.php/JNTETI/article/view/4', 'Dengan semakin maju dan canggihnya teknologi komputer saat ini terutama pada PC dan server, ditandai dengan bermunculannya prosesor dengan inti ganda 2 (duo core), atau inti ganda 4 (quad core) bahkan hingga inti ganda 6 (hexa core). Padahal belum semua aplikasi saat ini terutama diluar animasi 3D dan games yang dapat memanfaatkan secara optimal prosesor berinti banyak (multiprosesor) tersebut, membuat prosesor-prosesor canggih tersebut banyak bekerja dengan tingkat utilisasi yang rendah atau hanya sedikit sumber daya yang terpakai. Prosesor canggih tersebut dapat kita manfaatkan untuk menjalankan aplikasi-aplikasi dan services secara virtualisasi. Virtualisasi dapat dilihat sebagai bagian dari trend secara keseluruhan di perusahaan IT saat ini. Teknik virtualisasi semakin hari semakin terkenal dan banyak digunakan, dikarenakan selain melakukan penghematan sumberdaya, juga dapat memiliki kinerja yang cukup baik dalam menjalankan berbagai services sebuah server di dalam suatu jaringan. Bahkan virtualisasi kini dapat berjalan di atas infrastruktur cluster, yang akan membentuk HA (High Availability) server. Dengan menggunakan aplikasi seperti VirtualBox dan Proxmox, yang mana merupakan tools yang sangat kuat, mudah di-setting dan terutama gratis, dapat dibuat sebuah virtual appliances yang mencakup fungsi-fungsi dan services pada server di jaringan yang sebenarnya. Hal ini bertujuan untuk membuktikan seberapa efektif dan efisien penggunaan virtualisasi pada komputer berinti banyak (multi prosesor)', 4, 'OPENALEX', '{"doi": "10.22146/jnteti.v1i1.4", "openalex": "https://openalex.org/W1975011349"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('23cba255-76a8-40e7-a246-c11f9561e9f8', 'Penentuan Karakteristik Pengguna sebagai Pendukung Keputusan dalam Memilih Smartphone Menggunakan Forward Chaining', NULL, 2014, '2014-09-01', 'Ian Gatra Sandika; Adhistya Erna Permanasari; Sujoko Sumaryono', NULL, 'JOURNAL', NULL, 'https://www.neliti.com/publications/171816/penentuan-karakteristik-pengguna-sebagai-pendukung-keputusan-dalam-memilih-smart', 'Saat ini smartphone sudah menjadi kebutuhan primer bagi semua kalangan masyarakat kelas atas maupun kalangan bawah. Seiring kebutuhan tersebut banyak vendor-vendor smartphone yang menawarkan harga, fitur, operating sistem dan teknologi yang berbeda-beda. Akan tetapi, keinginan dan kebutuhan masyarakat yang semakin meningkat sering tidak sesuai dengan smartphone yang diinginkan dan yang dibutuhkan. Hal tersebut menyebabkan pengguna smartphone tidak dapat menentukan pilihan yang tepat sesuai dengan kebutuhannya karena seringnya pemilihan smartphone didasarkan pada gengsi dan perilaku konsumtif masyarakat. Penelitian ini dilakukan untuk memberikan saran kepada masyarakat agar dapat memilih smartphone yang sesuai dengan karakteristik masing-masing pengguna (kebutuhan pengguna). Karakteristik pengguna didapatkan dari pengolahan 16 pertanyaan yang diajukan oleh sistem. Metode yang digunakan dalam mengolah 16 pertanyaan tersebut adalah forward chaining. Forward chaining digunakan karena dalam sistem ini memberikan beberapa pertanyaan yang akan diolah menjadi suatu kesimpulan. Pertanyaan-pertanyaan tersebut diolah menggunakan software Swi prolog berdasarkan production rules untuk mendapatkan keluaran berupa saran kepada pengguna. Pengolahan tersebut didasarkan pada jawaban Y(Yes) dan N(No) serta tambahan range harga yang dimasukkan oleh pengguna. Hasil saran yang dikeluarkan sistem berupa karakteristik pengguna, harga dan jenis smartphone. Smartphone yang disarankan untuk pengguna didasarkan pada karakteristik yang telah ditentukan sistem, yaitu Adventures, Entertainer, Elegan dan Sosial media addict.', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W1570695738"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d6fdd11e-b7b9-45b6-9aa6-5993373a7ef7', 'PENILAIAN TINGKAT CAPABILITY TATA KELOLA TI PADA ASPEK MANAJEMAN SUMBER DAYA MANUSIA', NULL, 2014, '2014-02-08', 'Rahmi Novita; Eko Nugroho; Sujoko Sumaryono', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/443/421', 'T ata kelola TI merupakan salah satu pendorong utama proses transformasi bisnis menuju good governance. Untuk  menopang  penggelolaan  tata  kelola  TI, dibutuhkan SDM TI yang kompeten. Penelitian ini akan melakukan  penilaian  tingkat  capability  tata  kelola  TI pada aspek manajemen SDM. A l a t ukur yang digunakan pada penelitian ini adalah COBIT 5. Empat tahapan yang dilakukan dalam penelitian ini adalah pertama tahap awal yakni studi literatur, telaah dokumen dan perumusan latar belakang tujuan dan manfaat penelitian. Kedua adalah tahap pemecahan   masalah   meliputi   identifikasi  IT-related goals, pemetaan IT-related goals dengan proses COBIT 5, penyusunan kuesioner dan penentuan responden. Ketiga  tahap  perumusan  masalah, dilakukan  analisis data dan pada tahap keempat atau tahap akhir ditarik kesimpulan. Penilaian   akan   tingkat   Capability   proses   COBIT mengacu kepada standar Process Assessment Model (PAM) dari ICASA. Hasil dari penilaian capability tata kelola TI pada aspek manajemen dari 13 proses yang lakukan  penilaian diketahui  Dua  proses  berada  pada level 0, delapan proses pada level 1, satu proses pada level 2 dan dua proses pada level 3 .', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W2415363002"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('097ee715-d45b-41ee-9487-58e89d619c78', 'Pengujian Jarak dan Waktu Gabung Protokol IEEE 802.15.4./ ZigBee di Lingkungan Indoor', NULL, 2012, '2012-08-01', 'Koko Joni; Risanuri Hidayat; Sujoko Sumaryono', NULL, 'JOURNAL', '10.22146/jnteti.v1i2.18', 'http://ejnteti.jteti.ugm.ac.id/index.php/JNTETI/article/download/18/15', 'Protocol IEEE 802.15.4/ZigBee is a standard for low power personal network. This paper discusses about router, end device and coordinator using ZigBee protocol in term of distance and time to join. Testing carried out by pairing and On/Off method that constitute communication model from router or end device to coordinator. The result showed that with pairing methods could far distance until outside building with further distance about 65 meters, while the distance using On/Off method can reach few room in indoor area. Longest time to join need about 1 minute 15 seconds. Compare with pairing method that always connected, On/Off method need more time to connect in ZigBee Network. Protokol IEEE 802.15.4 / ZigBee merupakan standar untuk jaringan terbatas dengan konsumsi daya rendah. Paper ini membahas perangkat router, end device dan koordinator dengan protokol ZigBee terhadap jarak dan waktu gabung. Pengujian dilakukan dengan metode pairing dan On/Off, yang merupakan model komunikasi dari router atau end device ke koordinator. Hasil pengujian menunjukkan bahwa metode pairing dapat menjangkau jarak yang jauh hingga ke luar gedung dengan jarak terjauh lebih kurang 65 meter, sedangkan jarak jangkauan dengan metode On/Off hanya mencapai beberapa ruang di lingkungan indoor. Waktu gabung paling lama di butuhkan waktu 1 menit 15 detik. Dibanding dengan metode pairing yang selalu terhubung, metode On/Off membutuhkan selang waktu gabung untuk tersambung dalam jaringan ZigBee.', 2, 'OPENALEX', '{"doi": "10.22146/jnteti.v1i2.18", "openalex": "https://openalex.org/W596305536"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3699067d-bcf7-47db-bd1c-c8832560063d', 'ANALISIS PERFORMANCE JARINGAN KOMPUTER DENGAN MEKANISME LOAD BALANCING-FAILOVER', NULL, 2010, '2010-01-01', 'Ryan Ramandito; Sujoko Sumaryono; Sri Suning Kusumawardhani', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12023', NULL, 2, 'OPENALEX', '{"openalex": "https://openalex.org/W939747012"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('95e0493b-4056-4721-a88f-d1e00af2520e', 'INTERFACE PENGENDALIAN LEVEL DAN TEKANAN DENGAN DISTRIBUTED CONTROL SYSTEM', NULL, 2010, '2010-01-01', 'Hadi Annafi; Soedjatmiko; Sujoko Sumaryono', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/download.php?dataId=12024', NULL, 1, 'OPENALEX', '{"openalex": "https://openalex.org/W179080325"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('83b7acda-4aed-408d-b2e4-93c51f05bdfa', 'MODEL INTEGRASI DATA SISTEM INFORMASI PELAYANAN PUBLIK BERBASIS SERVICE ORIENTED ARCHITECTURE (SOA) UNTUK OPTIMALISASI PENDAPATAN ASLI DAERAH DI PEMERINTAH KOTA YOGYAKARTA', NULL, 2014, '2014-02-08', 'Joko Marwiyanto; Sujoko Sumaryono', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/view/413/392', 'Dalam rangka menjalankan e-Government seperti yang diamanatkan melalui Instruksi Presiden No 3 tahun 2003 tentang Kebijakan dan Strategi Nasional Pengembangan E-GOVERNMENT, Pemerintah Daerah berusaha sebaik-baiknya untuk memanfaatkan Teknologi Informasi meningkatkan pelayanan terhadap masyarakat. Namun demikian dalam pelaksanaannya penggunaan aplikasi sistem informasi belum dapat melakukan pertukaran data/informasi antar instansi. Sehingga diperlukan adanya teknologi untuk menjembatani agar dapat terjadi pertukaran data/informasi tersebut, yaitu dengan mengimplementasikan Service Oriented Architecture( SOA) Dengan terjadinya pertukaran data/informasi antar Dinas dapat mendukung optimalisasi penerimaan Pendapatan Asli Daerah.', 1, 'OPENALEX', '{"openalex": "https://openalex.org/W2418648019"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a12067d5-d982-4c96-a7dd-c1d610ade27f', 'Implementation and performance analysis of MPI cluster system in distributed rendering', NULL, 2016, '2016-01-01', 'Erick Irawadi Alwi; Teguh Bharata Adji; Sujoko Sumaryono', NULL, 'JOURNAL', '10.1109/cyberneticscom.2016.7892575', 'https://doi.org/10.1109/cyberneticscom.2016.7892575', 'Graphic image is compulsory in delivering information and communication in this information technology era. Graphic applications are used widely to manipulate images in advertising industries and in animation movie productions. In order to manipulate numerous and complex images, it is required long period of time and high-performance computers. However, computers with high-performance specification are still very expensive these days. This condition triggers the development of distributed processing technique using the implementation of computer cluster which does not require very advanced specifications. A computer cluster is a computer system that employs many computers (PCs) which are connected within a computer network and work simultaneously in parallel for solving given computational processes.', 1, 'OPENALEX', '{"doi": "10.1109/cyberneticscom.2016.7892575", "openalex": "https://openalex.org/W2604605965"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('fe91eb25-02fe-4e8b-b615-13f0f767da1d', 'Experience in implementing real time adaptive algorithm on TMS320C50 DSP', NULL, 2002, '2002-01-01', 'Sujoko Sumaryono; MSc. Adhi Susanto', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/58003/', NULL, 1, 'OPENALEX', '{"openalex": "https://openalex.org/W2475528293"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0c528c66-71ed-41ed-b343-b5d2eeb5362f', 'Pengukuran End-To-End Delay pada Jaringan ZigBee dengan Topologi Mata Jala', NULL, 2012, '2012-03-10', 'Eka Wahyudi; Risanuri Hidayat; Sujoko Sumaryono', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/37701/', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1041127675"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('7685919f-87e1-43b2-b721-0f3ae9807420', 'PEMANTAUAN PAPARAN RADIASI LlNGKUNGAN TERPADU DENGAN KOMUNIKASI GSM/GPRS', NULL, 2017, '2017-10-18', 'Ikhsan Shobari; Risanuri Hidayat; Sujoko Sumaryono', 'Jurnal Forum Nuklir', 'JOURNAL', '10.17146/jfn.2014.8.2.3711', 'https://doi.org/10.17146/jfn.2014.8.2.3711', 'PEMANTAUAN PAPARAN RADIASI LlNGKUNGAN TERPADU DENGAN KOMUNIKASI GSM/GPRS. Penjaminan pengoperasian reaktor yang tidak membahayakan pekerja dan masyarakat sangat penting untuk dilakukan. Untuk itu perlu dilakukan pemantauan paparan radiasi dan lingkungan secara terus menerus. Perkembangan teknologi informasi dan komunikasi terkini memungkinkan dilakukan pengukuran paparan radiasi dan lingkungan terpadu secara jarak jauh, on-line dan real time. Paper ini memperkenalkan dan membahas rancang bangun sistem pemantauan paparan radiasi lingkungan terpadu dengan memanfaatkan teknologi informasi dan komunikasi. Data berupa paparan radiasi, suhu, arah angin, kecepatan angina, dan curah hujan, dikirim secara periodis dengan memanfaatkan teknologi GSM/GPRS. Modul Arduino yang berbasis mikrokontroler AT Mega 328, digunakan untuk akuisi data dari kelima sensor tersebut, untuk selanjutnya melalui shield GSM/GPRS data dikirim ke komputer informasi proses melalui pesan singkat SMS. Data yang diterima ditampilkan dalam komputer dalam bentuk tabel dan dapat diolah dengan perangkat lunak lainnya. Hasil menunjukan bahwa sistem yang dibangun berhasil diimplemantasikan untuk pemantauan paparan radiasi lingkungan terpadu secara on-line dan real time untuk pemantauan jarak jauh. Rerata kesalahan pembacaan setelah dilakukan kalibrasi adalah 6,34 persen.Kata Kunci : Monitor Radiasi, lingkungan. mikrokontroler, komunikasi GSM/GPR', 0, 'OPENALEX', '{"doi": "10.17146/jfn.2014.8.2.3711", "openalex": "https://openalex.org/W1042110771"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c5fd8540-6071-4cb3-9fa4-45f188bb77d8', 'IMPLEMENTASI LAYANAN PESAN PENDEK SEBAGAI PIRANTI NOTIFIKASI SISTEM DETEKSI INTRUSI', NULL, 2007, '2007-08-01', 'Wahyu Sapto Aji; Soedjatmiko Soedjatmiko; Sujoko Sumaryono', 'TELKOMNIKA (Telecommunication Computing Electronics and Control)', 'JOURNAL', '10.12928/telkomnika.v5i2.1353', 'https://doi.org/10.12928/telkomnika.v5i2.1353', 'Penelitian ini mengkaji penerapan layanan pesan pendek (SMS) sebagai piranti notifikasi sistem deteksi intrusi/penyusupan (IDS) dalam usaha untuk meningkatkan keterawasan sistem. Penelitian dilakukan dengan membangun piranti SMS Gateway yang akan memberikan informasi berupa SMS jika terjadi kegiatan yang dianggap sebagai usaha percobaan intrusi. Sistem notifikasi ini juga diharapkan memberikan kemampuan administrator melakukan tindakan terbatas terhadap server apabila terjadi kegiatan intrusi tadi. Hasil penelitian menunjukkan telah dapat dikembangkan piranti notifikasi SMS. Waktu rerata yang dibutuhkan untuk menyampaikan informasi kepada administrator dalam simulasi serangan yang dilakukan berkisar pada angka 1.6 menit. Dalam pengujian dilakukan simulasi tindakan berupa pematian server, penguncian server, penyambungan dan pemutusan server ke internet dan reboot server.', 0, 'OPENALEX', '{"doi": "10.12928/telkomnika.v5i2.1353", "openalex": "https://openalex.org/W1533370300"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('18cfccaf-8cd4-44a5-8142-22b3c7f87011', 'Estimasi Lokasi Objek dalam Gedung Berbasis IEEE 802.11 menggunakan Metode Naive Bayes', NULL, 2012, '2012-07-12', 'Sutarti Sutarti; Widyawan Widyawan; Sujoko Sumaryono', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/91865/', 'WLAN has become very popular in
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('073cf2c4-8e64-4acf-9486-20291e236a09', 'Overhead Analysis as One Factor Scalibility of Private Cloud Computing for IAAS Service', NULL, 2013, '2013-05-01', 'Teguh Bharata Adji; Faisal Suryadi Nggilu; Sujoko Sumaryono', NULL, 'JOURNAL', NULL, 'http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.682.9011', 'Abstract — The rapid development of technology leads to improvement in a variety of computing concepts, information and communication technology(ICT). The ICT environment is become more complex and costly. Cloud Computing is one of phenomenon int the new ICT services, Cloud Computing model has three categories of services: Infrastructure As A Service (IAAS), Platform As A Service (PAAS), Software As A Service (SAAS). It also has four deployment models which are private cloud computing, community cloud, public cloud and hybrid Cloud. This research aims to determine the overhead of the virtualization environment. It is expected the private cloud with virtual technology, that utilizes the maximum resources does not degrade server scalability. The implementation of private cloud is using OpenStack with configuration multiple interfaces multiple servers. The results of the thesis indicate that the overhead of a single virtual machine is 114 ms (database server) and 212 ms (web server), to ten virtual machines are active 615 ms (database server) and 786 ms (web server). Overhead that occurs on a single VM can still be neglected, despite the performance degradation with increasing number of active virtual machines the execution time of servers application tends to be linear close to shape belongs to the physical servers. Index Terms — Overhead, private cloud computing, IAAS, OpenStack, multiple interfaces multiple servers. 1', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2118926204"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1f63df83-b2ae-4093-a019-9a489b262c86', 'PENGUJIAN PROTOKOL IEEE 802.15.4 / ZIGBEE DI LINGKUNGAN OUTDOOR', NULL, 2012, '2012-06-30', 'Koko Joni; Risanuri Hidayat; Sujoko Sumaryono', 'Seminar Nasional Informatika (SEMNASIF)', 'JOURNAL', NULL, 'http://jurnal.upnyk.ac.id/index.php/semnasif/article/download/1032/896', 'Protokol IEEE 802.15.4 ZigBee merupakan standar untuk jaringan terbatas dengan konsumsi daya yang rendah. Paper ini membahas perangkat router, end device dan koordinator dengan protokol IEEE 802.15.4/ZigBee terhadap jarak dan waktu gabung. Pengujian dilakukan dengan metode pairing dan On/Off, yang merupakan model komunikasi dari router atau end device ke koordinator. Hasil dari pengujian bisa digunakan acuan untuk merancang jaringan mesh dengan perangkat Xbee dalam hal jarak dan waktu untuk berbagai keperluan. Hasil pengujian menunjukkan dengan metode pairing dapat menjangkau jarak yang jauh sesuai spesifikasi teknis Xbee sedang dengan metode On/Off pencapaian tidak sejauh metode pairing dan memerlukan waktu dalam proses bergabung ke jaringan mesh.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2237003949"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('eb7fbba6-05f0-4736-89b0-16f0149fa31b', 'Simulasi Deployment Jaringan Sensor Nirkabel Berdasarkan Algoritma Particle Swarm Optimization', NULL, 2012, '2012-07-12', 'Zawiyah Saharuna; Widyawan Widyawan; Sujoko Sumaryono', NULL, 'JOURNAL', '10.22146/jnteti.v1i3.123', 'https://www.repository.ugm.ac.id/37634/', 'Deployment is one of several important issues in
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e2a71590-3d0e-4c66-9b6a-2f406223f296', 'Indonesian Automatic Speech Recognition system using CMUSphinx toolkit and limited dataset', NULL, 2016, '2016-11-01', 'Hamdan Prakoso; Ridi Ferdiana; Rudy Hartanto', NULL, 'JOURNAL', '10.1109/isesd.2016.7886734', 'https://doi.org/10.1109/isesd.2016.7886734', 'Building Automatic Speech Recognition (ASR) needs acoustic model, language model and dictionary for intended language, which is also applied for Indonesian ASR. In this paper, Indonesian ASR was built using CMUSphinx toolkit (a Hidden Markov Model based ASR tool) with limited dataset. We use digit corpus and own made language model to trained with the limited dataset. We also investigated the implementation of trained acoustic model by examine it in different SNR condition to several people. The best achievement of word error accuracy of the acoustic model is 86% on average. By examine it in different SNR condition, we got maximum accuracy of 80% on 27.764 dB environment.', 19, 'OPENALEX', '{"doi": "10.1109/isesd.2016.7886734", "openalex": "https://openalex.org/W2601477764"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e6a6a027-1bd6-4370-a680-5b5e8c8d1252', 'Considering Power Consumption of Wireless Stations Based on 802.11 Mode Control', NULL, 2012, '2012-07-12', 'Ramadhan Praditya Putra; Sujoko Sumaryono; Sri Suning Kusumawardani', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/37648/', 'The high bit rate 802.11n consumes more power
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f4e445e4-f3fa-4fae-872a-ce9cd38cc246', 'Perencanaan Strategis Sistem Informasi pada Bank Perkreditan Rakyat Menggunakan Metode WARD dan PEPPARD (Studi Kasus Bank Perkreditan Rakyat Jawa Timur)', NULL, 2012, '2012-07-14', 'Erwin Sutomo; Teguh Bharata Adji; Sujoko Sumaryono', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/id/eprint/32430', 'PT. Bank BPR Jatim memiliki 74 kantor se-Jawa Timur dan harus bersaing dengan 331 BPR di Jawa Timur. Sudah ada SI/TI yang digunakan tetapi antar kantor masih belum ada sistem yang terintegrasi. Proses pengolahan, penyampaian, dan penyajian informasi masih belum terintegrasi serta tidak real-time. Sehingga manajemen berpendapat investasi SI/TI yang telah dikeluarkan belum memberi manfaat bagi organisasi, khususnya terhadap pelayanan kepada nasabah. Manajemen menginginkan ada pengembangan SI/TI yang terencana dan sesuai dengan perkembangan organisasi. Untuk merencanakan pengembangan SI/TI yang baik diperlukan perencanaan strategis SI/TI. Perencanaan strategis dalam penelitian ini menggunakan metode Ward dan Peppard. Dalam penelitian ini dilakukan analisis internal bisnis menggunakan analisis SWOT dan value chain, serta analisis eksternal bisnis menggunakan analisis PEST, Porter’s 5 Force. Selain itu dilakukan analisis internal dan eksternal SI/TI. Hasil analisis tersebut kemudian diolah untuk merumuskan strategi SI/TI bagi PT. Bank BPR Jawa Timur. Hasil dari perencanaan strategis SI/TI berupa portofolio aplikasi yang terbagi dalam empat kuadran : strategic, high potential, support, dan key operational. Portofolio tersebut berisi 16 SI/TI yang dibutuhkan oleh PT. Bank BPR Jawa Timur.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2282927808"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e6483eb7-be5c-44c5-8999-066e4549d741', 'PARALLEL PROCESSING FOR INTEGRATION PROBLEM USING HIGH PERFORMANCE COMPUTING WITH OPENMPI : CASE STUDY ON THE NUMBER OF INTEGRATION INTERVAL', NULL, 2011, '2011-10-22', 'Teguh Bharata Adji; Muhammad Aditya Pradana; Sujoko Sumaryono', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/id/eprint/32423', 'Along with the increasing need to solve various problems of numerical computation effectively and efficiently, the need for a computer system with high computing capability has increased. Computer systems with high computing capability (high performance computing) offers the ability to integrate the resources of multiple computers to solve a problem of numerical computing. This computer system called computer cluster. The cluster must have the ability to perform computing process by using parallel computing mechanism called message passing. In this study, the implementation of message passing mechanism on a computer cluster is done by using Open Message passing Interface (OpenMPI) application. This study aims to analyze the performance of computer cluster using MPI mechanism in handling the process in parallel computing based on the execution time, speedup, and the efficiency. Parallel computing processes will be executed with OpenMPI application to solve the problems of numerical integration using trapezoidal method. The research method used in this study is by implementing OpenMPI on a Linux-based cluster system and then analyzing the performance of the system in dealing with parallel computing process to solve the numerical integration problems by increasing the number of intervals used in a numerical integration problem. The results of this study shows that by increasing number of intervals, the sequential execution time is initially faster than parallel execution time, although finally reduced significantly with the increase of number of integration interval. Instead, the parallel execution time continues to increase rapidly exceeding the sequential execution time.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2283988127"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d77fb141-c8f4-4412-89ca-6c09e3b71763', 'Perancangan Tapis Kapasitor Tersaklar pada VLSI', NULL, 1990, '1990-06-01', 'Sujoko Sumaryono', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/135771/', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2309109390"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('de4f175d-5dce-4a65-9c37-2f5eed40939b', 'ANALISIS FAKTOR-FAKTOR YANG MEMPENGARUHI KESENJANGAN DIGITAL (Studi Kasus: Kantor Camat pada Pemerintah XYZ)', NULL, 2014, '2014-02-08', 'Lalu Yudhi Prihadi; Ahmad Ridwan Sulaeman Ashari; Sujoko Sumaryono', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/442/420', 'F e nomena kesenjangan digital dicirikan dengan adanya kesenjangan antara warga negara dengan latar belakang sosial ekonomi yang berbeda berdasarkan kesempatan dan kemampuan mereka untuk mengakses dan   menggunakan   TIK.    Kesenjangan   digital   juga terkait dengan kesetaraan memperoleh peluang. P e nelitian ini akan dilakukan analisis faktor-faktor yang mempengaruhi dalam penyempitan kesenjangan digital menggunakan model pengukuran masyarakat informasi yang digunakan di Eropa yaitu SIBIS (Statistical Indicators Benchmarking the Information Society). Hasil penelitian ini menemukan bahwa terdapat dua faktor dari lima faktor yang diprediksi yang mempengaruhi penyempitan kesenjangan digital pada Pegawai Negeri Sipil (PNS) yang bertugas di Kantor Camat Pemerintah XYZ, yaitu ketersediaan akses TIK dan pemanfaatan TIK.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2413884275"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('425a7c4c-7325-45a8-85a6-31d2ad13cdef', 'Pemodelan Pemanfaatan Protokol SIP dalam Mobile Monitoring Kejadian Abnormal pada Sensor Nirkabel', NULL, 2014, '2014-02-08', 'Andreo Yudertha; Widyawan Widyawan; Sujoko Sumaryono', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/510/487', 'Teknologi Wireless Sensor Network (WSN) telah banyak diterapkan dalam berbagai bidang dalam memonitor gejala-gejala lingkungan. Salah satu aspek yang menjadi persoalan dalam memonitor dengan menggunakan WSN adalah intensitas pemantauan yang menuntut pengguna untuk selalu mengamati dari sistem monitoring setiap saat. Seiring perkembangan teknologi, WSN telah dikombinasikan dengan teknologi lainnya, seperti Internet. Pemanfaatan Internet pada WSN mampu meningkatkan mobilitas dalam memantau WSN serta kenyamanan bagi pengguna. Salah satu cara yang digunakan untuk mengimplementasikan pemantauan WSN melalui Internet selain dengan menggunakan protokol HTTP adalah memanfaatkan protokol SIP. Protokol SIP merupakan protokol pada layer aplikasi yang umumnya dimanfaatkan dalam mengatur sesi komunikasi pada VoIP. Perancangan model dilakukan dengan mengadaptasikan arsitektur dan komponen dari protokol SIP dalam menyampaikan data sensor ke pengamat. Data disampaikan ke user apabila terjadi kejadian abnormal pada objek yang dipantau. Selain itu, skema komunikasi yang diterapkan mengadopsi skema komunikasi pada aplikasi VoIP. Pada model yang dihasilkan dalam perancangan arsitektur, dapat dilihat bahwa protokol SIP dapat dijadikan media penyampaian data melalui Internet. Selain itu, dengan memanfaatkan protokol SIP mobilitas dari pengamat dapat meningkat dalam melakukan pemantauan.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2416314987"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d18b3401-11d5-4d6c-80ac-79d031fe87b2', 'Vowel Sound Analysis in the Indonesian Language using Multilevel Wavelet Entropy', NULL, 2019, '2019-10-01', 'Risanuri Hidayat; Achmad Rizal; Agus Bejo; Sujoko Sumaryono', NULL, 'JOURNAL', '10.1109/icsitech46713.2019.8987551', 'https://doi.org/10.1109/icsitech46713.2019.8987551', 'vowel is an integral part of speech signal processing. It can stand alone or be combined with a consonant to form specific sound. Previous studies have used wavelet transformation as sound vowel analysis method; however, these studies generally only used one level of wavelet decomposition in analyzing lung sound. This study, in turn, proposed entropy wavelet method with various levels of decomposition to obtain more comprehensive results of vowel sounds in various resolutions. It used the methods of multilevel wavelet entropy (MWE) and multilevel wavelet packet entropy (MWPE) in which the results showed 100% accuracy of MWE in the seventh level of Bior2.4 wavelet. Meanwhile, Haar wavelet and seventh level of Bior1.5 wavelet had 93.33% accuracy in MPWE. The combination of MWE and MWPE had 100% accuracy in the seventh level of Bior2.4 wavelet. Proposed method in this study can be used in a more extensive speech analysis.', 0, 'OPENALEX', '{"doi": "10.1109/icsitech46713.2019.8987551", "openalex": "https://openalex.org/W3006503306"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('aad4f557-3fa6-4f1b-868f-01199bfa7606', 'Building Vulnerability Assessment Using Hybrid Assessment Approaches: Object-Based Image Analysis and In-Situ Survey', NULL, 2009, '2009-12-01', 'Sujoko Sumaryono; G. Strunz; Robert J. Ludwig; Justin Blaise Post; Kai Zoßeder; Markus Mueck', 'AGUFM', 'JOURNAL', NULL, 'http://ui.adsabs.harvard.edu/abs/2009AGUFMNH31B1119S/abstract', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W3010126279"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a7bbdc1e-5a0a-4776-a3dc-5da45557a635', 'Design of H∞Control and Simplified Instrument Fault Detection on DC Motor', NULL, 2020, '2020-12-02', 'Lintang Erlangga; Bagas Budhi Permana; Ulynnuha Setiyadi; Samiadji Herdjunanto; Sujoko Sumaryono', NULL, 'PREPRINT', '10.36227/techrxiv.13300274.v1', 'https://doi.org/10.36227/techrxiv.13300274.v1', 'In the presence of uncertainty, a closed-loop system must be able to maintain its stability and performance. Uncertainty can be categorized into two meanings, disturbance from external systems and perturbation in a dynamical system. In this paper, we will present a robust control design by considering a disturbance from external factors, and analyze its robustness using Structured Singular Value respect to parametric uncertainty and external disturbance. Beside that, every control system has their own region to operate, outside that region a performance degradation will occur, and led into unstability. One factor to that catastrophic is a fault in instrument reading, to anticipate it, this paper also implement Simplified Instrument Fault Detection method to detect a sensor fault in order to give an alarm for further action.', 0, 'OPENALEX', '{"doi": "10.36227/techrxiv.13300274.v1", "openalex": "https://openalex.org/W3195061313"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('288eb7d4-161e-4b91-9eea-ab422fef8ff6', 'Design of H∞Control and Simplified Instrument Fault Detection on DC Motor', NULL, 2020, '2020-12-02', 'Lintang Erlangga; Bagas Budhi Permana; Ulynnuha Setiyadi; Samiadji Herdjunanto; Sujoko Sumaryono', NULL, 'PREPRINT', '10.36227/techrxiv.13300274', 'https://doi.org/10.36227/techrxiv.13300274', 'In the presence of uncertainty, a closed-loop system must be able to maintain its stability and performance. Uncertainty can be categorized into two meanings, disturbance from external systems and perturbation in a dynamical system. In this paper, we will present a robust control design by considering a disturbance from external factors, and analyze its robustness using Structured Singular Value respect to parametric uncertainty and external disturbance. Beside that, every control system has their own region to operate, outside that region a performance degradation will occur, and led into unstability. One factor to that catastrophic is a fault in instrument reading, to anticipate it, this paper also implement Simplified Instrument Fault Detection method to detect a sensor fault in order to give an alarm for further action.', 0, 'OPENALEX', '{"doi": "10.36227/techrxiv.13300274", "openalex": "https://openalex.org/W4236190891"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c0de6da9-a39b-447b-8b1b-44b1c43958e3', 'Perbandingan Performa OpenPLC dengan PLC Komersial', NULL, 2024, '2024-12-30', 'Enas Dhuhri Kusuma; Nifwan Arbi Nugroho; Addin Suwastono; Sujoko Sumaryono', 'Journal of Applied Electrical Engineering', 'JOURNAL', '10.30871/jaee.v8i2.8710', 'https://doi.org/10.30871/jaee.v8i2.8710', 'PLC konvensional biasanya mahal dan kurang fleksibel. Produsen PLC umumnya mendesain PLC mereka sedemikian rupa sehingga hanya dapat diprogram oleh perangkat lunak yang dibuat oleh mereka sendiri. Hal ini membuat fasilitas pendidikan seperti perguruan tinggi kesulitan dalam melatih operator PLC. Salah satu cara alternatif untuk melatih operator PLC adalah dengan menggunakan perangkat OpenPLC. OpenPLC adalah perangkat PLC open source yang relatif murah dan dirancang untuk bekerja seperti PLC konvensional dari tinjauan hardware maupun software. Karya tulis ini akan membahas perbandingan kinerja antara PLC konvensional dengan sistem OpenPLC. Beberapa aspek kinerja utama yang akan dibahas dalam makalah ini meliputi ukuran memori, waktu scan, dan ekspresi logika. Tulisan ini juga akan membahas tentang beberapa fitur yang hanya tersedia di salah satu jenis PLC. Pada bagian akhir kelebihan dan kekurangan dari PLC dan OpenPLC akan dibahas beserta tujuan penggunaannya masing-masing', 0, 'OPENALEX', '{"doi": "10.30871/jaee.v8i2.8710", "openalex": "https://openalex.org/W4407909032"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
