INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3dc2e103-44c8-4ad9-9341-bac60d9e1e8f', 'MERANCANG ULANG MOTOR INDUKSI 3 FASE KECEPATAN 1000 RPM DENGAN MENGGUNAKAN RANGKA STATOR MOTOR 1500 RPM', NULL, 2010, '2010-01-01', 'Roy Natal Silalahi; Bambang Sugiyantoro; F. Danang Wijaya', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12549', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2597692309"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3dd917e4-30a7-4c96-b393-6379b9aff6a3', 'Sistem Pengendalian Peralatan Elektronis jarak Jauh dengan Menggunakan Transceiver', NULL, 2010, '2010-01-01', 'Andrea Wirawan; Priyatmadi; Bambang Sugiyantoro', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12590', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2599151294"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('552405ad-6733-4c20-be21-11944a12fe80', 'PERKIRAANBEBAN PUNCAK JANGKA MENENGAH JARINGAN SYARAF TIRUAN DI PT.PLN (PERSERO) JAWA-BALI REGION III JATENG & DIY', NULL, 2010, '2010-01-01', 'Ibnu Salam; Bambang Sugiyantoro; Harnoko St', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12546', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2757813783"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('fbe95d7d-deba-4970-a067-43f6e649910d', 'Testing of Several Paper Types as Insulators for Electric Power Systems', NULL, 2019, '2019-03-27', 'Marganda Harliman Siagian; Timbul Haryono; Bambang Sugiyantoro', 'IJITEE (International Journal of Information Technology and Electrical Engineering)', 'JOURNAL', '10.22146/ijitee.43818', 'https://doi.org/10.22146/ijitee.43818', 'Abstract— This research was based on high voltage equipment failure due to an increase in temperature and humidity on insulating materials. This can cause the power system reliability to decrease. On the other hand, paper is frequently found and used in everyday life. Paper can be categorized as a solid insulator even tough its use in the electric power system can be considered as minimum. This paper aimed to determine electrical insulation characteristics of three types of paper on market and to determine the amount of failed voltage and leakage current of test materials included with other factors such as temperature rise effect as well as humidity conditions in sample testing. The employed test samples were photo paper, duplex paper, and samson craft paper with a length of 7 cm and width of 7 cm with different thickness for each paper type. Tests were carried out with two paper conditions, i.e. paper was soaked in Shell Diala B oil and was not soaked in Shell Diala B oil, so that the significance of the oil on the paper used as an ingredient in testing could be known. The test results showed that temperature and humidity affected dielectric strength magnitude and test sample leakage current value. In addition, it was also found that test sample result impregnated with Shell Diala B had a higher dielectric magnitude compared to the unimpregnated test sample. Test samples impregnated with Shell Diala B oil had a leakage current value which tended to be smaller than the unimpregnated test sample.', 0, 'OPENALEX', '{"doi": "10.22146/ijitee.43818", "openalex": "https://openalex.org/W2943417659"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('28721016-19cb-49ee-b1cd-76860358666b', 'Detection of Partial Discharge in Oil Filled-Tank using Acoustic in Audio Frequency', NULL, 2021, '2021-04-01', 'Mochammad Wahyudi; Noor Akhmad Setiawan; Bambang Sugiyantoro; I Made Yulistya Negara; Gilang Adityasakti', 'JAREE (Journal on Advanced Research in Electrical Engineering)', 'JOURNAL', '10.12962/jaree.v5i1.105', 'https://doi.org/10.12962/jaree.v5i1.105', 'In this paper, the acoustic emission of partial discharge (PD) in oil contained in the tank was detected by using microphone sensor. PD was generated by point-to-flat electrodes under DC high voltage. The given variables were the DC voltage stress, the electrode gap distance, and the location of PD and sensors. The acoustic and high frequency current were recorded along with the increased voltage. The acoustic signal was then transformed using the fast Fourier transform (FFT) to obtain the frequency spectrum. Furthermore, the acoustic waveforms, the acoustic frequency spectrum, and the PD current were analyzed and correlated. The results showed that the PD could be detected by its audio frequency signal. The impulse-shaped acoustic signal was recognized as a transition condition from normal to PD. The acoustic sensor attached to the outer wall of tank (contact type) was more sensitive than sensor that had a distance from the tank (non-contact type). The perfection level of impulse waveform may indicate the PD location in the oil-filled tank. The signal of acoustic and current did also not affect each other.', 0, 'OPENALEX', '{"doi": "10.12962/jaree.v5i1.105", "openalex": "https://openalex.org/W3142610839"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4cf4ce0a-e200-45ee-b42a-361477fa3551', 'Generation Expansion Planning for the Kalimantan Interconnected System Considering the Renewable Energy Mix and Carbon Dioxide Emissions Targets', NULL, 2024, '2024-10-23', 'Mary Anne Alvin; Lesnanto Multa Putranto; Bambang Sugiyantoro; Ahmad Edy Syukral Siregar', NULL, 'JOURNAL', '10.1109/icitee62483.2024.10808408', 'https://doi.org/10.1109/icitee62483.2024.10808408', 'The increasing annual demand for electricity requires an optimal generation expansion plan (GEP) while maintaining reliability levels, including renewable energy (RE) targets and carbon dioxide emission reductions to support global and national efforts against climate change. The optimization of GEP for the Kalimantan Interconnected System for the period 2026-2050 is carried out using OSeMOSYS software and the Linear Programming method. This optimization considers three scenarios: Business as Usual (BAU), RE Optimization, and Emission Optimization, which are analyzed in terms of installed capacity, renewable energy mix, carbon dioxide emissions, and levelized cost of electricity (LCOE). The Kalimantan Interconnected System in each scenario is dominated by coal and hydro power plants due to their economic advantages and abundant resources. The BAU scenario has the lowest LCOE of ¢8.20/kWh, but it does not support RE targets and results in high carbon dioxide emissions. The RE Optimization scenario meets the RE target with a LCOE of ¢8.49/kWh. Meanwhile, the Emission Optimization scenario meets both the RE target and emission reduction with the highest LCOE of ¢8.66/kWh, indicating that this scenario is the only one that can meet both targets, albeit with a high LCOE.', 0, 'OPENALEX', '{"doi": "10.1109/icitee62483.2024.10808408", "openalex": "https://openalex.org/W4405846186"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('35e1092e-6116-404f-a8c8-95be3b440d9f', 'Pengaruh Penambahan Kapasitor terhadap Unjuk Kerja Motor Induksi Tiga Fase Sangkar Tupai', NULL, 2014, '2014-10-07', 'Bambang Sugiyantoro; Tiyono Tiyono; M. Rasyid Aziz', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/78366', 'The most types of electric motors are used and
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('18ef3e84-c202-4546-b735-5e87593b6ca5', 'PERBANDINGAN UNJUK KERJA TANPA BEBAN MOTOR INDUKSI TIGA FASE 54 SLOT DENGAN KONEKSI DELTA (d) DAN WYE (Y)', NULL, 2010, '2010-01-01', 'Ari Hikmawan; Bambang Sugiyantoro; Harnoko St', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=11992', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W657938748"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0f9b67a6-54eb-4895-9e7e-f787060ddd7c', 'Face Recognition for Attendance System Detection', NULL, 2018, '2018-07-01', 'Rudy Hartanto; Marcus Nurtiantoro Adji', NULL, 'JOURNAL', '10.1109/iciteed.2018.8534942', 'https://doi.org/10.1109/iciteed.2018.8534942', 'These days, biometric authentication methods begin growing rapidly as one of promising authentication methods, besides the conventional authentication method. Almost all biometrics technologies require some actions by user, which are the user needs to place funds on the scanner to set the fingers or the hand geometry detection. The user shall stand still in a fixed position in front of the camera for iris or retina identification purpose. The face recognition method has several external advantages compared to the other biometric methods because this method can be done passively without explicit action or should be held by the user since the face image can be obtained by the camera from a certain distance. This method can be especially useful for mission and supervision. This research would develop and implement the face recognition system consists of four stage process. The four-stage process were face detection process using skin color detection and Haar Cascade algorithm, alignment process that contains face features normalization process, feature extraction process, and classification process using LBPH algorithm. Furthermore, the process would be continued to current system replacement with the system that has been built. The experimental results show that the system can recognize the faces captured automatically by the camera accurately.', 34, 'OPENALEX', '{"doi": "10.1109/iciteed.2018.8534942", "openalex": "https://openalex.org/W2901096422"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('dd37158c-afc7-4b3f-bedf-e5985e52b541', 'Seizure Type Detection in Epileptic EEG Signal using Empirical Mode Decomposition and Support Vector Machine', NULL, 2019, '2019-08-01', 'Inung Wijayanto; Rudy Hartanto; Hanung Adi Nugroho; Bondhan Winduratna', NULL, 'JOURNAL', '10.1109/isitia.2019.8937205', 'https://doi.org/10.1109/isitia.2019.8937205', 'Epilepsy is a serious neurological disorder that needs more attention by society. The International League Against Epilepsy (ILAE) mentioned that the term epilepsy referred to the number of seizure occurred in patients. Electroencephalogram signal is a common epilepsy diagnostic tools used by the neurologist. Research about the detection and classification of the epileptic signal from the EEG signal has massively conducted. In this research, we detect and classify four types of seizures which are focal non-specific seizure (FNSZ), generalized non-specific seizure (GNSZ), simple partial seizure (SPSZ), and tonic-clonic seizure (TNSZ). The EEG signal used was taken from Temple University Hospital EEG Seizure Corpus (TUSZ) version 1.2.0. The EEG signal decomposed with empirical mode decomposition (EMD) to extract five levels of intrinsic mode functions (IMFs). Feature extraction is done by calculating the mean, variance, skewness, kurtosis, standard deviation, and interquartile range. Support Vector Machine (SVM) used for classification with five-fold cross-validation. The best accuracy obtained is 95% by using quadratic SVM kernel.', 34, 'OPENALEX', '{"doi": "10.1109/isitia.2019.8937205", "openalex": "https://openalex.org/W3000002325"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5c153393-284f-47a7-b8ae-e1714775c569', 'The Role of IT Audit in the Era of Digital Transformation', NULL, 2018, '2018-09-26', 'Bayu Rima Aditya; Rudy Hartanto; Lukito Edi Nugroho', 'IOP Conference Series Materials Science and Engineering', 'JOURNAL', '10.1088/1757-899x/407/1/012164', 'https://doi.org/10.1088/1757-899x/407/1/012164', 'The purpose of this paper is to explain that the evolving digital transformation will automatically affect the role of IT audit. In the era of digital transformation, IT audit will become increasingly involved to ensure that IT implementation does not create unacceptable risks to the business. That way, the IT audit should have gained a favourable position as many companies are transforming the business as it is today. This research methodology use a qualitative approach by emphasizing the data analysis. The result of this research can contribute to the field of modern IT audit by presenting practical guidance for determining the role of IT audit in the era of digital transformation.', 32, 'OPENALEX', '{"doi": "10.1088/1757-899x/407/1/012164", "openalex": "https://openalex.org/W2892921791"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('660341a6-6280-48cc-a94d-8c9125448084', 'Caching strategy for Web application – a systematic literature review', NULL, 2020, '2020-10-05', 'Mulki Indana Zulfa; Rudy Hartanto; Adhistya Erna Permanasari', 'International Journal of Web Information Systems', 'JOURNAL', '10.1108/ijwis-06-2020-0032', 'https://doi.org/10.1108/ijwis-06-2020-0032', 'Purpose Internet users and Web-based applications continue to grow every day. The response time on a Web application really determines the convenience of its users. Caching Web content is one strategy that can be used to speed up response time. This strategy is divided into three main techniques, namely, Web caching, Web prefetching and application-level caching. The purpose of this paper is to put forward a literature review of caching strategy research that can be used in Web-based applications. Design/methodology/approach The methods used in this paper were as follows: determined the review method, conducted a review process, pros and cons analysis and explained conclusions. The review method is carried out by searching literature from leading journals and conferences. The first search process starts by determining keywords related to caching strategies. To limit the latest literature in accordance with current developments in website technology, search results are limited to the past 10 years, in English only and related to computer science only. Findings Note in advance that Web caching and Web prefetching are slightly overlapping techniques because they have the same goal of reducing latency on the user’s side. But actually, the two techniques are motivated by different basic mechanisms. Web caching uses the basic mechanism of cache replacement or the algorithm to change cache objects in memory when the cache capacity is full, whereas Web prefetching uses the basic mechanism of predicting cache objects that can be accessed in the future. This paper also contributes practical guidelines for choosing the appropriate caching strategy for Web-based applications. Originality/value This paper conducts a state-of-the art review of caching strategies that can be used in Web applications. Exclusively, this paper presents taxonomy, pros and cons of selected research and discusses data sets that are often used in caching strategy research. This paper also provides another contribution, namely, practical instructions for Web developers to decide the caching strategy.', 31, 'OPENALEX', '{"doi": "10.1108/ijwis-06-2020-0032", "openalex": "https://openalex.org/W3091809495"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0c86a0b5-f7ac-4c3d-9a10-24b8ae347a4c', 'A Study on Facial Expression Recognition in Assessing Teaching Skills: Datasets and Methods', NULL, 2019, '2019-01-01', 'Pipit Utami; Rudy Hartanto; Indah Soesanti', 'Procedia Computer Science', 'JOURNAL', '10.1016/j.procs.2019.11.154', 'https://doi.org/10.1016/j.procs.2019.11.154', 'Facial expressions recognition (FER) is an important modality in the future assessing teaching skill system (ATS). The fundamental difference with FER is in its low resolution image, unique occlusion of veiled teachers, and varied lighting conditions. However, it is still able to solve the problem of variations in head poses. This study, overall, began with the collection of articles from Scopus, created the FER taxonomy class and mapped the use of datasets. After finding out which datasets were suitable for the image of expression in teaching, a deeper discussion about classifier-classifier (using the same CK+ dataset) was capable of solving problems (low resolution image, occlusion, variation in lighting conditions and head poses). Finally, from the discussion conducted, it is known the potential for modification of algorithms, appropriate datasets and research opportunities for future FER in ATS.', 21, 'OPENALEX', '{"doi": "10.1016/j.procs.2019.11.154", "openalex": "https://openalex.org/W2997783537"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b6cde5f2-f44c-4f6a-9749-6111d095eb83', 'The EfficientNet Performance for Facial Expressions Recognition', NULL, 2022, '2022-12-08', 'Pipit Utami; Rudy Hartanto; Indah Soesanti', NULL, 'JOURNAL', '10.1109/isriti56927.2022.10053007', 'https://doi.org/10.1109/isriti56927.2022.10053007', 'Convolutional neural networks (CNN) have advanced significantly in object detection, image classification, and various other implementions, including Facial Expression Recognition (FER). Modern CNN models become slower and require more computation as they become deeper and larger. In this context, EfficientNet is moving in a new path by using compound scaling to improve accuracy. In existing FER research, EfficientNet is used as a pre-trained network (as is or as a fine-tuned EfficientNet) and is then combined with a variety of classifiers. Previous studies indicate that the addition of the EfficientNet index does not result in an increase in accuracy EfficientNet was used in this study as feature extractor and followed by GAP, FCL, and Softmax Layer as classifier. The best model in this study was EfficientNetB3 (accuracy: 94.44%, F1 score: 0.94, and average ROC-curve score: 0.97). EfficientNet can recognize both positive and negative emotions. The variety of specific emotional derivatives and suppressed negative emotions pose difficulties in teacher emotion recognition. Although the research results show that EfficientNet outperforms other deep CNN models, it is requisite to reexamine the basic network and compound scaling formulation so that it can become a sophisticated model for the new Teachers FER dataset.', 11, 'OPENALEX', '{"doi": "10.1109/isriti56927.2022.10053007", "openalex": "https://openalex.org/W4323520632"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0755a235-0ba7-4791-8a18-162abca443e2', 'Quantitative Analysis of Inter- and Intrahemispheric Coherence on Epileptic Electroencephalography Signal', NULL, 2022, '2022-04-01', 'Inung Wijayanto; Rudy Hartanto; Hanung Adi Nugroho', 'Journal of Medical Signals & Sensors', 'JOURNAL', '10.4103/jmss.jmss_63_20', 'https://doi.org/10.4103/jmss.jmss_63_20', 'When an epileptic seizure occurs, the neuron''s activity of the brain is dynamically changed, which affects the connectivity between brain regions. The connectivity of each brain region can be quantified by electroencephalography (EEG) coherence, which measures the statistical correlation between electrodes spatially separated on the scalp. Previous studies conducted a coherence analysis of all EEG electrodes covering all parts of the brain. However, in an epileptic condition, seizures occur in a specific region of the brain then spreading to other areas. Therefore, this study applies an energy-based channel selection process to determine the coherence analysis in the most active brain regions during the seizure. This paper presents a quantitative analysis of inter- and intrahemispheric coherence in epileptic EEG signals and the correlation with the channel activity to glean insights about brain area connectivity changes during epileptic seizures. The EEG signals are obtained from ten patients’ data from the CHB-MIT dataset. Pair-wise electrode spectral coherence is calculated in the full band and five sub-bands of EEG signals. The channel activity level is determined by calculating the energy of each channel in all patients. The EEG coherence observation in the preictal ( Cohpre ) and ictal ( Cohictal ) conditions showed a significant decrease of Cohictal in the most active channel, especially in the lower EEG sub-bands. This finding indicates that there is a strong correlation between the decrease of mean spectral coherence and channel activity. The decrease of coherence in epileptic conditions ( Cohictal &lt; Cohpre ) indicates low neuronal connectivity. There are some exceptions in some channel pairs, but a constant pattern is found in the high activity channel. This shows a strong correlation between the decrease of coherence and the channel activity. The finding in this study demonstrates that the neuronal connectivity of epileptic EEG signals is suitable to be analyzed in the more active brain regions.', 9, 'OPENALEX', '{"doi": "10.4103/jmss.jmss_63_20", "openalex": "https://openalex.org/W4283658923"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('295fb0ec-5c45-49f4-92e9-3d4b9fa0dcfb', 'Optimum object selection methods for spontaneous gaze-based interaction with linear and circular trajectories', NULL, 2024, '2024-01-11', 'Hafzatin Nurlatifa; Rudy Hartanto; Ahmad Ataka; Sunu Wibirama', 'Results in Engineering', 'JOURNAL', '10.1016/j.rineng.2024.101769', 'https://doi.org/10.1016/j.rineng.2024.101769', 'The demand for touchless technologies has increased since the outbreak of Covid-19. Spontaneous gaze-based interaction is a promising technique because it offers a natural approach for object selection using eye movements. There are two types of object trajectory in spontaneous gaze-based interaction: linear and circular trajectories. However, previous studies did not consider the optimum object selection method by taking into account the characteristics of each trajectory. In addition, previous studies suffered from high missed detection that caused spontaneous gaze-based applications to be less accurate and responsive. To address these scientific gaps, we conducted a novel study to propose optimum methods for object selection in linear and circular trajectories. The experimental results suggested that each trajectory requires a different combination of events detection and object selection techniques to achieve optimum performance. We recommend 2D Correlation as the object selection technique. In addition, we also recommend the Velocity and Movement Pattern Identification (I-VMP) and the Hidden Markov Model (HMM) as events detection techniques in linear and circular trajectories, respectively. The proposed approaches solved the missed detection problem and significantly increased the accuracy of gaze-based object selection to 95.60% and 99.73% on linear and circular trajectories, respectively. In the future, our discoveries are promising for the development of accurate, responsive, and seamless gaze-based touchless applications.', 8, 'OPENALEX', '{"doi": "10.1016/j.rineng.2024.101769", "openalex": "https://openalex.org/W4390754556"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c211c112-866c-4811-9b36-cb6e7c4cb66d', 'Harnessing Deep Learning and Technical Indicators for Enhanced Stock Predictions of Blue-Chip Stocks on the Indonesia Stock Exchange (IDX)', NULL, 2025, '2025-02-02', 'B. Yudi Dwiandiyanta; Rudy Hartanto; Ridi Ferdiana', 'Engineering Technology & Applied Science Research', 'JOURNAL', '10.48084/etasr.9850', 'https://doi.org/10.48084/etasr.9850', 'Given the limitations of existing models in accurately predicting stock prices, particularly in emerging markets such as Indonesia, this study aimed to evaluate the effectiveness of deep learning models in forecasting stock prices using blue-chip company shares traded on the Indonesia Stock Exchange (IDX). The main focus lies in combining historical stock data with a series of existing technical indicators, optimizing their integration to improve prediction accuracy. The accuracy of this method is reflected in a comprehensive evaluation of model performance using robust metrics, including R2, Mean Squared Error (MSE), and Root Mean Squared Error (RMSE). Empirical results show the superiority of models integrating technical indicators compared to models relying only on historical data. The LSTM model showed the most significant improvement, with R2 for ASII stock jumping by 14.59% after incorporating technical indicators. The prediction accuracy of the GRU model for BBCA shares increased significantly, as shown by a decrease of 45.16% in MSE. These findings underscore the critical role of feature selection in developing prediction models. Integrating technical indicators with historical stock data increases prediction accuracy and provides additional tools for informed decision-making.', 3, 'OPENALEX', '{"doi": "10.48084/etasr.9850", "openalex": "https://openalex.org/W4407078170"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('ec47b2bd-6e6b-40bb-83a4-040000d8a8af', 'Machine learning algorithm for improving performance on 3 AQ-screening classification', NULL, 2019, '2019-12-30', 'Taftazani Ghazi Pratama; Rudy Hartanto; Noor Akhmad Setiawan', 'Communications in Science and Technology', 'JOURNAL', '10.21924/cst.4.2.2019.118', 'https://doi.org/10.21924/cst.4.2.2019.118', 'Autism Spectrum Disorder (ASD) classification using machine learning can help parents, caregivers, psychiatrists, and patients to obtain the results of early detection of ASD. In this study, the dataset used is the autism-spectrum quotient for child, adolescent and adult, namely AQ-child, AQ-adolescent, AQ-adult. This study aims to improve the sensitivity and specificity of previous studies so that the classification results of ASD are better characterized by the reduced misclassification. The algorithm applied in this study: support vector machine (SVM), random forest (RF), artificial neural network (ANN). The evaluation results using 10-fold cross validation showed that RF succeeded in producing higher adult AQ sensitivity, which was 87.89%. The increase in the specificity level of AQ-Adolescents is better produced using an SVM of 86.33%.', 8, 'OPENALEX', '{"doi": "10.21924/cst.4.2.2019.118", "openalex": "https://openalex.org/W2996977618"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f763a9ba-431b-4f18-b72b-f1a44982af03', 'Comparative Analysis of XGBoost, Random Forest, and Logistic Regression for Classifying Jakarta’s Air Pollution Index (ISPU)', NULL, 2025, '2025-01-01', 'Indra Marihot Rajagukguk; Rudy Hartanto; Julian Julian; Rico Halim', 'Procedia Computer Science', 'JOURNAL', '10.1016/j.procs.2025.08.264', 'https://doi.org/10.1016/j.procs.2025.08.264', 'Jakarta’s air pollution is still a major problem for the environment and general public’s health. In this study, Jakarta’s Air Pollution Index (ISPU) is categorized into three groups: Good, Moderate, and Unhealthy based on a comparison of three monitored machine learning algorithms: Logistic Regression, Random Forest, and eXtreme Gradient Boosting (XGBoost). A total of 1,367 Data were used combining weather and air quality data from 2021 to 2024 were analyzed. The novelty of this study lies in evaluating and comparing the impact of three feature selection scenarios—without feature selection, Random Projection, and Pearson Correlation—on model performance. The tests evaluated the models’ F1 score, 10x cross-validation, accuracy, precision, and recall scores. XGBoost consistently performed better achieving the highest accuracy of 98.91%, consistently outperforming other models across all feature selection scenarios. Random Forest also showed strong accuracy (97.08%), particularly when using Pearson Correlation. Although Logistic Regression was arithmetic efficient and interpretable, performance suffered greatly when important features were eliminated. Pearson Correlation positively influenced model performance by removing weakly related features, especially for tree-based methods like XGBoost and Random Forest, which improved both accuracy and interpretability. In contrast, Random Projection caused a noticeable performance decline in all models due to its randomized nature, which may have removed or distorted essential feature relationships, especially in simpler models like Logistic Regression. These findings highlight the importance of appropriate feature selection in improving model accuracy and interpretability in air quality classification tasks.', 2, 'OPENALEX', '{"doi": "10.1016/j.procs.2025.08.264", "openalex": "https://openalex.org/W4415972099"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('66523bcd-a073-4b2e-9e1e-71871e521340', 'Android based real-time static Indonesian sign language recognition system prototype', NULL, 2016, '2016-10-01', 'Rudy Hartanto; Annisa Kartikasari', NULL, 'JOURNAL', '10.1109/iciteed.2016.7863311', 'https://doi.org/10.1109/iciteed.2016.7863311', 'Sign language uses gestures instead of speech sounds to communicate. But in general, normal people rarely trying to learn sign language to interact with the deaf community. Recently, there are many sign language recognition system that had been developed. But most of them were implemented using desktop and laptop computer, which is impractical due to its weight and size. This paper presents a prototype of real time static Indonesian sign language recognition using the Android Smart Phone, so it can be used anywhere and anytime. YCrCb color space combined with skin color detection is used to remove the background image and form a segmented image. Detection contour with convex hull algorithms are used to localize and save an area of the hand. Convexity defect algorithms then are used to extract the hand gesture''s features using a radiant line from the center of the palm to the fingertips. The classification of hand gesture that performs sign alphabets is accomplished using back propagation neural network algorithm in order to determine a suitable alphabet. The performance test of the system is done by recognizing some variation hand gesture poses for Indonesian sign language alphabet. The results show that the system can detect the position of the user''s hand. Furthermore, the system can recognize the alphabet sign from user hand gesture input, reaching 91.66% success rate in testing using Android devices in real time.', 27, 'OPENALEX', '{"doi": "10.1109/iciteed.2016.7863311", "openalex": "https://openalex.org/W2593059953"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('83385dc0-75aa-403f-85e3-875ff73a5bd8', 'Discrete Wavelet Denoising into MFCC for Noise Suppressive in Automatic Speech Recognition System', NULL, 2020, '2020-02-26', 'Hay Mar Soe Naing; Risanuri Hidayat; Rudy Hartanto; Yoshikazu Miyanaga', 'International journal of intelligent engineering and systems', 'JOURNAL', '10.22266/ijies2020.0430.08', 'https://doi.org/10.22266/ijies2020.0430.08', 'Automatic Speech Recognition (ASR) is a challenging task and the most problematic issues being in presence of background noise and substantial variability in speech. Extracting the noise-robust features adjust for speech degradations due to noise effect retained popular issue in recent years. This paper presented a framework for wavelet denoising scheme and analysed the different wavelet families and proper thresholding rule into feature extraction to enhance the performance of ASR system. Gaussian Mixture Model-based Hidden Markov Model (GMM-HMM) and Deep Neural Network (DNN)-HMM are used as the speech recognizer. The recognition performance shows that the noise-robust features are obtained while combining with the wavelet transform denoising into Mel Frequency Cepstral Coefficient (MFCC) on Aurora2 database. The best accuracy is gained by cross entropy DNN-HMM training using denoising with Coiflet wavelet and Rigrsure threshold, which provides 97.54% in 10dB, 93.13% in 5dB, 75.63% in 0dB and 37.29% in -5dB.', 24, 'OPENALEX', '{"doi": "10.22266/ijies2020.0430.08", "openalex": "https://openalex.org/W3007758482"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d157a56f-0048-4c52-86fc-604845ae76d7', 'Comparison of empirical mode decomposition and coarse-grained procedure for detecting pre-ictal and ictal condition in electroencephalography signal', NULL, 2020, '2020-01-01', 'Inung Wijayanto; Rudy Hartanto; Hanung Adi Nugroho', 'Informatics in Medicine Unlocked', 'JOURNAL', '10.1016/j.imu.2020.100325', 'https://doi.org/10.1016/j.imu.2020.100325', 'This study evaluates the use of multiscale signal analysis to detect and predict seizures by finding the ictal and pre-ictal condition in electroencephalography (EEG) recordings. There are three processing stages in this study. The first is to decompose EEG signals by using empirical mode decomposition (EMD) and a coarse-grained (CG) procedure to obtain signal information in multiple scales. The second is extracting the features by calculating the fractal dimension of the decomposed signals. Eventually, k-NN, Random Forest, and support vector machine (SVM) classifiers are used to classify ictal and pre-ictal conditions. We evaluate the system using a public dataset from Bonn University. The combination of EMD with five IMFs, FD, and SVM is used for seizure detection (normal vs. ictal) and the three-class problem (normal vs. pre-ictal vs. ictal). The accuracy for seizure detection is 100%. For the three-class problem, we achieved a highest accuracy of 99.7%, and sensitivity and specificity of 99.7% and 99.9%, respectively. The combination of CG, FD, and SVM is proposed to predict a seizure (normal vs. pre-ictal) and achieves a maximum classification accuracy from 99.3% to 100%. These results indicate that the use of EMD with five IMFs is suitable for detecting seizures, while CG is suitable for predicting seizures in EEG signals.', 20, 'OPENALEX', '{"doi": "10.1016/j.imu.2020.100325", "openalex": "https://openalex.org/W3016974233"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1ce1d76e-0816-43f4-b15f-ff24d6935852', 'Transfer Gambar melalui Gelombang RF pada Sistem Akses Informasi Internet Menggunakan Televisi', NULL, 2006, '2006-01-01', 'Selo Sulistyo', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/32310/', 'Penelitian ini bermaksud mengembangkan aplikasi perangkat lunak pengirim dan penerima gambar melalui kanal televisi analog. Gambar hasil konvesi dari file html (format umum informasi Internet) yang ada di server dikirimkan melalui gelombang RF pada frekuensi 300MHz dan diterima menggunakan TV tuner digital. PErangkat lunak pada sisi pengirim dikembangkatkan dengan bahasa pemrograman Delphi 6 sedangkan pada unit penerima menggunakan perangkat lunak Xavtv berbasis Linux.
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3648edf7-cce0-46f3-aa7b-92e5a5c391f3', 'High-resolution automated Fugl-Meyer Assessment using sensor data and regression model', NULL, 2017, '2017-07-01', 'Ricky Julianjatsono; Ridi Ferdiana; Rudy Hartanto', NULL, 'JOURNAL', '10.1109/icstc.2017.8011847', 'https://doi.org/10.1109/icstc.2017.8011847', 'Motor function assessment is a critical component in post-stroke rehabilitation program. Fugl-Meyer Assessment (FMA) is regarded as the most comprehensive tool to describe post-stroke patient''s motor function and is widely utilized. However, the FMA scoring system classifies patient''s motor function within only three levels (0, 1, or 2) for each assessment item. Hence, it''s difficult to observe minor improvement in patient''s motor function. To address this issue, a high-resolution scoring system was proposed in this research. Six regression models were built for six upper-extremity FMA items. These models were trained using data gathered from Microsoft Kinect sensor and glove sensor. The trained models could predict FMA scores with the resolution of 14 fractional digits. The representativeness of the predicted scores was evaluated by calculating their Pearson''s correlation with the actual kinematic variables. All predicted scores represent patient''s motor function better than standard FMA score. In addition, the highest correlation''s mean of 0.58 was found on shoulder elevation item which utilized Neural Network Regression algorithm. This algorithm also outperformed the other in most assessment items. The ability to observe the changes in patient''s motor function in detail helps therapists providing more responsive treatment and could likely increase the patient''s adherence toward the given treatment.', 19, 'OPENALEX', '{"doi": "10.1109/icstc.2017.8011847", "openalex": "https://openalex.org/W2747625785"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d293e270-9162-4ad7-8b33-5b2e60dce842', 'Higuchi and Katz Fractal Dimension for Detecting Interictal and Ictal State in Electroencephalogram Signal', NULL, 2019, '2019-10-01', 'Inung Wijayanto; Rudy Hartanto; Hanung Adi Nugroho', NULL, 'JOURNAL', '10.1109/iciteed.2019.8929940', 'https://doi.org/10.1109/iciteed.2019.8929940', 'Epilepsy is a neurological disorder which may occur in every human being. The existence of a seizure showed as the characteristic of this disorder. International League Against Epilepsy (ILAE) mentioned that the diagnose of epilepsy required a minimum of two seizure event in 24 hours. A standard tool used by the neurologist to diagnose epilepsy was Electroencephalogram (EEG). An automatic seizure detection in EEG signal may help them to identify the pattern of ictal condition. Since the characteristic of the EEG signal were dynamic and nonstationary, it was very challenging to interpret the signal pattern. In this study, we analyzed the use of Higuchi and Katz fractal dimension as a feature extraction method to detect an interictal and ictal state in the EEG signal. These two states were essential in the term of seizure detection and prediction system. EEG signal extracted into five frequency bands called delta, theta, alpha, beta, and gamma. Each frequency showed a different characteristic of brain-behavior in a specific condition. The extracted features then fed into a support vector machine (SVM) to classify between normal with interictal and ictal states. The proposed method able to determine normal vs. ictal state with 100% of accuracy. On the other hand, the best accuracy obtained for detecting normal vs. interictal state was 99.5%.', 19, 'OPENALEX', '{"doi": "10.1109/iciteed.2019.8929940", "openalex": "https://openalex.org/W2995918002"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e38a55da-4682-45a1-9cfa-923b2dc219b0', 'Genetic Algorithm for lecturing schedule optimization', NULL, 2019, '2019-01-31', 'David Kristiadi; Rudy Hartanto', 'IJCCS (Indonesian Journal of Computing and Cybernetics Systems)', 'JOURNAL', '10.22146/ijccs.43038', 'https://doi.org/10.22146/ijccs.43038', 'Scheduling is a classic problem in lecturing. Rooms, lecturers, times and scheduling constraints must be managed well to get an optimal schedule. University of Boyolali (UBY) also encounter the same scheduling problems. The problem was tried to be solved by building a library based on Genetic Algorithm (GA). GA is a computation method which inspired by natural selection. The computation consists of some operators i.e. Tournament Selection, Uniform Crossover, Weak Parent Replacement and two mutation operators (Interchanging Mutation and Violated Directed Mutation (VDM)). The two mutation method are compared to find which better mutation operator. The library was planned to have a capability to define custom constraints (scheduling requirements that were not accommodated by the library) without core program modifications. The test results show that VDM is more promising for optimal solutions than Interchanging Mutation. In UBY cases, optimal solution (fitness value=1) is reached in 12 minutes 41 second with adding 6 new room and inactivated 2 constraint i.e. lecturing begins at 14.00 except for 3rd semester of science law study program with morning class and lecturing participants must not over classroom capacity.', 18, 'OPENALEX', '{"doi": "10.22146/ijccs.43038", "openalex": "https://openalex.org/W2914988908"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5e6e87c2-27bf-4a89-a1cc-12eda81a6618', 'Classification of Batik Image using Grey Level Co-occurrence Matrix Feature Extraction and Correlation Based Feature Selection', NULL, 2018, '2018-11-01', 'Nani Sulistianingsih; Indah Soesanti; Rudy Hartanto', '2018 International Seminar on Research of Information Technology and Intelligent Systems (ISRITI)', 'JOURNAL', '10.1109/isriti.2018.8864237', 'https://doi.org/10.1109/isriti.2018.8864237', 'Batik is a cultural heritage that has become part of Indonesian society. Batik has a variety of patterns and motifs. Each region has varieties of motifs in terms of color, texture and production techniques. This study discusses the feature selection method for classification of batik image into Kawung, Lereng, Nitik and Tambal. Selection of the right features by eliminating redundant features can result in higher accuracy. Another important step is feature extraction. This research applies the Gray Level Co-occurrence Matrix feature extraction to extract features in the image of batik. The total features obtained by extracting batik images using GLCM are 20 features. From 20 features, CFS is able to reduce 70% of irrelevant features. The results showed that the classification of batik using Backpropagation resulted in an accuracy of 83% and the classification using the K-Nearest Neighbor method was 67%.', 16, 'OPENALEX', '{"doi": "10.1109/isriti.2018.8864237", "openalex": "https://openalex.org/W2979316862"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b9a43eab-bbc5-4eae-bdd9-dbf3d1baa475', 'Hybrid automatic speech recognition model for speech-to-text application in smartphones', NULL, 2019, '2019-11-01', 'Riky Kusumah; Rudy Hartanto; Risanuri Hidayat', NULL, 'JOURNAL', '10.1109/iciss48059.2019.8969804', 'https://doi.org/10.1109/iciss48059.2019.8969804', 'The development of speech recognition systems has been widely carried out in various fields. Its development is often used in smart device technology to facilitate users in giving instructions to a system through sound. Development of identical speech recognition with development to improve speech reading accuracy and fast response time processing. This paper aims to try an approach through hybrid methods by combining client-side and server-side services to benefit from both services. The smartphone device was chosen as a speech recognition computing device because it is a technological device that has become a necessity of everyday life in searching for information. In the paper we will propose a hybrid automatic speech recognition model, how the model works and the framework of the application.', 1, 'OPENALEX', '{"doi": "10.1109/iciss48059.2019.8969804", "openalex": "https://openalex.org/W3003179787"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('979513a2-3802-451f-94b5-b7ca364f4175', 'An Analysis of the New Employee Onboarding Process in Startup', NULL, 2018, '2018-07-01', 'Putu Yudia Pratiwi; Ridi Ferdiana; Rudy Hartanto', NULL, 'JOURNAL', '10.1109/iciteed.2018.8534884', 'https://doi.org/10.1109/iciteed.2018.8534884', 'Turnover is one of the factors that can cause the development of a company to be hampered, especially for startup. The high level of employee turnover caused by many things, one of them is employee dissatisfaction. Onboarding process is one of the ways that can be used to introduce the new employee to the culture and work environment so that it can develop job satisfaction and convenience. However, to get an effective result, onboarding process should also be done well and systematically. This paper describes how the onboarding process is done by the startups, especially those that specialize in software engineering. The study used literature review, interview and questionnaire methods. The interview was conducted with the leaders of six startups in Yogyakarta, while questionnaires were distributed to employee in each startup who have worked for about one year. The data of the questionnaire were analyzed using descriptive statistics. Based on the results, it was found that all startups have done the five aspects of onboarding on their new employees. But the average value on these five aspects is below 80%. The lowest average score of 67% is in the documentation aspect. While the lowest sub aspect is a sub aspect of developer-oriented documentation with an average value of 58.22% and this is included in enough criteria.', 14, 'OPENALEX', '{"doi": "10.1109/iciteed.2018.8534884", "openalex": "https://openalex.org/W2901111423"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a3366bfb-3b77-49f8-b10a-c40454e80736', 'The Attendance Marking System based on Eigenface Recognition using OpenCV and Python', NULL, 2020, '2020-05-01', 'Khem Puthea; Rudy Hartanto; Risanuri Hidayat', 'Journal of Physics Conference Series', 'JOURNAL', '10.1088/1742-6596/1551/1/012012', 'https://doi.org/10.1088/1742-6596/1551/1/012012', 'Abstract Attendance of students in a large classroom is hard to be handled by the traditional system, as it is time-consuming and has a high probability of error during the process of inputting data into the computer. This paper proposed automated attendance marking system using face recognition technique. The system deployed Haar cascade to find the positive and negative of the face and eigenface algorithm for face recognition by using python programming and OpenCV library. The proposed method using PCA to resolved the problems such as lightning of the images, noise from the camera, and the direction of the student faces. The attendance of the student was updated to the Excel sheet after student’s face has been recognized.', 13, 'OPENALEX', '{"doi": "10.1088/1742-6596/1551/1/012012", "openalex": "https://openalex.org/W3037155359"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e9e006c3-e651-46af-bb5b-87c888c9f171', 'Content-Based Image Retrieval for Traditional Indonesian Woven Fabric Images Using a Modified Convolutional Neural Network Method', NULL, 2023, '2023-08-18', 'Silvester Tena; Rudy Hartanto; Igi Ardiyanto', 'Journal of Imaging', 'JOURNAL', '10.3390/jimaging9080165', 'https://doi.org/10.3390/jimaging9080165', 'A content-based image retrieval system, as an Indonesian traditional woven fabric knowledge base, can be useful for artisans and trade promotions. However, creating an effective and efficient retrieval system is difficult due to the lack of an Indonesian traditional woven fabric dataset, and unique characteristics are not considered simultaneously. One type of traditional Indonesian fabric is ikat woven fabric. Thus, this study collected images of this traditional Indonesian woven fabric to create the TenunIkatNet dataset. The dataset consists of 120 classes and 4800 images. The images were captured perpendicularly, and the ikat woven fabrics were placed on different backgrounds, hung, and worn on the body, according to the utilization patterns. The feature extraction method using a modified convolutional neural network (MCNN) learns the unique features of Indonesian traditional woven fabrics. The experimental results show that the modified CNN model outperforms other pretrained CNN models (i.e., ResNet101, VGG16, DenseNet201, InceptionV3, MobileNetV2, Xception, and InceptionResNetV2) in top-5, top-10, top-20, and top-50 accuracies with scores of 99.96%, 99.88%, 99.50%, and 97.60%, respectively.', 13, 'OPENALEX', '{"doi": "10.3390/jimaging9080165", "openalex": "https://openalex.org/W4385987270"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('596ed860-0da4-465e-a3fd-ebca60a64ba4', 'MULTIDIMENSIONAL SCALING (MDS): SUSTAINABILITY ASSESSMENT MODEL OF COMMUNITY ECONOMIC EMPOWERMENT', NULL, 2021, '2021-12-01', 'Sri Fadilah; Yuni Rosidana; Mey Maemunah; Nopi Hernawati; Edi Sukarmanto; Rudy Hartanto', 'Polish Journal of Management Studies', 'JOURNAL', '10.17512/pjms.2021.24.2.08', 'https://doi.org/10.17512/pjms.2021.24.2.08', NULL, 12, 'OPENALEX', '{"doi": "10.17512/pjms.2021.24.2.08", "openalex": "https://openalex.org/W4205430038"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a0caf775-2b46-45d9-902d-a12ab3da2dbd', 'DETEKSI NOMOR KENDARAAN DENGAN METODE CONNECTED COMPONENT DAN SVM', NULL, 2015, '2015-01-01', 'Aris Budianto; Teguh Bharata Adji; Rudy Hartanto', NULL, 'JOURNAL', NULL, 'https://jurnal.darmajaya.ac.id/index.php/jtim/article/download/489/348', 'Research on License plate detection system will be developed in this research. Vehicle plates detection will use a camera that mounted on parking gate. Detection process starts with collecting data using the camera. Preprocessing includes rescale the image into (640.480) pixels, converting the image into grayscale. Smooting process with blur method is used to reduce the image noise. Edge detection using Sobel on the vertical direction and thresholding. Segmentation process will combine 2 methods, Morphology Filter and Connected Component. Support Vector Machine (SVM) is used to test whether the candidate is a plat plate or not. Parking System Testing obtained the following results: Parking System Accuracy in detecting motorcycle plate is 78% and the accuracy car plate detection is 78% Key words — nomor plat kendaraan, Filter Morfologi, Connected Component , Support Vector Machine (SVM).', 11, 'OPENALEX', '{"openalex": "https://openalex.org/W2517887075"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e4ddb153-8cc0-4d30-a6e5-25d6172a4831', 'A Systematic Review on Automatic Detection of Plasmodium Parasite', NULL, 2021, '2021-03-25', 'Amin Siddiq Sumi; Hanung Adi Nugroho; Rudy Hartanto', 'International Journal of Engineering and Technology Innovation', 'OTHER', '10.46604/ijeti.2021.6094', 'https://doi.org/10.46604/ijeti.2021.6094', 'Plasmodium parasite is the main cause of malaria which has taken many lives. Some research works have been conducted to detect the Plasmodium parasite automatically. This research aims to identify the development of current research in the area of Plasmodium parasite detection. The research uses a systematic literature review (SLR) approach comprising three stages, namely planning, conducting, and reporting. The search process is based on the keywords which were determined in advance. The selection process involves the inclusion and exclusion criteria. The search yields 45 literatures from five different digital libraries. The identification process finds out that 28 methods are applied and mainly categorizes as machine learning algorithms with performance achievements between 60% and 95%. Overall, the research of Plasmodium parasite detection today has focused on the development with artificial intelligence specifically related to machine and deep learning. These approaches are believed as the most effective approach to detect Plasmodium parasites.', 7, 'OPENALEX', '{"doi": "10.46604/ijeti.2021.6094", "openalex": "https://openalex.org/W3144924998"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('bf00c67c-1186-4286-acd9-b3065c58fc03', 'Content-based image retrieval for fabric images: A survey', NULL, 2021, '2021-09-01', 'Silvester Tena; Rudy Hartanto; Igi Ardiyanto', 'Indonesian Journal of Electrical Engineering and Computer Science', 'JOURNAL', '10.11591/ijeecs.v23.i3.pp1861-1872', 'https://doi.org/10.11591/ijeecs.v23.i3.pp1861-1872', 'In &lt;span&gt;recent years, a great deal of research has been conducted in the area of fabric image retrieval, especially the identification and classification of visual features. One of the challenges associated with the domain of content-based image retrieval (CBIR) is the semantic gap between low-level visual features and high-level human perceptions. Generally, CBIR includes two main components, namely feature extraction and similarity measurement. Therefore, this research aims to determine the content-based image retrieval for fabric using feature extraction techniques grouped into traditional methods and convolutional neural networks (CNN). Traditional descriptors deal with low-level features, while CNN addresses the high-level, called semantic features. Traditional descriptors have the advantage of shorter computation time and reduced system requirements. Meanwhile, CNN descriptors, which handle high-level features tailored to human perceptions, deal with large amounts of data and require a great deal of computation time. In general, the features of a CNN''s fully connected layers are used for matching query and database images. In several studies, the extracted features of the CNN''s convolutional layer were used for image retrieval. At the end of the CNN layer, hash codes are added to reduce &lt;/span&gt;search time.', 9, 'OPENALEX', '{"doi": "10.11591/ijeecs.v23.i3.pp1861-1872", "openalex": "https://openalex.org/W3199974124"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('144b6c9c-beb7-4dd5-a32e-ec4d9bb77ef1', '3D human face reconstruction using depth sensor of Kinect 2', NULL, 2018, '2018-03-01', 'Ratha Siv; Igi Ardiyanto; Rudy Hartanto', '2018 International Conference on Information and Communications Technology (ICOIACT)', 'JOURNAL', '10.1109/icoiact.2018.8350702', 'https://doi.org/10.1109/icoiact.2018.8350702', '3D Human Face Reconstruction or 3D Human Face Modeling is a construction of 3D geometry graphics of human face model which has been a very challenging research in both computer vision and computer graphics for over the last three decades. Researchers have proposed many methods for 3D human face reconstruction by using or not using 3D scanner. One of the affordable 3D scanner today is Microsoft Kinect which is well known as a motion sensor add-on for Xbox gaming console. By using the depth sensor of Kinect version 2, 3D human face reconstruction is possible to construct, yet the depth information from Kinect scanning alone may not produce a good quality of 3D model which could lose the details of the 3D face; therefore, the optimization and improvement are needed. This research is mainly aimed to reconstruct the 3D human face model by using a single shot of 3D depth information or point cloud from the depth sensor of Microsoft Kinect version 2, and then, reconstruct with the proposed method including Poisson Surface Reconstruction. The results come as expected and are measured by comparing to the result of the zoomed of original RGB point cloud which looks like a 3D model and to the result of Microsoft 3D applications.', 8, 'OPENALEX', '{"doi": "10.1109/icoiact.2018.8350702", "openalex": "https://openalex.org/W2799025349"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('964b72c3-99be-4d1b-9644-a3275867ae11', 'A Study on Signal Complexity Measurement for Epileptic Seizure Detection', NULL, 2019, '2019-10-01', 'Inung Wijayanto; Rudy Hartanto; Hanung Adi Nugroho; Noor Akhmad Setiawan', NULL, 'JOURNAL', '10.1109/icsengt.2019.8906319', 'https://doi.org/10.1109/icsengt.2019.8906319', 'Epilepsy is a sudden brain malfunction that represented by an exaggerated, high, and hypersynchronous neuron activity inside the brain. Electroencephalogram (EEG) is a tool that can be used to measure the electrical changes of the brain by using electrodes placed on the scalp. An ictal pattern in the EEG signal can be used to identify seizure condition. Neurologist search for the ictal state by determining slow, spike, and sharp wave in the EEG recording manually. However, the manual method is very vulnerable to human errors. That is why many research has been conducted to develop an automatic seizure detection system. Since the EEG signal is a nonlinear, nonstationary, and chaotic, it is considered as a complex signal. This paper discusses a brief study on signal complexity measurement in the EEG signal in the term of epileptic seizure detection. Complexity measurement based on statistic, entropy, and chaos analysis is explored in six processing domain.', 7, 'OPENALEX', '{"doi": "10.1109/icsengt.2019.8906319", "openalex": "https://openalex.org/W2990253690"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c712b9e4-b7fa-4e50-989d-e9a9a845f20e', 'Test Case Understandability Model', NULL, 2020, '2020-01-01', 'Novi Setiani; Ridi Ferdiana; Rudy Hartanto', 'IEEE Access', 'JOURNAL', '10.1109/access.2020.3022876', 'https://doi.org/10.1109/access.2020.3022876', 'Several automated test case generation techniques have been proposed to date, although the adoption of such techniques in the industry remains low. A key factor that has contributed to this low adoption rate is the difficulty experienced by the developer in terms of reading and understanding automatically generated test cases. For this reason, it is essential to construct a test case understandability model for improving the generated test case. In the present paper, we extracted 20 test case metrics, six developer related metrics and two understandability proxies from a white-box test case classification experiment. Based on these metrics, we employed classification and regression algorithms to build test case understandability model. From the experiment, we can conclude that combined metrics always exhibit better discriminatory performance in classification models as well as a higher correlation in regression models when compared to a model that involved only test case metrics or developer metrics.', 7, 'OPENALEX', '{"doi": "10.1109/access.2020.3022876", "openalex": "https://openalex.org/W3085713924"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a509beab-7d55-485e-a2f6-5d91eb4c45f5', 'Model compression using post-training dynamic range quantization for plant disease recognition', NULL, 2025, '2025-03-01', 'Harry Yuliansyah; Rudy Hartanto; Indah Soesanti', 'IET conference proceedings.', 'JOURNAL', '10.1049/icp.2025.0268', 'https://doi.org/10.1049/icp.2025.0268', 'This study investigates model compression techniques for plant disease recognition using leaf images, focusing on reducing the computational burden of deployment on resource-constrained devices. Utilizing the PlantVillage dataset, the study trained and evaluated 11 prominent CNN architectures by employing a pocket algorithm for performance optimization. This study examines three training scenarios: random weight initialization, ImageNet pre-trained weights with trainable layers, and ImageNet pre-trained weights with non-trainable layers. The results demonstrated superior performance in scenarios with trainable layers, with the Xception model achieving the highest minimum accuracy. Subsequently, the study implements magnitude-based pruning using the PolynomialDecay strategy, successfully reducing the model size by 90% while maintaining comparable accuracy. Further compression was achieved through post-training dynamic range quantization, yielding a compression ratio exceeding 90% for most models without significant accuracy degradation. This study highlights the effectiveness of combining pruning and quantization to deploy accurate and efficient plant disease recognition models on devices with limited resources.', 2, 'OPENALEX', '{"doi": "10.1049/icp.2025.0268", "openalex": "https://openalex.org/W4408164213"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('61f2709e-43fa-4273-95a9-29de0a8ccd32', 'Improving Cached Data Offloading Optimization Based on Enhanced Hybrid Ant Colony Genetic Algorithm', NULL, 2022, '2022-01-01', 'Mulki Indana Zulfa; Rudy Hartanto; Adhistya Erna Permanasari; Waleed Ali', 'IEEE Access', 'JOURNAL', '10.1109/access.2022.3197205', 'https://doi.org/10.1109/access.2022.3197205', 'The data offloading mechanism is one of the critical strategies needed on edge networks to help cloud computing network performance in serving user data requests. This strategy should be optimized to prevent network congestion. The main problem of this strategy is how to assess the priority of cached data so that the cache memory buffer capacity can be optimized. In this paper, we modeled the cached data offloading strategy using the Knapsack Problem 0/1 (KP01) approach. Several researchers proposed a meta-heuristic algorithm to solve cached data offloading using the KP01 approach. Meta-heuristic algorithms require a reliable solution selection method to find the global optimal solution. However, some studies still use the roulette wheel selection method to provide a set of solutions. The RWS method has a weakness of imbalance the particle fitness with its cumulative probability. Therefore, it is difficult to find the global optimal solution. This study proposed a nested-Roulette Wheel Selection (nRWS) method on hybrid Ant Colony Optimization (ACO) and Genetic Algorithm (GA) to address the cached data offloading optimization using the KP01 approach. The simulation results show that the proposed nRWS method is able to find the global optimal solution in terms of the value of the objective function and hit ratio which is superior to previous studies.', 5, 'OPENALEX', '{"doi": "10.1109/access.2022.3197205", "openalex": "https://openalex.org/W4290713857"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3ff9b249-325c-4795-bba5-0e87fff12808', 'LRU-GENACO: A Hybrid Cached Data Optimization Based on the Least Used Method Improved Using Ant Colony and Genetic Algorithms', NULL, 2022, '2022-09-20', 'Mulki Indana Zulfa; Rudy Hartanto; Adhistya Erna Permanasari; Waleed Ali', 'Electronics', 'JOURNAL', '10.3390/electronics11192978', 'https://doi.org/10.3390/electronics11192978', 'An optimization strategy for cached data offloading plays a crucial role in the edge network environment. This strategy can improve the performance of edge nodes with limited cache memory to serve data service requests from user terminals. The main challenge that must be solved in optimizing cached data offloading is assessing and selecting the cached data with the highest profit to be stored in the cache memory. Selecting the appropriate cached data can improve the utility of memory space to increase HR and reduce LSR. In this paper, we model the cached data offloading optimization strategy as the classic optimization KP01. The cached data offloading optimization strategy is then improved using a hybrid approach of three algorithms: LRU, ACO, and GA, called LRU-GENACO. The proposed LRU-GENACO was tested using four real proxy log datasets from IRCache. The simulation results show that the proposed LRU-GENACO hit ratio is superior to the LRU GDS SIZE algorithms by 13.1%, 26.96%, 53.78%, and 81.69%, respectively. The proposed LRU-GENACO method also reduces the average latency by 25.27%.', 5, 'OPENALEX', '{"doi": "10.3390/electronics11192978", "openalex": "https://openalex.org/W4296466975"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('496e1e63-a9af-4f0e-af36-b68f012bb4ea', 'Deep Learning Techniques for Lung Cancer Detection: A Systematic Literature Review', NULL, 2023, '2023-11-10', 'Sabilla Halimatus Mahmud; Indah Soesanti; Rudy Hartanto', NULL, 'JOURNAL', '10.1109/icoiact59844.2023.10455848', 'https://doi.org/10.1109/icoiact59844.2023.10455848', 'Lung cancer has been a leading cause of cancer-related deaths, with the number of fatalities in the United Kingdom between 2017 and 2019 reaching 34771, as reported by Cancer Research UK. Lung cancer is when cells inside the lung grow uncontrollably. Detecting nodules in lung cancer at an early stage can increase the chances of survival for humans. Researchers have been investigating the potential of artificial intelligence and deep learning to develop computer-aided detection (CAD) systems for automated lung cancer detection and classification. CAD systems could help radiologists detect lung cancer and improve lung cancer diagnosis accuracy. Our systematic literature review provided an overview of the performance of current deep-learning methods and datasets for detecting and classifying lung cancer using CT images. We conducted a systematic literature review using the PRISMA 2020. This paper gives the reader insights into various facets of lung cancer detection and motivates researchers to further explore opportunities for crafting models that can be seamlessly integrated into a CAD system.', 4, 'OPENALEX', '{"doi": "10.1109/icoiact59844.2023.10455848", "openalex": "https://openalex.org/W4392451040"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('bad97dfc-8a85-4c94-bf64-bc828bc04005', 'A Review E-Government Implementation: Its Impact on Public Value Creation and Citizen Perspectives', NULL, 2024, '2024-06-06', 'Nanang Hari Setyawan; Selo Sulistyo; Rudy Hartanto', NULL, 'OTHER', '10.1109/siml61815.2024.10578171', 'http://dx.doi.org/10.1109/siml61815.2024.10578171', 'The global expansion of e-government services reflects the rising demand for efficient government services among digital citizens. Governments must prioritize understanding public perspectives and values for effective citizen-centric e-government, involving all stakeholders for sustainable development and utilizing innovative technologies to overcome challenges. This systematic literature review (SLR) aims to explore citizen-centric e-government implementation worldwide, focusing on its impact on public value creation and citizen perception. By analyzing 69 papers from 2017 to 2023 using the PRISMA method, the review revealed diverse research landscapes and highlighted the importance of inclusive services. Key variables such as Information Quality, System Quality, and Trust in e-government significantly influenced citizen attitudes. Behavioral Intention to Use, Citizen Satisfaction, and Public Value emerged as prominent dependent variables. Notable countries like China, India, Nigeria, and Pakistan were extensively studied, employing various analytical techniques like Structural Equation Modeling (SEM) and thematic analysis. Frameworks such as UTAUT, TAM, and IS Success Model were commonly used, reflecting the multifaceted nature of e-government research and the need for comprehensive approaches.', 2, 'OPENALEX', '{"doi": "10.1109/siml61815.2024.10578171", "openalex": "https://openalex.org/W4400315276"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('08b3eda9-e872-4add-a315-21674b303614', 'A comparison of different part-of-speech tagging technique for text in Bahasa Indonesia', NULL, 2017, '2017-08-01', 'Ahmad Zuli Amrullah; Rudy Hartanto; I Wayan Mustika', NULL, 'JOURNAL', '10.1109/inaes.2017.8068538', 'https://doi.org/10.1109/inaes.2017.8068538', 'Part of speech tagging has some different methods or techniques to the problem in assigning each word of a text with a part-of-speech tag. In this paper, we conducted some part-of-speech tagging techniques for Bahasa Indonesia experiments using statistical approach (Unigram, Hidden Markov Models) and Brill''s tagger. In this study, we used Supervised POS Tagging approach requiring a large number of annotated training corpuses to tag properly. We used some resource annotation corpus of Bahasa. Those corpuses were implemented with POS Tagging techniques. We subsequently compared and analyzed the results. We also compared the accuracy and highlighted some advantages and disadvantages for every technique we used. Unigram showed a higher accuracy compared to HMM and Brill tagger with 88,37% on a tagged corpus.', 9, 'OPENALEX', '{"doi": "10.1109/inaes.2017.8068538", "openalex": "https://openalex.org/W2762573316"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9093af58-9574-4664-9b33-f661d869df54', 'A Front-End Technique for Automatic Noisy Speech Recognition', NULL, 2020, '2020-11-05', 'Hay Mar Soe Naing; Risanuri Hidayat; Rudy Hartanto; Yoshikazu Miyanaga', NULL, 'JOURNAL', '10.1109/o-cocosda50338.2020.9295006', 'https://doi.org/10.1109/o-cocosda50338.2020.9295006', 'The sounds in a real environment not often take place in isolation because sounds are building complex and usually happen concurrently. Auditory masking relates to the perceptual interaction between sound components. This paper proposes modeling the effect of simultaneous masking into the Mel frequency cepstral coefficient (MFCC) and effectively improve the performance of the resulting system. Moreover, the Gammatone frequency integration is presented to warp the energy spectrum which can provide gradually decaying the weights and compensate for the loss of spectral correlation. Experiments are carried out on the Aurora-2 database, and frame-level cross entropy-based deep neural network (DNN-HMM) training is used to build an acoustic model. While given models trained on multi-condition speech data, the accuracy of our proposed feature extraction method achieves up to 98.14% in case of 10dB, 94.40% in 5dB, 81.67% in 0dB and 51.5% in -5dB, respectively.', 6, 'OPENALEX', '{"doi": "10.1109/o-cocosda50338.2020.9295006", "openalex": "https://openalex.org/W3115627977"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c43ff21a-154e-4eea-ad2e-5dea9eb8cb91', 'Implementing Design Thinking in The Development of Digital Signage User Interface for Public Health Education', NULL, 2022, '2022-09-07', 'Dhimas Aji Suryakusuma; Harisno Harisno; Arif Wicaksono; Rudy Hartanto; Sunu Wibirama', NULL, 'JOURNAL', '10.1109/icst56971.2022.10136306', 'https://doi.org/10.1109/icst56971.2022.10136306', 'Covid-19 may spread through public facilities-such as digital signage. Gaze-based touchless technology allows digital signage to be accessed without touching the screen. Previous works, however, merely focused on seamless interaction without rigorous consideration of user interface development. Here we report an implementation of Design Thinking-a user-centered design method-in development of digital signage user interface. We conducted a survey of over 200 participants for categorizing important topics related with Covid-19. Next, we defined and developed personas and user interface. The interface was deployed in a touchless digital signage equipped with a Tobii ET5 eye tracker. Finally, we evaluated the proposed user interface design in a real-time experiment. We asked the participants to complete two tasks through different modes of button-fast (300 pixels/s) and slow (150 pixels/s) moving button. Our experimental results show that the participants achieved 96.88% of average Task Completion Rate for both fast- and slow-moving button. Our study implies that the user-centered design provides a reliable scientific method to develop a more user-friendly interface. Even in a novel technology such as touchless digital signage, appropriate user interface design may provide enjoyable interaction between users and the digital signage.', 5, 'OPENALEX', '{"doi": "10.1109/icst56971.2022.10136306", "openalex": "https://openalex.org/W4378882089"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f3726a52-f0dc-4e44-8073-0a510236fd78', 'Improving Performance of Eye Movements Classification Using CNN-Transformer Model', NULL, 2023, '2023-11-14', 'Ahmad Riznandi Suhari; Rudy Hartanto; Sunu Wibirama', NULL, 'JOURNAL', '10.1109/icamimia60881.2023.10427836', 'https://doi.org/10.1109/icamimia60881.2023.10427836', 'In the past decade, eye tracking has been a crucial approach for object selection in digital assistive technology as well as touchless digital signage. Accurate object selection depends on performance of eye movements classification. Many deep learning techniques have been proposed for eye movements classification. Despite of these numerous models, previous approaches have yet to achieve high classficiation accuracy—particularly when dealing with smooth pursuit eye movement. To bridge this scientific gap and improve the effectiveness of eye movement classification, we propose a hybrid CNN-Transformer model. We also incorporated Hyperband hyperparameter tuning to obtain the best parameter values of the model. We evaluated our approach in the GazeCom dataset. This dataset was enhanced with customized annotations designed to accommodate different types of eye movements. Our method yielded F1 scores of 0.9572, 0.9273, and 0.8358 for fixation, saccade, and smooth pursuit eye movements, respectively. The proposed method achieved superior F1 scores by a margin of 1% to 12.36% compared with the state-of-the-art Temporal Convolutional Network (TCN). A significant improvement was observed in the classification of smooth pursuit eye movement. The experimental results imply that the proposed method can serve as a guide for implementing the Transformer models for eye movements classification.', 5, 'OPENALEX', '{"doi": "10.1109/icamimia60881.2023.10427836", "openalex": "https://openalex.org/W4391792732"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b992dd15-a383-4f6f-bc2d-22b176a492be', 'Spontaneous Gaze-Based Application Using 2D Correlation and Velocity Threshold Identification', NULL, 2021, '2021-11-24', 'Hafzatin Nurlatifa; Rudy Hartanto; Sunu Wibirama', NULL, 'JOURNAL', '10.1109/icicos53627.2021.9651863', 'https://doi.org/10.1109/icicos53627.2021.9651863', 'Demand for touchless technology has grown with the surge of Covid-19 pandemic. Spontaneous gaze-based application is one of several promising technologies for touchless interaction. Despite of this potential, little attention has been paid to the performance of traditional eye movements classification methods on improving accuracy of gaze-based object selection. To handle this research gap, we proposed a novel workflow of spontaneous gaze-based object selection using 2D Correlation as similarity measure and Velocity Threshold Identification (I-VT) as a method for eye movements classification. We compared our method with Pearson Product-Moment Correlation (PPMC) as similarity measure and Dispersion Threshold Identification (I-DT) for eye movements classification. Our experimental results showed that the proposed method yielded object selection accuracy up to <tex xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">$95.62 \%\pm 3.48\%$</tex> . In future, our proposed method can be implemented in the development of touchless interactive technologies that adhere to the World Health Organization guidelines, especially during the Covid-19 pandemic.', 4, 'OPENALEX', '{"doi": "10.1109/icicos53627.2021.9651863", "openalex": "https://openalex.org/W4200417521"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b297b3b5-19dd-478d-b2d3-0f914404227d', 'Restorasi Citra Dengan Tapis Wiener Adaptif', NULL, 1996, '1996-01-01', 'Rudy Hartanto', 'Media Teknik', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=8371', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W128398307"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3daf4d12-406f-4f9f-9e8b-8a7a48620d81', 'Energy-Efficient Multi-Unmanned Aerial Vehicle Path Planning: A Comparative Study of Random, Greedy, and Clustering Strategies', NULL, 2026, '2026-03-16', 'Muhammad Anif; Selo Sulistyo; I Wayan Mustika', 'International Journal of Computational Methods and Experimental Measurements', 'JOURNAL', '10.56578/ijcmem140103', 'https://doi.org/10.56578/ijcmem140103', NULL, 0, 'OPENALEX', '{"doi": "10.56578/ijcmem140103", "openalex": "https://openalex.org/W7137121350"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('417f59c9-22be-45ea-881b-9725710a61eb', 'A Study of Event Detection Methods in Eye-Tracking Based on Its Properties', NULL, 2020, '2020-09-07', 'Hafzatin Nurlatifa; Sunu Wibirama; Rudy Hartanto', NULL, 'JOURNAL', '10.1109/icst50505.2020.9732839', 'https://doi.org/10.1109/icst50505.2020.9732839', 'The eye is one of means of human and computer interaction. Naturally, someone will direct their gaze to interesting objects. Eye-tracking is a technology aimed at understanding the direction of human gaze. Event-detection is a process of detecting and classifying eye movements that are divided into several types. Various studies in the field of event detection play an essential role in improving the quality of eye-tracking technology. Discussion of research properties is important to see trends in event detection research and to introduce this research to new researchers. This paper reviews some properties used in eye-tracking research, especially in the field of event detection, including eye data, sampling frequency, types of video-based eye-trackers, types of stimulus, types of eye movements, and signal denoising. This paper also discusses the development of research over the past few years and the challenges faced in event detection research. This review paper can be a guide for new researchers who wish to continue research in the field of eye-tracking, especially event detection.', 4, 'OPENALEX', '{"doi": "10.1109/icst50505.2020.9732839", "openalex": "https://openalex.org/W4251153896"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9008842e-30bc-4a65-8588-2dee81982fc3', 'Improving Image Fidelity using Skip Connections Autoencoder', NULL, 2024, '2024-10-23', 'Atyanta Nika Rumaksari; Risanuri Hidayat; Rudy Hartanto', NULL, 'JOURNAL', '10.1109/icitee62483.2024.10808412', 'https://doi.org/10.1109/icitee62483.2024.10808412', 'This study presents an advanced autoencoder model with skip connections designed to enhance the image fidelity quality. Traditional methods often face challenges in preserving high-resolution details and textures, particularly in tasks involving noise reduction, super-resolution, and low-light enhancement. Our model leverages skip connections to maintain essential spatial information across different layers, effectively addressing the vanishing gradient problem and improving gradient propagation during training. We compare our model against several state-of-the-art methods, including the Overall Improved Autoencoder (OIAE), Cascade Decoders-Based Autoencoders, and Edge-Aware Autoencoder Design, evaluating performance based on Mean Squared Error (MSE), Peak Signal-to-Noise Ratio (PSNR), and Structural Similarity Index (SSIM). Our autoencoder consistently achieves superior results, with MSE of 5.889e-05, PSNR consistently above 40 dB, and SSIM close to 1. These findings demonstrate the significant advantages of incorporating skip connections, which allow for better retention of high-resolution features and more accurate image reconstructions.', 1, 'OPENALEX', '{"doi": "10.1109/icitee62483.2024.10808412", "openalex": "https://openalex.org/W4405845187"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0771df59-d277-4c55-aed0-449de067d7df', 'PENGUJIAN DAN EVALUASI BUKU INTERAKTIF AUGMENTED REALITY ARca 3D', NULL, 2014, '2014-02-08', 'Andria Kusuma Wahyudi; Ridi Ferdiana; Rudy Hartanto', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/267/255', 'Paper ini membahas tentang evaluasi dan pengujian dalam pembuatan ARca. ARca merupakan buku interaktif dalam pembelajaran candi Prambanan menggunakan augmented reality yang dilengkapi interaksi virtual button. Penelitian ini membahas pengujian dan evaluasi teknis dari aplikasi ARca yaitu pengujian pendeteksian, pengujian pelacakan, dan pengujian feature. Pengujian terdiri dari indentifikasi jarak, sudut, waktu pendeteksian dan luas area halaman buku untuk menampilkan augmented reality. Dari pengujian dan evaluasi ditemukanlah ukuran jarak, sudut, luas permukaan, dan kondisi ideal untuk penggunaan dan perancangan buku ARca. Hasil tersebut yang menjadi standar dalam penggunaan dan pengembangan buku ARca.', 8, 'OPENALEX', '{"openalex": "https://openalex.org/W2344864049"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5e613197-548d-4a09-a865-0305aba46ca9', 'Startup Learning Path (SLP): A Learning Model for Startup Employees Using Agile Learning Approach', NULL, 2019, '2019-12-01', 'Egi Endeska Putra; Ridi Ferdiana; Rudy Hartanto', 'Journal of Physics Conference Series', 'JOURNAL', '10.1088/1742-6596/1339/1/012095', 'https://doi.org/10.1088/1742-6596/1339/1/012095', 'Abstract The growth rate of startup numbers in Indonesia is very high due to the increase of people interest in the technology utilization, particularly Smartphone. However, more than 75% startup that has been increasing has experienced the failure. This is related to many factors, one of which is the lack of qualified Human Resources. This research aims to propose a learning model called Startup Learning Path (SLP), designed using agile methodology approach to be an alternative that can be used by startup to increase the quality of the employees’ competence in supporting the startup to realize the vision and mission.', 5, 'OPENALEX', '{"doi": "10.1088/1742-6596/1339/1/012095", "openalex": "https://openalex.org/W2994942110"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('764f58e2-8644-44c2-9c47-3e6e6de1e969', 'GenACO a multi-objective cached data offloading optimization based on genetic algorithm and ant colony optimization', NULL, 2021, '2021-09-28', 'Mulki Indana Zulfa; Rudy Hartanto; Adhistya Erna Permanasari; Waleed Ali', 'PeerJ Computer Science', 'JOURNAL', '10.7717/peerj-cs.729', 'https://doi.org/10.7717/peerj-cs.729', 'BACKGROUND: Data exchange and management have been observed to be improving with the rapid growth of 5G technology, edge computing, and the Internet of Things (IoT). Moreover, edge computing is expected to quickly serve extensive and massive data requests despite its limited storage capacity. Such a situation needs data caching and offloading capabilities for proper distribution to users. These capabilities also need to be optimized due to the experience constraints, such as data priority determination, limited storage, and execution time. METHODS: We proposed a novel framework called Genetic and Ant Colony Optimization (GenACO) to improve the performance of the cached data optimization implemented in previous research by providing a more optimum objective function value. GenACO improves the solution selection probability mechanism to ensure a more reliable balancing of the exploration and exploitation process involved in finding solutions. Moreover, the GenACO has two modes: cyclic and non-cyclic, confirmed to have the ability to increase the optimal cached data solution, improve average solution quality, and reduce the total time consumption from the previous research results. RESULT: The experimental results demonstrated that the proposed GenACO outperformed the previous work by minimizing the objective function of cached data optimization from 0.4374 to 0.4350 and reducing the time consumption by up to 47%.', 5, 'OPENALEX', '{"doi": "10.7717/peerj-cs.729", "openalex": "https://openalex.org/W3204824366"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('8c7fdf7e-8291-46a8-9523-04c47c422887', 'Perancangan Awal Antarmuka Gesture Tangan Berbasis Visual', NULL, 2012, '2012-01-01', 'Rudy Hartanto; Marcus Nurtiantoro Aji', NULL, 'JOURNAL', '10.22146/jnteti.v1i1.7', 'http://ejnteti.jteti.ugm.ac.id/index.php/JNTETI/article/view/7', 'Human computer interaction has a long history to become more intuitive. For human being, gesture of different kind is one of the most intuitive and common communication. However, vision-based hand gesture recognition is a challenging problem, which are involved complex computation, due to high degree of freedom in humand hand. In this paper we use hand gesture captured by web-cam instead of mice, for natural and intuitive human-computer interaction. Skin detections method is used to create a segmented hand image and to differentiate with the background. A contours and convex hull algorithm is used to recognize hand area as well as the number of finger tip of hand gesture image to be mapped with button. And for moving detection of hand gesture, the Lucas-Kanade pyramidal algorithm were used. The result shows that this system can operate well so we can interact with computer using our hand gesture instead using a mice. Hartanto1, Marcus Nurtiantoro Aji2 Interaksi antara komputer dan manusia telah mengalami sejarah yang panjang untuk dapat menjadi lebih intuitif. Bagi manusia, perubahan sikap merupakan salah satu bentuk komunikasi yang paling umum dan intuitif. Namun, pengenalan gerak tangan merupakan masalah yang cukup menantang, dimana membutuhkan perhitungan secara kompleks, akibat dari tingginya derajat kebabasan dari tangan manusia. Dalam paper ini digunakan penangkapan gerakan tangan menggunakan kamera web, untuk hubungan antara manusia dan komputer yang lebih alami dan intuitif. Metode deteksi kulit digunakan untuk membuat gambar tangan tersegmentasi dan dapat dibedakan dengan latar belakang. Algoritma hull digunakan untuk mengenali daerah tangan serta jumlah ujung jari gambar isyarat tangan untuk dipetakan dengan tombol. Lucas-Kanade piramidal algoritma selanjutnya digunakan untuk mendeteksi gerakan tangan yang bergerak. Hasil penelitian menunjukkan bahwa sistem ini dapat beroperasi dengan baik sehingga kita dapat berinteraksi dengan komputer dengan menggunakan gerakan tangan, tanpa perlu menggunakan tetikus.', 4, 'OPENALEX', '{"doi": "10.22146/jnteti.v1i1.7", "openalex": "https://openalex.org/W2395902765"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('98482254-3d19-414e-a099-5728ce87a9a7', 'Prototype of Student Attendance Application Based on Face Recognition Using Eigenface Algorithm', NULL, 2019, '2019-09-13', 'Tio Eko Prabowo; Rudy Hartanto; Sunu Wibirama', 'IJITEE (International Journal of Information Technology and Electrical Engineering)', 'JOURNAL', '10.22146/ijitee.46724', 'https://doi.org/10.22146/ijitee.46724', 'Prototype of face recognition based attendance application that has been developed to overcome weaknesses in DTETI UGM student manual attendance system has several weaknesses. These weaknesses are a decrease in facial recognition accuracy when operating under conditions of varying environmental light intensity and in condition of face rotating towards z axis rotation centre. In addition, application prototype also does not yet have a database to store attendance results. In this paper, a new application prototype has been developed using Eigenface face detection and recognition algorithm and Haar-based Cascade Classifier. Meanwhile, to overcome prototype performance weaknesses of the previously developed application, a pre-processing method was proposed in another study was added. Processes in the method were geometry transformation, histogram levelling separately, image smoothing using bilateral filtering, and elliptical masking. The test results showed that in the category of various environmental light intensity conditions, face recognition accuracy from developed application prototypes was 16.71% better than previous application prototypes. Meanwhile, in category of face slope conditions at z axis rotation centre, face recognition accuracy from developed application prototype was 38.47% better. Attendance database system was also successfully implemented and running without error.', 4, 'OPENALEX', '{"doi": "10.22146/ijitee.46724", "openalex": "https://openalex.org/W2973301741"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2a339587-c6c4-4415-99e6-0bb9e11fd3d9', 'The Interface Development of Hospital Information System Management Using Goal-Directed Design Method', NULL, 2019, '2019-07-01', 'Adhistya Erna Permanasari; Faroh Nur Alfani; Rudy Hartanto; Guntari Titik Mulyani', NULL, 'JOURNAL', '10.1109/iceei47359.2019.8988860', 'https://doi.org/10.1109/iceei47359.2019.8988860', 'Prof. Soeparwi Animal Hospital is one of the animal hospitals located in Yogyakarta. In its current operations, the administrative flow is still running manually using paper records. This study developed the interface of the administration system subsystem of the hospital. The development of this information system interface emphasized the user experience aspect using the goal-directed design method. The evaluation of user satisfaction was done using the questionnaire of user interface satisfaction (QUIS) method and presentation of the final results. This study developed the administration subsystem interface of Prof. Soeparwi Animal Hospital, which could meet user needs, business processes, and integration between the hospital''s subsystem. The interface evaluation resulted in a user satisfaction score of 8.1125 from the acceptance level of 5, the more efficient service flow, and it received a positive response for further development from the hospital management. Thus, it can be concluded that the interface succeeded in achieving the design goals through the goal-directed design method.', 4, 'OPENALEX', '{"doi": "10.1109/iceei47359.2019.8988860", "openalex": "https://openalex.org/W3005827653"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4cb0d9f3-ae39-4c3e-bc04-6d2a8847e113', 'Developer’s Perspectives on Unit Test Cases Understandability', NULL, 2021, '2021-08-20', 'Novi Setiani; Ridi Ferdiana; Rudy Hartanto', NULL, 'JOURNAL', '10.1109/icsess52187.2021.9522166', 'https://doi.org/10.1109/icsess52187.2021.9522166', 'Good unit testing plays the most important role when it comes to driving and evaluating software quality. However, writing effective tests is a very expensive and time-consuming practice. To reduce such load on developers, there are many different techniques for automatically generating test suites for an existing source code. However, how automatically generated test cases compare to manually written cases is an open research question. There are some understandability issues regarding autogenerated test cases. This paper presents an experiment based on A/B testing methodology to gather developer preferences at test cases presentation. This survey involved 44 developers from 17 country. It founds that majority developers prefer the manual written than automatic generated test cases. This result brings some new perspectives to improve the quality of the automatic generated test case.', 4, 'OPENALEX', '{"doi": "10.1109/icsess52187.2021.9522166", "openalex": "https://openalex.org/W3197208344"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('94af5600-430a-4021-8a1a-b91257a24b21', 'Towards Two-Step Fine-Tuned Abstractive Summarization for Low-Resource Language Using Transformer T5', NULL, 2025, '2025-01-01', 'Salhazan Nasution; Ridi Ferdiana; Rudy Hartanto', 'International Journal of Advanced Computer Science and Applications', 'JOURNAL', '10.14569/ijacsa.2025.01602120', 'https://doi.org/10.14569/ijacsa.2025.01602120', 'This study explores the potential of two-step fine-tuning for abstractive summarization in a low-resource language, focusing on Indonesian. Leveraging the Transformer-T5 model, the research investigates the impact of transfer learning across two tasks: machine translation and text summarization. Four configurations were evaluated, ranging from zero-shot to two-step fine-tuned models. The evaluation, conducted using the ROUGE metric, shows that the two-step fine-tuned model (T5-MT-SUM) achieved the best performance, with ROUGE-1: 0.7126, ROUGE- 2: 0.6416, and ROUGE-L: 0.6816, outperforming all baselines. These findings demonstrate the effectiveness of task transfer-ability in improving abstractive summarization performance for low-resource languages like Indonesian. This study provides a pathway for advancing natural language processing (NLP) in low-resource language through two-step transfer learning.', 1, 'OPENALEX', '{"doi": "10.14569/ijacsa.2025.01602120", "openalex": "https://openalex.org/W4408069284"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f19b9025-e008-48aa-baba-22e8741ce423', 'A Brief Study of The Use of Pattern Recognition in Online Learning: Recommendation for Assessing Teaching Skills Automatically Online Based', NULL, 2022, '2022-06-25', 'Pipit Utami; Rudy Hartanto; Indah Soesanti', 'Elinvo (Electronics Informatics and Vocational Education)', 'JOURNAL', '10.21831/elinvo.v7i1.51354', 'https://doi.org/10.21831/elinvo.v7i1.51354', 'Online learning has become a trend for the current generation of students who have been exposed to advanced information and communication technology. Smart education can use pattern recognition. Manual assessments are subjective and inconsistent. To overcome these problems, pattern recognition can be used in the non-verbal aspect assessment system. This study describes pattern recognition in online learning about the functions, modalities, and algorithms and specifically related to the recognition system of non-verbal aspects of teaching skills. The literature study was carried out through the stages of planning, selection, extraction, and selection. There are 86 articles reviewed. The first result is the functions of implementing pattern recognition in online learning are engagement recognition, attention detection, emotion recognition, learning behavior, learning activity recognition, authentication, teaching training, etc. using four classifications of modality: visual, audio, biosignal, behavioral, and CNN as the most widely used learning algorithm. Secondly, all modalities (except behavioral) and CNN algorithm can be used for assessing teaching skills. Early development of the non-verbal aspect assessment system can use Facial Expression Recognition (FER) and Hand Gesture Recognition (HGR). The future analysis needs to focus on technology characteristics, the meaningfulness of the content, and the proper teaching mode. In the end, hopefully, prospective teachers will acquire technology that can make it easier for them to practice teaching and get objective assessments.', 4, 'OPENALEX', '{"doi": "10.21831/elinvo.v7i1.51354", "openalex": "https://openalex.org/W4361758239"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6bb17bdb-4361-47b2-be44-351979a43fa1', 'Using Double-Density Dual Tree Wavelet Transform into MFCC for Noisy Speech Recognition', NULL, 2020, '2020-10-06', 'Hay Mar Soe Naing; Risanuri Hidayat; Rudy Hartanto; Yoshikazu Miyanaga', NULL, 'JOURNAL', '10.1109/icitee49829.2020.9271737', 'https://doi.org/10.1109/icitee49829.2020.9271737', 'The automatic speech recognition has gained significant progress in technology as well as in many applications. However, speech fluctuations due to noise effects significantly reduce recognition accuracy, and recognition on noisy channels is more difficult to generate correct word sequences than in a clean environment. Extracting meaningful acoustic information from noisy speech utterances has been a challenging task recently. Therefore, we present a combination of Mel frequency cepstrum coefficient (MFCC) and double-density dual tree wavelet transformation denoising algorithm to recognize noisy speech utterances. Hybrid frame-level cross entropy deep neural network-hidden Markov model (DNN-HMM) is used as an acoustic modeling activity. According to a suite of experiments, the proposed denoising method provides better performance without affecting the accuracy of higher sound intensity levels. Experimental results demonstrate that the recognition accuracy reach up to 96.6% in 10dB, 91.84% in 5dB, 78.05% in 0dB and 49.37% in -5dB, respectively.', 3, 'OPENALEX', '{"doi": "10.1109/icitee49829.2020.9271737", "openalex": "https://openalex.org/W3108739059"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1333e466-44ea-4923-bc9c-5e200c0cf239', 'East Nusa Tenggara Weaving Image Retrieval Using Convolutional Neural Network', NULL, 2021, '2021-12-16', 'Silvester Tena; Rudy Hartanto; Igi Ardiyanto', '2021 4th International Seminar on Research of Information Technology and Intelligent Systems (ISRITI)', 'JOURNAL', '10.1109/isriti54043.2021.9702843', 'https://doi.org/10.1109/isriti54043.2021.9702843', 'The popularity of East Nusa Tenggara (ENT) province is attributed to a variety of traditional woven fabrics with local cultural attributes. Each tribe in the province has its design and colors that differentiate the fabrics leading to diverse decorative motifs. Due to different varieties, it is challenging for users to know both the type of motif and its origins. In this research, several Convolutional neural network (CNN) architecture benchmarks were carried out for ENT weaving images retrieval. The image retrieval method was chosen for the study since it has feature extraction and similarity measurement, which make searching and selection relatively easier. Furthermore, the CNN method is often used for feature extraction due to its ability to recognize objects while hashing and hamming distance algorithms help reduce the computation time for similarity testing. This study was conducted by comparing several pre-trained CNN architectures, including VGG16, ResNet101, InceptionV3, and Discrete Wavelet Transform. The results showed that the highest accuracy is ResNet101 architecture with 100%, 88.50%, and 55% at top=1, top=5, and top=10, respectively. The pre-trained CNN model and Discrete Wavelet Transform combination provided better results in case the feature dimensions were above 16-bit. The feature dimensions are generally based on the best 6-bit hashing code, though they are computationally time-consuming.', 3, 'OPENALEX', '{"doi": "10.1109/isriti54043.2021.9702843", "openalex": "https://openalex.org/W4211110798"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4da493c5-585b-4c9f-8240-71a5c86bf740', 'Systematic Literature Review: Stock Price Prediction Using Machine Learning and Deep Learning', NULL, 2021, '2021-01-01', 'Grace Yoby Dopi; Rudy Hartanto; Silmi Fauziati', 'Advances in economics, business and management research/Advances in Economics, Business and Management Research', 'JOURNAL', '10.2991/aebmr.k.211117.008', 'https://doi.org/10.2991/aebmr.k.211117.008', 'This research was conducted using a literature review method to analyze various studies that will identify the type of analysis with the attributes used, the methods used, the methods most often used, and the methods that have the best performance. This study collected research from 2016 -July 2021, selected based on predetermined criteria and then collected 40 papers. This review found that there are four research topics, namely estimation, classification, clustering, and association. The findings of this study are four research topics, namely fundamentals, technicals, sentiment analysis, and even a combination of analyzes that use their respective attributes and datasets. There are thirty-one different methods found to be used in predicting stock prices. LSTM, MLP, RF, and SVM are the most widely used methods. In addition, MLP is a method that gives the best performance of 71.63% and LSTM of 70%. The use of combined machine learning methods with ensemble techniques, deep learning, and selection of input attributes in pre-processing is recommended for better accuracy.', 3, 'OPENALEX', '{"doi": "10.2991/aebmr.k.211117.008", "openalex": "https://openalex.org/W4212967865"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5e32a4f1-4753-4197-a0ec-30e87e40f9d7', 'Etika Di Sekitar Perawatan Lansia', NULL, 2008, '2008-07-01', 'Rudy Hartanto', 'Respons: Jurnal Etika Sosial', 'JOURNAL', '10.25170/respons.v13i01.393', 'http://ejournal.atmajaya.ac.id/index.php/respons/article/view/393', 'Abstract:  This article talks about ethical problem in medicine, mainly about the old people with alzhimer. Being old is not anyone choise, because it is a natural proccess of every living beings. Many people get alzhimer by the time they get older. The ethical question according to that matter, is it ethical for the doctor to revealed his diognose to the alzhimer patient. Since revealed the analized would make patiens become restless. All the problem discuss in this article. Kata Kunci:  Persoalan orang lanjut usia, Tua kronologis dan biologis, Alzhimer', 0, 'OPENALEX', '{"doi": "10.25170/respons.v13i01.393", "openalex": "https://openalex.org/W2916664834"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('73a48ff4-add8-4f20-8380-7109fc706bf6', 'Performance Comparison of Swarm Intelligence Algorithms for Web Caching Strategy', NULL, 2021, '2021-07-17', 'Mulki Indana Zulfa; Rudy Hartanto; Adhistya Erna Permanasari', NULL, 'JOURNAL', '10.1109/comnetsat53002.2021.9530778', 'https://doi.org/10.1109/comnetsat53002.2021.9530778', 'Web caching is one strategy that can be used to speed up response times by storing frequently accessed data in the cache server. Given the cache server limited capacity, it is necessary to determine the priority of cached data that can enter the cache server. This study simulated cached data prioritization based on an objective function as a characteristic of problem-solving using an optimization approach. The objective function of web caching is formulated based on the variable data size, count access, and frequency-time access. Then we use the knapsack problem method to find the optimal solution. The Simulations run three swarm intelligence algorithms Ant Colony Optimization (ACO), Genetic Algorithm (GA), and Binary Particle Swarm Optimization (BPSO), divided into several scenarios. The simulation results show that the GA algorithm relatively stable and fast to convergence. The ACO algorithm has the advantage of a non-random initial solution but has followed the pheromone trail. The BPSO algorithm is the fastest, but the resulting solution quality is not as good as ACO and GA.', 2, 'OPENALEX', '{"doi": "10.1109/comnetsat53002.2021.9530778", "openalex": "https://openalex.org/W3201352631"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('cbb11b91-8f91-4df9-8cde-0696bb9ea144', 'Optimization of Stock Predictions on Indonesia Stock Exchange: A New Hybrid Deep Learning Method', NULL, 2025, '2025-02-02', 'B. Yudi Dwiandiyanta; Rudy Hartanto; Ridi Ferdiana', 'Engineering Technology & Applied Science Research', 'JOURNAL', '10.48084/etasr.9363', 'https://doi.org/10.48084/etasr.9363', 'This study presents a new method for predicting stock prices on the Indonesia Stock Exchange (IDX) using a hybrid deep learning model. The proposed model combines historical price data, consisting of open, high, low, and close values, with technical indicators such as Moving Average (MA), Simple Moving Average (SMA), and Exponential Moving Average (EMA). The proposed model offered improved accuracy and efficiency using distinct architectures of Recurrent Neural Network (RNN) and Gated Recurrent Unit (GRU) to process the datasets. The results showed that the proposed hybrid model significantly outperformed traditional single-architecture models in terms of R2, achieving 0.98 for the BBCA stock, surpassing models using only RNN or GRU. In addition, comparable improvements were observed with additional equities, such as the PT. Bank Mandiri Tbk (BMRI) and PT. Bank Negara Indonesia Tbk (BBNI) stocks, achieving an R2 of 0.99, demonstrating the proficiency of the proposed model in capturing the complex dynamics of the stock market. The results demonstrated the significant potential of combining historical data and technical indicators into the modeling procedure to predict stock prices. This process can benefit investors and economic forecasters in the stock market. The results could be further expanded by classifying datasets and investigating different sets of models to improve the performance of financial forecasting.', 2, 'OPENALEX', '{"doi": "10.48084/etasr.9363", "openalex": "https://openalex.org/W4407079345"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0935de56-abcf-4d3b-84d9-a7a599f80f03', 'User-Centered Design on Metacognitive Training System: A Case in Algorithm and Data Structure Course', NULL, 2018, '2018-07-01', 'Indriana Hidayah; Teguh Bharata Adji; Noor Akhmad Setiawan; S. Fauziati; Rudy Hartanto; Mukhamad Angga Gumilang', NULL, 'JOURNAL', '10.1109/iciteed.2018.8534811', 'https://doi.org/10.1109/iciteed.2018.8534811', 'Metacognitive training system (MTS) is a computer-based learning system aimed at developing students'' metacognition. Metacognition is needed to develop students'' self-regulation which is required for learning complex topics such as algorithm and data structure (ADS). Previously, we develop an MTS to support algorithm-learning. However, the approach tends to be technology-centered, thus, producing low usability score. Therefore, this paper proposes an incorporation of user-centered design (UCD) into the development of the MTS to produce a more usable system. As a result, new information architecture, wireframe, and user interface design are obtained. Finally, the system usability testing is conducted to compare two versions of the MTS, i.e. older and newer version. The result shows that the newer version has higher usability scale. In addition, the newer version of the MTS shows a positive impact on a real learning situation, indicated by the significant difference on students'' performance between control and experiment group.', 4, 'OPENALEX', '{"doi": "10.1109/iciteed.2018.8534811", "openalex": "https://openalex.org/W2901976582"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('783fcfba-9b2a-4d38-9bf9-b2a1ab53a663', 'The Advantage of Augmented Reality Technology for Supporting Learning Media in Ethics Learning', NULL, 2021, '2021-09-18', 'Adhistya Erna Permanasari; Said Hirzi Hadi; Rudy Hartanto; Mahfud Sholihin', NULL, 'JOURNAL', '10.1109/icet53279.2021.9575114', 'https://doi.org/10.1109/icet53279.2021.9575114', 'Ethics is defined as a set of moral principles that distinguish what is right and what is wrong. The unethical actions referred to here are actions that violate the ethics that apply in the environment. To find out about ethical violations in society, ethical awareness is needed to determine what to do to deal with offenses committed by a person or a group. Ethics learning is needed to increase ethical sensitivity. One of the most effective learning media is using augmented reality (AR) technology. AR is a concept that blends virtual reality with real-world reality (AR), and it is a natural way to experience 3D objects and data. Virtual things in two dimensions (2D) or three dimensions (3D) tend to be organic and unified with the real world. The purpose of this study is to answer the question of whether simulation-based AR technology can improve learning effectiveness and increase ethical sensitivity in students by conducting studies of relevant studies.', 3, 'OPENALEX', '{"doi": "10.1109/icet53279.2021.9575114", "openalex": "https://openalex.org/W3208299889"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('dfaa99a0-c544-4db8-8a4f-b67d588eaa07', 'Review: Implementasi Holap Untuk Optimasi Query Sistem Basis Data Terdistribusi Dengan Pendekatan Algoritma Genetik', NULL, 2014, '2014-12-06', 'Rahmad Syaifudin; Selo Selo; Rudy Hartanto', 'JURNAL SISTEM INFORMASI BISNIS', 'JOURNAL', '10.21456/vol4iss3pp164-171', 'https://doi.org/10.21456/vol4iss3pp164-171', 'Distributed Database is one of database that is under control of the Database Management System (DBMS) was focused on storage devices are separated from one and another. Optimization data query on distributed database system not be separated from data processing methods that used. Then for fast query optimization this database need some required methods that can optimize it. Hybrid online analytical processing (HOLAP) or often to call Hybrid-OLAP is one of technology for optimization query on distributed database. Genetic Algorithm is one of algorithm for heuristic searching was based on the mechanisms of biological evolution. Process of genetic algorithm is combining a selection process, using a crossover operator and mutation to get the best solution. From the reviews about implementation HOLAP with Genetic Algorithm approach was expected being used as a basis research on HOLAP implementation for query optimization on distributed database with genetic algorithm approach. Keyword s : Query Optimization; Distributed database; HOLAP; OLAP; Genetetic algorithm.', 2, 'OPENALEX', '{"doi": "10.21456/vol4iss3pp164-171", "openalex": "https://openalex.org/W2291245908"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5dd68dec-f854-4ecb-8b94-9c7accae191c', 'Students’ Self-Monitoring Skill Classification in Learning Activities', NULL, 2020, '2020-01-01', 'Intan Sulistyaningrum Sakkinah; Rudy Hartanto; Adhistya Erna Permanasari', NULL, 'JOURNAL', '10.2991/assehr.k.200521.014', 'https://doi.org/10.2991/assehr.k.200521.014', 'Intelligent Tutoring System (ITS) provides personalized instruction based on the level of knowledge and learning preferences of students. At ITS, student modeling has an important role; the role of student modeling in ITS includes student knowledge that is used to produce lessons, problems, feedback, and personalized learning guidance. ITS has the potential to develop into metacognitive tools. One of the metacognitive strategies is self-monitoring. Self-monitoring is a metacognitive strategy that students possibly control their learning activities. Developing an ITS with metacognitive needs rules for the treatment. The rules in ITS are from the classification method. This study focuses on self-monitoring skill as the metacognitive strategy to develop ITS. This paper will provide a method which can classify students'' selfmonitoring skill. Bayesian network is used as a method to classify students'' self-monitoring in this research. The result shows that the Bayesian network can classify students'' selfmonitoring skill accurately. The accuracy result for the classification is 94%. The classification of self-monitoring skill can be used to develop metacognitive scaffolding in an ITS.', 2, 'OPENALEX', '{"doi": "10.2991/assehr.k.200521.014", "openalex": "https://openalex.org/W3026969088"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('831c8934-faea-4d26-9b2e-36e0dc03261d', 'Web Caching Strategy Optimization Based on Ant Colony Optimization and Genetic Algorithm', NULL, 2021, '2021-07-21', 'Mulki Indana Zulfa; Rudy Hartanto; Adhistya Erna Permanasari; Waleed Ali', NULL, 'JOURNAL', '10.1109/isitia52817.2021.9502260', 'https://doi.org/10.1109/isitia52817.2021.9502260', 'Web caching is a strategy that can be used to speed up website access on the client-side. This strategy is implemented by storing as many popular web objects as possible on the cache server. All web objects stored on a cache server are called cached data. Requests for cached web data on the cache server are much faster than requests directly to the origin server. Not all web objects can fit on the cache server due to their limited capacity. Therefore, optimizing cached data in a web caching strategy will determine which web objects can enter the cache server to have maximum profit. This paper simulates a web caching strategy optimization with a knapsack problem approach using the Ant Colony optimization (ACO), Genetic Algorithm (GA), and a combination of the two. Knapsack profit is seen from the number of web objects that can be entered into the cache server but with the minimum objective function value. The simulation results show that the combination of ACO and GA is faster to produce an optimal solution and is not easily trapped by the local optimum.', 2, 'OPENALEX', '{"doi": "10.1109/isitia52817.2021.9502260", "openalex": "https://openalex.org/W3191572751"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('75e886ad-1054-4068-81d2-089d0b093674', 'Wrapper Subset Feature Selection for Optimal Feature Selection in Epileptic Seizure Signal Classification', NULL, 2021, '2021-01-01', 'Inung Wijayanto; Rudy Hartanto; Hanung Adi Nugroho', 'Lecture notes in electrical engineering', 'BOOK_CHAPTER', '10.1007/978-981-33-6926-9_50', 'https://doi.org/10.1007/978-981-33-6926-9_50', NULL, 1, 'OPENALEX', '{"doi": "10.1007/978-981-33-6926-9_50", "openalex": "https://openalex.org/W3153790170"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('355a19c0-952d-45be-9224-d3ef395382e7', 'Modified Usability Test Scenario: User Story Approach to Evaluate Data Visualization Dashboard', NULL, 2021, '2021-06-18', 'Nurul Tiara Kadir; Rudy Hartanto; Selo Sulistyo', 'IJITEE (International Journal of Information Technology and Electrical Engineering)', 'JOURNAL', '10.22146/ijitee.61201', 'https://doi.org/10.22146/ijitee.61201', 'The data processing results are commonly displayed in a dashboard with various graphic visualization forms to deliver new knowledge easier to understand by users. However, many data analysis dashboards cannot communicate the knowledge effectively and efficiently given the unsuitable design implementation. Therefore, research to measure the interface display''s effectiveness in the data analysis system is deemed necessary. This research proposed a scenario modification in the usability test with a user story approach to measuring the system interface display in delivering the information to users. The approach of a usability test with the user story is expected to be capable of helping the researcher in understanding the user habits indirectly. There were 20 participants to validate the proposed method. Participants were asked to use the system and answer several questions to develop their user experience. After developing user experience for each user, the System Usability Scale (SUS) was conducted. SUS score results obtained from this research was 75.25. Besides, the researcher also measured the understanding level among the users using questionnaires. The questionnaire results were converted into numbers and resulted in a mean value of 91.8. Those two values indicate the users'' ability to use the system well and obtain the new knowledge displayed in the data analysis dashboard.', 1, 'OPENALEX', '{"doi": "10.22146/ijitee.61201", "openalex": "https://openalex.org/W3175812433"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('96118952-0487-473d-a14c-e87f174b4ff9', 'The Characteristics of Goat Milk Synbiotics-Yogurt using Lactobacillus plantarum as Probiotic and Inulin of Mangrove Apple (Sonneratia caseolaris)', NULL, 2022, '2022-01-01', 'Jeki Mediantari Wahyu Wibawanti; Sri Mulyani; Rudy Hartanto; Ahmad Ni’matullah Al–Baarri; Yoyok Budi Pramono; Anang Mohamad Legowo', 'Advances in Animal and Veterinary Sciences', 'JOURNAL', '10.17582/journal.aavs/2022/10.11.2457.2463', 'https://doi.org/10.17582/journal.aavs/2022/10.11.2457.2463', 'Yogurt has grown in popularity, and it is regarded as a healthy food due to its high levels of essential nutrients Many synbiotic-based foods have been developed, including yogurt products made from probiotics and oats (Lim, 2017), sorghum flour (Sukarminah et al., 2019), and monk fruit extract (Ban et al., 2020). Synbiotics are widely used in fermentation beverages because they improve beneficial bacteria and provide good nutrition in the gut Synbiotics are the combination of prebiotics and probiotics that has been formulated to stimulate the growth of microorganism They were developed to help probiotics survive in the gastrointestinal tract The synergistic activities of prebiotics and probiotics have had a greater impact on the effectiveness of gut microbiota than', 1, 'OPENALEX', '{"doi": "10.17582/journal.aavs/2022/10.11.2457.2463", "openalex": "https://openalex.org/W4312815487"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a039e48c-042c-4d16-9e53-58739d7a6a7b', 'Dunia Christina', NULL, 2023, '2023-06-25', 'Rudy Hartanto', 'Jurnal Online Dekonstruksi', 'JOURNAL', '10.54154/dekonstruksi.v9i03.171', 'http://dx.doi.org/10.54154/dekonstruksi.v9i03.171', 'Dua kunci sukses perupa representasional, yaitu mempunyai bakat observasi sehingga mereka akan diam, mengamati, dan melukis obyek tersebut sampai ke setiap rincinya. Dan sebuah penghayatan tertentu, serupa dengan seorang aktor yang sedang membawakan peran. Penghayatan ini mensyaratkan sebuah penyatuan tertentu antara sang subyek dan obyeknya. Karena tidak suka menggunakan kursi roda, Christina biasa ngésot menggunakan kekuatan bahu, lengan, dan panggulnya. Respons empatik Andy Wyeth terhadap hidup Christina yang sulit sebagai penyandang disabilitas, begitu kuat sampai ia menciptakan lukisan “Dunia Christina” yang kemudian dikoleksi oleh MOMA dan membuatnya terkenal.', 0, 'OPENALEX', '{"doi": "10.54154/dekonstruksi.v9i03.171", "openalex": "https://openalex.org/W4381950895"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('fc09ae85-8383-463a-a20a-965ceb02079d', 'Government product recommendation systems in e-Katalog: leveraging large language models with retrieval-augmented generation', NULL, 2025, '2025-03-01', 'Ayu Rosalina Wibowo; Silmi Fauziati; Rudy Hartanto', 'IET conference proceedings.', 'JOURNAL', '10.1049/icp.2025.0317', 'https://doi.org/10.1049/icp.2025.0317', 'Indonesia''s electronic catalog (e-Katalog) is a platform developed to facilitate government procurement, providing an extensive collection of products and services that simplifies purchasing processes, enhances transparency, and reduces costs. However, the exponential growth in the number of listed products has led to challenges such as information overload, complicating the selection process for buyers. E-katalog lacks the ability to effectively deliver personalized, context-aware recommendations that could further support procurement strategies. To address these challenges, this research aims to develop a product recommendation system for e-Katalog using large language models (LLMs) integrated with the Retrieval-Augmented Generation (RAG) framework. The goal is to provide contextual and relevant recommendations, prioritizing MSMEs and local products to support effective procurement decision-making by government institutions. This study compares three embedding models all-MiniLM-L6-v2, all-distilroberta-v1, and all-mpnet-base-v2, based on their effectiveness in product retrieval, with all-mpnet-base-v2 achieving the highest average similarity score of 0.72. This enabled the RAG-based system, powered by GPT-3.5 Turbo, to deliver more targeted and meaningful product suggestions, thereby effectively promoting local products and MSMEs.', 1, 'OPENALEX', '{"doi": "10.1049/icp.2025.0317", "openalex": "https://openalex.org/W4408157487"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1310e25f-19e4-4022-af88-d21be140e0f2', 'Multi-Objective Optimization for Disaster Evacuation using NSGA-II: A Case Study in Parangtritis', NULL, 2025, '2025-01-21', 'Cindy Inka Sari; Lukito Edi Nugroho; Rudy Hartanto', NULL, 'JOURNAL', '10.1109/icocseti63724.2025.11020422', 'https://doi.org/10.1109/icocseti63724.2025.11020422', 'Parangtritis, a popular tourist destination on the southern coast of Java, faces a high tsunami risk due to tectonic activity along nearby subduction zones. The main challenges in this area include a large number of tourists, vulnerable populations such as the elderly and disabled, and limited shelter capacity, which can lead to congestion during evacuation. To address these issues, this study proposes a multi-objective approach using the Non-dominated Sorting Genetic Algorithm II (NSGA-II) to support efficient and adaptive evacuation planning. The model optimizes five objective functions: evacuation distance, evacuation time, shelter capacity, congestion costs, and shelter distribution variance, while conducting sensitivity analysis to ensure solution stability. The implementation results show that NSGA-II effectively generates high-quality Pareto fronts, validated using hypervolume and Generational Distance (GD) metrics, and highlights trade-offs between evacuation objectives, offering data-driven insights for designing more efficient evacuation strategies in Parangtritis.', 1, 'OPENALEX', '{"doi": "10.1109/icocseti63724.2025.11020422", "openalex": "https://openalex.org/W4410987433"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2aeadfbb-6daf-4348-89bf-46cc5723fbfc', 'Complexity Based Multilevel Signal Analysis for Epileptic Seizure Detection', NULL, 2020, '2020-11-24', 'Inung Wijayanto; Rudy Hartanto; Hanung Adi Nugroho', NULL, 'JOURNAL', '10.1109/icoiact50329.2020.9331975', 'https://doi.org/10.1109/icoiact50329.2020.9331975', 'The electroencephalogram (EEG) signal is a signal produced by a complex biological system. Thus, a signal complexity analysis can be useful for analyzing the EEG signal. Many studies have shown the vast development of signal complexity analysis in the EEG. The most commonly used methods were the entropy and fractal dimension measurement. These methods were able to perform well in the epileptic EEG seizure detection system. They were suitable for time, frequency, and wavelet domain signal processing. The use of wavelet analysis, such as discrete wavelet transform (DWT) and wavelet packet decomposition (WPD), was quite famous. In many studies, the feature extraction process was performed in the DWT or WPD process sub-band signal. One of the developments of WPD was called as the multilevel wavelet packet entropy (MWPE), which produced less features than that of WPD. This study developed a new method based on WPE, which used signal complexity measurement at each level as in MWPE. The seizure detection process in this study was started with a channel selection method to reduce the processed channels. EEG signals from selected channels were then decomposed using a five-level of wavelet packet decomposition (WPD), producing 32 wavelet coefficients. The feature extraction process was performed using the entropy and fractal dimension for all 32 sub-bands, that were segmented using a ten-minute non-overlapping window. A support vector machine (SVM) was used to classify the feature set into a seizure and normal conditions. The system was evaluated using the CHBMIT EEG dataset, which was recorded from 24 patients having a total of 198 seizure events. The highest average accuracy of 91% was achieved by using multilevel wavelet higuchi fractal dimension (MWHF) analysis. This indicates that the use of fractal based measurement has a good opportunity to be implemented in epileptic seizure detection and prediction system.', 3, 'OPENALEX', '{"doi": "10.1109/icoiact50329.2020.9331975", "openalex": "https://openalex.org/W3128811140"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5b04b148-ce67-4353-b0d1-832851ae79b8', 'Pengembangan Aplikasi Konversi Representasi Not Balok Ke Not Angka Untuk Paduan Suara Campur', NULL, 2012, '2012-07-31', 'Lukas Chrisantyo; Rudy Hartanto; Lukito Edy Nugroho', 'Jurnal Informatika', 'JOURNAL', '10.21460/inf.2012.81.115', 'https://doi.org/10.21460/inf.2012.81.115', 'Beam notation is a notation that is officially used in the whole world as an intermediary to do musical communication. In Indonesia, notation that is more absorbed and mostly easy to learn autodidactly is numbered notation, while beam notation is more difficult to learn and tend to be avioded. Traditionally, beam notation can be converted to numbered notation by fully relying on human skills and abilities. It is obvious that the conversion process would require much time and energy. Therefore, a new conversion application is developed to cope the conversion from beam notation into numbered notation specally for mixed choir, with representated in a XML file called MusicXML. MusicXML is a representation of beam notation that are more easily to be compressed and has a universal characteristic, can be opened in a wide range of applications. The purpose of this research was to design a fast, reliable and accurate application to convert beam notation into numbered notation for mixed choir which consist of multiple voice parts, according to the prevailing theory of music. Kata-kunci: rekayasa perangkat lunak, konversi notasi musik, MusicXML', 2, 'OPENALEX', '{"doi": "10.21460/inf.2012.81.115", "openalex": "https://openalex.org/W1915109947"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('27ca33d9-0c40-460e-aa5a-3199b4f4c19c', 'Developer Payroll Approaches for Startup Environment Based on Agile Project Management', NULL, 2019, '2019-01-01', 'Yang Agita Rindri; Ridi Ferdiana; Rudy Hartanto', 'Procedia Computer Science', 'JOURNAL', '10.1016/j.procs.2019.11.100', 'https://doi.org/10.1016/j.procs.2019.11.100', 'Formulating developer payroll in a software development project is important for organizations to provide an equitable salary formulation that can motivate developers to work professionally. Payroll can also be used as references in planning the cost of software development projects in order to meet startup financial success. In the literature, developer payroll estimations can be obtained by multiplying the number of working hours on a project with the developer''s wage. However, multiplying the number of working hours with the developer''s wage is considered unfair because each developer has different competencies and performance. In addition, not much attention given to understanding how to estimate developer payroll in software development organizations by considering different competencies and performance. For those reasons, it is important to understand how to overcome the different developer''s competencies and performance in developer payroll formulation. Thus, the competency and performance factors can be formulated into the developer payroll. This paper proposes a method in calculating developer payroll for a startup environment based on Agile Project Management by considering the developer''s competency and performance parameters. The parameters consist of how many years developers have been working, what the type of developer role is, how many bugs developers produce and how many days developers are not able to complete the task on time. This study is expected to provide an alternative method to formulate developer payroll at startup environment.', 1, 'OPENALEX', '{"doi": "10.1016/j.procs.2019.11.100", "openalex": "https://openalex.org/W2997597494"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f4876716-1f21-4357-8004-103007a6efb1', 'Development and evaluation of a low cost music based exergame using microsoft kinect', NULL, 2016, '2016-10-01', 'Ricky Julianjatsono; Ridi Ferdiana; Rudy Hartanto', NULL, 'JOURNAL', '10.1109/iciteed.2016.7863261', 'https://doi.org/10.1109/iciteed.2016.7863261', 'Non-communicable Diseases (NCD) has become a worldwide problem. In 2012, 38 million or approximately 68% of deaths in the world are caused by NCD. The impacts caused by NCD are growing year after year. Physical inactivity is addressed as one of the main factors of NCD. Numerous efforts have been made to suppress its prevalence. Providing active game (exergame) is considered to be one of the most effective solutions. Even though there are some exergames that have been developed, there are still rooms for improvement. Thus, a new exergame called Beat-Beat Fitness (BBF) will be developed in this research. BBF contains several innovative features that likely enhance the psychophysiological impact to the players. The psychophysiological effect is measured using a questionnaire to observe the improvement created by BBF compared to several existing exergame. As the result, BBF has higher level of engagement than Kinect Dance Central. It also has higher usability level than Kinect Just Dance and Kinect Dance Central. Additional features proposed in this study are proven in increasing the psychophysiological effect of an exergame. The results of this study can be used as a reference for the development of incoming exergames.', 2, 'OPENALEX', '{"doi": "10.1109/iciteed.2016.7863261", "openalex": "https://openalex.org/W2592765110"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('558825af-516c-47db-b74c-ca3bfa74d1b8', 'Penyusunan Tata Kelola Keamanan Informasi pada Produksi Film Animasi (Kasus di PT. XX)', NULL, 2017, '2017-08-28', 'Ayu Candra Dewi; Eko Nugroho; Rudy Hartanto', 'Seminar Nasional Teknologi dan Informatika 2017', 'JOURNAL', NULL, 'https://www.neliti.com/publications/172691/penyusunan-tata-kelola-keamanan-informasi-pada-produksi-film-animasi-kasus-di-pt', 'Berjalannya perkembangan teknolgi informasi yang semakin maju dan pesat di era global ini, hal ini berpengaruh terhadap penggunaan teknologi informasi di kalangan Perusahaan swasta. PT. XX yang juga beketergantungan erat terhadap teknologi informasi dalam kegiatan produksi film animasi. Namun, permasalahan teknologi informasi yang berperan penting terhadap Perusahaan seringkali kurang mendapat perhatian. Akibatnya tidak dipungkiri akan muncul ancaman maupun kelemahan dalam teknologi informasi yang menganggu jalannya kegiatan produksi film animasi. Oleh karena itu diperlukannya pengelolaan teknologi informasi yang dituangkan dalam tata kelola untuk mengelola ancaman maupun kelemahan yang muncul. SNI ISO/IEC 27001:2005 merupakan framework sistem manajemen keamanan informasi yang dapat dijadikan dasar dalam pengelolaan informasi', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W2780854216"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c7e30930-7e0b-4e34-b8a4-d3d2e1f55cfb', 'API Design and Development for Developer Payroll in Startups Based on Agile Productivity Factors', NULL, 2019, '2019-07-01', 'Yang Agita Rindri; Rudy Hartanto; Ridi Ferdiana', '2019 5th International Conference on Science and Technology (ICST)', 'JOURNAL', '10.1109/icst47872.2019.9166252', 'https://doi.org/10.1109/icst47872.2019.9166252', 'Software startups are growing rapidly now. One of the important challenges faced by startups is how to formulate and calculate payroll for developers appropriately and easily that can satisfy both developers and startups. To help startups in calculating the developer payroll formulation appropriately and easily, a payroll application is required. However, developing a payroll application is not too easy and takes a lot of effort for startups. Especially for new startups that still do not have more resources in developing a payroll application. In this paper, Application Programming Interface (API) for developer payroll is designed and implemented based on agile projects. The API is designed based on the payroll calculation method that considers developer productivity parameters, i.e developer''s years of experience, type of roles, bug, and timeliness. API for developer payroll is expected to facilitate and ease the development of developer payroll information system by startups in need. This study designed and developed 7 Payroll REST API resources using ASP.NET Web API. The API testing is conducted using POSTMAN with 100% successful test results.', 2, 'OPENALEX', '{"doi": "10.1109/icst47872.2019.9166252", "openalex": "https://openalex.org/W3049620884"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1ca6d997-d97e-437b-918e-7a24295f5b05', 'Pengembangan Hypermedia Learning Environment (HLE) untuk Meningkatkan Self-Regulated Learning Berdasarkan Kemampuan Self-Monitoring', NULL, 2022, '2022-05-30', 'Intan Sulistyaningrum Sakkinah; Rudy Hartanto; Adhistya Erna Permanasari', 'Jurnal Nasional Teknik Elektro dan Teknologi Informasi (JNTETI)', 'JOURNAL', '10.22146/jnteti.v11i2.3480', 'https://doi.org/10.22146/jnteti.v11i2.3480', 'Penggunaan media pembelajaran saat ini telah berkembang pesat. Dewasa ini banyak penelitian yang menggunakan komputer sebagai media pembelajaran yang adaptif bagi mahasiswa; salah satu contohnya adalah hypermedia learning environment (HLE). Media HLE dikembangkan untuk membantu mahasiswa dalam belajar, misalnya pada situasi pandemi COVID-19 saat ini, yang mengharuskan semua aktivitas pembelajaran dilakukan secara daring (online). Salah satu bidang yang terkena dampak pandemi ini adalah bidang pendidikan, yaitu semua kegiatan pembelajaran dialihkan menjadi daring. Oleh karena itu, pembelajaran berbasis web HLE dapat membantu mahasiswa untuk tetap belajar dari rumah. HLE saat ini sedang dikembangkan untuk meningkatkan kemampuan mahasiswa dalam proses self-regulated learning (SRL). Ada komponen penting di dalam SRL, yakni self-monitoring. Namun, dalam perkembangannya, HLE yang dikembangkan tidak berbasis self-monitoring. Dalam penelitian ini, HLE adaptif dikembangkan berdasarkan kemampuan self-monitoring mahasiswa. Dalam pengembangannya, sistem HLE menggunakan metode pengembangan agile, yaitu Scrum. Pengumpulan data awal untuk klasifikasi mahasiswa dilakukan menggunakan self-regulatory inventory (SRI). SRI merupakan instrumen yang digunakan untuk mengukur kemampuan self-monitoring mahasiswa. Data kemudian diolah hingga dapat mengklasifikasikan siswa menjadi tiga kelas, yaitu high, medium, dan low. Hasil klasifikasi kemampuan siswa kemudian digunakan untuk mengembangkan bantuan pembelajaran pada HLE. Pengembangan bantuan yang disediakan adalah dalam bentuk teks dan video yang disesuaikan dengan tingkat self-monitoring mahasiswa. Dari hasil pengembangan, didapatkan bahwa semua fungsi HLE dapat berjalan dengan baik. Sistem diuji coba kepada dua belas mahasiswa untuk mengetahui tingkat usability dengan menggunakan system usability scale (SUS). Hasil menunjukkan kategori good, dengan skor 72,92. Untuk penelitian selanjutnya, dapat dilakukan implementasi pada mahasiswa dan mengukur keefektifan sistem yang telah dikembangkan.', 2, 'OPENALEX', '{"doi": "10.22146/jnteti.v11i2.3480", "openalex": "https://openalex.org/W4281747981"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9ad8da9a-70b5-4b0e-9eab-92426a2819fe', 'MANAJEMEN RISIKO KEAMANAN INFORMASI DENGAN MENGGUNAKAN METODE OCTAVE ALLEGRO DAN KONTROL ISO 27001 PADA INSTANSI PELAYANAN PENYELENGGARA PUBLIK', NULL, 2018, '2018-04-20', 'Surya Tri Atmaja Ramadhani; Rudy Hartanto; Eko Nugroho', NULL, 'JOURNAL', NULL, 'https://jurnal.teknikunkris.ac.id/index.php/SEMNASTEK/article/view/99', 'Informasi adalah aset yang sangat bernilai bagi Pemerintah. Informasi menjadi bahan dasar utama dalam proses perencanaan, pengoperasian, pengembangan, pemeliharaan dan pengambilan kebijakan agar kinerja organisasi lebih optimal. Aspek keamanan informasi sangat penting diperhatikan karena jika terjadi masalah keamanan informasi yang menyangkut kerahasiaan (confidentiality), keutuhan (integrity) dan ketersediaan (availability) maka kinerja tata kelola teknologi informasi dan komunikasi dapat terganggu. Pemerintah Kabupaten Kulonprogo membutuhkan perlindungan terhadap aset informasinya yang sebagian besar mengelola layanan informasi rahasia untuk tujuan melaksanakan e-government. Penelitian ini mengimplementasikan framework OCTAVE Allegro dan ISO 27001 untuk melakukan penilaian risiko terhadap aset informasi yang mendukung layanan teknologi informasi pada pemerintah kabupaten di Kulonprogo. Hasil akhirnya adalah kebijakan yang direkomendasikan oleh penelitian ini dapat mengarahkan organisasi untuk mempertimbangkan Sumber daya manusia dan layanan teknologi informasi yang digunakan.', 1, 'OPENALEX', '{"openalex": "https://openalex.org/W2953062778"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5217ba64-6d2a-40a5-9d8f-4cb4bb3a2bb4', 'PERANCANGAN SISTEM MANAJAMEN INSIDEN KEAMANAN INFORMASI BERDASARKAN SNI ISO/IEC 27035 DI INSTANSI PEMERINTAH', NULL, 2020, '2020-07-28', 'Wikankara; Rudy Hartanto; Lukito Edi Nugroho', 'Jurnal Teknologi Technoscientia', 'JOURNAL', '10.34151/technoscientia.v13i1.2927', 'https://doi.org/10.34151/technoscientia.v13i1.2927', 'The government services of information technology are required to always run optimally. On the other hand, many information services are still faced with security incidents. In terms of human resources, technology, policy, and procedural aspects, the focus problem has not been on security incidents of information. Therefore, we need information security incident management system as one of the system solutions that must be provided to ensure the sustainability of information services and IT systems. The purpose of this research is able to provide security information of incidents having a management system that was adopted and developed based on ISO/IEC 27035 standardization. The research methodology was carried out by using qualitative methods with case studies. The preparation of the document refers to the results of the assessment approach between the current conditions of business processes and the incident management of information security. It has been carried out with the clauses required by ISO/ IEC 27035. The results of this study are policy documents and procedures for the incident management systems of information security specifically designed as a reference standard in government. Finally, the use of structured policies and procedures can improve performance in handling incidents faced by the government.', 1, 'OPENALEX', '{"doi": "10.34151/technoscientia.v13i1.2927", "openalex": "https://openalex.org/W3210906892"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6f57f595-74dc-46c3-96fe-5226b86b4322', 'A New Benchmark Dataset for Indonesian Traditional Woven Fabric Image Recognition and Image Retrieval', NULL, 2022, '2022-08-25', 'Silvester Tena; Rudy Hartanto; Igi Ardiyanto', NULL, 'JOURNAL', '10.1109/icitacee55701.2022.9924111', 'https://doi.org/10.1109/icitacee55701.2022.9924111', 'This study aims to develop the TenunIkatNet dataset as one of the benchmarks for image recognition and retrieval problems, especially in Indonesian traditional fabrics. These are due to the present absence of the dataset for traditional fibers, especially the tenun ikat (woven) fabrics of East Nusa Tenggara (ENT). The TenunIkatNet dataset contains 120 types of fabric each being captured 40 times, leading to the collection of 4,800 original images at traditional shops and craftsmen. These shooting variations are often internally and externally carried out within the mini-studio box and another fabric background, before being hanged, and worn on the body. In this condition, the utilized Nikon D5600 camera produced 24 megapixels of RGB (red, green, blue) images, with the pre-processing and visual procedural application obtaining a 256x256 display according to the input feature extraction method. Furthermore, the data augmentation processes such as flipping, random rotating, zooming, and shear range, increased the number of images, with each type of tenun ikat fabric being randomly augmented by two images. This led to the production of 9,600 images based on the number of training datasets. Despite this, the testing and validation data were 960 images each. The TenunIkatNet dataset is expected to develop image recognition, classification, and retrieval algorithms, while also being useful for the preservation of local culture, as a knowledge base in the fields of education, crafts, and trade. In this report, two pre-trained Convolution Neural Network (CNN) methods with a transfer learning procedure, namely ResNet101 and DenseNet201. The results showed that the retrieval accuracy of two pre-trained models is 100% in the top-1. While the retrieval accuracy of DenseNet201 outperformed the ResNet101 method in the top-5 at 44.75% and 44.38%, respectively. Subsequently, the method had higher retrieval accuracy than ResNet101, although the query time was slower.', 1, 'OPENALEX', '{"doi": "10.1109/icitacee55701.2022.9924111", "openalex": "https://openalex.org/W4312681910"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4bf041ce-df68-4a61-ac9f-190a37ad03d1', 'Maqasid Sharia Index and Efficiency Indonesian Sharia Banking: Pre-Merger &amp; Post Merger', NULL, 2022, '2022-09-18', 'Riyang Mardini; Irena Paramita Pramono; Rudy Hartanto; Fathurahman Marshall Avicenna; Ilmawati Aranni; Rida Adinda', 'Kajian Akuntansi', 'JOURNAL', '10.29313/ka.v23i2.10183', 'http://dx.doi.org/10.29313/ka.v23i2.10183', 'This study aims to examine the impact of the merger of PT Bank Syariah in Indonesia Tbk on the level of efficiency and performance of Islamic finance in Islamic banking in Indonesia. The research period used is one year before the merger, and after the merger, in year 2019 and 2021 at Bank Umum Syariah Indonesia. This study uses a quantitative research model that uses secondary data in the form of quarterly financial reports obtained from the annual report. The data analysis used is a non-parametric approach Data Envelopment Analysis (DEA) and Maqasid Syariah Index (MSI) to measure the level of efficiency of the financial performance of the Islamic banking industry in Indonesia through three main categories of Ibn Ashur''s maqashid sharia developed by Abu Zahrah, namely tahdzib al-fard ( individual education), iqamah al-adl (justice) and maslahah (welfare). The result of this study show that Islamic Financial Performance and Efficiency Level have not shown a significant increase.', 1, 'OPENALEX', '{"doi": "10.29313/ka.v23i2.10183", "openalex": "https://openalex.org/W4324124895"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('cc692d86-edc0-4900-aedc-b017986e5e5c', 'Comparative Analysis of Masked and Unmasked for Face Recognition Using VGG Face and MTCNN', NULL, 2023, '2023-01-01', 'Hanif Sunarko; Risanuri Hidayat; Rudy Hartanto', NULL, 'JOURNAL', '10.4108/eai.5-10-2022.2327473', 'http://dx.doi.org/10.4108/eai.5-10-2022.2327473', 'Face recognition is a system that is widely used in various fields such as security, attendance system, and other fields. Currently Covid-19 is still a major problem around the world and almost everyone is protecting themselves with masks. This is a problem for the face recognition system. This hap', 1, 'OPENALEX', '{"doi": "10.4108/eai.5-10-2022.2327473", "openalex": "https://openalex.org/W4385278150"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('bde04ac6-16b7-49c4-80d0-6e6ce48b7439', 'AI-enabled Exit Strategy of Emergency Vehicle Preemption', NULL, 2023, '2023-10-26', 'Kunti Khoirunnisaa; Rudy Hartanto; I Wayan Mustika; Kuntpong Woraratpanya; Ika Arva Arshella', NULL, 'JOURNAL', '10.1109/icitee59582.2023.10317753', 'http://dx.doi.org/10.1109/icitee59582.2023.10317753', 'Emergency Vehicle Preemption (EVP) is a system employed by traffic lights to prioritize emergency vehicles, such as ambulances, fire engines, and police cars. This technology allows these vehicles to safely pass through crowded intersections by stopping traffic from other directions. However, it is essential to consider that preempting the regular traffic signal control could have implications for the safety and efficiency of both the prioritized emergency vehicle and the overall flow of regular traffic at the intersection. Research on EVP and Exit Strategy has been extensively developed and implemented in various commercial products, including the Trafficware 980 ATC V76 signal controller. Trafficware offers multiple EVP schemes and Exit Strategy modes that can be customized by traffic operators to suit their specific requirements. Studies have indicated that certain Exit Strategies perform optimally under specific traffic conditions. Yet, the complexity of traffic conditions poses a challenge for traffic operators to optimize the Trafficware''s performance by selecting the most effective Exit Strategy mode. To address this, Artificial Intelligence (AI) with Reinforcement Learning (RL) techniques used to improve the Trafficware 980 ATC V76 system. Particularly, the Exit to Fixed Phase strategy will be optimized, enabling Trafficware to dynamically choose the most suitable exit phase from the available four phases based on real-time traffic conditions. Implementing this optimization will replace the current fixed exit phase selection with a more adaptable and responsive approach, leading to improved traffic management and efficiency, ultimately resulting in reduced waiting times. The results show that the AI-enabled exit strategy can reduce the waiting time with the best performance up to 7.8% compared to no exit strategy. The Trafficware 980 ATC V76 has been upgraded with the ability to adjust signals based on policies to recover from congestion caused by preemption.', 1, 'OPENALEX', '{"doi": "10.1109/icitee59582.2023.10317753", "openalex": "https://openalex.org/W4388821467"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('898fb957-33f4-4a08-85e1-6d156c6669b9', 'Klasifikasi citra multispektral', NULL, 1998, '1998-01-01', 'Rudy Hartanto; M.Sc. Adhi Susanto', NULL, 'OTHER', NULL, 'https://repository.ugm.ac.id/41984/', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1264443133"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('655a6775-1e2e-44b7-b753-82efd61bdd9c', 'Indications of Tonsillectomy and Adenoidectomy in Dr. Hasan Sadikin General Hospital Bandung', NULL, 2015, '2015-03-01', 'Dini Atiyah; Agung Dinasti Permana; Rudy Hartanto', 'Althea Medical Journal', 'JOURNAL', '10.15850/amj.v2n1.447', 'https://doi.org/10.15850/amj.v2n1.447', 'Background : Tonsillectomy is the intervention to take out the palatine tonsils either whole or sub capsular, while adenoidectomy is the intervention of extraction of the adenoid gland which is commonly done with curettage method. Both interventions are done to eliminate repeated infections and also obstructions due to inflammation and hypertrophy of the tonsils and adenoids. This study was conducted to examine the indications of tonsillectomy and adenoidectomy in the Departement of Otorhinolaryngology and Head Neck Surgery Dr. Hasan Sadikin General Hospital Bandung in the period of January 2009–December 2011. Methods : A cross-sectional descriptive study was conducted in October–November of 2012 using 207 medical records of patients who had tonsillectomy and adenoidectomy executed in the Department of Otorhinolaryngology and Head Neck Surgery Dr. Hasan Sadikin General Hospital, Bandung in the period of January 2009–December 2011. Data collected were age, gender, main complaint, tonsil size, history of repeated infections, history of snoring as well as of Obstructive Sleep Apnea Syndrome (OSAS). The indication for tonsillectomy and adenoidectomy such as infection, obstruction and neoplasia was selected. Results : The indications of tonsillectomy and adenoidectomy were infection at 106 (51.2%) patients, obstruction at 100 (48.3%) patients, and neoplasia at 1 (0.05%) patient. Conclusions : The most numerous indications for tonsillectomy and tonsilloadenoidectomy in the Department of Otorhinolaryngology and Head Neck Surgery Dr. Hasan Sadikin General Hospital were infection. Keywords : Adenoid, adenoidectomy, indication, tonsil, tonsillectomy DOI : 10.15850/amj.v2n1.447', 0, 'OPENALEX', '{"doi": "10.15850/amj.v2n1.447", "openalex": "https://openalex.org/W1593863616"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6ba447ff-2ebf-44de-b1c3-f673b643b03e', 'REKONSTRUKSI TIGA DIMENSI (3D) RELIEF CANDI MENGGUNAKAN GAMBAR DUA DIMENSI (2D) TUNGGAL', NULL, 2013, '2013-12-05', 'Dedi Ary Prasetya; Indah Soesanti; Rudy Hartanto', NULL, 'JOURNAL', NULL, 'https://publikasiilmiah.ums.ac.id/bitstream/11617/4179/1/TE12_Dedi%20Ary%20Prasetya_UMS.pdf', 'Rekonstruksi tiga dimensi (3D) menggunakan satu gambar mempunyai keuntungan dimana gambar, dalam hal ini foto relief, lebih mudah didapatkan melalui berbagai sumber semisal dari website internet dan murah dibandingkan penggunaan 3D scanner. Obyek yang menjadi fokus dalam penelitian ini adalah gambar relief batu yang biasanya ada di atas dinding-dinding candi peninggalan masa kerajaan Hindu-Budha di Indonesia. Metode rekonstruksi 3D obyek relief candi ini menggunakan asumsi sederhana, yaitu berdasarkan gelap terang dari gambar. Pertama kali adalah proses memperoleh point cloud dari dengan cara: gambar dibuat menjadi grayscale lalu dikelompokkan berdasarkan tingkat keabuannya untuk kemudian diambil fiturnya menggunakan algoritma SIFT. Fitur yang dihasilkan lalu disusun secara bertingkat. Fitur paling gelap pada layer terbawah kemudian diberikan jarak tertentu untuk menempatkan tiap layer di atasnya . Point cloud ini lalu direkonstruksi menjadi sebuah obyek 3D dengan menghubungkan tiap titik yang ada menggunakan algoritma Ball-Pivoting untuk membentuk mesh 3D. Hasil rekonstruksi masih menunjukkan kekurangan, yaitu tidak semua permukaan dapat direkonstruksi sehingga muncul lubang-lubang, dan kedalaman relief masih kurang sesuai dengan relief aslinya. Saat diberikan tekstur memang nampak relief yang timbul namun bila diamati lebih detail beberapa bagian tidak sesuai dengan kedalaman yang sesungguhnya. Hal ini disebabkan karena fitur yang dimunculkan memang tidak bisa lengkap, tingkat kedalaman yang kurang sesuai, dan algoritma pembentukan mesh hanya bisa menjangkau titik-titik terdekat saja.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1803481705"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('314c23b3-8459-49a2-bfc9-6a676c63d723', 'PEMODELAN PENGENALAN PENANDA AUGMENTED REALITY DENGAN METAIO CREATOR', NULL, 2014, '2014-02-08', 'Yudi Setiawan; Ridi Ferdiana; Rudy Hartanto', 'SEMNASTEKNOMEDIA ONLINE', 'JOURNAL', NULL, 'https://ojs.amikom.ac.id/index.php/semnasteknomedia/article/download/1084/1050', 'Paper ini membahas pemodelan pengenalan penanda Augmented Reality (AR) yang dirancang dengan menggunakan Metaio Creator berbasis desktop, untuk memberikan informasi spesifikasi dari sebuah smartphone. Aplikasi ini bekerja dengan mengarahkan pc camera ke arah penanda, kemudian aplikasi akan memberikan informasi tambahan secara virtual mengenai smartphone tersebut. Informasi yang diterima oleh konsumen meliputi spesifikasi dan fitur unggulan smartphone. Pengujian dilakukan terhadap proses pengenalan penanda (natural printed AR marker) yang meliputi jarak jangkauan pengenalan penanda dan luas area penanda yang dapat dikenali oleh aplikasi AR. Hasil dari penelitian ini berupa jarak jangkauan yang baik antara penanda terhadap pc camera dan luas area penanda yang baik untuk ditangkap oleh pc camera. Sehingga user dapat mengetahui jangkauan dan luas area penanda yang baik dalam menjalankan aplikasi Augmented Reality.', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2471742459"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('59d9a8dc-89f4-4599-adff-3d19d6240c93', 'REKONSTRUKSI TIGA DIMENSI (3D) RELIEF CANDI MENGGUNAKAN SEGMENTASI GRAYSCALE CITRA DUA DIMENSI (2D) TUNGGAL', NULL, 2015, '2015-10-15', 'Dedi Ary Prasetya; Indah Soesanti; Rudy Hartanto', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/106298', 'Rekonstruksi tiga dimensi (3D) menggunakan satu citra mempunyai keuntungan dimana citra, dalam hal ini foto relief, lebih mudah didapatkan melalui berbagai sumber dan murah dibandingkan penggunaan 3D scanner. Obyek yang menjadi fokus dalam penelitian ini adalah citra relief batu yang biasanya ada pada dinding candi peninggalan masa kerajaan Hindu-Budha di Indonesia, yang direkonstruksi secara 3D dengan metode baru yang relative sederhana dalam mendapatkan kedalaman dan lekuk reliefnya dari sebuah citra dua dimensi (2D).INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('20e96444-f046-48a1-8d9a-4d75dbf8a733', 'SISTEM PENANGANAN EVENTLABORATORIUM BERBASIS WEB', NULL, 2010, '2010-01-01', 'Sulistyo Dwi Atmojo; Rudy Hartanto; Addin Suwastono', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12565', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2603603680"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('46167b96-554c-445a-8dba-48876dc25d62', 'Microsoft kinectを用いた低コスト音楽基づくexergameの開発と評価【Powered by NICT】', NULL, 2016, '2016-01-01', 'Julianjatsono Ricky; Ridi Ferdiana; Rudy Hartanto', 'IEEE Conference Proceedings', 'JOURNAL', NULL, 'https://jglobal.jst.go.jp/public/201702253602460851', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2743485714"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
