INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('bd775ea1-405f-48f6-a110-3d4d98bcd4dc', 'Anew static VAR compensator using SVC MERS for induction generator voltage controller', NULL, 2007, '2007-01-01', 'F. Danang Wijaya; Takanori Isobe; Kazuhiro Usuki; Jan Arild Wiik; Ryuichi Shimada', 'Journal of the Japan Institute of Power Electronics', 'JOURNAL', '10.5416/jipe2003.33.0_228', 'https://doi.org/10.5416/jipe2003.33.0_228', NULL, 0, 'OPENALEX', '{"doi": "10.5416/jipe2003.33.0_228", "openalex": "https://openalex.org/W2402673026"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('7b64f9b4-8a7b-40d7-9409-50fb8a809d8c', 'Analisis perilaku thermal motor induksi sangkar tupai yang menggunakan kendali kecepatan PWM inverter', NULL, 2001, '2001-01-01', 'F. Danang Wijaya; MT Ir. Hamzah Berahim', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/45577/', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2479557044"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d74c28ed-d114-4b8c-ace5-ad5f25a7592c', 'ANALISIS INVERTER SATU FASA PADA KONFIGURASI MASTER-SLAVE', NULL, 2016, '2016-09-03', 'Noviarianto Noviarianto; F. Danang Wijaya; Eka Firmansyah', 'Prosiding Sains Nasional dan Teknologi', 'JOURNAL', '10.36499/psnst.v1i1.1562', 'http://doi.org/10.36499/psnst.v1i1.1562', 'Inverter merupakan peralatan untuk mengkonversi sumber energi listrik DC menjadi AC. Sumber energi listrik dc diperoleh dari energi matahari dengan menggunakan panel surya. Pemilihan kapasitas daya inverter harus disesuaikan dengan sumber energi yang dihasilkan sehingga didapatkan daya dengan kapasitas yang optimal. Modul inverter dengan kemampuan kapasitas daya listrik yang relatif kecil merupakan salah satu alternatif. Walaupun kapasitasnya kecil modul inverter mempunyai sifat modular sehingga memungkinkan untuk dikembangkan. Beban listrik dengan kapasitas yang melebihi daya dari modul inverter dapat dilayani dengan cara memasang beberapa modul inverter secara paralel. Teknik master slave merupakan salah satu cara yangÂ dapat diterapkan pada proses paralel. Dengan menjadikan salah satu modul inverter sebagai master dan modul inverter yang lain terhubung sebagai slave. Simulasi dengan sofware menunjukkan bahwa teknik ini dapat membagi arus 60 â€“ 50%, kemampuan mengikuti perubahan beban yang cukup seragam dan steady state yang cepat tercapai dalam waktu 10 ms. Kata kunci: inverter,Â master-slave, paralel inverter, THD', 0, 'OPENALEX', '{"doi": "10.36499/psnst.v1i1.1562", "openalex": "https://openalex.org/W2558582370"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c0fbea81-b4ca-486d-a23b-b598ec3ccad8', 'Studi Alokasi Biaya Berbasis Kurva Beban Pelanggan PT PLN (persero) Tabun 2010 Sebagai Dasar Penentuan Tarif Listrik', NULL, 2010, '2010-01-01', 'Moh. Imamuddin S.S; F. Danang Wijaya; Avrin Nur Widiastuti', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12542', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2603374038"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
