INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b565ea94-bf77-49b8-abd7-2e90187bdbcd', '風力エネルギー変換システムのための粒子群最適化を用いた最大電力点追跡の動的応答【Powered by NICT】', NULL, 2016, '2016-01-01', 'Daud Pribadi Kukuh; F. Danang Wijaya; Sarjiya Sarjiya', 'IEEE Conference Proceedings', 'JOURNAL', NULL, 'http://jglobal.jst.go.jp/public/201702241374094881', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2747794387"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('291bd343-f765-4d2a-952b-f53f0ffd0bf7', '311/100V,1kW位相シフトフルブリッジDC‐DCコンバータにおける0電圧スイッチングを達成するための2高周波変圧器設計の比較【Powered by NICT】', NULL, 2016, '2016-01-01', 'Toni; F. Danang Wijaya; Firmansyah Eka', 'IEEE Conference Proceedings', 'JOURNAL', NULL, 'http://jglobal.jst.go.jp/public/201702264960065359', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2751711649"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4050bc5a-0e57-4eb4-aba3-86cf71d76190', 'Design optimization of Quasi-flat linear PM generator for wave energy converter in south coast of Java using flower pollination algorithm', NULL, 2017, '2017-08-01', 'Budi Azhari; F. Danang Wijaya; Muhammad Rifa''i Putra Sugita; Kukuh Daud Pribadi', NULL, 'JOURNAL', '10.1109/inaes.2017.8068569', 'https://doi.org/10.1109/inaes.2017.8068569', 'South coast of Java has been highly preferred as the placement location of wave energy converter, due to its relatively huge energy potential. Furthermore, linear permanent magnet generator (LPMG) has became one of the popular methods to convert wave energy to electrical energy. Based on the shape of stator core, there are several models of LPMG. Quasi-flat LPMG is one of them, which has rectangular stator core shape. In this paper, the quasi-flat LPMG would be designed and optimized. The design considered wave characteristics in the south coast of Java. Meanwhile, the optimization was performed to minimize resulted copper loss for equal output power. To achieve the optimization goal, flower pollination algorithm (FPA) was used. This algorithm continuously adjusts several geometrical parameter of the LPMG by certain mechanism until the objective function is met. The results showed that the optimization could reduce the resulted copper loss of about 71.95%. It also increased the electrical efficiency from 83.2% to 95.28%.', 0, 'OPENALEX', '{"doi": "10.1109/inaes.2017.8068569", "openalex": "https://openalex.org/W2763187841"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4195e4f7-043b-48b8-b37e-1c6e887285c6', 'Microhydro Power in West Papua: A Comprehensive Assessment as a Potential Replacement for Diesel Generators', NULL, 2024, '2024-01-01', 'Elias Kondorura Bawan; F. Danang Wijaya; Husni Rois Ali; Juan C. Vásquez', 'International Journal of Renewable Energy Research', 'JOURNAL', '10.20508/ijrer.v14i4.14534.g8953', 'https://doi.org/10.20508/ijrer.v14i4.14534.g8953', 'F ossil fuel-based sources of energy in both transition and developed countries are still the main primary contributor s to the environmental carbon footprint . In Indonesia, West Papua province remains to depend largely on diesel generators as its primary source of electrical energy, rather than renewable energy sources. This occurs due to multiple socio-techno-economic factors, e.g. limited research for renewable energy potential, lack of public understanding of renewable energy benefits, and a shortage of national commitment. In this article, a thorough analysis of micro hydro power potential to electrify a typical development area in West Papua is provided in order to address the abovementioned research challenge s . The study introduces a method for determining the potential of micro hydropower in West Papua based on evapotranspiration, flow duration curve, and plant capacity factor . In this sense , Penman and F.J Mock approaches are proposed in order to calculate the evapotranspiration value and to calculate the discharge quantity respectively . In addition, a reliable discharge analysis will be conducted , which requires temperature, humidity, rainfall, solar radiation, and wind speed data . Thirty rivers have the potential the capacity to be used as micro-hydro generator facilities. Based on monthly data from 2012 to 2021, a micro-hydro power potential of 4,769.97 kW with an estimated annual energy production of 13,956.09 MWh to serve a demand of 25,087.02 kWh/year is calculated. Hydropower energy can save around 7,815.4 million CERs. Local governments can construct micro-hydro power plants in distant locations to replace diesel power plants, or a hybrid system to improve service quality.', 0, 'OPENALEX', '{"doi": "10.20508/ijrer.v14i4.14534.g8953", "openalex": "https://openalex.org/W4406038160"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
