INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5c313a16-972a-4282-831b-a79a51fdea3f', 'AUTOMATISASI PENGISIAN CAIRAN TERPROGRAM KEDALAM TIGA BEJANA TERPISAH BEDA UKURAN BERBASIS SENSOR ULTRASONIK DENGAN MIKROKONTROLER ATMEGA 32', NULL, 2010, '2010-01-01', 'Ain Sahara; Adhi Susanto; Addin Suwastono', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12587', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2601899987"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('794f52b7-395d-4459-9db9-589be4104a0f', 'KENDALl AKSES PINTU RUANGAN DENGAN RFID BERBASIS MIKROKONTROLER ATMEGA32', NULL, 2010, '2010-01-01', 'Ajeng Swasti Fisnaeni; Priyatmadi; Addin Suwastono', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12588', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2602541031"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('790ad751-5f3f-4233-9d28-d4ee038a0808', 'PENGEMBANGAN ASSEMBLER UNTUK ARSITEKTUR PROSESOR GAMA32 BERBASIS PYTHON', NULL, 2019, '2019-01-01', 'Fathin Luqman Tantow; Agus Bejo; Addin Suwastono', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/168463', 'Laboratorium Teknik Digital DTETI FT UGM tengah mengembangkan sebuah model prosesor dengan arsitektur 32-bit yang dinamai GAMA32. Pengembangan prosesor ini berada pada tahap verifikasi model. Proses verifikasi model memerlukan program yang harus dibuat secara manual dalam kode mesin (biner), sehingga proses tersebut membutuhkan waktu yang lama serta rentan terjadi kesalahan. Untuk mempermudah pembuatan program untuk proses verifikasi perlu dibuat sebuah assembler. Assembler adalah program yang dapat menerjemahkan program tekstual menjadi instruksi biner. Instruksi biner dibutuhkan prosesor untuk menjalankan operasi yang diinginkan. Penelitian ini bertujuan untuk merancang assembler yang dapat membantu pengembangan prosesor khususnya dalam proses verifikasi. Assembler yang dibuat diuji kemampuan penerjemahan dari bahasa assembly menjadi kode mesin dari arsitektur prosesor GAMA32. Kode mesin yang dihasilkan lalu dijalankan dalam model prosesor GAMA32. Hasil pengujian pada semua variasi instruksi menunjukkan bahwa assembler berhasil menerjemahkan kode assembly yang ada menjadi kode mesin arsitektur prosesor GAMA32.
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0159162e-d24c-4556-b07f-e2f968870bab', 'Perancangan dan Implementasi Cyclic Redundancy Check – 16 sebagai Metode Error Checking pada Transmisi Pesan Protokol Modbus Remote Terminal Unit Berbasis Microcontroller Unit', NULL, 2016, '2016-03-11', 'Arief Wisnu Wardana; Eka Firmansyah; Addin Suwastono', 'Jurnal Nasional Teknik Elektro', 'JOURNAL', '10.20449/jnte.v5i1.189', 'https://doi.org/10.20449/jnte.v5i1.189', 'This paper presents about the Cyclic Redundancy Check – 16, a generator polynomial for error detection, which is normally used in MODBUS Remote Terminal Unit. It starts with explaining the noise phenomena that are often generated into a useful signal when it is transmitted through a noisy channel. Some types of error which usually affects bits of a transmitted data bytes are introduced. The complete method for designing a good generator polynomial for detecting the error is then presented. Next, Cyclic Redundancy Check -16 as an example of generator polynimial is discussed. The explanation includes method for software implementation of the CRC. Two methods are introduced which are loop – driven method and table - driven method. Finally, result of designed generator polynomial is shown, which consists of the algorithm and the routine example. The CRC -16 routine is then tested using some MODBUS messages.Keywords - Noise, generator polynomial, Cyclic Redundancy Check, MODBUS Remote Terminal Unit, lood – driven, table – driven, algorithm.Abstrak-Paper ini membahas tentang Cyclic Redundancy Check – 16, sebuah generator polynomial untuk mendeteksi error, yang biasanya digunakan pada MODBUS Remote Terminal Unit. Diawali dengan penjelasan tentang fenomena derau yang biasanya menyertai sebuah sinyal utama ketika sinyal tersebut ditransmisikan melalui sebuah kanal berderau. Beberapa tipe error yang biasanya mempengaruhi bit bit dari byte data yang ditransmisikan kemudian dijelaskan. Metode lengkap untuk mendesain sebuah generator polynomial untuk mendeteksi error kemudian dipaparkan. Selanjutnya, Cyclic Redundancy Check – 16 sebagai sebuah contoh generator polynomial dibahas. Pembahasan meliputi metode untuk implemenrasi software dari CRC tersebut. Dua metode diperkenalkan yaitu metode loop – driven dan metode table – driven. Pada bagian akhir, ditunjukkan hasil dari generator polynomial yang dirancang, yang terdiri dari algoritma nya dan salah satu contoh rutin programnya. Rutin CRC – 16 tersebut kemudian dites dengan menggunakan beberapa pesan MODBUS. Kata Kunci - Noise, generator polynomial, Cyclic Redundancy Check, MODBUS Remote Terminal Unit, lood – driven, table – driven, algorithm', 0, 'OPENALEX', '{"doi": "10.20449/jnte.v5i1.189", "openalex": "https://openalex.org/W4238847196"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d82eb20c-7aa2-451c-a90d-9512d743bb49', 'Monitoring and Control System for Building Application Using Modbus Remote Terminal Unit Protocol with AVR at Mega Family Microcontroller Unit', NULL, 2016, '2016-04-30', 'Arief Wisnu Wardhana; Eka Firmansyah; Addin Suwastono', 'Zenodo (CERN European Organization for Nuclear Research)', 'JOURNAL', '10.5281/zenodo.3274825', 'https://zenodo.org/record/3274825', 'This paper presents the design of a monitoring and control system that will be installed in buildings and used as a building management system for monitoring dan controlling mechanical and electrical devices embedded in the building. The system implements the master slave RS485 multidrop configuration. The system hardware consists of sensor, controller, and actuator. Arduino board with AT Mega series microcontroller unit (MCU) is used as controller. MCU’s ADC will be used as sensor. MODBUS remote terminal unit is used as protocol and implemented inside the master and slave progam inside the MCU. At the end of this paper, the result of transmission with various baud rate setting, various cable length, multiple message frames and are presented.', 0, 'OPENALEX', '{"doi": "10.5281/zenodo.3274825", "openalex": "https://openalex.org/W4299860847"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('81903178-798b-4c1a-adbb-b263ddf19c07', 'IMPLEMENTASI DATA FORWARDING SERVER DALAM PENGELOLAAN DATA UGM COCOA TEACHING AND LEARNING INDUSTRY, BATANG, JAWA TENGAH', NULL, 2024, '2024-06-30', 'Enas Dhuhri Kusuma; Addin Suwastono; Della Yesmin Pebrianto', 'RISTEK Jurnal Riset Inovasi dan Teknologi Kabupaten Batang', 'JOURNAL', '10.55686/ristek.v8i2.170', 'http://dx.doi.org/10.55686/ristek.v8i2.170', 'UGM Cocoa Teaching and Learning Industry (CTLI) merupakan pabrik milik UGM yang berfokus pada pengolahan biji kakao yang terletak di Kabupaten Batang, Jawa Tengah. Selain itu, CTLI juga memiliki peran sebagai badan riset dan inovasi dengan tujuan menemukan pengetahuan dan terobosan teknologi baru dalam industri kakao. CTLI dalam melakukan pengolahan biji kakao telah menggunakan mesin berteknologi tinggi sehingga data – data pada mesin dapat terekam. Pada awal berdirinya, CTLI berlangganan layanan Mindsphere dari Siemens untuk melakukan pengumpulan dan manajemen data sehingga data dapat tersimpan dengan baik pada database pabrik. Tetapi saat ini, CTLI memberhentikan langganan Mindsphere sehingga data produksi tidak dapat tersimpan ke dalam database. Dalam rangka mengatasi masalah tersebut, digunakanlah protokol komunikasi OPC UA untuk mendapatkan data dari sistem pabrik dan meneruskan data tersebut menggunakan Node-RED yang kemudian disimpan ke dalam database pabrik. Database ini bersifat lokal yang tersimpan di PC CTLI sehingga untuk mengakses dari jarak jauh dapat dilakukan menggunakan Anydesk. Data yang telah tersimpan dalam database dapat digunakan untuk melakukan pengembangan maupun optimalisasi operasional CTLI di kemudian hari.', 0, 'OPENALEX', '{"doi": "10.55686/ristek.v8i2.170", "openalex": "https://openalex.org/W4400172975"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2cce84f4-33b1-4b0c-bd65-14f1da739c93', 'Optimal Sizing and Placement of Wind-Based Distributed Generation to Minimize Losses Using Flower Pollination Algorithm', NULL, 2018, '2018-11-06', 'Dian Budhi Santoso; Sarjiya Sarjiya; Fredi Prima Sakti', 'JTERA (Jurnal Teknologi Rekayasa)', 'JOURNAL', '10.31544/jtera.v3.i2.2018.167-176', 'https://doi.org/10.31544/jtera.v3.i2.2018.167-176', 'Penempatan DG dapat mempengaruhi aliran daya dan tegangan pada bus di sistem distribusi. Oleh karena itu, penempatan DG harus diperhitungkan dan direncanakan secara detail agar dapat bekerja secara optimal. Penempatan DG yang tidak optimal dapat meningkatkan losses pada sistem, sehingga berpengaruh terhadap profil tegangan yang akan menurun. Penempatan dan kapasitas DG yang optimal dapat berpengaruh kepada peningkatan profil tegangan, mengurangi losses, peningkatkan kapasitas distribusi, dan peningkatkan keandalan pada sistem. Beberapa metode optimisasi banyak yang bermunculan mulai dari optimisasi klasikal, pendekatan analitis, sampai yang terbaru yaitu metaheuristik. Salah satu metode optimisasi metaheuristik terbaru adalah Flower Pollination Algorithm (FPA) yang merupakan metode optimisasi yang terinspirasi dari proses penyerbukan bunga. FPA lebih efisien dengan menghasilkan hasil yang lebih baik dan memiliki kecepatan konvergen yang lebih tinggi jika dibandingakan dengan metode metaheuristik lainnya. Pada penelitian ini, FPA digunakan untuk menentukan lokasi dan kapasitas wind-based DG yang optimal dengan single DG dan multi DG untuk meminimalkan rugi-rugi daya pada sistem tes IEEE 33-bus dan meningkatkan profil tegangan. Untuk mengetahui kinerja dari FPA, akan dibandingkan dengan metode optimasi lain. Selain itu, jumlah dan kapasitas wind-based DG yang dipasang pada bus terpilih akan diperhitungkan. Hasil simulasi menunjukkan bahwa metode yang diusulkan telah berhasil dengan baik menentukan lokasi dan kapasitas DG.', 16, 'OPENALEX', '{"doi": "10.31544/jtera.v3.i2.2018.167-176", "openalex": "https://openalex.org/W2899652708"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('fa0965ea-a023-4804-8b32-d385a8dbf705', 'Review of HVDC technologies for weak grid interconnectors', NULL, 2024, '2024-10-07', 'Roni Irnawan; Rian Fatah Mochamad; Filipe Faria da Silva; Qi Zhang; Sarjiya Sarjiya; Claus Leth Bak; Evy Haryadi', 'Electrical Engineering', 'JOURNAL', '10.1007/s00202-024-02761-6', 'https://doi.org/10.1007/s00202-024-02761-6', 'HVDC has experienced substantial growth in utilization globally, attributable to its superior capacity for transmitting large amounts of power relative to its HVAC counterpart and its increasingly competitive pricing. Voltage source converter technology, a variant of HVDC, is particularly well suited for transferring bulk offshore power, whether in point-to-point or multiterminal configurations. Most existing HVDC connections function as interconnections between strong AC grids or between strong and weak/islanded AC grids. However, with the expanding use of distant offshore generation, the establishment of energy islands, and the electrical interconnection of archipelagic nations such as Indonesia, the potential arises for HVDC to link two weak AC grids or even a weak and very weak AC grid. This paper provides a comprehensive review of various HVDC technologies appropriate for such connections, focusing on converters, cables, and circuit breakers. It also offers a technological and methodological assessment of HVDC reinforcement for interconnecting weak AC grids. Furthermore, the paper examines HVDC applications concerning control strategies optimized for weak grid interconnections. Finally, it presents case studies of HVDC implementations for weak grid interconnections in Indonesia.', 11, 'OPENALEX', '{"doi": "10.1007/s00202-024-02761-6", "openalex": "https://openalex.org/W4403194633"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a1cd4847-1043-4388-bca8-50e22d4b5598', 'A comparative study of PID, ANFIS and hybrid PID-ANFIS controllers for speed control of Brushless DC Motor drive', NULL, 2013, '2013-11-01', 'Hidayat Hidayat; Sasongko Pramonohadi; Sarjiya Sarjiya; Suharyanto Suharyanto', NULL, 'JOURNAL', '10.1109/ic3ina.2013.6819159', 'https://doi.org/10.1109/ic3ina.2013.6819159', 'This paper presents a comparative study of various controllers for the speed control of Brushless Direct Current Motor (BLDCM) to improve a performance of control. The most commonly used controller for the speed control of BLDCM is Proportional Integral Derivative (PID) controller. However, the PID controller has advantages such as: a good response, the simple structure and robustness of method, but it has disadvantages such as: optimally tuning gains of PID have been quit difficult and it cannot adapt a non-linier state of plant. Further, ANFIS controller has the ability to automatically learn and adapt with a state of plant. A novel hybrid controller that combines the advantages of PID controller and ANFIS controller is desired to improve the response of plant. To model of BLDCM is used an identification system method. Simulation results are presented and analyzed for all the controllers. It is observed that hybrid PID-ANFIS based controllers give better responses than PID or ANFIS for the speed control of BLDCM drive.', 30, 'OPENALEX', '{"doi": "10.1109/ic3ina.2013.6819159", "openalex": "https://openalex.org/W2547514297"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e2b406dd-e809-4167-b36f-0bc08aae3a43', 'Maximum penetration determination of variable renewable energy generation: A case in Java–Bali power systems', NULL, 2020, '2020-08-29', 'Tumiran; Lesnanto Multa Putranto; Sarjiya Sarjiya; Eko Yudo Pramono', 'Renewable Energy', 'JOURNAL', '10.1016/j.renene.2020.08.048', 'https://doi.org/10.1016/j.renene.2020.08.048', NULL, 24, 'OPENALEX', '{"doi": "10.1016/j.renene.2020.08.048", "openalex": "https://openalex.org/W3082933947"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d08e9b1d-4216-447e-9900-209845ce0f95', 'Generation expansion planning with a renewable energy target and interconnection option: A case study of the Sulawesi region, Indonesia', NULL, 2023, '2023-07-01', 'Sarjiya Sarjiya; Lesnanto Multa Putranto; Tumiran; Rizki Firmansyah Setya Budi; Dwi Novitasari; Deendarlianto Deendarlianto', 'Renewable and Sustainable Energy Reviews', 'JOURNAL', '10.1016/j.rser.2023.113489', 'https://doi.org/10.1016/j.rser.2023.113489', NULL, 24, 'OPENALEX', '{"doi": "10.1016/j.rser.2023.113489", "openalex": "https://openalex.org/W4382877043"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('791a8ead-0ca2-4214-a0b1-d5cea0cd498d', 'Modeling of high uncertainty photovoltaic generation in quasi dynamic power flow on distribution systems: A case study in Java Island, Indonesia', NULL, 2024, '2024-01-05', 'Jimmy Trio Putra; Sarjiya Sarjiya; M. Isnaeni Bambang Setyonegoro', 'Results in Engineering', 'JOURNAL', '10.1016/j.rineng.2023.101747', 'https://doi.org/10.1016/j.rineng.2023.101747', 'Integrating uncertainties associated with photovoltaic (PV) generation is an important aspect used to ensure the planning and operation of power distribution systems. Therefore, this research proposed an uncertainty model for PV generation by combining the methods of change point detection, cyclic k-means clustering (KMC), Monte Carlo simulation (MCS) with freedman diaconis estimator (FDE), and KMC with soft-dynamic time warping (DTW). Firstly, a seasonal split was performed using change point detection techniques and cyclic KMC to identify shifts in global horizontal irradiance (GHI) points. Secondly, the uncertainty of the GHI was generated using MCS for each season and the FDE method to optimize the number of bins of the data distribution. Finally, the PV generation curve from MCS was simplified through KMC with the soft-DTW metric, which facilitated a more straightforward representation of a PV profile. The impact of PV profile integration on quasi-dynamic power flow was tested on an IEEE 33 Bus system. The voltage profile on the feeder significantly impacted the PV integration, specifically during hours when high PV power is produced. For instance, at 11:00 a.m., voltage values on buses 18, 17, and 33 increased from 0.933, 0.934, and 0.935, respectively, to 0.982, 0.980, and 0.972. Similarly, with the value of power losses, the greater the PV power profile produced at a certain hour, the smaller the losses generated. The experimental results of the uncertainties PV model proposed in this research indicated that changes in electrical parameters change over time according to the input PV power profile produced.', 24, 'OPENALEX', '{"doi": "10.1016/j.rineng.2023.101747", "openalex": "https://openalex.org/W4390607398"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2e1fb1b5-3836-4550-a6ff-30fd25575b89', 'Long-Term Generation Expansion Planning in Sulawesi Electricity System Considering High Share of Intermittent Renewable Energy Resource', NULL, 2019, '2019-10-01', 'Ahmad Ahmad Muthahhari; Lesnanto Multa Putranto; Sarjiya Sarjiya; Faqih Shokhib Anugerah; Adi Priyanto; Suroso Isnandar; Ira Savitri', NULL, 'JOURNAL', '10.1109/iciteed.2019.8929948', 'https://doi.org/10.1109/iciteed.2019.8929948', 'To fulfill electrical energy needs and ensure the sustainability of development in some area, generation expansion planning (GEP) is required. GEP optimizes the number, type, time and capacity of the generating units during a specified time horizon for fulfilling the demand. The optimization procedure is to minimize total cost under some technical constraints. In this paper, Long Term GEP in Sulawesi electricity system is determined considering the intermittent of renewable energy. Considering intermittent renewable energy in GEP, renewable energy proportion can increase by 9.77% to 19.32% and reduce coal energy from 75.19% to 61.67% in 2050. Another aspect is the environmental benefit of the system which the annual emission reduces from 45.8 million tons to 42 million tons. Moreover, the reserve margin increases from 42.57% to 65.3%, which make the average electricity generation costs increase from Rpl,OS6. 04/kWh to Rpl,124. 29/kWh.', 17, 'OPENALEX', '{"doi": "10.1109/iciteed.2019.8929948", "openalex": "https://openalex.org/W2996582242"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2da81560-163b-49ab-b95c-aa9ee11951d8', 'Environmental Considerations in Long-Term Generation Expansion Planning with Emission Limitations: An Analysis of the Sulawesi Power System in Indonesia', NULL, 2020, '2020-09-23', 'Ahmad Adhiim Muthahhari; Lesnanto Multa Putranto; Sarjiya Sarjiya; Tumiran; Faqih Shokhib Anugerah; Adi Priyanto; Suroso Isnandar; Ira Savitri', NULL, 'JOURNAL', '10.1109/fortei-icee50915.2020.9249863', 'https://doi.org/10.1109/fortei-icee50915.2020.9249863', 'One of the problems faced by most countries in the world is ensuring energy security and climate change issues at the same time. Generation expansion planning (GEP) that considers the environmental aspect is required. GEP needs to consider CO <inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emission production to ensure energy and environmental sustainability in the future year. In this paper, Long-Term GEP performed with variable renewable energy (VRE) and emission limitation to achieve Indonesian Government emission reduction target mentioned in RUPTL document. This paper uses the Sulawesi power system as a study case to perform the Long-term GEP. Considering the emission limit in the GEP, the renewable energy mix is increased and meet the Indonesian government’s target for 31% renewable energy mix in 2050. The renewable energy mix increased from 26.57% to 32.39% in 2050. With those energy mixes, the average CO <inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emission reduces from 41.96 Mtons to 27.04 Mtons. The limitation of CO <inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emission produces a higher total cost. Total costs increase from 113,107 million dollars to 129,074 million dollars while considering the environmental aspect.', 16, 'OPENALEX', '{"doi": "10.1109/fortei-icee50915.2020.9249863", "openalex": "https://openalex.org/W3101825899"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('eb89c46b-d269-47fa-8ab1-993f840caa33', 'Role of the energy-carbon-economy nexus and CO2 abatement cost in supporting energy policy analysis: A multi-scenario analysis of the Java-Bali system', NULL, 2023, '2023-09-15', 'Sarjiya Sarjiya; Lesnanto Multa Putranto; Rizki Firmansyah Setya Budi; Dwi Novitasari; Deendarlianto Deendarlianto; Tumiran', 'Renewable and Sustainable Energy Reviews', 'JOURNAL', '10.1016/j.rser.2023.113708', 'https://doi.org/10.1016/j.rser.2023.113708', NULL, 14, 'OPENALEX', '{"doi": "10.1016/j.rser.2023.113708", "openalex": "https://openalex.org/W4386767555"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('18f2ba20-6667-43fa-9d70-48757e773097', 'Study of rooftop PV hosting capacity in 20 kV systems in facing distributed generation penetration', NULL, 2024, '2024-07-11', 'M. Isnaeni Bambang Setyonegoro; Roni Irnawan; Lesnanto Multa Putranto; Eka Firmansyah; Wijaya Yudha Atmaja; N. Adi; Zaenal Arifin; R. Linggar Gusti; D. Prastianto; Sarjiya Sarjiya', 'Results in Engineering', 'JOURNAL', '10.1016/j.rineng.2024.102517', 'https://doi.org/10.1016/j.rineng.2024.102517', '---With the increasing request for integrating rooftop photovoltaic (PV) systems into the distribution grid, it is crucial to prevent the potential negative impacts of high PV penetration. Considering the uncertainty and variability characteristics of high rooftop PV penetration, a stochastic approach for determining PV hosting capacity (HC)—the maximum capacity of a PV system to receive electricity from the power distribution network before the network reaches an operating limit violation—is necessary. Therefore, this study proposes calculating PV hosting capacity using the Monte Carlo simulation. Unlike previous works, this paper uses real feeders as case studies, representing both urban and rural areas. The feeder representing an urban area with many industrial and business customers has a higher hosting capacity, 31 % of full load, compared to the feeder representing rural areas, which has 18 % of full load. By using actual feeders that represent urban and rural areas, more representative results for specific problems can be achieved without assuming urban and rural feeders have the same specific problems.', 10, 'OPENALEX', '{"doi": "10.1016/j.rineng.2024.102517", "openalex": "https://openalex.org/W4400553107"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('117f6f11-c5d5-42ba-b3c9-e3a0857c7a62', 'A systematic literature review of optimal placement of fast charging station', NULL, 2024, '2024-10-23', 'Jimmy Trio Putra; M. Isnaeni Bambang Setyonegoro; Taco Niet; Sarjiya Sarjiya', 'e-Prime - Advances in Electrical Engineering Electronics and Energy', 'JOURNAL', '10.1016/j.prime.2024.100818', 'https://doi.org/10.1016/j.prime.2024.100818', 'Electric vehicles (EV) have increased in the last few decades due to their ability to reduce greenhouse gas emissions (GHG). Support for the electrification of the transportation sector has encouraged researchers to investigate the optimal placement of fast charging stations (FCS). In this study, we conducted a systematic literature review of 84 primary studies between 2019 and 2024 by identifying objective function and solution techniques, uncertainty, stakeholders, and network classification. We identified the objective functions most commonly used by authors related to technical and cost-solving problems using techniques: conventional (41.7%), metaheuristic (33.3%), hybrid (22.6%), and other (2.4%). Several researchers have also considered various uncertainty parameters from EV, FCS demand, and distributed generation (DG) power output with the most popular probabilistic method to solve problems. Furthermore, the role of stakeholders and network classification is also reviewed in this article. Our study contributes to the field by providing a comprehensive overview of the most significant journals and highlighting future research on the optimal placement of FCS. Future work must focus on improving parameters, models, methods, and using real data from various factors related to FCS demand. • A systematic literature review of problem formulation and optimization methods of FCS. • Overview of uncertainty parameters and modeling techniques of FCS demand. • Reviewing stakeholders and network classification of FCS. • Identifying journals related to FCS placement using PRISMA and Bibliometrix.', 5, 'OPENALEX', '{"doi": "10.1016/j.prime.2024.100818", "openalex": "https://openalex.org/W4403680888"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5d04ef9e-2db0-417a-af74-daaf6709a1fb', 'Long-term Electricity Demand Forecasting of Sumatera System Based on Electricity Consumption Intensity and Indonesia Population Projection 2010-2035', NULL, 2015, '2015-04-01', 'Suhono; Sarjiya Sarjiya; Sarjiya; Sarjiya', 'Energy Procedia', 'JOURNAL', '10.1016/j.egypro.2015.03.277', 'https://doi.org/10.1016/j.egypro.2015.03.277', 'An important step in energy management especially in electricity planning is demand forecasting. A simple model is presented using LEAP (Long-range Energy Alternative Planning System) as a tool and Sumatera systems as a case study. It aims to be easy to understand and applicable. Electricity demand in household sector is calculated based on data of population, household size, electrification ratio and electricity intensity. On the other hand, electricity demand in non-household sector is calculated as a product of number of customers and its electricity intensity. The base year is 2010 and 2025 is the end of forecasting period. The result shows that electricity demand in Sumatera system would be increase more than seven times compared to base year value. A comparative study was also carried out.', 26, 'OPENALEX', '{"doi": "10.1016/j.egypro.2015.03.277", "openalex": "https://openalex.org/W393105729"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('db40c23a-df41-4acc-b656-c6ed68ade234', 'A Bayesian Approach for RF-Based Indoor Localisation', NULL, 2007, '2007-10-01', 'Widyawan Widyawan; Martin Klepal; Dirk Pesch', NULL, 'JOURNAL', '10.1109/iswcs.2007.4392316', 'https://doi.org/10.1109/iswcs.2007.4392316', 'The proliferation of Wireless LAN and Wireless Sensor Network make the technologies become an attractive proposition for indoor localisation. Both technologies have provided communication infrastructure and hence RF-based localisation with WLAN and WSN becomes a software-only solution. WLAN-based localisation generally provides room accuracy, therefore sensor data fusion with WSN is proposed when better location accuracy is needed. This paper will describe a Bayesian approach for indoor localisation. A suboptimal sequential Bayesian method of Particle Filter combined with Map Filtering technique is used for sensor data fusion between WLAN and WSN. The location system performance also will be evaluated.', 37, 'OPENALEX', '{"doi": "10.1109/iswcs.2007.4392316", "openalex": "https://openalex.org/W2141089953"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6e68906d-7121-4615-b24c-9eb5816f888d', 'Optimal Sizing and Siting of PV-Based Distributed Generation for Losses Minimization of Distribution using Flower Pollination Algorithm', NULL, 2019, '2019-07-01', 'Tegar Arifin Prasetyo; Sarjiya Sarjiya; Lesnanto Multa Putranto', '2019 International Conference on Information and Communications Technology (ICOIACT)', 'JOURNAL', '10.1109/icoiact46704.2019.8938424', 'https://doi.org/10.1109/icoiact46704.2019.8938424', 'Distributed Generation (DG) installation in the distribution system aimed to reduce power losses, increase the voltage profile, and increase the amount of power supplied. One DG that can be implemented is based on photovoltaic (PV). The stochastic PV characteristics will cause ups and downs of the power produced. When the power generated is greater than the load downstream, it will potentially cause the power flow to be two-way. The method for determining the placement location and optimal DG capacity is needed so that the effect of PV penetration on changes in power flow and voltage profile is still within the permissible limits.This study proposed the FPA algorithm to determine the optimal location and DG capacity to reduce power losses in the distribution system with a case study of distribution network in Semanu Substation, Gunung Kidul Yogyakarta. The findings confirmed that the FPA method can be used to determine the placement location and optimal DG capacity of 9.501 MW, with active power losses after DG having decreased by 68.75%, and reactive power losses of 61.40%.', 22, 'OPENALEX', '{"doi": "10.1109/icoiact46704.2019.8938424", "openalex": "https://openalex.org/W2998135534"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('900d0597-20df-4712-9ddc-34127702b922', 'Hosting Capacity Improvement Using Reactive Power Control Strategy of Rooftop PV Inverters', NULL, 2019, '2019-08-01', 'Wijaya Yudha Atmaja; Sarjiya Sarjiya; M. P. Lesnanto; Eko Yudo Pramono', NULL, 'JOURNAL', '10.1109/sege.2019.8859888', 'https://doi.org/10.1109/sege.2019.8859888', 'Since on-grid rooftop photovoltaic (PV) installation is rapidly growing, and the interconnection requests of a new rooftop PV installation are still increasing, the improvement of PV hosting capacity of large-scale rooftop PV penetration needs to be studied. In this paper, the strategy to improve PV hosting capacity using reactive power control of PV inverters is provided. Since the load demand and PV output vary with the time, the results are provided in time-series. Monte Carlo based method is constructed to model the random nature of PV penetration concerning PV size and location. Furthermore, an evaluation study is provided to obtain the appropriate PV power factor setting of which the PV hosting capacities are the highest. Firstly, several possible settings of PV power factor are constructed to conduct an evaluation study of reactive power control scenarios. Secondly, the best setting is chosen concerning the ability for generating the highest PV hosting capacity. In addition, a case study is provided to assess the best setting presented by the evaluation study. The results show that rooftop PV penetration with lagging power factor setting of PV inverters generates higher PV hosting capacity compared to rooftop PV penetration with unity power factor setting, with an improvement rate of 96%.', 20, 'OPENALEX', '{"doi": "10.1109/sege.2019.8859888", "openalex": "https://openalex.org/W2979425166"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('511c0720-1220-417a-94b6-e2a0c446a773', 'Achieving New and Renewable Energy Target: A Case Study of Java-Bali Power System, Indonesia', NULL, 2020, '2020-09-15', 'Sarjiya Sarjiya; Rizki Firmansyah Setya Budi; Lesnanto Putra Multanto', NULL, 'JOURNAL', '10.1109/spies48661.2020.9242984', 'https://doi.org/10.1109/spies48661.2020.9242984', 'New and renewable energy (N&RE) become alternative energy to reduce the dependency on fossil energy in the power sector. However, many countries have encountered obstacles in the process of reducing dependency. The obstacles that arise are very specific depending on the conditions of the country. Therefore, the strategies are taken by each country also different. An example is in Indonesia. Indonesia’s National Energy Policy (NEP) has a mandate to achieve N&RE target of 23% in 2025 and 31% in 2050. Because of the unique characteristic of Indonesia, the strategies to achieve these targets differ from other countries. This research used the Java-Bali power system in Indonesia as a case study to find the strategies. A generation expansion planning (GEP) by considering alternative strategies to achieve the target in Java-Bali has been conducted. This research used the MoMANI-OSeMOSYS as a GEP model. Three scenarios have been developed: business as usual (BAU), renewable energy (RE), and new and renewable energy (N&RE) scenario. The results show that the implementation of the N&RE target causes the generation cost increase and the CO <inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emission decrease. Achieving the N&RE target requires the role of nuclear energy.', 17, 'OPENALEX', '{"doi": "10.1109/spies48661.2020.9242984", "openalex": "https://openalex.org/W3097890624"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('bd718d79-0c9b-4662-a718-7972b44593fd', 'Transmission Expansion Planning for the Optimization of Renewable Energy Integration in the Sulawesi Electricity System', NULL, 2021, '2021-09-21', 'Tumiran; Lesnanto Multa Putranto; Roni Irnawan; Sarjiya Sarjiya; Adi Priyanto; Suroso Isnandar; Ira Savitri', 'Sustainability', 'JOURNAL', '10.3390/su131810477', 'https://doi.org/10.3390/su131810477', 'In order to meet the growth in demand and the renewable energy integration target, the Sulawesi Electricity System (SES) should be expanded. Currently, the SES is divided into two systems, namely South and North Sulawesi. These two systems have different characteristics, such as the system size, reliability and operational cost. North Sulawesi is smaller, weaker and more expensive than the South System. In order to improve the system reliability, generation and transmission expansion planning should be executed simultaneously to meet the economical investment cost and satisfy the reliability standard. For this purpose, the necessity of a backbone system with a higher voltage level than the existing 150 kV system should be considered, including the interconnection option between the two existing systems in Sulawesi. A methodology based on economic and technical criteria was developed to determine the backbone voltage level. Two voltage level options were considered, namely 275 and 500 kV. Several criteria were considered in order to determine the backbone voltage level, including the economic voltage, the line-loading limit, N-1 contingency, short circuiting, transient stability, voltage stability and small signal stability. The backbone voltage candidates should fulfil all of the criteria. The simulation was conducted in base- and high-demand scenarios, considering the fluctuation of future economic growth. The load flow and the dynamic analysis were simulated in a DIgSILENT Power Factory environment. The results showed that the 275 kV backbone, which was built in 2022, would violate three criteria: the economic voltage, N-1 contingency and voltage stability. On the other hand, the 500 kV backbone voltage level fulfills all of the criteria. The result of this research was considered in the electricity planning documents in Sulawesi. From a technical and economical perspective, the 500 kV backbone was chosen for the SES.', 17, 'OPENALEX', '{"doi": "10.3390/su131810477", "openalex": "https://openalex.org/W3201446830"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('edb87911-ab6e-4991-843e-765fd0dfe044', 'Transient Stability Assessment of Large Scale Grid-Connected Photovoltaic on Transmission System', NULL, 2018, '2018-03-01', 'Muammar Zainuddin; Sarjiya Sarjiya; Tri Pratiwi Handayani; Wahri Sunanda; Frengki Eka Putra Surusa', NULL, 'JOURNAL', '10.1109/icgea.2018.8356270', 'https://doi.org/10.1109/icgea.2018.8356270', 'The purpose of this study is to measure the transient stability of large scale grid-connected photovoltaic in transmission line. This research used a transient stability analysis to measure the stability of the power angle stability, frequency stability, voltage stability, active power response, reactive power response of the synchronous generator and critical clearing time. It analyzed during the occurrence of the three-phase short-circuit interruption and the change in PV system power injection. This simulations was conducted in four conditions namely a system without PV and systems with solar radiation intensity 1000 W/m <sup xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</sup> , 700 W/m <sup xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</sup> and 500 W/m <sup xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</sup> respectively. The study used a large test system representing of the Gorontalo Province interconnection as a case study. The simulation results showed that the higher intensity of solar radiation resulted in the higher the stability of transient influence in the electrical transmission system.', 13, 'OPENALEX', '{"doi": "10.1109/icgea.2018.8356270", "openalex": "https://openalex.org/W2800363928"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('13b9a7a8-4454-4808-a7c5-6f7a629e2c6b', 'Minimization of Power Losses through Optimal Placement and Sizing from Solar Power and Battery Energy Storage System in Distribution System', NULL, 2020, '2020-12-10', 'Mahardira Dewantara; Lesnanto Multa Putranto; Roni Irnawan; Sarjiya Sarjiya', '2020 3rd International Seminar on Research of Information Technology and Intelligent Systems (ISRITI)', 'JOURNAL', '10.1109/isriti51436.2020.9315446', 'https://doi.org/10.1109/isriti51436.2020.9315446', 'The main concern of renewable generation is that it can help reduce power losses in the grid. Renewable power plants such as Photovoltaic (PV) assisted by a Battery Energy Storage System (BESS) with the right placement and size can provide significant benefits they can certainly further help reduce power loss. This paper, it aims to simulate the power flow by optimizing the placement and size of the PV and BESS considering the power loss using the integrated python DIgSILENT PowerFactory. The proposed methodology concept uses a modified IEEE 33 bus. There are two scenarios, namely systems that are only supported by PV and systems that are supported by PV and BESS, which see the state of charge (SOC). Optimization of placement and size using a Genetic Algorithm (GA). The results obtained from the optimized placement and size show a decrease in power loss, where in the first case, the placement of PV is located on bus 9 with PV capacity can reduce power loss to 2201.66 kW, and the second case, placement of PV is located on bus 9 with PV capacity and BESS is located on bus 16 by looking at the battery operation pattern can reduce the power loss to 2180.01 kW.', 13, 'OPENALEX', '{"doi": "10.1109/isriti51436.2020.9315446", "openalex": "https://openalex.org/W3127202573"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c1027439-b719-441f-9aba-433d4ce26e3d', 'Potential of Biomass as RE Source for Sustainable Electricity Supply in Eastern Indonesia', NULL, 2021, '2021-10-05', 'Tumiran; Mohammad Na’iem; Sarjiya Sarjiya; Lesnanto Multa Putranto; Tomy Listyanto; Adi Priyanto; Ahmad Adhiim Muthahhari; Rizki Firmansyah Setya Budi', '2021 3rd International Conference on High Voltage Engineering and Power Systems (ICHVEPS)', 'JOURNAL', '10.1109/ichveps53178.2021.9601067', 'https://doi.org/10.1109/ichveps53178.2021.9601067', 'Indonesia is working hard to fulfil the quantity, quality, and reliability of the electricity supply in eastern Indonesia. The geographical condition of eastern Indonesia, which consists of thousands of islands with a scattered population and relatively low density, makes it challenging to electrify this region economically. This region still relies on fossil fuels to produce electricity. This dependency becomes a primary problem due to cost production, security of fossil supply and not being environmentally friendly. An option to reduce fossil fuels dependency and ensure the sustainability of electricity supply and reach the economic production cost is to replace fossil energy with renewable energy (RE) sources. However, no research in this area focuses on finding the most economical and sustainable RE sources. Therefore, this research focuses on finding RE sources based on local energy resources, guaranteeing sustainability, supporting local economic growth, and operating at a reasonable cost. The research''s results show that the biomass sources potential in eastern Indonesia is immense, distributed over a vast area. The projected electricity demand in Eastern Indonesia towards 2050 will reach 15.9 TWh, and it needs to be supported by more than 4,200 MW of generating capacity. Suppose it is targeted that by 2050 electrical energy from RE will reach 31%. In that case, it is projected that the aggregate biomass required will reach 5.86 million tons, with the average conversion of wood biomass to produce calories ranging from 4,200 to 4,600 kcal/kg. The volume of forest products will supply the Biomass power plant to reach 1.28 GW. These potential needs can be met by energy plantations covering 1,130,738 ha spread across various islands in Eastern Indonesia. In addition, the sustainable preparation of biomass forests will also drive people''s economy in this region.', 13, 'OPENALEX', '{"doi": "10.1109/ichveps53178.2021.9601067", "openalex": "https://openalex.org/W3216061769"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3a69a8e6-191f-40f8-92ff-406e89b11a15', 'Effect of Distributed Photovoltaic Generation Installation on Voltage Profile: A Case Study of Rural Distribution System in Yogyakarta Indonesia', NULL, 2019, '2019-07-01', 'Anugrah Fitrah Gusnanda; Sarjiya Sarjiya; Lesnanto Multa Putranto', '2019 International Conference on Information and Communications Technology (ICOIACT)', 'JOURNAL', '10.1109/icoiact46704.2019.8938534', 'https://doi.org/10.1109/icoiact46704.2019.8938534', 'Distributed generation (DG) is one of the new approach in the installation of power plants which the plant location is no longer centralized, but it was spread on the distribution of electricity feeders. Nowadays, the application of distributed generation has increased because it is related to smart feeders and it was related to the development with clean, renewable energy technologies based on solar and wind. This supports government programs to use renewable energy in 2025 by 23% where 35,000 MW of 23% is solar panels in Indonesia. Large-scale development of distributed power plants can affect the conditions of the distribution feeder. Therefore, it is necessary to know the impact of the installation of distributed power plants. This study was conducted to analyze the effects of the penetration of the distributed power plant in this case photovoltaic in 2 cases of installation location. First, the distributed generation was placed in the center of the feeder. Second, distributed generation was placed at the end of the feeder. Simulation in this study was conducted using the Open Distribution System (OpenDSS) software with real data of rural distribution feeder in Bantul Regency, Special Region of Yogyakarta, Indonesia. The 20kV distribution feeder was used in this feeder, and it was divided into one feeder. The results of this study are expected to provide information about the impact of the power plant penetration spread on voltage and power losses in the distribution feeder, especially in the Bantul feeder. The results of the study show that the installation of distributed power plants enhances the voltage profile.', 12, 'OPENALEX', '{"doi": "10.1109/icoiact46704.2019.8938534", "openalex": "https://openalex.org/W2998425808"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('40d07aa2-d735-49af-ba12-63ebdd21daeb', 'Study of overcurrent protection on distribution network with distributed generation: An Indonesian case', NULL, 2017, '2017-10-01', 'Septiantoro Hudananta; Timbul Haryono; Sarjiya Sarjiya', NULL, 'JOURNAL', '10.1109/isemantic.2017.8251856', 'https://doi.org/10.1109/isemantic.2017.8251856', 'Increasing of electrical demand causes the need of more effective generation system in the distribution of power. Distributed Generation (DG) is a generation system that can resolve the problem. Installation of DG has complex impacts on the distribution network such as change of the voltage profile, short circuit current, power loss network, harmonics and reliability of the system. Therefore, the installation of DG involves the evaluation of protection coordination in accordance with the size, type and placement of DG installation. In this study, the impact of the installation of DG on the coordination of protection on radial distribution network was studied. The distribution system that was used in this study is data from the distribution system of PT. PLN (Persero) Central Java Region. In general, the installation of DG in Central Java has two configurations. First, the installation of DG is done by connecting directly to the 20 kV busbar substation using the express line. Second, the installation is done by connecting DG in the feeder line. The results show that the existing protection coordination settings still work properly for protection coordination settings after the installation of DG.', 11, 'OPENALEX', '{"doi": "10.1109/isemantic.2017.8251856", "openalex": "https://openalex.org/W2783970739"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('ffc31c9c-d331-4221-9af5-0058ae0111ae', 'Assessing Potential Scenarios for Achieving New and Renewable Energy Targets in Java-Bali Power System, Indonesia', NULL, 2022, '2022-03-20', 'Sarjiya Sarjiya; Lesnanto Multa Putranto; Roni Irnawan; Rizki Firmansyah Setya Budi', 'International Journal of Energy Economics and Policy', 'JOURNAL', '10.32479/ijeep.12852', 'https://doi.org/10.32479/ijeep.12852', 'Geographic circumstances, government policies, and power system characteristics face many countries struggling to achieve their new and renewable energy (NRE). In addition, one characteristic of renewable energy (RE) which cannot be moved is a severe problem for archipelagic countries like Indonesia in achieving their NRE targets. Therefore, this research creates a long-term open-source generation expansion planning (GEP) model that considers renewable energy integration between islands, government policies, and power system characteristics of Indonesia. The model proposes a high voltage direct current (HVDC) line to facilitate abundant energy transfer between islands. The research also included multiple scenario analyses based on the potential strategies that could realistically be applied. Based on the long-term GEP model results, possible alternative routes to achieving NRE targets are mapped and assessed by considering power system characteristics and national energy policies. Specifically, the Java-Bali system of Indonesia is employed as a case study to demonstrate the performance of the proposed long-term GEP model. The optimum planning to achieve the targets produces the generation cost of 7.05 cents USD/kWh and the CO2 emission reduction of 2,297 million tons of CO2.', 11, 'OPENALEX', '{"doi": "10.32479/ijeep.12852", "openalex": "https://openalex.org/W4221002146"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('20ff3d70-0413-4b66-9b6e-f54be0126880', 'A Voltage Rise Mitigation Control Scheme of Utility-Scale Battery in High PV Penetration', NULL, 2021, '2021-10-05', 'Wijaya Yudha Atmaja; Sarjiya Sarjiya; Lesnanto Multa Putranto', '2021 3rd International Conference on High Voltage Engineering and Power Systems (ICHVEPS)', 'JOURNAL', '10.1109/ichveps53178.2021.9601108', 'https://doi.org/10.1109/ichveps53178.2021.9601108', 'In the distribution grids with high R/X proportion, active power curtailment (APC) of battery energy storage system (BESS) becomes an effective strategy for mitigating voltage rise, which is caused by high photovoltaic (PV) penetration. To this purpose, previous researches have presented studies of utilityscale BESS implementation for utility-scale PV penetration. However, the requests for customer-scale PV integration into distribution grids are rapidly increasing. This condition leads to the requirements for studying the performance of utilityscale BESS for the customer-scale PV penetration. Therefore, this article proposes a voltage rise mitigation control scheme of utility-scale BESS for high penetration of customer-scale PV systems. Since the previous studies provided the BESS implementation for utility-scale PV penetration, implementing the BESS control scheme on the distribution system with high customer-scale PV penetration is necessary. It is because, in the last few years, the PV penetration is increasing massively. Moreover, to perform an appropriate BESS control, a control scheme based on the maximum voltage is proposed in this research. To justify the proposed method, the IEEE 123-node test feeder is employed. The results indicate that the proposed control scheme can be used by the distribution system operator in utilizing the utility-scale BESS for voltage rise mitigation in the system with high penetration of customer-scale PV systems. Specifically, this article provides the foundation for performing future studies.', 8, 'OPENALEX', '{"doi": "10.1109/ichveps53178.2021.9601108", "openalex": "https://openalex.org/W3217128875"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6d4b4d6f-812a-4b31-86a5-4427940d6d29', 'Evaluasi Keandalan Perencanaan Pembangkit Wilayah Jawa-Bali dengan Mempertimbangkan Ketidakpastian Peramalan Beban', NULL, 2017, '2017-06-08', 'Avrin Nur Widiastuti; Sarjiya Sarjiya; Kukuh Arung Pinanditho; Eko Tri Prastyo', 'Jurnal Nasional Teknik Elektro dan Teknologi Informasi (JNTETI)', 'JOURNAL', '10.22146/jnteti.v6i2.320', 'http://doi.org/10.22146/jnteti.v6i2.320', 'Power system reliability is one of important aspects of power system operation. Lack of capacity in the generation system will affect reliability level of the power system. System evaluation needs to be done to know whether the system is still reliable to supply the load that is projected to increase 8.2% per year. Java-Bali system evaluation planning period 2015-2024 is conducted in this paper. Load forecast uncertainty (LFU) is one of the parameters that needs to be considered when conducting system planning. It is because load tends to be uncertain. This research uses two scenarios: without and with load forecast uncertainty. Reliability indexes LOLE and LOLP are used to evaluate the Java-Bali system. All calculations are based on a program using MATLAB. The result shows that reliability indexes LOLE and LOLP are higher with considering LFU. It means reliability decreases, rather than planning without considering LFU. Moreover, Java-Bali system reliability indexes meet the PLN’s standard value with the best value acquired in 2019.', 7, 'OPENALEX', '{"doi": "10.22146/jnteti.v6i2.320", "openalex": "https://openalex.org/W2735341093"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b4bf97d7-52a3-4d54-8946-84321b539a2f', 'A Determination of PV and Wind Power Plant Penetration into a Power System', NULL, 2020, '2020-05-28', 'Musthafa Abdur Rosyied; Sarjiya Sarjiya; Lesnanto Multa Putranto; Izzuddin Fathin Azhar; Eko Yudo Pramono', 'Journal FORTEI-JEERI', 'JOURNAL', '10.46962/forteijeeri.v1i1.5', 'https://doi.org/10.46962/forteijeeri.v1i1.5', 'PT. PLN (Persero) has planned to develop a new renewable energy which has a minimum energy mix of 23% in 2025 and 31% in 2030. An intermittent renewable energy plant, which is uncontrollable and unpredictable, will begin to be massively used. Associated to the intermittent nature of the of intermittent renewable energy source (IRES), adequate system flexibility is necessary. This study determined the penetration level IRES generating unit using the systems load and existing generating unit ramping rate characteristic, IRES generating unit’s ramping rate and system’s technical minimum load (TML) on the Java Bali System based on the 2017 operation condition. The results showed that the TML value of the operating plant was 12164,69 MW. The ramping up and down capabilities of conventional power plants are 945.04 MW / 30 min and 4006.08 MW / 30 min where ± 5% of penetration of IRES was still applicable for the Java Bali System.', 2, 'OPENALEX', '{"doi": "10.46962/forteijeeri.v1i1.5", "openalex": "https://openalex.org/W3113396163"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('959905ad-3432-4b4c-b752-e0eb266831a6', 'Development of PV hosting-capacity prediction method based on Markov Chain for high PV penetration with utility-scale battery storage on low-voltage grid', NULL, 2023, '2023-09-27', 'Wijaya Yudha Atmaja; Sarjiya Sarjiya; Lesnanto Multa Putranto', 'International Journal of Sustainable Energy', 'JOURNAL', '10.1080/14786451.2023.2261759', 'https://doi.org/10.1080/14786451.2023.2261759', 'The previous stochastic hosting capacity prediction method using the Monte Carlo method for high photovoltaic (PV) penetration with a battery energy storage system (BESS) required a large number of computations to achieve the expected accuracy.The problem of high computational load must be addressed so that the electrical distribution planner can practically use the PV hosting capacity prediction in actual situations.Therefore, this study developed a Markov-chain-based PV hosting capacity prediction method for high PV penetration using BESS.The proposed method is described in detail, followed by case and validation studies.The obtained hosting capacity was 123.58 kW, which increased to 3676.4 kW after the utility-scale BESS implementation.The results demonstrate that the proposed Markovchain-based PV hosting capacity prediction method outperforms the Monte Carlo method, which is the most popular stochastic hosting capacity method, in terms of accuracy and computational cost.', 7, 'OPENALEX', '{"doi": "10.1080/14786451.2023.2261759", "openalex": "https://openalex.org/W4387099261"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('706737e4-4c25-433b-a4c8-30178ce401ad', 'Model-Free Approach to DC Microgrid Optimal Operation under System Uncertainty Based on Reinforcement Learning', NULL, 2023, '2023-07-14', 'Roni Irnawan; Ahmad Ataka; Muhammad Yasirroni; Lesnanto Multa Putranto; Husni Rois Ali; Eka Firmansyah; Sarjiya Sarjiya', 'Energies', 'JOURNAL', '10.3390/en16145369', 'https://doi.org/10.3390/en16145369', 'There has been tremendous interest in the development of DC microgrid systems which consist of interconnected DC renewable energy sources. However, operating a DC microgrid system optimally by minimizing operational cost and ensures stability remains a problem when the system’s model is not available. In this paper, a novel model-free approach to perform operation control of DC microgrids based on reinforcement learning algorithms, specifically Q-learning and Q-network, has been proposed. This approach circumvents the need to know the accurate model of a DC grid by exploiting an interaction with the DC microgrids to learn the best policy, which leads to more optimal operation. The proposed approach has been compared with with mixed-integer quadratic programming (MIQP) as the baseline deterministic model that requires an accurate system model. The result shows that, in a system of three nodes, both Q-learning (74.2707) and Q-network (74.4254) are able to learn to make a control decision that is close to the MIQP (75.0489) solution. With the introduction of both model uncertainty and noisy sensor measurements, the Q-network performs better (72.3714) compared to MIQP (72.1596), whereas Q-learn fails to learn.', 6, 'OPENALEX', '{"doi": "10.3390/en16145369", "openalex": "https://openalex.org/W4384301183"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c3b4cd71-5d00-4510-8414-0850d1479a24', 'The Masterplan for Developing Electricity Systems for Archipelagic Area by Considering Local Energy Resources: A Case Study of Maluku Islands', NULL, 2019, '2019-08-01', 'Tumiran; Sarjiya Sarjiya; Lesnanto Multa Putranto; Wahri Sunanda; Roni Irnawan; Adi Priyanto; Ira Savitri', NULL, 'JOURNAL', '10.1109/sege.2019.8859915', 'https://doi.org/10.1109/sege.2019.8859915', 'Maluku Province have an electrification ratio of 79.62%, which is among the lowest in Indonesia. This number needs to be increased, such that the economic growth is encouraged and the energy demand can be met. However, there are several challenges hinder the expansion plan of the generation capacity in Maluku, e.g. uneven distribution of the population over a thousand islands. Currently, the main energy sources for Maluku is fossil fuel (diesel power plant). In this paper, the potential of alternative energy resources in Maluku is provided. Based on the statistics, the masterplan for developing electricity systems in Maluku is developed. This plan is initiated by holding a focus group discussion (FGD) with several stakeholders to gain knowledge on the potential energy resources location and size, also to determine the electricity demand growth in Maluku. In the end, the optimization of generation expansion planning can be performed by considering some constraints to retrieve the most suitable power plant resources for Maluku.', 4, 'OPENALEX', '{"doi": "10.1109/sege.2019.8859915", "openalex": "https://openalex.org/W2980079658"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f0845555-9a5b-453c-a1c5-7c60131850f8', 'Optimizing Local Renewable Energy Resources for Reducing Energy Dependency on An Isolated Island: A Case Study of Saumlaki Island, Indonesia', NULL, 2023, '2023-08-06', 'Tumiran; Sarjiya Sarjiya; Lesnanto Multa Putranto; Rizki Firmansyah Setya Budi; Ahmad Adhiim Muthahhari', NULL, 'JOURNAL', '10.1109/ichveps58902.2023.10257316', 'https://doi.org/10.1109/ichveps58902.2023.10257316', 'Saumlaki system is located on a small remote island that experiences an electricity supply crisis. Another problem faced in the Saumlaki system is energy dependency on fossil fuels supplied from other islands. To overcome these problems, it is necessary to use local renewable energy resources. However, using renewable energy resources potentially increase the generation cost. Therefore, a well-planned generation expansion planning that optimizes local RES in Saumlaki is necessary to achieve an optimal generation mix and cost. Therefore, this research addresses this issue and aims to find an optimal power development plan in the Saumlaki system by maximizing local RE resources and reducing its energy dependency on external sources. The optimization in this research is done through the MILP method with a planning horizon starting in 2023 to 2032. The research results show a decrease in generation costs from 16.36 cents/kWh to 8.81 cents/kWh. Biomass power plants play a crucial role in supplying electricity in Saumlaki with reliable, sustainable, and eco-friendly energy. Using local biomass energy has also helped reduce the Saumlaki system''s reliance on HSD energy imported from other islands. This is demonstrated by the decrease in the proportion of HSD in the energy mix from 100% to only 45% in 2032, achieved through the use of 55% biomass energy, which amounts to 30.7 GWh.', 4, 'OPENALEX', '{"doi": "10.1109/ichveps58902.2023.10257316", "openalex": "https://openalex.org/W4387064339"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('377a2e59-a440-4aee-b15d-57cd59a875ae', 'OPTIMASI PENEMPATAN DAN KAPASITAS DISTRIBUTED GENERATION DENGAN METODE FLOWER POLLINATION ALGORITHM', NULL, 2015, '2015-01-01', 'M Rifki Ali; Sarjiya Sarjiya; Sri Widiastuti', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/90133', 'Distributed Generation (DG) memiliki banyak keunggulan yaitu dapat memperbaiki profil tegangan, mengurangi rugi-rugi daya dalam aliran listrik, mitigasi kapasitas pembangkitan di jaringan transmisi dan distribusi, meningkatkan keandalan, dan kualitas daya. Selain itu DG juga berperan mengurangi biaya operasional pada saat beban puncak, kemampuan menyokong grid, dan meningkatkan sekuritas pada bebanAƒi?½A‚Â¢AƒÂ¯A‚Â?A‚Â½AƒÂ¯A‚Â?A‚Â½beban kritis. Oleh karena itu dibutuhkan penempatan DG dan alokasi kapasitas daya yang optimal untuk mendapatkan biaya serendah-rendahnya dan manfaat setinggi-tingginya dengan metode optimasi.INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4e9cbe1b-f579-4e51-a94b-2da4c9d90616', 'Performance of OWC-Type Wave Power Plants in the Waters of Sumbawa Island, Indonesia', NULL, 2024, '2024-09-03', 'Adnan Sandy Dwi Marta; Deendarlianto Deendarlianto; Indarto Indarto; Sarjiya Sarjiya; Samsul Kamal; Ekrar Winata', NULL, 'JOURNAL', '10.1109/ict-pep63827.2024.10733542', 'https://doi.org/10.1109/ict-pep63827.2024.10733542', 'Sumbawa Island, Indonesia, has substantial wave energy potential derived from the Indian Ocean. This significant wave energy potential, along with the Indonesian government''s support for energy transition and zero carbon policies, necessitates detailed location-specific assessments of wave energy converter performance. One wave power plant that has reached a Technology Readiness Level of eight is the oscillating water column (OWC) type. Wave energy converter research using an L-shaped OWC chamber was conducted in a two-dimensional wave flume at the Coastal Engineering Laboratory of the National Research and Innovation Agency. The study involved varying the wave period characteristics found in Sumbawa Island, Indonesia, to evaluate the performance of the Wells turbine as the converter. The research results indicate that the performance of the L-shaped OWC with a Wells turbine is influenced by changes in wave periods. The water oscillation within the chamber affects the air pressure inside the chamber and the turbine duct of the OWC, which in turn impacts the turbine''s rotation speed (RPM) and the overall performance of the wave energy converter. The best performance was achieved with a wave period scenario of 7.5 seconds at 7,089 RPM, while the lowest performance was observed with a wave period scenario of 11.5 seconds at 5,190 RPM.', 3, 'OPENALEX', '{"doi": "10.1109/ict-pep63827.2024.10733542", "openalex": "https://openalex.org/W4403937643"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2378a13d-6820-41e3-9bff-44fb70864870', 'Optimal Power Flow Considering Generation and Loss Costs Using Particle Swarm Optimization (PSO) on the Gorontalo Power System', NULL, 2025, '2025-09-03', 'Azhar Ade Prasetya; Sarjiya Sarjiya; Yusuf Susilo Wijoyo; Mukhamad Daris Alfarrel', NULL, 'JOURNAL', '10.1109/ict-pep67281.2025.11232092', 'https://doi.org/10.1109/ict-pep67281.2025.11232092', 'The increasing demand for electricity in Gorontalo province, driven by steady economic growth, poses significant operational challenges in the regional power system, which is interconnected with the north Sulawesi grid through a 150 kV transmission network. High generation costs and substantial transmission losses due to the extended network require the development of cost-efficient power dispatch strategies. This study investigates the application of Particle Swarm Optimization (PSO) to solve the Optimal Power Flow (OPF) problem with a focus on minimizing the total cost of electricity delivery, comprising both generation cost and transmission loss cost. Rather than proposing a new optimization method, the study employs a well-established PSO algorithm to evaluate its performance in addressing conflicting objectives within the OPF framework. The Gorontalo power system serves as a case study to demonstrate the practical effectiveness of the method. The results indicate that a combined optimization of the generation and transmission losses provides the most economical solution compared to single-objective approaches. The findings also support the potential of PSO in power system optimization and suggest future directions involving multi-objective formulations, larger system models, and integration of renewable energy sources.', 1, 'OPENALEX', '{"doi": "10.1109/ict-pep67281.2025.11232092", "openalex": "https://openalex.org/W4416183082"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('86ddc143-7289-4915-bac9-9b785ba089d2', 'Thermal unit commitment solution using genetic algorithm combined with the principle of tabu search and priority list method', NULL, 2013, '2013-10-01', 'Sarjiya Sarjiya; Arief Budi Mulyawan; Apri Setiawan; Andi Sudiarso', NULL, 'JOURNAL', '10.1109/iciteed.2013.6676278', 'https://doi.org/10.1109/iciteed.2013.6676278', 'Unit commitment (UC) is one of optimization problem which is important in electrical power systems as effort to minimize generation cost by applying an effective scheduling. However, the size of search space and many constraints in this problem are becoming the problems. This paper will present hybrid algorithm which integrates genetic algorithm (GA) combined with the principle of tabu search (TS) and priority list (PL) methods to solve the UC problem. PL will be used for solving the unit scheduled problem. GA and the principle of TS are used for solving the economic dispatch problem. To optimize GA parameters, design of experiment (DOE) method will be used. The proposed algorithm is tested on the IEEE 10 unit systems for a one day scheduling periods. The results are compared with methodological priority list, shuffled frog leaping algorithm, hybrid particle swarm optimization, standard GA, integer coded GA, and Lagrange relaxation GA methods. This proposed hybrid method shows that the total cost of the unit commitment problem is better than other compared methods and near-optimal solution.', 16, 'OPENALEX', '{"doi": "10.1109/iciteed.2013.6676278", "openalex": "https://openalex.org/W2102020458"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('076f4ece-7db3-437c-a23a-7fbb6f52b4ed', 'Power transformer incipient faults diagnosis using Dissolved Gas Analysis and Rough Set', NULL, 2012, '2012-09-01', 'Noor Akhmad Setiawan; Sarjiya Sarjiya; Zenith Adhiarga', NULL, 'JOURNAL', '10.1109/cmd.2012.6416311', 'https://doi.org/10.1109/cmd.2012.6416311', 'Dissolved Gas Analysis (DGA) is standard technique to detect and diagnose power transformer incipient faults. Many methods based on DGA have been proposed such as Duval Triangle, IEC, Roger''s Ratio, Key Gases, etc. The relationship between gas and type of faults is difficult to model and highly non-linear. Knowledge Discovery from Data (KDD) based on Rough Set Theory (RST) can be used to find that relationship. Thus RST is used in this research. The objective of this research is to diagnose incipient fault of power transformer. The diagnosis method is using DGA and RST. All of possible gas ratios are used as input to determine types of fault. The value of gas ratios are discretized before being processed with Rough Set Theory (RST). The number of input attributes is reduced using RST. The knowledge is extracted in the form of IF-THEN rules. The extracted and reduced rules are used to diagnose the incipient faults of power transformer. The resulting rules have the accuracy of 81.25%.', 15, 'OPENALEX', '{"doi": "10.1109/cmd.2012.6416311", "openalex": "https://openalex.org/W2545219709"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('33004d9c-c265-4cf3-bdb9-7948405d0d40', 'Optimasi Daya Reaktif Distributed Generation untuk Pengaturan Tegangan Sistem Distribusi dan Transmisi Tenaga Listrik', NULL, 2015, '2015-01-01', 'Jimmy Trio Putra; Sarjiya Sarjiya; M.T. Ir. M. Isnaeni Bs', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/91926', 'Perubahan tegangan dan aliran daya yang diberikan oleh Distributed Generation (DG) akan memberikan tantangan yang baru terhadap sistem tenaga listrik konvensional. Penelitian ini bertujuan untuk mengukur besarnya dampak pemasangan pembangkit PV terhadap profil tegangan sistem dan gangguan fluktuasi tegangan terhadap sistem distribusi dan transmisi tenaga listrik. Penelitian ini meggunakan jaringan distribusi 10 kV yang berasal dari jaringan transmisi 70 kV dimodelkan menggunakan simulasi Open Distribution System Simulator (OpenDSS) dan Matrix Laboratory (MATLAB) untuk meneliti dampak pemasangan pembangkit PV yang intermittent dan variability beban perumahan, industrial dan komersial terhadap sistem. Perbandingan antara sistem distribusi dan transmisi tanpa dan adanya pemasangan pembangkit PV ditunjukkan. Profil tegangan dan fluktuasi tegangan setiap bus pada sistem distribusi dan transmisi dianalisis. Studi ini menunjukan bahwa intermittent pembangkit PV dan variability beban setiap jam dapat berpengaruh terhadap profil tegangan dan fluktuasi tegangan sistem distribusi dan transmisi tergantung dari kondisi pembebanan, pembangkitan dan mode strategi pengendalian yang diterapkan. Pemanfaatan daya reaktif optimal DG dengan metode Flower Pollination Algorithm (FPA) dapat menjadi salah satu solusi dalam memperbaiki profil tegangan dan mengurangi fluktuasi tegangan baik pada sistem distribusi maupun transmisi dengan adanya pemasangan DG. Perbandingan profil tegangan setelah skenario pemanfaatan optimal daya reaktif ke sistem menunjukkan bahwa mode strategi ini dapat berdampak baik terhadap profil tegangan dan fluktuasi tegangan sistem.INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('775ccbe3-d12a-481c-950f-cc54f40eabdf', 'Study on Photovoltaic Hosting in Yogyakarta Electric Distribution Network', NULL, 2018, '2018-09-01', 'Faishal Fuad Rahman S.; Kristianto Adi W.; Sarjiya Sarjiya; Lesnanto Multa Putranto', NULL, 'JOURNAL', '10.1109/icitacee.2018.8576961', 'https://doi.org/10.1109/icitacee.2018.8576961', 'The development of power generation technology enables the location of the plant which is no longer centralized but becomes scattered in several distribution channel locations close to the load. The interconnection of PV into the distribution network may result in potential disruption of operating conditions and result in problems in power quality. The hosting capacity is defined as the number of new production or consumption that can be interconnected with the network without any adverse impact on the reliability or quality of the voltage on the consumer. The hosting capacity also ensures that there are no broken parameters, i.e., the current carrying capacity distribution network and power flow direction. An iteration approach with voltage constraints, power flow, and current conductivity capability is used to determine the amount of PV power capacity that can be injected into the network. The impact of PV interconnection into the network, especially the voltage and power flow is studied to determine the capacity of PV hosting. The results show that the PV hosting capacity of the distribution network in Yogyakarta through GI Kentungan is equal to the current load on the distribution network.', 12, 'OPENALEX', '{"doi": "10.1109/icitacee.2018.8576961", "openalex": "https://openalex.org/W2905133985"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('607ef813-c716-49e0-b150-f32e7b9ca0f0', 'Wind and Solar Power Plant Modelling and Its Impact to the Jawa-Bali Power Grid', NULL, 2018, '2018-10-01', 'Sarjiya Sarjiya; Lesnanto Multa Putranto; M Isnaini BS; Musthafa Abdur Rosyied; Pandu Lukhyswara; Febian Melwa Reksa Aditya; Eko Yudo Pramono; Suroso Isnandar', NULL, 'JOURNAL', '10.1109/appeec.2018.8566584', 'https://doi.org/10.1109/appeec.2018.8566584', 'PT. PLN (Persero) has to develop renewable energy which has a minimum energy mix of 23% in 2025 and 31% in 2030. An intermittent renewable-energy power plant like wind and solar power plant, which is uncontrollable and unpredictable, will be massively penetrated. For that reason, sufficient system flexibility is necessary. The effects of intermittent wind and solar power plants in Java-Bali are conducted in this research. The intermittency of wind and solar power plant are modelled from the historical weather data in some areas with the total capacity 1,930 MW, system peak load is 25,325 MW and the total generation capacity before penetration is 35,517 MW. Then the ramping rate difference before and after penetration for every station is evaluated, which can be increases or decreases. Nevertheless, the observations in this study are the increment of maximum ramp up requirement in 30 minutes resolution in Bekasi 4 EHV station become 125.46 MW (before 65 MW) and maximum ramp down requirement in Bekasi 3 EHV station as become 90.36 MW (before 45 MW). For ensuring the ramping rate requirement, Java-Bali system has to increase the flexibility.', 11, 'OPENALEX', '{"doi": "10.1109/appeec.2018.8566584", "openalex": "https://openalex.org/W2904448910"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6d50e2ee-0b7b-4b8a-8757-a07a8f448897', 'Reactive power optimization of distributed generation for voltage regulation of distribution systems', NULL, 2016, '2016-10-01', 'Jimmy Trio Putra; Sarjiya Sarjiya', NULL, 'JOURNAL', '10.1109/iciteed.2016.7863288', 'https://doi.org/10.1109/iciteed.2016.7863288', 'Additional intermittent PV generation and variability load profiles can cause problems in voltage regulation of power systems. Nowadays, PV does not participate in the system voltage control; it can cause a voltage increase or decrease and cause voltage fluctuation disturbance along the feeder. However, the situation can be different if PV participated in voltage control. This paper proposes an approach of flower pollination algorithm as a solution to determine optimal reactive power value that can be produced by PV. Result showed PV generation as variable power factor can positively affect voltage profile and can also reduce voltage fluctuation disturbance both in distribution and transmission system.', 10, 'OPENALEX', '{"doi": "10.1109/iciteed.2016.7863288", "openalex": "https://openalex.org/W2592645781"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c5881ec1-ec1f-4fd3-8913-10173e62b3fe', 'Modified flower pollination algorithm for nonsmooth and multiple fuel options economic dispatch', NULL, 2016, '2016-10-01', 'Sarjiya Sarjiya; Pradipta Hafiza Putra; Toga Ardian Saputra', NULL, 'JOURNAL', '10.1109/iciteed.2016.7863285', 'https://doi.org/10.1109/iciteed.2016.7863285', 'Economic dispatch determines the optimal power generation output to meet the system load at the lowest possible cost. Characteristics of each generating unit may have an impact on the effectivity of the method used in solving economic dispatch problem. Conventional gradient-based methods are inapplicable in economic dispatch problem with non-smooth cost functions and multiple fuel options. In this paper, modified flower pollination algorithm (MFPA) with lambda iteration approach (LI) is proposed. The proposed method is tested on a 10-generator system with non-smooth and multiple fuel options. MFPA results in lower fuel cost compared to FPA. Furthermore, MFPA is tested against other methods used in similar economic dispatch problems. MFPA produces a better solution compared to some of the methods.', 10, 'OPENALEX', '{"doi": "10.1109/iciteed.2016.7863285", "openalex": "https://openalex.org/W2594283884"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9f4fae6e-4a20-4276-b9cc-7337b0961952', 'Rooftop Photovoltaic Hosting Capacity Assessment: A Case Study of Rural Distribution Grids in Yogyakarta, Indonesia', NULL, 2019, '2019-07-01', 'Wijaya Yudha Atmaja; Sarjiya Sarjiya; Lesnanto Multa Putranto; Surya Santoso', NULL, 'JOURNAL', '10.1109/iceei47359.2019.8988810', 'https://doi.org/10.1109/iceei47359.2019.8988810', 'Negative impacts of large-scale rooftop photovoltaic (PV) penetration may cause performance deterioration of distribution grids. Consequently, a rooftop PV hosting capacity analysis is becoming a concern of utility. In this work, a proposed method based on Monte Carlo process is developed to assess the PV hosting capacities on the basis of substation power factor. To consider the actual conditions, three selected feeders including feeder F1, feeder F2, and feeder F3, with distinct grid characteristics from Yogyakarta Province of Indonesia are employed. To obtain a detailed result of the rooftop PV hosting capacity, the customer with rooftop PV is randomly selected one by one. The proposed method is performed with over/undervoltage, substation power factor and reverse power flow limit. The comparative study is provided to investigate the impacts of the operational limits on the rooftop PV hosting capacity. Since the load demand and PV output vary with the time, the analyses are conducted in a time-series framework. In this work, constant PQ of loads is assigned, and all rooftop PV systems are assumed to have unity power factor. The results show that the substation power factor limit is more restrictive compared to overvoltage limit and reverse power flow limit. The substation power factor limits the rooftop PV penetration on feeder F1, feeder F2, and feeder F3, respectively, 86.52%, 79.37%, and 85.85% faster than reverse power flow limit. The results also indicate that the substation power factor decreases with the increasing of rooftop PV penetration.', 8, 'OPENALEX', '{"doi": "10.1109/iceei47359.2019.8988810", "openalex": "https://openalex.org/W3006414425"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a9cfd1e3-3bfe-494d-9a20-da078266d9d1', 'Evaluasi Penempatan Dan Jumlah Saklar ABSW Pad a Saluran Distribusi Primer Gardu Induk Mangkunegaran', NULL, 2010, '2010-01-01', 'Sekar Aditya Pranawa; I Nengah Sumerti; Sarjiya Sarjiya', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/download.php?dataId=12012', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W107072377"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c0a07303-afc1-4dc4-88f1-a23566c92a7f', 'Optimal Scheduling of Hybrid Renewable Energy System Using MIQP Method', NULL, 2013, '2013-02-04', 'Sarjiya Sarjiya; Timbul Haryono; Winasis Winasis', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/135113/', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1217107124"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5f818c04-3854-4db7-83fe-ef3169e731d1', 'Unit Commitment with Primary Frequency Regulation Consideration in the Southern Sulawesi Power System', NULL, 2020, '2020-10-06', 'Candra Febri Nugraha; Lesnanto Multa Putranto; Muhammad Isnaeni Bambang Setyonegoro; Sarjiya Sarjiya; Suroso Isnandar', NULL, 'JOURNAL', '10.1109/icitee49829.2020.9271759', 'https://doi.org/10.1109/icitee49829.2020.9271759', 'To increase the penetration level of renewable energy generation, the readiness of the existing power system needs to be considered, especially in terms of the system’s ramping rate and frequency response capability. Even, a high penetration level of renewable energy can potentially reduce generating units generation cost, the system capability to perform the frequency response is decreased. For this reason, the quality of the frequency response needs to be considered in operation planning. In this paper, a unit commitment model was developed with considering the adequacy of primary frequency regulation (PFR). The effect of PFR constraints was analyzed by comparing the scheduling results and the frequency response with the conventional UC models. The result of this research shows that by considering the PFR constraints, the optimization results in an increasing number of committed generating units, thus resulting in more distributed reserves. The additional constraints increase the conventional unit generation costs from $48,017 to $51,636 on the simulated scenario. However, the proposed model shows its advantages in the system dynamic frequency performance, shown by an increase in frequency nadir and steady-state frequency of 490 mHz and 70 mHz respectively during low load conditions.', 8, 'OPENALEX', '{"doi": "10.1109/icitee49829.2020.9271759", "openalex": "https://openalex.org/W3107210941"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9d15cb17-a399-4857-a616-124f28ac7c01', 'Battery energy storage system to reduce voltage rise under high penetration of customer-scale photovoltaics', NULL, 2022, '2022-10-24', 'Wijaya Yudha Atmaja; Sarjiya Sarjiya; Lesnanto Multa Putranto', 'International Journal of Sustainable Energy', 'JOURNAL', '10.1080/14786451.2022.2136176', 'https://doi.org/10.1080/14786451.2022.2136176', 'Unmanaged high penetration of customer-scale photovoltaic on the distribution network results in voltage rises along the network. However, the performance of the implemented battery energy storage system (BESS) to prevent voltage rise under that high penetration condition was unclear because the previous penetration models did not consider the intermittency and variability characteristics of the penetration due to their model simplifications. Therefore, this research proposes a BESS control scheme to mitigate impermissible voltage rises by considering the penetration characteristics of intermittency and variability. As a result, the proposed model outperformed the previous model by providing a more complete representation of the actual penetration issues, and thus the expected contribution of the BESS control scheme in reducing voltage rises could be provided.', 6, 'OPENALEX', '{"doi": "10.1080/14786451.2022.2136176", "openalex": "https://openalex.org/W4307285979"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9d80bf6f-43b9-4772-a233-79223a52a67c', 'The Prospect of Rooftop Photovoltaic Development Considering Global Horizontal Irradiation Uncertainty and Government Policies: A Case of Java Island, Indonesia', NULL, 2022, '2022-07-19', 'Rizki Firmansyah Setya Budi; Sarjiya Sarjiya; Sasongko Pramoho Hadi', 'International Journal of Energy Economics and Policy', 'JOURNAL', '10.32479/ijeep.13066', 'https://doi.org/10.32479/ijeep.13066', 'Global horizontal irradiation uncertainty and government policy significantly affect the economics of rooftop photovoltaic development. Unfortunately, previous studies neglect these aspects. Therefore, it is necessary to undertake the economic analysis of rooftop photovoltaic development by considering its global horizontal irradiation uncertainty and government policies. This research creates a model that can be used to perform analysis and assess rooftop photovoltaic development prospects by considering irradiation uncertainty and government policies. The attractiveness of rooftop photovoltaic development is indicated by the value of the Levelized cost of electricity, net present value, and internal rate of return. Monte Carlo simulation models irradiation uncertainty. Java Island in Indonesia is used as a case study to show the performance of the proposed model. The research results show that the rooftop photovoltaic is not economically viable if built by the utility. Rooftop photovoltaic systems are only profitable when built by the private sector and is used for internal usage only. These rooftop photovoltaic investments provide an internal rate of return above 14%, which shows that investors with green capital funds and local investors are interested in investing. The emission reductions from a 100 m2 rooftop photovoltaic system vary from 214 to 384 tons of CO2 per year.', 5, 'OPENALEX', '{"doi": "10.32479/ijeep.13066", "openalex": "https://openalex.org/W4286222828"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('37fcfaa8-8f53-46f0-9a88-9e9a190e45c5', 'Determination of Maximum Grid-Connected Photovoltaic Penetration Level Based on Unit Commitment Solution', NULL, 2019, '2019-07-01', 'Penang Rahimta Mara; Sarjiya Sarjiya; Lesnanto Multa Putranto; Muhammad Yasirroni', NULL, 'JOURNAL', '10.1109/iceei47359.2019.8988911', 'https://doi.org/10.1109/iceei47359.2019.8988911', 'This paper presents a study of the permissible photovoltaic (PV) power penetration related to generation scheduling by considering system and generator units constraints. The unit commitment problem is solved using Mixed Integer Quadratic Programming (MIQP). High PV penetration lowered net-load profile during the daytime. More PV penetration on the grid, the smaller the net-load profile occurs. When PV penetration is too large, the algorithm fail to find a unit commitment solution due to the net-load ramping at certain hours is higher than the maximum ramping capability of the generator unit. The infeasible solution of unit commitment problem occurred at PV penetration 69% due to the lack of ramp-up of generators.', 4, 'OPENALEX', '{"doi": "10.1109/iceei47359.2019.8988911", "openalex": "https://openalex.org/W2996274685"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('34b723ab-ae3e-4131-a5c6-3b09b3f5f6d3', 'Review on Battery Energy Storage System for Power System with Grid Connected Wind Farm', NULL, 2020, '2020-09-07', 'Evando Diotama; Lesnanto Multa Putranto; Sarjiya Sarjiya; Roni Irnawan', NULL, 'JOURNAL', '10.1109/icst50505.2020.9732801', 'https://doi.org/10.1109/icst50505.2020.9732801', 'Wind power has massive potency to be developed, by the fact that wind resource is more environmentally friendly than conventional non-renewable resources. However, wind power generation tends to unstable due to its intermittency. The installation of BESS (Battery Energy Storage System) on the power system which utilizes wind resource may overcome this intermittency problem. In this paper, a review on placement and sizing optimization of BESS in power system with wind farm integration has presented. The comparison of various methods indicates that placement and sizing optimization of BESS can reduce the loss. Hence the better stability can be obtained.', 4, 'OPENALEX', '{"doi": "10.1109/icst50505.2020.9732801", "openalex": "https://openalex.org/W4243603814"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('95362567-1a74-43d7-aa4f-f79a2fff9306', 'Simulasi Optimal Power Flow Sistem Kelistrikan PT. PLN (Persero) P3BS UPB Sumatera Bagian Utara', NULL, 2013, '2013-10-07', 'Sarjiya Sarjiya; Lesnanto Multa Putranto; Sitohang Nathan', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/135110/', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1260814941"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3c145302-6d46-457c-8633-e0cea4002ff9', 'Renewable Energy Potential Mapping of Industrial Area in Central Java', NULL, 2022, '2022-10-18', 'Ekrar Winata; Dwi Novitasari; Wangi Pandan Sari; Sarjiya Sarjiya', NULL, 'JOURNAL', '10.1109/ict-pep57242.2022.9988779', 'https://doi.org/10.1109/ict-pep57242.2022.9988779', 'The industrial sector is one of the economic pillars providing the largest portion of Indonesia''s national Gross Domestic Product. The sector is affected by the government planning to reduce greenhouse gas emissions (GHG) through Eco-Industrial Park Program. An example of the program is implementing renewable energy (RE) to support the business process, such as providing electricity needs. The national electricity company (PT.PLN) currently provides electricity in the industrial area. This research analyzes the demand and supply of electricity in the industrial area to support government programs. Central Java is chosen as a case study because it has an enormous capacity for industrial areas compared to the other province in Indonesia, and the local government commits to promoting renewable energy. The results show that seven industrial areas in Central Java Province require 1,274.7 MW of electricity. Furthermore, the renewable energy potential is analyzed within a radius of 25 km from the industrial area. The resources that analyze are solar, wind, biomass, and hydro. For example, the total energy potential in Sugihmanik areas for solar, wind biomass, and hydro is 5.13, 0.1, 2.54, and 21.58 MW, respectively. Based on the analysis, it is known that each industrial area can provide electricity demand by utilizing renewable energy potential around their area.', 1, 'OPENALEX', '{"doi": "10.1109/ict-pep57242.2022.9988779", "openalex": "https://openalex.org/W4313289125"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9c0b0c50-bb6a-4dfb-9850-ad62f76ccd65', 'Economic Feasibility of Wind Farm: A Case Study for Coastal Area in South Purworejo, Indonesia', NULL, 2015, '2015-01-01', 'Ismail Ismail; Samsul Kamal; Purnomo Purnomo; Sarjiya Sarjiya; Budi Hartono', 'Energy Procedia', 'JOURNAL', '10.1016/j.egypro.2015.01.049', 'https://doi.org/10.1016/j.egypro.2015.01.049', 'Economic feasibility for the development of wind energy potential into wind farm in coastal area of South Purworejo is strategic for Indonesia. The methods used were analysis and evaluation study which involve three analyses, i.e. economic analysis based on scenarios, risk, and sensitivity. The results of the economic analysis based on Scenario 1 with net present value are USD 70 422 642.29 and internal rate return value is 11.38% which serves as the most optimal result. Analysis that considers the obtained risk has probability distribution of internal rate return is above the discount rate reaching 89.3%.', 11, 'OPENALEX', '{"doi": "10.1016/j.egypro.2015.01.049", "openalex": "https://openalex.org/W2060691856"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('44c5bb39-42f0-4fda-a98c-aa7e31c52b77', 'Performance analysis of Adaptive Neuro Fuzzy Inference Systems (ANFIS) for speed control of brushless DC motor', NULL, 2011, '2011-07-01', 'Hidayat Hidayat; P H Sasongko; Sarjiya Sarjiya; Suharyanto Suharyanto', NULL, 'JOURNAL', '10.1109/iceei.2011.6021755', 'https://doi.org/10.1109/iceei.2011.6021755', 'This paper presents a performance analysis of Adaptive Neuro Fuzzy Inference Systems (ANFIS) which is applied to control the speed of Brushless Direct Current Motor (BLDCM). The proposed strategy of speed BLDCM controller is operating which is similar to the conventional direct current motor. This strategy is implemented base on quadratic axis control and zero direct axis current. The aim of the speed controller is to obtain the speed motor operating similar to a speed setting. The input of the controller is speed measured by speed sensor encoder. The output is level voltage supplying stator windings BLDCM through pulse wide modulation controller of inverter. The ANFIS controller is used to decide the pulse wide to of the inverter. It has two input variables speed error, speed error rate and the output variable is the voltage to represent stator current. The variables are represented into fuzzy sets called fuzzy membership functions that their function form and number will be varied until acquired the best characteristic of dynamic response systems. Using MATLAB Simulink, the performance analysis at this strategy is emphasized on the transient parameter of dynamic response. The simulation results show that the best response of speed control is the bell function with five membership functions.', 10, 'OPENALEX', '{"doi": "10.1109/iceei.2011.6021755", "openalex": "https://openalex.org/W2075305625"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('dd0cbc98-efad-4a11-8ab6-2072398309c1', 'Optimal solution of reliability constrained unit commitment using hybrid genetic algorithm-priority list method', NULL, 2014, '2014-10-01', 'Sarjiya Sarjiya; Arief Budi Mulyawan; Andi Sudiarso', NULL, 'JOURNAL', '10.1109/iciteed.2014.7007946', 'https://doi.org/10.1109/iciteed.2014.7007946', 'This paper presents the completion of unit commitment (UC) problem using genetic algorithm based on priority list approach. In solving this UC problem, reliability constraint is also considered to increase the feasibility of the obtained solution. Reliability constraint used in this paper is loss of load probability index to evaluate the required spinning reserve. Meanwhile, the sub problem, economic load dispatch problem is solved by using lambda iteration. This method is tested on case study 26 unit system. Priority list which is used in this paper can make genetic algorithm to convergence better and faster. The results of the proposed hybrid method are compared with other methods referred in this paper.', 5, 'OPENALEX', '{"doi": "10.1109/iciteed.2014.7007946", "openalex": "https://openalex.org/W2088680079"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6db0208e-e67b-4e32-8f32-c16951008643', 'Short-Term Load Forecasting With Long Short-Term Memory: A Case Study of Java-Bali System', NULL, 2020, '2020-10-06', 'Makhmudun Ainuri; Sarjiya Sarjiya; Igi Ardiyanto', NULL, 'JOURNAL', '10.1109/icitee49829.2020.9271763', 'https://doi.org/10.1109/icitee49829.2020.9271763', 'Short-term Load Forecasting (STLF) plays an important role in power system operation. It will be used for manage power balance between the dynamic power demand and power supply. This research presents a Long Short-term Memory (LSTM) and Recurrent Neural Network (RNN) for short-term load forecasting Java-Bali power system. We compare the performance of these network architecture models using Mean Average Percentage Error (MAPE) and Root Mean Squared Error (RMSE) to choose the best models for development Java-Bali power system operationalization in the future. The result show LSTM can forecast better than RNN due to vanishing and exploding gradient condition. The best LSTM model has MAPE 5,67% and RMSE 1683,09MW.', 4, 'OPENALEX', '{"doi": "10.1109/icitee49829.2020.9271763", "openalex": "https://openalex.org/W3107390203"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2a81ad46-1155-4264-9800-58c67a121d14', 'ANALISIS KEMAMPUAN BAYAR MASYARAKAT INDONESIA TERHADAP ENERGI LISTRIK', NULL, 2010, '2010-01-01', 'Sasongko Aribowo; Sarjiya Sarjiya; Avrin Nur Widiastuti', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12168', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2757504011"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c2705fa3-bcc4-4197-ad14-a0bd64497218', 'Optimasi Cadangan Berputar dengan Kekangan Keandalan Menggunakan Algoritma Genetika Mempertimbangkan Ketidakpastian Pembangkitan dan Beban', NULL, 2017, '2017-01-01', 'Toga Ardian Saputra; Sarjiya Sarjiya; Dea Ir. Sasongko Pramono Hadi', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/downloadfile/113764/potongan/S1-2017-348424-introduction.pdf', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2788812661"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('110c1c23-92be-4ef6-b5b5-785030519f0a', 'Analysis of Performance Index in Transmission Expansion Planning of Sulawesi''s Electricity System', NULL, 2020, '2020-12-10', 'Damai Bela Nusantara; Lesnanto Multa Putranto; Sarjiya Sarjiya; Suroso Isnandar; Thomas Kristian Yudhantomo', '2020 3rd International Seminar on Research of Information Technology and Intelligent Systems (ISRITI)', 'JOURNAL', '10.1109/isriti51436.2020.9315480', 'https://doi.org/10.1109/isriti51436.2020.9315480', 'Sulawesi''s electricity system needs to maintain the sustainability of the electricity supply which is stable, reliable, safe, eco-friendly, and able to meet the needs of the community. For that reason, the transmission expansion-planning program 2018-2050 is proposed. Considering the load growth, primary energy, and the power flow, it is necessary to build the transmission backbone, which for Indonesian case maybe 275 kV or 500 kV. The determination of the backbone''s voltage requires some criteria, one of them is to performing contingency analysis which can be obtained by performance index analysis. Performance index analysis, consist of voltage performance index and active power performance index, is simulated using the DIg-SILENT PowerFactory 15.1.7 software for two generation planning scenarios, regional balanced and resourced based. If the transmission system has exceeded the level of set severity of the contingency case, it is necessary to choose the 500 kV Extra High Voltage Overhead Transmission Line.', 4, 'OPENALEX', '{"doi": "10.1109/isriti51436.2020.9315480", "openalex": "https://openalex.org/W3126655296"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2e7d0d53-345e-4714-a56a-b4f3130b4179', 'OPTIMASI PENGEMBANGAN PEMBANGKIT SISTEM KELISTRIKAN JAWA-MADURA-BALI MENGGUNAKAN GAME THEORY: MULTI-PERIOD FRAMEWORK, BI-LEVEL, DAN MULTI-OBJECTIVE OPTIMIZATION METHOD', NULL, 2017, '2017-01-01', 'Rizki Firmansyah S B; Sarjiya Sarjiya; Dea. Prof.Dr.Ir. Sasongko Pramono H', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/116803', 'Perencanaan jangka panjang sistem kelistrikan Jawa-Madura-Bali (Jamali) secara optimal diperlukan untuk mendukung pertumbuhan ekonomi nasional dan kebijakan energi nasional. Sebuah model optimasi yang dapat merepresentasikan proses lelang dan penunjukkan langsung independent power producer (IPP) dengan mempertimbangkan jangka waktu yang panjang (multi-period framework) dan multi-objective function (ekonomis, handal, dan ramah lingkungan), diperlukan dalam proses perencanaan pengembangan pembangkit sistem kelistrikan Jamali. Tujuan dari penelitian ini adalah membuat sebuah metode yang merupakan modifikasi dari metode game theory agar dapat digunakan untuk optimasi pembangkit Sistem Jamali, memperoleh komposisi pembangkit sistem kelistrikan Jamali yang optimal dari tahun 2015-2035, dan mengetahui pengaruh perubahan nilai discount rate, laju pertumbuhan kebutuhan listrik, dan harga emisi CO2 terhadap hasil pengembangan pembangkit Sistem Jamali khususnya pada biaya pokok pembangkitan.INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9a4052e9-6895-47f6-9ad1-f701934a4f4c', 'Minimum SCR and Impact of PLL Gain on Flat Start Capability on a Point to Point VSC-HVDC Interconnection', NULL, 2023, '2023-06-25', 'Roni Irnawan; Rian Fatah Mochamad; Filipe Faria da Silva; Qi Zhang; Sarjiya Sarjiya', NULL, 'JOURNAL', '10.1109/powertech55446.2023.10202918', 'https://doi.org/10.1109/powertech55446.2023.10202918', 'This paper investigates the minimum grid strength requirements to the interconnection between two islands using HVDC, which are considered as weak or very weak networks, e.g., Sumba and Sumbawa islands in Indonesia. Renewable energy source power is transmitted from one island to the other one through an HVDC interconnector. However, the electricity network in the landing island is underdevelopment, with non-uniform 70 - 150 kV long transmission lines between generators and loads; therefore, its grid strength can be considered weak or very weak grid depending on transferred power. Simulations will consider different scenarios of power transfer through the HVDC link. The minimum AC-side grid strength in the form of short circuit rating (SCR) required to achieve a flat start for each scenario is investigated. It is found that minimum SCR is not constant, but rather follows a pattern of the minimum SCR increasing linearly when the amount of power transfer increases. It is also confirmed that the phase-locked loop (PLL) plays an influential role in the interconnection where a reduced proportional gain for the PLL can turn a marginally unstable into a marginally stable system.', 4, 'OPENALEX', '{"doi": "10.1109/powertech55446.2023.10202918", "openalex": "https://openalex.org/W4385694937"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('18b495fc-deb4-4640-9853-41a9acbefed4', 'Application of genetic algorithm for optimal sizing and placement of distribution transformers in PT PLN East Medan Indonesia', NULL, 2016, '2016-01-01', 'Sarjiya Sarjiya; Husni Rois Ali; Reynold B. A. Pardede', 'AIP conference proceedings', 'JOURNAL', '10.1063/1.4958520', 'https://doi.org/10.1063/1.4958520', 'The distribution system is the closest network to the customer. Therefore, the distribution network should be designed economically to obtain a particular level of quality. A good long-term planning needs to be carried out to get such a system. One such plan is to get the optimal sizing and placement of distribution transformers. The objective of the study is to obtain optimal location and capacity of the distribution transformer in PT PLN (Persero) East Medan, North Sumatra. The location and optimum capacity are obtained by minimizing the investment costs and operational costs of electric power distribution system without violating voltage constraint. Genetic Algorithm method is used to get the optimal costs. The results show that optimal sizing and placement distribution transformers problem in PT PLN (Persero) East Medan, Sumatera Utara can be solved efficiently using Genetic Algorithm in less than 200 generations. Sensitivity analysis on the utilization factor, demand factor and coincidence factor have been reported. The increase of the demand factor and coincidence factor are directly proportional to the increase in investment costs. Meanwhile, the utilization factor is inversely proportional to the value of the investment cost.', 3, 'OPENALEX', '{"doi": "10.1063/1.4958520", "openalex": "https://openalex.org/W2341182608"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('99430daa-29f0-4d7c-b2af-e6dd16dc489b', 'Value of Loss Load Analysis of Java-Bali System Based on Macro Economic Data', NULL, 2020, '2020-06-03', 'Christina Purwaningsih; Sarjiya Sarjiya; Yusuf Susilo Wijoyo', 'Journal FORTEI-JEERI', 'JOURNAL', '10.46962/forteijeeri.v1i1.7', 'https://doi.org/10.46962/forteijeeri.v1i1.7', 'Industrial and business sectors have big influence to gross domestic product in some regions (GDP). Beside that, GDP is influenced by electricity consumption. That statement is the reason why value of loss load (VOLL) had to be calculated. This research calculates VOLL for getting the value of outage cost, efficiency and productivity industrial and business sector in each Area Pengaturan Beban (APB) and in entire Java-Bali region. VOLL is calculated by macroeconomic analysis because this method has more time efficiency than survey analysis. VOLL forecasting in 2016-2023 are calculated too in this research. After that, the outage cost forecasting in hierarchical level 1 (HL 1) can be gotten if expected energy not supplied (EENS) from HL 1 is calculated. Before EENS calculation is held, analysis of another reliability indices such as loss of load expectation (LOLE) and loss of load probability (LOLP) were calculated. The calculation results show that VOLL in 2017 is 35,100.67 Rp/kWh and EENS in HL 1 is 7.25 MWh. Total outage cost from calculation is 289 million rupiahs.', 3, 'OPENALEX', '{"doi": "10.46962/forteijeeri.v1i1.7", "openalex": "https://openalex.org/W3120167328"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b2aa6aff-9868-45b3-904f-04334d94b19e', 'Desain Purwarupa Generator Linier Untuk Pembangkit Listrik Tenaga Ombak Skala Piko di Pantai Selatan Jawa', NULL, 2017, '2017-01-01', 'Budi Azhari; S.T. Eng. F. Danang Wijaya; Sarjiya Sarjiya', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/109526', 'Pemanfaatan energi terbarukan untuk pembangkit listrik kini menjadi penting untuk mengurangi ketergantungan terhadap bahan bakar fosil, meningkatkan rasio elektrifikasi, dan mengurangi emisi karbon. Salah satu sumber energi terbarukan yang potensial untuk dikembangkan adalah energi ombak. Beberapa wilayah di Indonesia memiliki potensi energi ombak yang besar. Salah satunya pantai selatan Jawa. Generator linier magnet permanen (GLMP) mulai banyak dikembangkan untuk mengkonversi energi mekanik ombak menjadi energi listrik. Generator ini dapat digolongkan menjadi beberapa hal berdasarkan kriteria tertentu, salah satunya adalah bahan inti. Bedasarkan hal tersebut terdapat model iron-cored, semi iron-cored, dan air-cored. Perbedaan di antara ketiganya yaitu seberapa besar material besi mengisi inti stator.INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4b3eb8eb-d87f-4a99-8ec0-5e4b2ed7ff54', 'Generation and Transmission Expansion Planning in Remote Areas by considering Renewable Energy Policy and Local Energy Resources: The Case Study of Jayapura Power System', NULL, 2021, '2021-10-05', 'Tumiran; Sarjiya Sarjiya; Lesnanto Multa Putranto; Edwin Nugraha Putra; Rizki Firmansyah Setya Budi; Candra Febri Nugraha', '2021 3rd International Conference on High Voltage Engineering and Power Systems (ICHVEPS)', 'JOURNAL', '10.1109/ichveps53178.2021.9600932', 'https://doi.org/10.1109/ichveps53178.2021.9600932', 'A generation and transmission expansion planning (G&TEP) is crucial to obtain economical, reliable, and sustainable power supply. Several factors, including renewable energy policy, archipelago country, uneven distribution of demand and energy resources, and remote areas, increase the complexity of G&TEP problems. Therefore, a G&TEP model by considering these factors is required. This study developed a G&TEP model by taking renewable energy policy and local energy resources into account. This model was implemented in the Jayapura power system to represent a system that is experiencing the aforementioned issues. In addition, the electricity generation in Jayapura is still dominated by high-cost diesel fuel. The research results show that the economical, reliable, and sustainable power supply in Jayapura can be achieved. The optimal result provides a generation cost of 8.4 cents USD/kWh. The renewable energy mix increases from 23% in 2025 to 60% in 2050. Biomass power plants, which utilize local energy sources, contribute the most to the renewable energy share. In addition, the expansion of the transmission line is 385.6 circuit kilometers long and is dominated by 70 kV lines. Furthermore, the 11 existing substations are expanded, and five new substations are built.', 3, 'OPENALEX', '{"doi": "10.1109/ichveps53178.2021.9600932", "openalex": "https://openalex.org/W3215773165"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('ebace680-9f0a-4649-abf1-fa54ea29400f', 'Investigating the influences of two position (non-staggered and staggered) of wind turbine arrays to produce power in a wind farm', NULL, 2016, '2016-01-01', 'Ismail Ismail; Samsul Kamal; Purnomo Purnomo; Sarjiya Sarjiya', 'AIP conference proceedings', 'JOURNAL', '10.1063/1.4949294', 'https://doi.org/10.1063/1.4949294', 'This investigation was conducted to identify the influences of the two positions (non-staggered and staggered) of wind turbine arrays. Identification on down-scaled size wind turbine arrays was carried out in an open circuit, suction-type wind tunnel. Based on the results of the experiment, empirical relations for the centreline velocity deficit, tipline velocity deficit and wake radius are proposed. The non-staggered position results are larger power generated than that of the staggered position, this influenced by the trend deficit in velocity that makes wind turbine generated power difference between staggered position and non-stagger position. The area used non-staggered position larger than staggered position. Result staggered position has become one of the solutions to harness wind farms confined areas.', 2, 'OPENALEX', '{"doi": "10.1063/1.4949294", "openalex": "https://openalex.org/W2509118607"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('335b6116-3800-4b84-b210-7e06e69a2995', 'Application of Demand Response Scheme for Generation Scheduling and Dispatch for Reducing Generation Cost', NULL, 2019, '2019-10-01', 'Fikriyan Fajar Al Farobi; Sarjiya Sarjiya; Lesnanto Multa Putranto; Muhammad Yasirroni', NULL, 'JOURNAL', '10.1109/ieeeconf48524.2019.9102498', 'https://doi.org/10.1109/ieeeconf48524.2019.9102498', 'Demand response (DR), a program motivates consumers to change their load in a period. The response load demand is being a problem in unit commitment (UC). However, UC is related to fulfilling load demand and minimizing the total operation cost of the generating unit without violation of the system and unit constraints. The UC and DR problems are solved using Mixed-Integer Quadratic Programming (MIQP). Load shifting affected by the application of DR is going to affect the percentage of load factor. The higher percentage of load factor has a potential benefit for the utility. The performance of the proposed method is tested using the standard IEEE 10-unit test system. The simulation result shows that the proposed method is capable of increasing 5% load factor with DR. The simulation result also show that the proposed method is capable of reducing at 0.59% of the total generation cost.', 2, 'OPENALEX', '{"doi": "10.1109/ieeeconf48524.2019.9102498", "openalex": "https://openalex.org/W3029863229"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('c051a0aa-d3db-480f-afb8-11ec29e18de7', 'Integration Challenges of Climate-Energy-Water-Food Nexus in Indonesia’s Power Generation Sector', NULL, 2020, '2020-09-23', 'Dwi Novitasari; Sarjiya Sarjiya; Rachmawan Budiarto', NULL, 'JOURNAL', '10.1109/fortei-icee50915.2020.9249906', 'https://doi.org/10.1109/fortei-icee50915.2020.9249906', 'Food, energy, and water are irreplaceable human’s basic needs. In Indonesia, 65% of its population live in the coastal area where they do not have sufficient energy access to conduct their daily activities. The risk of sea-level rise due to climate change is another challenge for those communities. Regarding climate change, Indonesia is predicted to contribute to 573 million tons of CO <inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emissions in 2038, coming from power generation. Climate change also affects the quantity and quality of water. Due to its demand for water, Java Island will face the most significant challenge on water scarcity because the water resources cannot meet those demands. It will affect the food security and well-being of the communities. Climate, land-use, energy, water, food (CLEWF)nexus are inseparable because those variables influence the welfare of communities. This paper discussed about challenges in CLEWF analysis based on power generation perspectives in Indonesia. The study concludes that there are four challenges for integrating CLEWF nexus: 1)data availability, 2) supply-demand gap identification, 3)method of analysis and 4) policies integrating variables of CLEWF.', 2, 'OPENALEX', '{"doi": "10.1109/fortei-icee50915.2020.9249906", "openalex": "https://openalex.org/W3098021104"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('7db4257a-e75b-41ae-b773-a86572478cb7', 'Impact of Sizing and Placement on Energy Storage System in Generation Scheduling Considering Transmission Losses', NULL, 2019, '2019-10-01', 'Imron; Lesnanto Multa Putranto; Sarjiya Sarjiya; Muhammad Yasirroni', NULL, 'JOURNAL', '10.1109/ieeeconf48524.2019.9102627', 'https://doi.org/10.1109/ieeeconf48524.2019.9102627', 'The existence energy storage system (ESS) can reduce some of the problems in the power system. The problems occur in dispatch, stability, and economical at generation and transmission. ESS is one of a solution to overcome issues about intermittency, load shifting, frequency regulation, energy arbitrage, reserve power support, etc. Impact of size and location of ESS give a significant benefit to the power system. The objective of this paper is to investigate proper sizing and placement of ESS considering the transmission losses. The condition of transmission losses can influence power scheduling on Unit commitment (UC) and reliability system. Thus, an important technique for considering certain ESS is needed. The optimization of the ESS operation is solved using mix integer quadratic programming (MIQP). The result of the optimization is used as input for UC to optimize cost for scheduling generations. The next step is using the UC output to perform power flow analysis for evaluating transmission losses. The total operational cost 24 hours without ESS up to $136.23, ESS installed 100 MWh up to $135.47, ESS installed 60 MWh up to $135.7, and ESS installed 40 MWh up to $135.74. While the result of total losses without ESS reaches 217.636 MW and ESS installed reaches 212.187 MW at bus 6. If ESS installed at bus 19, the losses increase to 220.729 MW. Therefore, the difference in ESS capacity has an impact on system operation, while the placement of ESS yields different losses. The next step of developed optimization needs to be determined ESS of proper location and sizing capacity as part of systems using the best methods metaheuristic to complete the best results.', 2, 'OPENALEX', '{"doi": "10.1109/ieeeconf48524.2019.9102627", "openalex": "https://openalex.org/W3032606823"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('21514cfe-5823-46a7-8066-4c11fc52063c', 'Realizing National Targets through Generation Expansion Planning: A Transition Energy Case Study of Java-Bali Power System, Indonesia', NULL, 2024, '2024-10-16', 'Reka Mustika Sari; Sarjiya Sarjiya; Lesnanto Multa Putranto', NULL, 'JOURNAL', '10.1109/iconeei64414.2024.10747999', 'https://doi.org/10.1109/iconeei64414.2024.10747999', 'Indonesia has committed to a comprehensive energy transition strategy, aiming to achieve a 31% new and renewable energy (NRE) mix by 2050 and net zero emissions (NZE) by 2060 or earlier. As an interim milestone, Indonesia’s Enhanced Nationally Determined Contributions (NDC) target calls for reduction in greenhouse gas (GHG) emissions by 2030, focusing on cleaner energy adoption and reduced fossil fuel dependency. This study evaluates Indonesia’s potential to realize these national targets, focusing on the Java-Bali power system, which accounts for 70% of the country’s electricity consumption. Using the MoMANI-OSeMOSYS model. Two scenarios were developed: business as usual (BAU) and NRE. The analysis, which simulates until 2034, aligns with Indonesia’s Enhanced NDC target. Results indicate that the NRE scenario, while having a slightly higher levelized cost of energy (LCOE) at 9 cents USD/kWh compared to BAU’s 8.8 cents USD/kWh, achieves significant reductions in CO<inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emissions. This outcome is driven by a reduction in coal and diesel consumption, offset by an increase in nuclear, solar, and biomass energy production. Although the NRE scenario entails higher initial costs, it offers substantial environmental benefits that support Indonesia’s Enhanced NDC objectives by 2030 and build a strong foundation for realizing the national targets.', 2, 'OPENALEX', '{"doi": "10.1109/iconeei64414.2024.10747999", "openalex": "https://openalex.org/W4404317373"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b1d32082-e4ff-4764-aed7-d7f422d64a25', 'Achieving Net Zero Emissions by 2060: The Role of Nuclear and Renewable Energy in Indonesia’s Energy Transition', NULL, 2024, '2024-12-11', 'Ihsan Ahmad Badrianto; Sarjiya Sarjiya; Roni Irnawan', NULL, 'JOURNAL', '10.1109/isriti64779.2024.10963626', 'https://doi.org/10.1109/isriti64779.2024.10963626', 'Indonesia has committed to achieving Net Zero Emissions by 2060 or earlier in response to the Paris Agreement. Demand growth and Indonesia’s reliance on fossil fuels, particularly coal, are driving the country to reduce greenhouse gas emissions and expedite its transition to cleaner energy sources. The purpose of this study is to examine Indonesia’s potential and opportunities for decarbonization in the energy sector and to identify other approaches for the country’s energy transition. This study utilized the Open Source Energy Modeling System (OSeMOSYS) with the clicSAND interface as a tool for long-term modeling. The aim was to compare power generation capacity, investment, and CO<inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emissions across three different scenarios. The three scenarios include business as usual, coal phase-out 2045, and net zero emission scenarios depending on national targets. These scenarios were simulated in different years with varying aims and were optimized accordingly. The findings indicate that the net zero emission scenario yields lower levels of greenhouse gas emissions and is more economically efficient compared to the other scenarios. The results show that the net zero emission scenario produces much lower CO<inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emissions (25,957 MtCO<inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf>), which is less than the coal phase-out scenario (45,266 MtCO<inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf>) at similar costs (4315 and 4344 billion USD). This study argues that the utilization of widespread new and renewable energy and the gradual elimination of coal are crucial tactics to expedite the shift toward sustainable energy and attain a state of zero net emissions by the year 2060.', 2, 'OPENALEX', '{"doi": "10.1109/isriti64779.2024.10963626", "openalex": "https://openalex.org/W4409494743"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('6caffb5d-6868-4c58-873f-f3d4ad876247', 'PENGARUH PENAMBAHAN SILIKON TERHADAP SUDUT KONTAK HIDROPOBIK DAN KARAKTERISTIK ARUS BOCOR PERMUKAAN BAHAN RESIN EPOKSI', NULL, 2011, '2011-01-01', 'Abdul Syakur; Ika Novia A; Sarjiya Sarjiya; Hamzah Berahim', 'DOAJ (DOAJ: Directory of Open Access Journals)', 'JOURNAL', '10.14710/teknik.v32i3.1733', 'https://doaj.org/article/1b0fd0e6e5da440cbf3a283c59fbb131', 'Currently, polymer materials such as epoxy resin have been used as an insulator in the distribution andtransmission line. Some advantages of using this epoxy resin material having the dielectric properties are betterthan porcelain and glass insulators. On the other side, epoxy resins are also disadvantage the surface ishygroscopic. For the repair was done by adding the surface properties of silicone rubber materialThis paper describes the effect of adding silicone rubber against contact angle of hidrophobicity and surfaceleakage current characteristics of epoxy resin materials ( Di-Glycidyl Ether of Bisphenol A (DGEBA) andMethaphenilene Diamine (MPDA). The study was conducted in the laboratory using the electrode method IEC587:1984 with NH4Cl contaminants. The voltage applied to the epoxy resin sample at 3.5 kV and 50 HzfrequencyThe experimental results showed that the addition of silicon rubber in epoxy resin makes the surface materialcontact angle increases. The higher percentage of silicone rubber, the greater the contact angle and the longertime required for the occurrence of surface discharge.', 4, 'OPENALEX', '{"doi": "10.14710/teknik.v32i3.1733", "openalex": "https://openalex.org/W1550870601"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e7ffe271-d990-463e-ac6d-60e156fe2f78', 'Determination of Maximum Grid-Connected Photovoltaic Penetration Level Based on Unit Commitment Solution', NULL, 2019, '2019-09-30', 'Penang Rahimta Mara; Sarjiya Sarjiya; Lesnanto Multa Putranto; Muhammad Yasirroni', 'International Journal on Electrical Engineering and Informatics', 'JOURNAL', '10.15676/ijeei.2019.11.3.11', 'https://doi.org/10.15676/ijeei.2019.11.3.11', NULL, 3, 'OPENALEX', '{"doi": "10.15676/ijeei.2019.11.3.11", "openalex": "https://openalex.org/W3046834824"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('26c13784-42c3-4bf2-9f50-a9ca14cf2e48', 'Challenges In Using Renewable Energy for Islands in Indonesia: A Case Study of Karimunjawa', NULL, 2020, '2020-10-20', 'Dwi Novitasari; Fiki Rahmatika Salis; Rachmawan Budiarto; Sarjiya Sarjiya', NULL, 'JOURNAL', '10.1109/icue49301.2020.9307078', 'https://doi.org/10.1109/icue49301.2020.9307078', 'Karimunjawa subdistrict which is located in Central Java Province received electricity supply in 2006 by using diesel powerplant. The Government of Indonesia also installed solar powerplants in 3 of 5 islands in Karimunjawa subdistrict. The management of the solar powerplants in the islands provides challenges not only in technical, but also in economic and social aspects caused by technology which is still new for community. This paper discussed about the challenges in implementing renewable energy technology in islands. The data was collected by (1) daily energy demand survey in 45 households in Karimunjawa (2) observation and (3) stakeholders'' interview. The results showed the importance of (1) developing productive used of energy, (2) the collaboration among many parties (3) technical, social and economic assistance in all project phase and (4) community engagement.', 3, 'OPENALEX', '{"doi": "10.1109/icue49301.2020.9307078", "openalex": "https://openalex.org/W3120118099"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('9d6a84d8-5033-499c-b991-7618c75ec463', 'Assessing The Impact of Variable Renewable Energy on Generation Expansion Planning and System Reliability: A Case Study of Java Bali System', NULL, 2023, '2023-08-13', 'Tumiran; Sarjiya Sarjiya; Lesnanto Multa Putranto; Ahmad Adhiim Muthahhari; Rizki Firmansyah Setya Budi', NULL, 'JOURNAL', '10.1109/sege59172.2023.10274567', 'http://dx.doi.org/10.1109/sege59172.2023.10274567', 'Previous studies show that integrating variable renewable energy (VRE) impacts system reliability and operational requirements. With Indonesia’s target to increase the use of VRE to achieve a net zero emission target, an assessment of the impact of VRE on energy planning and system reliability is necessary. The Java-Bali System does not incorporate VRE in reserve margin or reliability calculation. However, the cost implications of VRE investments in system planning must be considered. Therefore, in this research, an assessment is conducted to evaluate the impact of VRE on power system planning and reliability by considering the investment effects of VRE in a generation expansion planning (GEP) while also assessing the system’s reliability level. The GEP is conducted using a mixed integer linear programming (MILP) formula, followed by an evaluation of the impact of VRE on the reserve margin and investment costs. Based on the assessment of GEP for the Java Bali system, the electricity system has met the minimum reserve margin limit of 36.79% in 2030 without considering the contribution of the VRE power plant. In 2030, the VRE power plants of 3.1 GW are not considered in the reserve margin calculation. Building the 3.1 GW VRE power plant requires an investment of 1,440.8 million USD. If the VRE power plants are considered in the RM calculation, the RM becomes 44.67%. It shows the system overcapacity by adding the VRE to the RM calculation. Therefore, considering the VRE power plants in the RM calculation is crucial, and it is essential to obtain the firm capacity of the VRE power plant. The firm capacity shows the equivalent capacity of VRE PP in comparison to dispatchable power plants.', 2, 'OPENALEX', '{"doi": "10.1109/sege59172.2023.10274567", "openalex": "https://openalex.org/W4387487477"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e09c746f-c4b3-4121-b0df-6afe0a8475a8', 'Yogyakarta Electricity System Expansion Planning Considering Renewable Energy and CO2 Emission Reduction', NULL, 2023, '2023-08-09', 'Kriskalia Mayangkari; Sarjiya Sarjiya; Sasongko Hadi Pramono', NULL, 'JOURNAL', '10.1109/ice3is59323.2023.10335239', 'http://dx.doi.org/10.1109/ice3is59323.2023.10335239', 'Yogyakarta Province lacks fossil fuel and natural gas resources. Consequently, it relies on the supply of Java-Madura-Bali electrical system to meet its electricity needs. However, this system is dominated by fossil and gas power plants which produce CO<inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emissions. One of the solutions to reduce CO<inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emissions is by utilizing renewable energy. In this paper, electrical system planning used two scenarios, namely the Business as Usual and renewable energy with energy storage scenario. Contribution of renewable energy power plants has been analyzed based on two aspects, namely electricity production and reduction of CO<inf xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:xlink="http://www.w3.org/1999/xlink">2</inf> emissions. Model was simulated with Low Emissions Analysis Platform software and optimization was solved with Next Energy Modelling System for Optimization. During the planning period the renewable energy scenario contribution of generated electricity by 92% and the import of electricity from Java-Madura-Bali system by 8%. From 2033 to 2036 renewable energy scenario will be capable of supplying the electricity system by 100% without any imports from grid. The renewable energy scenario can reduce emissions by 84 % from the Business as Usual scenario. Cost-Benefit analysis shows that the renewable energy scenario can produce Net Present Value cost of 2.3 billion USD less than the Business as Usual scenario.', 2, 'OPENALEX', '{"doi": "10.1109/ice3is59323.2023.10335239", "openalex": "https://openalex.org/W4389544763"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('ac208562-8524-4bf7-bdc8-cd10a02a585e', 'Stochastic Unit Commitment in Various System Sizes under High Uncertainty Photovoltaic Forecast', NULL, 2023, '2023-02-24', 'Muhammad Yasirroni; Lesnanto Multa Putranto; Sarjiya Sarjiya; Husni Rois Ali; Indra Triwibowo; Qiangqiang Xie', 'Jurnal Nasional Teknik Elektro dan Teknologi Informasi (JNTETI)', 'JOURNAL', '10.22146/jnteti.v12i1.5281', 'https://doi.org/10.22146/jnteti.v12i1.5281', 'This paper proposes a stochastic unit commitment (SUC) approach to solve a day-ahead unit commitment (UC) problem in a system with high uncertainty net load which is caused by photovoltaic (PV) power plants. In contrast with robust unit commitment (RUC) which only considers the worst-case scenario, SUC considers every possible scenario with its probability. Multiple possible PV curves were obtained using k-means clustering on historical data. The proportion of cluster members was used as a weight factor representing the occurrence probability of PV curves. The test was separated into two-step tests, namely day-ahead and real-time markets, using IEEE 10 generating unit system and solved using CPLEX. The results showed that in a day-ahead UC, SUC ($539,896) had lower cost than RUC ($548,005). However, when the total energy generated was considered, the SUC (20.78 $/MWh) cost higher compared to RUC (20.75 $/MWh). It is because the solution proposed by SUC is as robust as the RUC, but the generation cost formulation also considers over-commitment. Thus, SUC produced a fairer price for the independent power producer and electric utility in the day-ahead calculation. The results also showed that in the test environment of the real-time market, SUC was able to produce a robust solution without going into over-commitment. It is clearly shown in a 30 units system test with 10 centroids, in which SUC had a cheaper solution (20.7253 $/MWh) compared to RUC (20.7285 $/MWh), without violating power balance or going to load shedding.', 1, 'OPENALEX', '{"doi": "10.22146/jnteti.v12i1.5281", "openalex": "https://openalex.org/W4322615678"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('862182c5-9cb7-4e33-8382-c91e0d595b56', 'Impact of Coal Supply Constraint and Renewable Energy Mixed Target on a Power System Planning A Case Study of Southern Sulawesi System', NULL, 2023, '2023-10-26', 'Amira Hanun; Sarjiya Sarjiya; Lesnanto Multa Putranto; Tumiran; Ira Savitri; Daud Farel', NULL, 'JOURNAL', '10.1109/icitee59582.2023.10317640', 'http://dx.doi.org/10.1109/icitee59582.2023.10317640', 'The effect of coal price fluctuation may affect the energy security of power system with high penetration of coal power plant. Moreover, the net zero emission trend make the power system utility do the energy transition to retire the existing coal power plant and to revise the power system planning. To deal with those problems, a generation expansion plan is proposed to limit the coal supply to the coal power plant. The energy conversion constraint is added to the standard linear model of generation expansion planning. The percentage of coal supply limitation is developed as the scenario and compared to the base case. The proposed method is simulated for 10 years planning horizon in Southern Sulawesi Power System which has high potential of renewable energy and coal power plant planning. As the result, the coal supply limitation requires 13.24% increment of reserve margin. Moreover, coal supply limitation increase the LCOE 2.23, 2.03 and 1.89 c$/kWh for 30, 25 and 20% coal supply limitation.', 1, 'OPENALEX', '{"doi": "10.1109/icitee59582.2023.10317640", "openalex": "https://openalex.org/W4388821547"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('5f3fe9ef-420e-4c76-898b-1695e2cb21e0', 'Optimizing Renewable Energy Resources on an Isolated Island to Support an Archipelagic Country''s Net Zero Emission Target: A Case Study of Sumba Island, Indonesia', NULL, 2024, '2024-09-03', 'Wachid Marindra Hary Setyawan; Sarjiya Sarjiya; Lesnanto Multa Putranto', NULL, 'JOURNAL', '10.1109/ict-pep63827.2024.10733421', 'https://doi.org/10.1109/ict-pep63827.2024.10733421', 'Sumba Island, rich in solar and wind potential, faces challenges in developing RES due to isolated grids and low electricity demand. U sing renewable energy in Sumba is necessary to support Indonesia''s NZE goals by effectively integrating Sumba''s renew abIes into the national grid and potentially connecting it to regions with high electricity demand. This study focuses on the sustainable GEP for Sumba, optimizing renewable energy potential, improving energy storage, and exploring inter-island connectivity through MILP to achieve the optimal value of the total system cost and the least investment with predetermined boundaries. Several scenarios were examined, and the results show that connecting Sumba to nearby islands with higher electricity demands would increase the use of local RES. With the NZE interconnected scenario, the solar PV potential can be maximized up to 76.8%, while the wind share can reach 58.4%. However, in the other scenarios, the potential use of solar PV and wind remains below 6%. Energy storage will become more necessary as solar PV and wind power use rises, increasing the proportion of renewable energy in 2060. Moreover, interconnection reduces the cost of electricity compared to an isolated system, but it can increase investment costs.', 1, 'OPENALEX', '{"doi": "10.1109/ict-pep63827.2024.10733421", "openalex": "https://openalex.org/W4403938364"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('633fa0a8-bdea-4a6a-99aa-3ed69ec5610b', 'Evaluation of Co-firing in a Pulverized Coal Boiler Using Multi-Biomass: Sawdust and Rice Husks', NULL, 2024, '2024-11-22', 'Faqih Alfaruq; Tumiran; Sarjiya Sarjiya', NULL, 'JOURNAL', '10.1109/iceecit63698.2024.10859495', 'https://doi.org/10.1109/iceecit63698.2024.10859495', 'This study investigates the impact of co-firing biomass with coal at Pulverized Coal (PC) Boiler-type power plant. While fossil fuels, particularly coal, continue to dominate global energy production, they significantly contribute to greenhouse gas (GHG) emissions. Despite efforts to reduce coal-fired power generation capacity in Indonesia, coal remains a major component of the country''s energy mix. To support the government''s renewable energy goals and reduce GHG emissions, biomass co-firing is being explored as a viable solution. Various biomass types, including saw dust, rice husks, cocopeat, and palm shells, were evaluated for their potential in co-firing applications. Unlike other studies that utilize a single type of biomass, this study employs multiple biomass types, specifically sawdust and rice husks. The use of multi-biomass offers an alternative solution to the challenge of biomass feedstock availability. This research assesses both the technical and economic feasibility of biomass co-firing, with a focus on gross calorific value (GCV), Hardgrove Grindability Index (HGI), generation cost and emissions reduction. Laboratory tests and combustion modeling were conducted to analyze the performance and environmental impacts. The results indicate that biomass co-firing can effectively reduce emissions while maintaining operational performance, positioning it as a promising strategy for sustainable energy production in Indonesia. In this paper, the authors aim to explore the impact of biomass utilization as a co-firing material in a PC Boiler power plant.', 1, 'OPENALEX', '{"doi": "10.1109/iceecit63698.2024.10859495", "openalex": "https://openalex.org/W4407128999"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('26b29555-fb3b-417f-91ec-26f8caefc27f', 'Stochastic enhancement of distribution network to increase hosting capacity and reduce voltage deviation', NULL, 2025, '2025-07-15', 'Wijaya Yudha Atmaja; Filipe Faria da Silva; Sarjiya Sarjiya', 'e-Prime - Advances in Electrical Engineering Electronics and Energy', 'JOURNAL', '10.1016/j.prime.2025.101073', 'https://doi.org/10.1016/j.prime.2025.101073', 'Exceeding the hosting capacity limits of photovoltaic (PV) systems can disrupt distribution network performance, leading to voltage instability and undesirable voltage rises. As PV integration expands, there is a need for the stochastic enhancement of distribution networks to increase hosting capacity and reduce voltage deviation. Traditional deterministic approaches often fail to address the inherent uncertainties in distributed PV penetration and to effectively utilize the VAR compensation capabilities of PV inverters. To overcome these limitations, a unified stochastic framework that integrates VAR compensation functions is introduced. A key contribution of this study is the probabilistic candidate selection method, which considers all customers as potential PV adopters and thus reflects real-world uncertainties in VAR compensation. Another contribution is the use of an unsimplified distribution grid model, offering a realistic representation of network conditions. A final contribution is the development of time-series based indices that capture the dynamic impacts of VAR compensation under varying load demand and solar irradiance. The results demonstrate that this methodology provides a practical approach for the stochastic enhancement of distribution networks, increasing hosting capacity and reducing voltage deviation.', 1, 'OPENALEX', '{"doi": "10.1016/j.prime.2025.101073", "openalex": "https://openalex.org/W4412438632"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('35697d3c-d6f3-4364-94b7-7dda2fb44dd8', 'Modelling the speed control of Brushless DC Motor base on identification system', NULL, 2013, '2013-11-01', 'Hidayat Hidayat; Sasongko Pramonohadi; Sarjiya Sarjiya; Suharyanto Suharyanto', NULL, 'JOURNAL', '10.1109/icici-bme.2013.6698499', 'https://doi.org/10.1109/icici-bme.2013.6698499', 'This paper presents a practice method to model the speed control of Brushless Direct Current Motor (BLDCM) system. This method only needs a dynamic response of BLDCM when given a step input. Further, the data response is represented in to the data series that used as source form the BLDCM model. BLDCM model''s is generated by estimation parameter base on the least squares algorithm using that''s data. Further, the model is evaluated by the MATLAB simulink and then compared by response of the real plant. The results show that the response characteristic of the speed control of BLDCM base on model is similar to the response of the real plant.', 5, 'OPENALEX', '{"doi": "10.1109/icici-bme.2013.6698499", "openalex": "https://openalex.org/W2139091497"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('b5946f2f-e264-4246-b31d-870c8255da70', 'Roadmap energy in special region of Yogyakarta to empower renewable energy source', NULL, 2014, '2014-05-01', 'Yusnan Badruzzaman; Sarjiya Sarjiya; Avrin Nur Widiastuti', '2014 International Symposium on Technology Management and Emerging Technologies', 'JOURNAL', '10.1109/istmet.2014.6936520', 'https://doi.org/10.1109/istmet.2014.6936520', 'Yogyakarta does not have any non renewable energy sources such as liquid fossil fuels, coal and natural gas. Consequently, these energy resources must be supplied from other provinces. This study purposed to evaluate the existing energy demand and supply in Yogyakarta and to predict the supply and demand by empowering the use of renewable energy which meets the objective of the energy mix and energy elasticity of less than 1. The objectives of energy mix for renewable energy based on KEN and KED scenarios were 17% and 9.28% respectively in 2025. This study used a model of LEAP (Long-range Energy Alternatives Planning System) version: 2011.0.0.40.', 4, 'OPENALEX', '{"doi": "10.1109/istmet.2014.6936520", "openalex": "https://openalex.org/W2027662537"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3121d4fd-4cc6-48fb-a41f-7b16ebe054c3', 'OPTIMISASI PENEMPATAN DAN KAPASITAS WIND-BASED DISTRIBUTED GENERATION UNTUK MINIMISASI LOSSES MENGGUNAKAN FLOWER POLLINATION ALGORITHM', NULL, 2017, '2017-01-01', 'Dian Budhi Santoso; Sarjiya Sarjiya; Dea. Ir. Sasongko P. Hadi', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/116783', 'Distributed generation (DG) adalah teknologi pembangkitan energi listrik berskala kecil yang menghasilkan daya listrik di suatu tempat yang lebih dekat dengan konsumen dibandingkan dengan pusat pembangkit listrik. Pembangkit energi listrik ini dapat dihubungkan secara langsung ke konsumen atau ke sistem distribusi maupun transmisi. Terdapat beberapa tipe DG berdasarkan teknologi yang digunakannya, yaitu traditional combustion generators, dan non-traditional combustion generators. Salah satu bentuk DG non-traditional combustion generators adalah wind turbine. Wind turbine bukan merupakan energi yang baru, melainkan sudah digunakan selama beberapa dekade. Wind turbine termasuk dalam kategori pembangkit listrik yang ramah lingkungan karena tidak menghasilkan polusi seperti jenis pembangkit lain.INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('2f05a3b1-c586-45c3-b867-6ba94e2747fe', 'Design of Robust Power System Stabilizer in an Interconnected Power System with Wind Power Penetrations', NULL, 2010, '2010-06-01', 'Cuk Supriyadi; Issarachai Ngamroo; Sarjiya Sarjiya; Tumiran; Yuichiro Mitani', 'InTech eBooks', 'BOOK_CHAPTER', '10.5772/8352', 'https://doi.org/10.5772/8352', 'Design of Robust Power System Stabilizer in an Interconnected Power System with Wind Power Penetrations', 2, 'OPENALEX', '{"doi": "10.5772/8352", "openalex": "https://openalex.org/W1505481050"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('a8583633-021d-4e91-a97a-99dd8e2ca9c3', 'An Interleaved Totem-Pole Power Factor Correction Converter', NULL, 2010, '2010-03-26', 'Eka Firmansyah; Satoshi Tomioka; 聡 富岡; Seiya Abe; 征哉 安部; Masahito Shoyama; 正仁 庄山; Tamotsu Ninomiya; 保 二宮; サトシ トミオカ; セイヤ アベ; マサヒト ショウヤマ; タモツ ニノミヤ', 'QIR (Kyushu University Institutional Repository) (Kyushu University)', 'JOURNAL', '10.15017/17889', 'http://hdl.handle.net/2324/17889', 'This paper explains about basic working principles, implementation problems, and experimental results of a new power factor correction (PFC) topology. In this proposed topology, a totem-pole boost PFC circuit that works under interleaved critical-conduction-mode (CRM) condition is presented. The circuit is developed towards high efficiency, high performance, lowcost, simple control scheme, and low conducted electro magnetic interference (EMI) PFC circuit. The application is targeted toward middle power applications that normally employs continuous or non-bridgeless interleaved boost converter.', 2, 'OPENALEX', '{"doi": "10.15017/17889", "openalex": "https://openalex.org/W2399369631"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0a94e7f4-2c7b-4d6c-8fd9-59b681e9b4c3', 'Optimized Design of Wind Farm Configuration: Case Study', NULL, 2014, '2014-12-15', 'Ismail Ismail; Samsul Kamal; Purnomo Purnomo; Sarjiya Sarjiya; Prajitno Prajitno', NULL, 'JOURNAL', NULL, 'https://www.ajouronline.com/index.php?journal=AJAS&page=article&op=view&path%5B%5D=2089', 'The initial result of wind energy study conducted in onshore Purworejo in one year (October 2004 ~ September 2005) shows that potential wind speed on the heights of 100 m with the Weibull shape parameter is 1.74 and the Weibull scale parameter is 6.93 m/s. The research is located near fishery industrial activity, fish auction market and transmission network electric. Study for the development of potential wind energy into wind farm in coastal area of South Purworejo is strategic for Central Java Province, Indonesia. In numerical procedure, two-numerical phases are conducted, and they cover (i) numerical based on capacity factor and (ii) numerical based on wind farm configuration design. From result and discussion can be concluded that wind farm configuration with size L row = 4000 m and L col = 1000 m, wind turbines with a diameter of 113 m with 42 turbines, produced total energy about 363382.71 MWh per year with ratio cost per energy about 0.000079, and it has the most optimal result.', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W1608385010"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('d0b9bd39-b2d5-485d-b1a8-c07925a09ae2', 'ALGORITMA GENETIKA SEBAGAI SOLUSI OPTIMAL POWER FLOW PADA SISTEM KELISTRIKAN 500 KV JAWA BALI', NULL, 2013, '2013-08-01', 'Yassir Yassir; Sarjiya Sarjiya; Timbul Haryono', 'Transmisi: Jurnal Ilmiah Teknik Elektro', 'JOURNAL', '10.12777/transmisi.15.3.107-113', 'https://ejournal.undip.ac.id/index.php/transmisi/article/download/5265/4750', 'Abstrak Optimal power flow dengan batasan transmisi adalah salah satu solusi optimisasi biaya produksi energi listrik dengan tetap menjaga keandalan sistem. Pada penelitian ini diaplikasikan metode Algoritma Genetika (AG) dengan daya aktif pembangkit, tegangan bus pembangkit, tap transformator dan injeksi kapasitor digunakan sebagai variabel control. Efektifitas metode diuji pada kasus sistem IEEE 30 bus, dan dibandingkan dengan metode evolutionary programming (EP) , differential evolution (DE) dan particle swarm optimization (PSO) . Hasil simulasi menunjukkan metode yang diusulkan lebih baik dari metode pembanding . Simulasi pada sistem tenaga Jawa-Bali 500 kV dengan metode yang diusulkan dapat mengurangi biaya pembangkitan sebesar 13,4% dibanding dengan data operasi PT. PLN (Persero). Kata kunci : Optimal Power Flow,  batasan transmisi, Algoritma Genetika. Abstract Transmission constrained Optimal Power Flow is one of several methods to minimize fuel costs while maintaining system reliability constraints. In this study, Genetic Algorithm was applied to solve the problem of OPF. Active power generator, generator bus voltages, transformer tap and injection capacitor used as control variables. Effectiveness of the method was tested on IEEE 30 bus system case and it is compared with the evolutionary programming (EP), differential evolution (DE) and particle swarm optimization (PSO) method. Simulation results using the proposed method give better result than the mentioned methods. Simulation on the Java-Bali 500 kV power system based on proposed method can reduce the cost 13,4% compared with the existing operation of PT. PLN (Persero). Keywords :  Optimal Power Flow, Genetic Algorithm, transmission constraint.', 2, 'OPENALEX', '{"doi": "10.12777/transmisi.15.3.107-113", "openalex": "https://openalex.org/W1910774403"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('027c501e-1186-444a-8dde-782ae2fa308d', 'Evaluation of Reactive Power Control for High PV Penetration on Low-Voltage Distribution Network', NULL, 2021, '2021-10-14', 'Wijaya Yudha Atmaja; Sarjiya Sarjiya; Lesnanto Multa Putranto', NULL, 'JOURNAL', '10.1109/icitee53064.2021.9611863', 'https://doi.org/10.1109/icitee53064.2021.9611863', 'Because of the limitation on the number of photovoltaic (PV) systems hosted by the distribution network, the improvement of hosting capacity needs to be studied. This objective is usually achieved by restricting the PV penetration level. However, as it only limits the number of PV penetration, the solution does not address the problem with excellence. As another option, a reactive power control (RPC) is employed by several studies. By controlling the absorption and injection of reactive power, the hosting capacity is able to be increased. Nevertheless, the simplified models provided previously cause difficulties in interpreting the results. Consequently, it is questioning the practical implementation of the RPC, especially for high PV penetration. Therefore, this article provides an evaluation of customer-scale RPC performance for hosting capacity improvement. A stochastic framework is applied to deal with the uncertainty and variability of the solar irradiance and penetration process. An algorithm for hosting capacity determination with the implementation of RPC on the basis of overvoltage is developed. Moreover, two discussions are provided, the sensitivity analysis of the RPC impact of customer-scale PV inverter on hosting capacity and the impact assessment of the proposed stochastic model on hosting capacity. The results show that the implementation of an appropriate RPC leads the distribution network to host additional PV systems.', 2, 'OPENALEX', '{"doi": "10.1109/icitee53064.2021.9611863", "openalex": "https://openalex.org/W3216485398"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('028296d3-050d-45bf-b458-f9be022539ef', 'Customer Behavior and EV Charging Service Business', NULL, 2021, '2021-09-29', 'Kevin Gausultan Hadith Mangunkusumo; Roni Irnawan; Derajat Sulistyo Widhyharto; Sunyoto Usman; Sarjiya Sarjiya; Lesnanto Multa Putranto; Imam Muthohar; Fajar Nurrohman Haryadi', NULL, 'JOURNAL', '10.1109/ict-pep53949.2021.9600991', 'https://doi.org/10.1109/ict-pep53949.2021.9600991', 'The transportation sector in Indonesia is estimated to absorb more than 50% of the total national fuel consumption. One form of fuel saving effort carried out by PLN (Indonesia’s electricity company) is to encourage the growth of battery-based electric vehicles (EV). On the other hand, a strategy of adding electrical loads is needed to absorb underutilized power plants and increase the percentage of annual load growth. Electricity charging infrastructure for EV is an alternative solution to solve these problems. In this study, cluster sampling and purposive sampling methods were used. Furthermore, in order to improve the comprehensiveness of the research, a Focus Group Discussion (FGD) was conducted by involving the government, experts, observers, and transportation business actors as well as corresponding PLN Units. From the result, it is known that important aspects in the development of public electric vehicle charging stations (SPKLU) are: designation, development, and governance, its locations, and payment systems. SPKLU business development needs to pay attention to driving behavior (mobility and driving time) which forms a monocentric and polycentric pattern, i.e. correlated with the driving anxiety factor. Optimizing the functions of these aspects for SPKLU businesses must be supported by stakeholder engagement (participation of the government, PLN, investors, implementing contractors, and suppliers), good governance, and customer adaptability.', 2, 'OPENALEX', '{"doi": "10.1109/ict-pep53949.2021.9600991", "openalex": "https://openalex.org/W3217116375"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e0a60603-d4c6-45e2-928e-5a0cf49c3219', 'Studi Pengukuran Partial Discharge Pada Bahan Resin Epoksi', NULL, 2008, '2008-01-01', 'Abdul Syakur; Winarko Ap; Hamzah Berahim; Sarjiya Sarjiya; Rochmadi Rochmadi', 'Transmisi', 'JOURNAL', '10.12777/transmisi.10.1.49-52', 'http://ejournal.undip.ac.id/index.php/transmisi/article/view/1592/0', 'Polimer materials now have been broadly used for high voltage isolation device. After long operation the polimer isolation can have degradation or decreasing in isolation quality until it became improper isolation. One main caused about this degradation is the deformity for instance the pointed conductor between the conductor to isolation interface that could make the partial discharge. Therefore is so important to have the information about the partial discharge characteristics of  isolation material at operational condition. In this paper the research about the influences of voltage and application time of voltage to partial discharge characteristics was explained . This research used the epoxy resin for isolation and needle-plane electrode measurement method  with 50 Hz ac voltage to investigate the partial discharge parameters such as the number of positive and negative charge and the maximum charge of positive and negative. Keywords:  partial discharge,  resin epoksi,  elektroda jarum-bidang.', 1, 'OPENALEX', '{"doi": "10.12777/transmisi.10.1.49-52", "openalex": "https://openalex.org/W1503648232"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('fa74feab-6037-4a2d-92fe-fa6a17ea7a9f', 'Design and Experiment of Open Circuit Low Speed Wind Tunnel', NULL, 2014, '2014-09-03', 'Ismail Ismail; Samsul Kamal; Purnomo Purnomo; Sarjiya Sarjiya; Ahmad Al Anshary', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/135109/', NULL, 1, 'OPENALEX', '{"openalex": "https://openalex.org/W1810402994"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('caf090a9-c829-48d5-a897-86004a07ebda', 'MICROCONTROLLER BASED HYDROGEN SULFIDE (H2S) MONITORING IN BIOGAS SYSTEM', NULL, 2013, '2013-07-31', 'Diah Yuniarti; Sarjiya Sarjiya; Ambar Pertiwiningrum', 'ASEAN Journal of Systems Engineering', 'JOURNAL', '10.22146/ajse.v1i1.2354', 'https://doi.org/10.22146/ajse.v1i1.2354', 'Energy issue, particularly related to fossil fuel, is one the main issues today. Biogas is a new and renewable energy issued in National Research Agenda (ARN) 2010-2014 to overcome the energy crisis problem. A so called purification process is used to remove contaminants in biogas, including H2S in order to improve the standard requirement of biogas application. In this research, H2S concentration in biogas system is measured and monitored by H2S monitoring system.The hardware system comprises of piping and microcontroller AVR 8535 systems while the software system comprises of codes written in Delphi 7.0 and Code Vision AVR Eval. The result of the system is displayed on LCD or computer to enable the monitoring process by operator. The monitoring of H2S sensor responses will be carried out for recycled BFA size of 60+100 mesh and -200 mesh.Experiment has been conducted for sensor warming up time and response time for H2S and CH4 sensor, calibration process for H2S sensor and filter column. Based on sensor calibration experiment, transfer function of TGS825 sensor from calibration is y = 0.0203x + 27.153. The best adsorption model which represents BFA adsorption of biogas from tofu waste in the research is Thomas model.', 1, 'OPENALEX', '{"doi": "10.22146/ajse.v1i1.2354", "openalex": "https://openalex.org/W2206765233"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('80458487-854e-4b00-a2b1-7affc9e548f5', 'PENGOPTIMALAN OPERASI PEMBANGKIT LISTRIK TENAGA HIBRIDA SURYA - ANGIN UNTUK MENGURANGI EXCESS ELECTRICITY MENGGUNAKAN MIX INTEGER LINEAR PROGRAMMING', NULL, 2015, '2015-12-03', 'Winasis Winasis; Imron Rosyadi; Sarjiya Sarjiya', 'Transmisi: Jurnal Ilmiah Teknik Elektro', 'JOURNAL', '10.12777/transmisi.17.4.186-193', 'https://ejournal.undip.ac.id/index.php/transmisi/article/download/9598/pdf', 'Salah satu upaya yang dilakukan dalam pemenuhan kebutuhan energi listrik  adalah dengan memanfaatkan sumber energi baru dan terbarukan (EBT) seperti : energi matahari dan energi angin sebagai Pembangkit Listrik Tenaga Hibrida (PLTH). Penelitian ini bertujuan menganalisis pengoptimalan pengoperasian sistem PLTH Surya Angin dengan studi  kasus pada PLTH Pantai Baru Bantul menggunakan metode Mix Integer Linear Programming . pengoptimalan bertujuan untuk meminimalkan excess electricity dan memaksimalkan pemanfaatan potensi energi terbarukan dengan memperhatikan batasan-batasan yang terkait dengan kapasitas modul sel surya, kapasitas turbin angin, kapasitas inverter, dan kendala baterai. Permasalahan optimisasi dan batasan operasi diformulasikan sebagai model Mix Integer Linear Programming (MILP) dan diselesaikan menggunakan software optimisasi Tomlab CPLEX. Simulasi model optimisasi menggunakan data pembangkit listrik hibrida surya angin Pantai Baru dilakukan dengan skenario penambahan beban non-critical ( dummy ) pada sistem pembangkit hibrida. Berdasarkan hasil simulasi didapatkan nilai excess electricity dapat dikurangi dan pemanfaatan energi pada beban dapat dimaksimalkan. Kata kunci: excess electricity, MILP, pembangkit listrik tenaga hibrida, pengoptimalan', 1, 'OPENALEX', '{"doi": "10.12777/transmisi.17.4.186-193", "openalex": "https://openalex.org/W2266331056"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('cbeffe0b-9569-4697-8001-a7ec707a0c7c', 'Electricity tariff of Bunaken hybrid Genset-PVs-battery system based on LRMC method', NULL, 2015, '2015-11-01', 'Sarjiya Sarjiya; Yusuf Susilo Wijoyo; Rayyan', NULL, 'JOURNAL', '10.1109/iccsce.2015.7482221', 'https://doi.org/10.1109/iccsce.2015.7482221', 'As revealed by the blueprint 2005–2025 of PEN/Pengelolaan Energi Nasional (National Energy Management), government has set a national target in which that all villages in Indonesia by 2025 must be provided by electricity with the electrification ratio of 95%. This is the benchmark that all areas - even the remotest areas - have to be electrified. Bunaken is an area as one of the tourist attractions in Indonesia that has implemented a hybrid Power System to fulfill its electricity needs. Electricity tariff (locally abbreviated as TDL) adopted by the Government is considered less appropriate for not reflecting the costs burdened by PLN (State Electricity Enterprise) as the power producer.', 1, 'OPENALEX', '{"doi": "10.1109/iccsce.2015.7482221", "openalex": "https://openalex.org/W2340008837"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('87c24682-f99a-45e4-9912-20367ee26726', 'Substation expansion planning in Kulon progo region using imperialist competitive algorithm', NULL, 2017, '2017-10-01', 'Sarjiya Sarjiya; Tiyono; Beny Septian Pardede', NULL, 'JOURNAL', '10.1109/iciteed.2017.8250512', 'https://doi.org/10.1109/iciteed.2017.8250512', 'The objective of substation expansion planning (SEP) is to prepare the capacity of a substation in order to supply the load growth in the future. The planning is conducted also to minimize the investment and operation cost of the substation, by finding its optimal location, capacity, and construction time. This paper proposes SEP using an imperialist competitive algorithm (ICA) and geographical information system (GIS). The type of planning is one stage, with 10 years period time (long-term). Two alternatives of SEP, which are the expansion of existing substation and the construction of a new substation in the new location are analyzed and compared. The alternative with a lower cost without breaking the constraints is taken. The effect of ICA parameters is also tested to find the best optimum value and the fastest execution time. Finally, the comparison between ICA and Genetic Algorithm (GA) is done to prove the effectiveness of the method in the SEP.', 1, 'OPENALEX', '{"doi": "10.1109/iciteed.2017.8250512", "openalex": "https://openalex.org/W2783597001"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e3cb9f1e-f804-4ef1-a5d3-5b2076874a23', 'Optimasi Sistem Hybrid Pembangkit Listrik Tenaga Angin Dan Pembangkit Listrik Tenaga Ombak', NULL, 2017, '2017-01-01', 'Kukuh Daud Pribadi; S.T. Eng. F. Danang Wijaya; Sarjiya Sarjiya', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/109508', 'Energi ombak dan energi angin merupakan sumber energi yang memanfaatkan aliran angin. Kecepatan angin yang berubah-ubah dari waktu ke waktu menjadi salah satu faktor penghambat dari pemanfaatan energi angin dan energi ombak untuk menjadi energi listrik. Perubahan kecepatan angin yang relatif cepat ini berimbas pada ketidak-optimalan proses ekstraksi daya oleh PLTB dan PLTO. Untuk mengoptimalkan proses ekstraksi daya, sistem hybrid angin dan ombak (SHAO) dilengkapi dengan algoritma maximum power point tracking (MPPT) particle swarm optimization (PSO). Hasil penelitian menunjukkan bahwa dengan menggunakan algoritma MPPT berbasis PSO, maximum power point dapat dicapai. Sehingga efisiensi SHAO dapat meningkat menjadi 94% pada bagian angin dan 92% pada bagian ombak. Dengan menggunakan MPPT berbasis PSO, SHAO dapat merespon dengan baik perubahan kecepatan angin dan ombak, baik itu perubahan dari kecepatan rendah ke kecepatan yang lebih tinggi atau perubahan dari kecepatan tinggi ke kecepatan rendah dimana waktu untuk mencapai kondisi steady-state yang baru adalah Â± 0,1 s. Pada kecepatan angin dan ombak yang bervariasi, algoritma PSO dapat mempertahankan Cp sistem di kisaran 0,47-0,48 sehingga daya dapat diekstrak secara maksimal
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('143c5430-d213-4a2d-bfa7-977ad3d9527d', 'Korelasi kompetensi profesional, motivasi kerja, dan budaya organisasi sekolah dengan produktivitas kerja guru SMP/MTs se-Kecamatan Temon', NULL, 2016, '2016-06-01', 'Sarjiya Sarjiya; Mulyoto Mulyoto', 'Wiyata Dharma Jurnal Penelitian dan Evaluasi Pendidikan', 'JOURNAL', '10.30738/wdpep.v4i2.2271', 'https://jurnal.ustjogja.ac.id/index.php/wd/article/view/2271', 'This study aims to determine  the  correlation  between: (1)  teachers’ professional  competence  and teachers’ working productivity, (2) teachers’ working motivation and teachers’ working productivity, (3) school organizational culture and teachers’ working productivity, (4) teachers’ professional competence, teachers’ working motivation,  and  school organizational  culture  altogether  and  teachers’ working productivity. This research is a descriptive quantitative research a kind of correlational research. The study population was all SMP / MTs teachers in Temon subdistrict in Kulon Progo Regency, amounting to 119 teachers. The samples are 92 teachers who were taken by proportional cluster random sampling technique. Data were analyzed using correlation technique are simple, double, and partial. The results of the regression analysis on the significance level of 5% showed that: (l) there is a significant positive correlation between the professional competence of teachers in the teachers’ working productivity with the effective contribution of 39.4%. (2) there is a significant positive correlation with the productivity of teachers’ working motivation of teachers with the effective contribution of 12.8%. (3) there is a significant positive correlation between organizational culture of schools with teachers working productivity with the effective contribution of 9.8%., And (4) there is a significant positive correlation jointly between the professional competence of teachers, teachers’ working motivation, and organizational culture of the school with the teachers working productivity with the effective contribution 62.0%. This suggests that the three independent variables have a significant positive correlation of working productivity of teachers.', 1, 'OPENALEX', '{"doi": "10.30738/wdpep.v4i2.2271", "openalex": "https://openalex.org/W2954046556"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('cc52a80d-1e5f-4184-bfd5-135864b4ed94', 'Ant Colony Optimization for Resolving Unit Commitment Issues by Considering Reliability Constraints', NULL, 2019, '2019-11-11', 'Alan Abdu Robbi Afifi; Sarjiya Sarjiya; Yusuf Susilo Wijoyo', 'IJITEE (International Journal of Information Technology and Electrical Engineering)', 'JOURNAL', '10.22146/ijitee.49422', 'https://doi.org/10.22146/ijitee.49422', 'Unit Commitment or generator scheduling is one of complex combination issues aiming to obtain the cheapest generating power total costs. Ant Colony Optimization is proposed as a method to solve Unit Commitment issues because it has a better result convergence according to one of journals that reviews methods to solve Unit Commitment issues. Ant Colony Optimization modification into Nodal Ant Colony Optimization as well as addition of several elements are also conducted to overcome Ant Colony Optimization limitations in resolving Unit Commitment issues. Nodal Ant Colony Optimization simulations are then compared with Genetic Algorithm and Simulated Annealing methods which previously has similar simulations. Reliability index combination in a form of Loss of Load Probability and Expected Unserved Energy are also added as reliability constraints in the system. Comparison of three methods shows that Nodal Ant Colony Optimization is able to provide better results up to 0.08% cheaper than Genetic Algorithm or Simulated Annealing methods.', 1, 'OPENALEX', '{"doi": "10.22146/ijitee.49422", "openalex": "https://openalex.org/W2998361245"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('91470ac6-188e-4650-a5ef-c1b0693599b2', 'Evaluation of rooftop photovoltaic allocation strategies of hosting capacity analysis in low-voltage grid', NULL, 2020, '2020-01-01', 'Wijaya Yudha Atmaja; Sarjiya Sarjiya; Lesnanto Multa Putranto', 'AIP conference proceedings', 'JOURNAL', '10.1063/5.0013574', 'https://doi.org/10.1063/5.0013574', 'To prevent the performance degradation of a low-voltage distribution grid, in dealing with large-scale rooftop photovoltaic penetration, a hosting capacity analysis needs to be provided. Since accuracy is a necessity in determining the hosting capacity, an evaluation of the rooftop photovoltaic allocation strategies concerning its accuracy is required. Therefore, the objective of this work is to provide a study of rooftop photovoltaic allocation strategies evaluation of hosting capacity analysis in the low-voltage distribution grid. To consider the actual issues, a real low-voltage distribution grid from Indonesia is employed. Over/undervoltage and feeder operating power factor are assigned as the operational performance limits considered for determining the hosting capacity. This work begins with assessing six possible scenarios concerning rooftop photovoltaic distribution flow direction. The results show that the feeder operating power factor is observed as the most restrictive limit. These also indicate that several distinct locations must be considered to develop allocation strategies. According to these results, three LDCRPA (locational dependence constrained rooftop photovoltaic allocation) strategies are developed, including strategy with null locational dependence, two locational dependences, and three locational dependences. Furthermore, these strategies are employed to determine the rooftop photovoltaic hosting capacities, and the accuracy assessment is applied. The results show that, with a tolerance value of 0.09, the strategy considering two locational dependences generates the highest accuracy of 0.952381 compared with the other strategies.', 1, 'OPENALEX', '{"doi": "10.1063/5.0013574", "openalex": "https://openalex.org/W3083264688"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('82dfdae1-fbfb-4f89-9b47-18a34d9cb36b', 'ANN for Optimal Operation of BESS in a Grid Integrated Wind Farm', NULL, 2020, '2020-09-23', 'Evando Diotama; Roni Irnawan; Lesnanto Multa Putranto; Sarjiya Sarjiya', NULL, 'JOURNAL', '10.1109/fortei-icee50915.2020.9249874', 'https://doi.org/10.1109/fortei-icee50915.2020.9249874', 'The combination of windfarm and battery energy storage system (BESS) can be developed massively by the fact that many countries are planning to add more penetrations to the grid system in large scale. In large scale capacity, fluctuation of renewable energy resource might increase the loss of a system. That problem is also affected by the state of charge (SOC) of battery. The objective of this paper is to simulate the load flow and optimize the BESS operation using python integrated with DIgSILENT PowerFactory. Further, we compare the system power losses of three cases, i.e.: the system that is only supported by windfarm, adding BESS to the system and optimizing BESS operation. The optimization of BESS operation is done by using ANN (Artificial Neural Network). The optimized BESS operation reduced the average system power losses by 13% from the system that only utilizes windfarm.', 1, 'OPENALEX', '{"doi": "10.1109/fortei-icee50915.2020.9249874", "openalex": "https://openalex.org/W3101481625"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0f3a2cf0-386e-477a-82d9-bca566be2fda', 'AUDIT ENERGI DAN PERANCANGAN BUILDING ENERGY MANAGEMENT SYSTEM UNTUK RUANG E5 DAN E6 DEPARTEMEN TEKNIK ELEKTRO DAN TEKNOLOGI INFORMASI UNIVERSITAS GADJAH MADA', NULL, 2018, '2018-01-01', 'Muchammad Ilham Maul; S.T. Avrin Nur Widiastuti; Sarjiya Sarjiya', NULL, 'JOURNAL', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/164693', 'Penggunaan energi yang efisien bertujuan untuk mengurangi jumlah energi yang dibutuhkan serta untuk memelihara kelestarian sumber daya energi. Pada Peraturan Pemerintah Republik Indonesia Nomor 70 Tahun 2009 tentang konservasienergi ditegaskan perlunya dilakukan audit kepada bangunan. Sementara pada Peraturan menteri ESDM Nomor 13 Tahun 2012 pasal 4 disebutkan bahwa objek-objek yang menjadi target penghematan adalah sistem tata udara dan sistem tata cahaya. Ruang E5 dan E6 sebagai bagian dari UGM perlu menjalankan penghematan energi. Penelitian ini terfokus kepada audit energi listrik dan perancangan BEMS sebagai bagian dari penerapan penghematan energi di Ruang E5 dan E6. Kedua ruang saat ini sedang dijadikan percontohan dari penerapan audit energi dan penerapan BEMS untuk ruangan.INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('e5f41ec2-2d08-4be1-96cd-5c6fe7550bf1', 'Photovoltaic Penetration with MILP Method and Technical Minimum Loading Consideration', NULL, 2023, '2023-02-03', 'Alfi Bahar; Muhammad Yasirroni; Sarjiya Sarjiya; M. Isnaeni Bambang Setyonegoro', 'Jurnal Nasional Teknik Elektro dan Teknologi Informasi (JNTETI)', 'JOURNAL', '10.22146/jnteti.v12i1.4531', 'http://dx.doi.org/10.22146/jnteti.v12i1.4531', 'Technological development and the reduction of installation costs have caused a rapid growth of solar power plants in Indonesia. The National Electricity Company (Perusahaan Listrik Negara, PLN) strives to achieve the energy mix of renewable energy to 23% by 2025. Solar power plants are unique in that they only supply their power during the daytime. It makes solar power plants connected to the power system change the load profile of the Java-Bali system. In this study, the penetration of solar power plants changed the scheduling of the Java-Bali system because the penetration was installed to the technical minimum loading of existing power plants. When penetration is too big, thermal generator scheduling failure is possible. Unit commitment and economic dispatch with mixed-integer linear programming (MILP) method using CPLEX and Python were carried out to calculate the fuel and generation costs per kWh before and after the penetration. MILP was used to solve the cost fuel equation, namely an integer and nonlinear mix equations, that are challenging to be solved using standar nonlinear programming methods. Due to the use of the MILP-UC, all objective function equations and restraint functions must be linear functions. The tests were conducted for three years, from 2023 to 2025. Simulation results on the Java-Bali system show that the capacity of solar power plants penetrating the Java-Bali system against the peak load will be 52%, 52%, and 50% in 2023, 2024, and 2025, respectively. Meanwhile, penetration of solar power plants to technical minimum loading of existing power plants resulted in the fuel cost falling by 23% in 2023 and 22% in 2024 and 2025. Lastly, the cost of generation per kWh will be decreased by 8% in 2023 and will be as low as 7% in 2024 and 2025.', 1, 'OPENALEX', '{"doi": "10.22146/jnteti.v12i1.4531", "openalex": "https://openalex.org/W4322615733"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3469a5bf-0cdb-4833-a507-4321144fe070', 'RANCANG BANGUN ALAT PENGGILING TEBU UNTUK MENINGKATKAN VOLUME AIR NIRA PADA INDUSTRI KECIL GULA MERAH', NULL, 2011, '2011-01-01', 'Syamsul Maarif; Sarjiya Sarjiya', NULL, 'OTHER', NULL, 'https://repository.ugm.ac.id/89597/', 'Sugar import volume in Indonesia always increases from year to year. It is caused by increasing sugar consumption of Indonesian people from year to year. Despitefully, the national sugar production always decreases because of decreasing in sugarcane planting areas and productivity such as the decline of the rendement. Declining of rendement is caused by unoptimal design and operation of sugarcane crusher machine and also in the plant treatment. The solution to avoid rendement declining due to unoptimal design of sugarcane crusher machine can be done by redesign it. The redesigned machine is expected to increase the juice sugar volume 5% more than the previous model of existing machine. Machine is designed using double action system which uses two pairs of rollers to increase the juice sugar. Sugarcane crusher machine that is already in the market uses a single action system which using a pair of roller. Single action system can be represented by disabling a pair of roller in the double action system. The production capacity of the designed sugar cane crusher machine is about 900 kg/hour. Based on the results of 10 times crushing from single action to double action system, it is achieved that the increasing of PS 77 and BL sugarcane are 31.19% and 16.86% respectively. From the economic analysis is found that benefit cost ratio (B/C) is 1.18 for breakeven point in Rp. 3.956.044,00 with payback period of 2.3 years and the return on investment (ROI) is 17.88%.', 2, 'OPENALEX', '{"openalex": "https://openalex.org/W2166599234"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
