INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('57c840a4-f161-4bd5-a0f2-186d3716e443', 'A Systematic Literature Review of Optimal Placement of Fast Charging Station', NULL, 2024, '2024-01-01', 'Jimmy Trio Putra; M. Isnaeni Bambang Setyonegoro; Taco Niet; Sarjiya Sarjiya', 'SSRN Electronic Journal', 'PREPRINT', '10.2139/ssrn.4891122', 'http://dx.doi.org/10.2139/ssrn.4891122', NULL, 1, 'OPENALEX', '{"doi": "10.2139/ssrn.4891122", "openalex": "https://openalex.org/W4400487108"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('4680bd64-a54e-4a58-b098-817a44105b49', 'Perhitungan losses teknis jaringan distribusi primer dengan menggunakan profil beban :: Studi kasus penyulang GNDH Gi Lagadar PT. PLN (Persero) APJ Cimahi', NULL, 2008, '2008-01-01', 'Arief Nugraha; Sarjiya Sarjiya', NULL, 'OTHER', NULL, 'http://etd.repository.ugm.ac.id/penelitian/detail/40147', 'Losses teknis pada jaringan distribusi primer tegangan menengah disebabkan arus beban di jaringan penghantar. Penyulang Gunung Dukuh (GNDH) merupakan salah satu penyulang dipasok dari Gardu Induk (GI) Lagadar di PT.PLN (Persero) APJ Cimahi. Permintaan kebutuhan daya listrik pelanggan yang dipasok dari gardu distribusi mempengaruhi losses teknis jaringan primer tegangan menengah. Penyulang Gunung Dukuh (GNDH) mempunyai panjang penghantar radial dari GI sampai ujung penyulang 40 km, pasokan daya di pangkal penyulang berkisar 220 A. Perhitungan perlu dilakukan untuk mengetahui losses teknis penyulang GNDH dan evaluasi pelaksanaan rekonfigurasi jaringan.INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('3177ce85-ff36-46fa-b314-e0fa9a173a6e', 'ANALISIS PERENCANAAN GATEWAY GIMANGKUNEGARAN PT. PLN (PERSERO) APJ SURAKARTA', NULL, 2010, '2010-01-01', 'Musthafa Kamal Hasany; I Nengah Sumerti; Sarjiya Sarjiya', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12007', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W1039810819"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
