INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('88ac9453-5ccd-4488-887f-4036c67f40d2', 'PENGUJIAN KARAKTERISTIK GENERATOR PUT ARAN RENDAH AXIAL FLUX PERMANENT MAGNET (AFPM)', NULL, 2010, '2010-01-01', 'Anandita Willy K; Sarjiya Sarjiya; Avrin Nur Widiastuti', 'JURNAL PENELITIAN TEKNIK ELEKTRO', 'JOURNAL', NULL, 'http://i-lib.ugm.ac.id/jurnal/detail.php?dataId=12167', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2596767494"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('58eea89c-3090-4dcc-8aba-592f0f1dfb1d', 'Reactive Power Optimization of DistributedGeneration for Voltage Regulation ofDistribution Systems', NULL, 2016, '2016-10-05', 'Jimmy Trio Putra; Sarjiya Sarjiya', NULL, 'JOURNAL', NULL, 'https://repository.ugm.ac.id/139179/', 'Additional intermittent PV generation and
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('494be685-fdd3-4f86-a45e-f7d51a09ad21', 'A Reinforcement Learning Approach for Frequency-Based Security Constrained Unit Commitment', NULL, 2025, '2025-02-15', 'Muhammad Yasirroni; Lesnanto Multa Putranto; Sarjiya Sarjiya; Armayau Yusuf', NULL, 'JOURNAL', '10.1109/cpeee64598.2025.10987385', 'https://doi.org/10.1109/cpeee64598.2025.10987385', 'This study investigates the capability of an offline reinforcement learning-based approach to address the dual objectives of optimal generation operation and system frequency stability. The Deep Deterministic Policy Gradient (DDPG) algorithm is used to produce generator status, initial voltage magnitude, active power generation, and reactive power generation for a given load profile and distribution. The New England 39-bus model is used as the the test case. This study generates 2,116 random scenarios and operating points with N-1 contingencies. The research findings indicate that the generator capacity utilization factor impacts frequency stability. The DDPG algorithm is able to understand the characteristics that lead to its capability in providing actions towards better stability and lower operational costs. In offline training with tabular data, DDPG achieves average rewards of 0.237, higher than random actions at 0.079.', 0, 'OPENALEX', '{"doi": "10.1109/cpeee64598.2025.10987385", "openalex": "https://openalex.org/W4410342624"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('0258d566-35c1-491a-a0aa-5e5699486110', 'Optimasi Aliran Daya pada Sistem Kelistrikan Opsi Nuklir Berdasarkan Multi-Objective Function: Fuel Cost dan Flat Voltage Profile', NULL, 2017, '2017-03-10', 'Rizki Firmansyah Setya Budi; Sarjiya Sarjiya; Sasongko Hadi Pramono', 'Jurnal Pengembangan Energi Nuklir', 'JOURNAL', '10.17146/jpen.2016.18.2.3127', 'https://doi.org/10.17146/jpen.2016.18.2.3127', 'Tujuan dari pengoperasian sistem tenaga listrik adalah untuk memasok daya dengan kualitas baik dan biaya pembangkitan seminimal mungkin. Kualitas yang baik membutuhkan biaya yang lebih besar, sehingga untuk mencapai tujuan tersebut diperlukan optimasi dengan fungsi obyektif yang bertujuan untuk memaksimalkan kualitas sekaligus meminimalkan biaya. Penelitian ini bertujuanuntuk mendapatkan kondisi aliran daya optimal atau optimal power flow (OPF) dari segi biaya pembangkitan maupun kualitas tenaga listrik di suatu sistem kelistrikan dengan opsi nuklir pada waktu beban puncak dengan menggabungkan fungsi obyektif fuel cost dan flat voltage profile. Fungsi obyektif fuel cost bertujuan untuk meminimalkan biaya pembangkitan sedangkan fungsi obyektif flat voltage profile bertujuan untuk memaksimalkan kualitas dengan meminimalkan perbedaan/variasi tegangan dalam sebuah sistem. Penelitian dilakukan melalui studi literatur, penentuan fungsi obyektif optimasi, penggabungan fungsi objektif, simulasi menggunakan contoh kasus dan analisis sensitivitas. Contoh kasus menggunakan sistem IEEE 9 Bus yang telah ditambahkan fungsi bahan bakar PLTN, PLTU, dan PLTG. Simulasi menggunakan program bantu ETAP 12.6.0. Analisis sensitivitas dilakukan dengan menggunakan nilai pembobotan dari 0-100% untuk tiap fungsi obyektif. Hasil simulasi menunjukkan bahwa OPF dicapai pada faktor pembebanan 60% untuk fuel cost dan 40% untuk flat voltage profile. Biaya pembangkitan padakondisi optimal tersebut sebesar 7266 US$/jam dengan selisih tegangan maksimum minimumnya sebesar 2,85%. Pada sistem ini PLTU membangkitkan daya sebesar 133,2 MW + 22,1 MVar dan PLTG sebesar 80,7 MW + 13,8 MVar. Sedangkan PLTN membangkitkan daya sebesar 89,9 MW + 12,9 Mvar dan akan ekonomis jika membangkitkan daya kurang dari 90 MW.', 0, 'OPENALEX', '{"doi": "10.17146/jpen.2016.18.2.3127", "openalex": "https://openalex.org/W2605103560"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
