INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('1c94746f-01d8-46ef-a90e-da295888a1be', 'IDENTIFIKASI KOMPOSISI UNSUR LOGAM BERAT PADA LINDI TEMPAT PEMROSESAN AKHIR (TPA) SAMPAH KOTA PADANG MENGGUNAKAN X – RAY FLUORESCENCE (XRF)', NULL, 2015, '2015-01-01', 'Iswandi Iswandi', NULL, 'JOURNAL', NULL, 'http://repository.unp.ac.id/8016/', 'Final waste processing site of Padang City is located on Air dingin, Kelurahan Balai Gadang, Koto Tangah Sub – distrik has 8 leachate holding pond. At 8 leachate holding pond flowe in to river next to final processing site. Most of residents around the final processing site use water fromriver and well around waste processing site as a source of clean water for daily life. This research aims to know composition ofheavy metal in sedimen of leachate pond, river sediment and gutter sediment of final waste processing site Air Dingin, Padang City. The sample used in this research are 4 samples of leachate pond sediment, 1 sample of gutter, 1 sample of riversediment which have been measured magnetic susceptibility values. The measurement result XRF will show content of elements contained in the samples. Determining the content of heavy metal using determined by matched measurement result with periodic table. The measurement  result using XRF further made in to table and graph. The measurement result using XRF show that heavy metal contained insample of leachate pond sediment are Titanium (Ti), Vanadium ( V), Cromium ( Cr ), Manganese ( Mn ), Iron ( Fe ), Cobalt ( Co ), Zinc ( Zn ), Rhadium ( Rh ), Neodinium ( Nd ), Eopium ( Eu ), Iterbium ( Yb ), Indium ( In ) and Zirconium (Zr). At measurement composition of sediment sample is acquired that heavy metal similar to result of leachate sample measurement, only Iterbium (Yb), Indium (In)  not foynd, where as on sediment sample of gutter also there is heavy metal that similar to composition sample of leachate and only Indium (In) not found.  The heavy metal that dominant find on sample as leachate sediment, river sediment, and gutter sediment is iron with percentage 33.664 % and rhadium with percentage 30.587 %. Heavy metal at final waste processing site Air Dingin suppose get in through metallic waste, chemical waste such as vehicles waste, waste of iron and steel, battery alectric devices, insecticide residuethat not classified weel. When wastes polish by water which get in to final waste processing site, water result of waste degradation sediment at mound of waste and flow to leachate holding wast', 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2338129079"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('f762ea1b-cd5a-4d33-93c8-0a4b73296ca9', 'B-5-180 Investigation of Doppler Frequency Shift of Dynamic BAN Channel through Analysis of On-Body Antenna Movement', NULL, 2010, '2010-03-02', 'Iswandi Iswandi; Min‐Seok Kim; Yuuki Terao; Jun‐ichi Takada', '電子情報通信学会総合大会講演論文集', 'JOURNAL', NULL, 'http://ci.nii.ac.jp/naid/110007883660', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W256971817"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
INSERT INTO public.publications (id, title, slug, year, publication_date, authors_text, venue, publication_type, doi, url, abstract, citation_count, source, external_ids, verified_status, fetch_batch_id, created_at, updated_at) VALUES ('22669f6e-deef-41ee-9870-38824dba815d', 'Potential SRTM Data for Peak Flow Analysis, Case Study at Lipat Kain Watershed, Kampar Watershed – Riau Province', NULL, 2006, '2006-01-01', 'Iswandi Iswandi', NULL, 'JOURNAL', NULL, 'https://repository.ipb.ac.id/handle/123456789/9523', NULL, 0, 'OPENALEX', '{"openalex": "https://openalex.org/W2610363150"}', 'NEEDS_REVIEW', 'openalex_20260709T173707Z', '2026-07-17 13:49:46.262812+00', '2026-07-17 13:49:46.262812+00');
